// 自動產生檔案，請勿手動編輯 —— 執行 build_book_text_data.py 重新產生
// 來源：bible_data/bible_text/LUK.json（A1下載產出）

const LUK_DATA = {"book": "LUK", "book_zh": "路加福音", "chapters": {"1": {"verses": {"1": {"en": "Since many have undertaken to set in order a narrative concerning those matters which have been fulfilled among us,", "zh": "提阿非羅大人哪，有好些人提筆作書，述說在我們中間所成就的事，是照傳道的人從起初親眼看見又傳給我們的。", "ja": "わたしたちの間に成就された出来事を、最初から親しく見た人々であって、"}, "2": {"en": "even as those who from the beginning were eyewitnesses and servants of the word delivered them to us,", "zh": "", "ja": "御言に仕えた人々が伝えたとおり物語に書き連ねようと、多くの人が手を着けましたが、"}, "3": {"en": "it seemed good to me also, having traced the course of all things accurately from the first, to write to you in order, most excellent Theophilus;", "zh": "這些事我既從起頭都詳細考察了，就定意要按着次序寫給你，", "ja": "テオピロ閣下よ、わたしもすべての事を初めから詳しく調べていますので、ここに、それを順序正しく書きつづって、閣下に献じることにしました。"}, "4": {"en": "that you might know the certainty concerning the things in which you were instructed.", "zh": "使你知道所學之道都是確實的。", "ja": "すでにお聞きになっている事が確実であることを、これによって十分に知っていただきたいためであります。"}, "5": {"en": "There was in the days of Herod, the king of Judea, a certain priest named Zacharias, of the priestly division of Abijah. He had a wife of the daughters of Aaron, and her name was Elizabeth.", "zh": "當猶太王希律的時候，亞比雅班裏有一個祭司，名叫撒迦利亞；他妻子是亞倫的後人，名叫伊利莎白。", "ja": "ユダヤの王ヘロデの世に、アビヤの組の祭司で名をザカリヤという者がいた。その妻はアロン家の娘のひとりで、名をエリサベツといった。"}, "6": {"en": "They were both righteous before God, walking blamelessly in all the commandments and ordinances of the Lord.", "zh": "他們二人在上帝面前都是義人，遵行主的一切誡命禮儀，沒有可指摘的，", "ja": "ふたりとも神のみまえに正しい人であって、主の戒めと定めとを、みな落度なく行っていた。"}, "7": {"en": "But they had no child, because Elizabeth was barren, and they both were well advanced in years.", "zh": "只是沒有孩子；因為伊利莎白不生育，兩個人又年紀老邁了。", "ja": "ところが、エリサベツは不妊の女であったため、彼らには子がなく、そしてふたりともすでに年老いていた。"}, "8": {"en": "Now while he executed the priest’s office before God in the order of his division", "zh": "撒迦利亞按班次在上帝面前供祭司的職分，", "ja": "さてザカリヤは、その組が当番になり神のみまえに祭司の務をしていたとき、"}, "9": {"en": "according to the custom of the priest’s office, his lot was to enter into the temple of the Lord and burn incense.", "zh": "照祭司的規矩掣籤，得進主殿燒香。", "ja": "祭司職の慣例に従ってくじを引いたところ、主の聖所にはいって香をたくことになった。"}, "10": {"en": "The whole multitude of the people were praying outside at the hour of incense.", "zh": "燒香的時候，眾百姓在外面禱告。", "ja": "香をたいている間、多くの民衆はみな外で祈っていた。"}, "11": {"en": "An angel of the Lord appeared to him, standing on the right side of the altar of incense.", "zh": "有主的使者站在香壇的右邊，向他顯現。", "ja": "すると主の御使が現れて、香壇の右に立った。"}, "12": {"en": "Zacharias was troubled when he saw him, and fear fell upon him.", "zh": "撒迦利亞看見，就驚慌害怕。", "ja": "ザカリヤはこれを見て、おじ惑い、恐怖の念に襲われた。"}, "13": {"en": "But the angel said to him, “Don’t be afraid, Zacharias, because your request has been heard. Your wife, Elizabeth, will bear you a son, and you shall call his name John.", "zh": "天使對他說：「撒迦利亞，不要害怕，因為你的祈禱已經被聽見了。你的妻子伊利莎白要給你生一個兒子，你要給他起名叫約翰。", "ja": "そこで御使が彼に言った、「恐れるな、ザカリヤよ、あなたの祈が聞きいれられたのだ。あなたの妻エリサベツは男の子を産むであろう。その子をヨハネと名づけなさい。"}, "14": {"en": "You will have joy and gladness, and many will rejoice at his birth.", "zh": "你必歡喜快樂；有許多人因他出世，也必喜樂。", "ja": "彼はあなたに喜びと楽しみとをもたらし、多くの人々もその誕生を喜ぶであろう。"}, "15": {"en": "For he will be great in the sight of the Lord, and he will drink no wine nor strong drink. He will be filled with the Holy Spirit, even from his mother’s womb.", "zh": "他在主面前將要為大，淡酒濃酒都不喝，從母腹裏就被聖靈充滿了。", "ja": "彼は主のみまえに大いなる者となり、ぶどう酒や強い酒をいっさい飲まず、母の胎内にいる時からすでに聖霊に満たされており、"}, "16": {"en": "He will turn many of the children of Israel to the Lord their God.", "zh": "他要使許多以色列人回轉，歸於主－他們的上帝。", "ja": "そして、イスラエルの多くの子らを、主なる彼らの神に立ち帰らせるであろう。"}, "17": {"en": "He will go before him in the spirit and power of Elijah, ‘to turn the hearts of the fathers to the children,’ and the disobedient to the wisdom of the just; to prepare a people prepared for the Lord.”", "zh": "他必有以利亞的心志能力，行在主的前面，叫為父的心轉向兒女，叫悖逆的人轉從義人的智慧，又為主預備合用的百姓。」", "ja": "彼はエリヤの霊と力とをもって、みまえに先立って行き、父の心を子に向けさせ、逆らう者に義人の思いを持たせて、整えられた民を主に備えるであろう」。"}, "18": {"en": "Zacharias said to the angel, “How can I be sure of this? For I am an old man, and my wife is well advanced in years.”", "zh": "撒迦利亞對天使說：「我憑着甚麼可知道這事呢？我已經老了，我的妻子也年紀老邁了。」", "ja": "するとザカリヤは御使に言った、「どうしてそんな事が、わたしにわかるでしょうか。わたしは老人ですし、妻も年をとっています」。"}, "19": {"en": "The angel answered him, “I am Gabriel, who stands in the presence of God. I was sent to speak to you and to bring you this good news.", "zh": "天使回答說：「我是站在上帝面前的加百列，奉差而來對你說話，將這好信息報給你。", "ja": "御使が答えて言った、「わたしは神のみまえに立つガブリエルであって、この喜ばしい知らせをあなたに語り伝えるために、つかわされたものである。"}, "20": {"en": "Behold, you will be silent and not able to speak until the day that these things will happen, because you didn’t believe my words, which will be fulfilled in their proper time.”", "zh": "到了時候，這話必然應驗；只因你不信，你必啞巴，不能說話，直到這事成就的日子。」", "ja": "時が来れば成就するわたしの言葉を信じなかったから、あなたはおしになり、この事の起る日まで、ものが言えなくなる」。"}, "21": {"en": "The people were waiting for Zacharias, and they marveled that he delayed in the temple.", "zh": "百姓等候撒迦利亞，詫異他許久在殿裏。", "ja": "民衆はザカリヤを待っていたので、彼が聖所内で暇どっているのを不思議に思っていた。"}, "22": {"en": "When he came out, he could not speak to them. They perceived that he had seen a vision in the temple. He continued making signs to them, and remained mute.", "zh": "及至他出來，不能和他們說話，他們就知道他在殿裏見了異象；因為他直向他們打手式，竟成了啞巴。", "ja": "ついに彼は出てきたが、物が言えなかったので、人々は彼が聖所内でまぼろしを見たのだと悟った。彼は彼らに合図をするだけで、引きつづき、おしのままでいた。"}, "23": {"en": "When the days of his service were fulfilled, he departed to his house.", "zh": "他供職的日子已滿，就回家去了。", "ja": "それから務の期日が終ったので、家に帰った。"}, "24": {"en": "After these days Elizabeth his wife conceived, and she hid herself five months, saying,", "zh": "這些日子以後，他的妻子伊利莎白懷了孕，就隱藏了五個月，", "ja": "そののち、妻エリサベツはみごもり、五か月のあいだ引きこもっていたが、"}, "25": {"en": "“Thus has the Lord done to me in the days in which he looked at me, to take away my reproach among men.”", "zh": "說：「主在眷顧我的日子，這樣看待我，要把我在人間的羞恥除掉。」", "ja": "「主は、今わたしを心にかけてくださって、人々の間からわたしの恥を取り除くために、こうしてくださいました」と言った。"}, "26": {"en": "Now in the sixth month, the angel Gabriel was sent from God to a city of Galilee named Nazareth,", "zh": "到了第六個月，天使加百列奉上帝的差遣往加利利的一座城去（這城名叫拿撒勒），", "ja": "六か月目に、御使ガブリエルが、神からつかわされて、ナザレというガリラヤの町の一処女のもとにきた。"}, "27": {"en": "to a virgin pledged to be married to a man whose name was Joseph, of David’s house. The virgin’s name was Mary.", "zh": "到一個童女那裏，是已經許配大衛家的一個人，名叫約瑟。童女的名字叫馬利亞；", "ja": "この処女はダビデ家の出であるヨセフという人のいいなづけになっていて、名をマリヤといった。"}, "28": {"en": "Having come in, the angel said to her, “Rejoice, you highly favored one! The Lord is with you. Blessed are you among women!”", "zh": "天使進去，對她說：「蒙大恩的女子，我問你安，主和你同在了！」", "ja": "御使がマリヤのところにきて言った、「恵まれた女よ、おめでとう、主があなたと共におられます」。"}, "29": {"en": "But when she saw him, she was greatly troubled at the saying, and considered what kind of salutation this might be.", "zh": "馬利亞因這話就很驚慌，又反覆思想這樣問安是甚麼意思。", "ja": "この言葉にマリヤはひどく胸騒ぎがして、このあいさつはなんの事であろうかと、思いめぐらしていた。"}, "30": {"en": "The angel said to her, “Don’t be afraid, Mary, for you have found favor with God.", "zh": "天使對她說：「馬利亞，不要怕！你在上帝面前已經蒙恩了。", "ja": "すると御使が言った、「恐れるな、マリヤよ、あなたは神から恵みをいただいているのです。"}, "31": {"en": "Behold, you will conceive in your womb and give birth to a son, and shall name him ‘Jesus.’", "zh": "你要懷孕生子，可以給他起名叫耶穌。", "ja": "見よ、あなたはみごもって男の子を産むでしょう。その子をイエスと名づけなさい。"}, "32": {"en": "He will be great and will be called the Son of the Most High. The Lord God will give him the throne of his father David,", "zh": "他要為大，稱為至高者的兒子；主上帝要把他祖大衛的位給他。", "ja": "彼は大いなる者となり、いと高き者の子と、となえられるでしょう。そして、主なる神は彼に父ダビデの王座をお与えになり、"}, "33": {"en": "and he will reign over the house of Jacob forever. There will be no end to his Kingdom.”", "zh": "他要作雅各家的王，直到永遠；他的國也沒有窮盡。」", "ja": "彼はとこしえにヤコブの家を支配し、その支配は限りなく続くでしょう」。"}, "34": {"en": "Mary said to the angel, “How can this be, seeing I am a virgin?”", "zh": "馬利亞對天使說：「我沒有出嫁，怎麼有這事呢？」", "ja": "そこでマリヤは御使に言った、「どうして、そんな事があり得ましょうか。わたしにはまだ夫がありませんのに」。"}, "35": {"en": "The angel answered her, “The Holy Spirit will come on you, and the power of the Most High will overshadow you. Therefore also the holy one who is born from you will be called the Son of God.", "zh": "天使回答說：「聖靈要臨到你身上，至高者的能力要蔭庇你，因此所要生的聖者必稱為上帝的兒子 。", "ja": "御使が答えて言った、「聖霊があなたに臨み、いと高き者の力があなたをおおうでしょう。それゆえに、生れ出る子は聖なるものであり、神の子と、となえられるでしょう。"}, "36": {"en": "Behold, Elizabeth your relative also has conceived a son in her old age; and this is the sixth month with her who was called barren.", "zh": "況且你的親戚伊利莎白，在年老的時候也懷了男胎，就是那素來稱為不生育的，現在有孕六個月了。", "ja": "あなたの親族エリサベツも老年ながら子を宿しています。不妊の女といわれていたのに、はや六か月になっています。"}, "37": {"en": "For nothing spoken by God is impossible.”", "zh": "因為，出於上帝的話，沒有一句不帶能力的。」", "ja": "神には、なんでもできないことはありません」。"}, "38": {"en": "Mary said, “Behold, the servant of the Lord; let it be done to me according to your word.” Then the angel departed from her.", "zh": "馬利亞說：「我是主的使女，情願照你的話成就在我身上。」天使就離開她去了。", "ja": "そこでマリヤが言った、「わたしは主のはしためです。お言葉どおりこの身に成りますように」。そして御使は彼女から離れて行った。"}, "39": {"en": "Mary arose in those days and went into the hill country with haste, into a city of Judah,", "zh": "那時候，馬利亞起身，急忙往山地裏去，來到猶大的一座城；", "ja": "そのころ、マリヤは立って、大急ぎで山里へむかいユダの町に行き、"}, "40": {"en": "and entered into the house of Zacharias and greeted Elizabeth.", "zh": "進了撒迦利亞的家，問伊利莎白安。", "ja": "ザカリヤの家にはいってエリサベツにあいさつした。"}, "41": {"en": "When Elizabeth heard Mary’s greeting, the baby leaped in her womb; and Elizabeth was filled with the Holy Spirit.", "zh": "伊利莎白一聽馬利亞問安，所懷的胎就在腹裏跳動。伊利莎白且被聖靈充滿，", "ja": "エリサベツがマリヤのあいさつを聞いたとき、その子が胎内でおどった。エリサベツは聖霊に満たされ、"}, "42": {"en": "She called out with a loud voice and said, “Blessed are you among women, and blessed is the fruit of your womb!", "zh": "高聲喊着說：「你在婦女中是有福的！你所懷的胎也是有福的！", "ja": "声高く叫んで言った、「あなたは女の中で祝福されたかた、あなたの胎の実も祝福されています。"}, "43": {"en": "Why am I so favored, that the mother of my Lord should come to me?", "zh": "我主的母到我這裏來，這是從哪裏得的呢？", "ja": "主の母上がわたしのところにきてくださるとは、なんという光栄でしょう。"}, "44": {"en": "For behold, when the voice of your greeting came into my ears, the baby leaped in my womb for joy!", "zh": "因為你問安的聲音一入我耳，我腹裏的胎就歡喜跳動。", "ja": "ごらんなさい。あなたのあいさつの声がわたしの耳にはいったとき、子供が胎内で喜びおどりました。"}, "45": {"en": "Blessed is she who believed, for there will be a fulfillment of the things which have been spoken to her from the Lord!”", "zh": "這相信的女子是有福的！因為主對她所說的話都要應驗。」", "ja": "主のお語りになったことが必ず成就すると信じた女は、なんとさいわいなことでしょう」。"}, "46": {"en": "Mary said, “My soul magnifies the Lord.", "zh": "馬利亞說： 我心尊主為大；", "ja": "するとマリヤは言った、「わたしの魂は主をあがめ、"}, "47": {"en": "My spirit has rejoiced in God my Savior,", "zh": "我靈以上帝我的救主為樂；", "ja": "わたしの霊は救主なる神をたたえます。"}, "48": {"en": "for he has looked at the humble state of his servant. For behold, from now on, all generations will call me blessed.", "zh": "因為他顧念他使女的卑微； 從今以後， 萬代要稱我有福。", "ja": "この卑しい女をさえ、心にかけてくださいました。今からのち代々の人々は、わたしをさいわいな女と言うでしょう、"}, "49": {"en": "For he who is mighty has done great things for me. Holy is his name.", "zh": "那有權能的，為我成就了大事； 他的名為聖。", "ja": "力あるかたが、わたしに大きな事をしてくださったからです。そのみ名はきよく、"}, "50": {"en": "His mercy is for generations and generations on those who fear him.", "zh": "他憐憫敬畏他的人， 直到世世代代。", "ja": "そのあわれみは、代々限りなく主をかしこみ恐れる者に及びます。"}, "51": {"en": "He has shown strength with his arm. He has scattered the proud in the imagination of their hearts.", "zh": "他用膀臂施展大能； 那狂傲的人正心裏妄想就被他趕散了。", "ja": "主はみ腕をもって力をふるい、心の思いのおごり高ぶる者を追い散らし、"}, "52": {"en": "He has put down princes from their thrones, and has exalted the lowly.", "zh": "他叫有權柄的失位， 叫卑賤的升高；", "ja": "権力ある者を王座から引きおろし、卑しい者を引き上げ、"}, "53": {"en": "He has filled the hungry with good things. He has sent the rich away empty.", "zh": "叫飢餓的得飽美食， 叫富足的空手回去。", "ja": "飢えている者を良いもので飽かせ、富んでいる者を空腹のまま帰らせなさいます。"}, "54": {"en": "He has given help to Israel, his servant, that he might remember mercy,", "zh": "他扶助了他的僕人以色列，", "ja": "主は、あわれみをお忘れにならず、その僕イスラエルを助けてくださいました、"}, "55": {"en": "as he spoke to our fathers, to Abraham and his offspring forever.”", "zh": "為要記念亞伯拉罕和他的後裔， 施憐憫直到永遠， 正如從前對我們列祖所說的話。", "ja": "わたしたちの父祖アブラハムとその子孫とをとこしえにあわれむと約束なさったとおりに」。"}, "56": {"en": "Mary stayed with her about three months, and then returned to her house.", "zh": "馬利亞和伊利莎白同住，約有三個月，就回家去了。", "ja": "マリヤは、エリサベツのところに三か月ほど滞在してから、家に帰った。"}, "57": {"en": "Now the time that Elizabeth should give birth was fulfilled, and she gave birth to a son.", "zh": "伊利莎白的產期到了，就生了一個兒子。", "ja": "さてエリサベツは月が満ちて、男の子を産んだ。"}, "58": {"en": "Her neighbors and her relatives heard that the Lord had magnified his mercy toward her, and they rejoiced with her.", "zh": "鄰里親族聽見主向她大施憐憫，就和她一同歡樂。", "ja": "近所の人々や親族は、主が大きなあわれみを彼女におかけになったことを聞いて、共どもに喜んだ。"}, "59": {"en": "On the eighth day, they came to circumcise the child; and they would have called him Zacharias, after the name of his father.", "zh": "到了第八日，他們來要給孩子行割禮，並要照他父親的名字叫他撒迦利亞。", "ja": "八日目になったので、幼な子に割礼をするために人々がきて、父の名にちなんでザカリヤという名にしようとした。"}, "60": {"en": "His mother answered, “Not so; but he will be called John.”", "zh": "他母親說：「不可！要叫他約翰。」", "ja": "ところが、母親は、「いいえ、ヨハネという名にしなくてはいけません」と言った。"}, "61": {"en": "They said to her, “There is no one among your relatives who is called by this name.”", "zh": "他們說：「你親族中沒有叫這名字的。」", "ja": "人々は、「あなたの親族の中には、そういう名のついた者は、ひとりもいません」と彼女に言った。"}, "62": {"en": "They made signs to his father, what he would have him called.", "zh": "他們就向他父親打手式，問他要叫這孩子甚麼名字。", "ja": "そして父親に、どんな名にしたいのですかと、合図で尋ねた。"}, "63": {"en": "He asked for a writing tablet, and wrote, “His name is John.”", "zh": "他要了一塊寫字的板，就寫上，說：「他的名字是約翰。」他們便都希奇。", "ja": "ザカリヤは書板を持ってこさせて、それに「その名はヨハネ」と書いたので、みんなの者は不思議に思った。"}, "64": {"en": "They all marveled.   His mouth was opened immediately and his tongue freed, and he spoke, blessing God.", "zh": "撒迦利亞的口立時開了，舌頭也舒展了，就說出話來，稱頌上帝。", "ja": "すると、立ちどころにザカリヤの口が開けて舌がゆるみ、語り出して神をほめたたえた。"}, "65": {"en": "Fear came on all who lived around them, and all these sayings were talked about throughout all the hill country of Judea.", "zh": "周圍居住的人都懼怕；這一切的事就傳遍了猶太的山地。", "ja": "近所の人々はみな恐れをいだき、またユダヤの山里の至るところに、これらの事がことごとく語り伝えられたので、"}, "66": {"en": "All who heard them laid them up in their heart, saying, “What then will this child be?” The hand of the Lord was with him.", "zh": "凡聽見的人都將這事放在心裏，說：「這個孩子將來怎麼樣呢？因為有主與他同在。」", "ja": "聞く者たちは皆それを心に留めて、「この子は、いったい、どんな者になるだろう」と語り合った。主のみ手が彼と共にあった。"}, "67": {"en": "His father Zacharias was filled with the Holy Spirit, and prophesied, saying,", "zh": "他父親撒迦利亞被聖靈充滿了，就預言說：", "ja": "父ザカリヤは聖霊に満たされ、預言して言った、"}, "68": {"en": "“Blessed be the Lord, the God of Israel, for he has visited and redeemed his people;", "zh": "主－以色列的上帝是應當稱頌的！ 因他眷顧他的百姓，為他們施行救贖，", "ja": "「主なるイスラエルの神は、ほむべきかな。神はその民を顧みてこれをあがない、"}, "69": {"en": "and has raised up a horn of salvation for us in the house of his servant David", "zh": "在他僕人大衛家中， 為我們興起了拯救的角，", "ja": "わたしたちのために救の角を僕ダビデの家にお立てになった。"}, "70": {"en": "(as he spoke by the mouth of his holy prophets who have been from of old),", "zh": "正如主藉着從創世以來聖先知的口所說的話，", "ja": "古くから、聖なる預言者たちの口によってお語りになったように、"}, "71": {"en": "salvation from our enemies and from the hand of all who hate us;", "zh": "拯救我們脫離仇敵 和一切恨我們之人的手，", "ja": "わたしたちを敵から、またすべてわたしたちを憎む者の手から、救い出すためである。"}, "72": {"en": "to show mercy toward our fathers, to remember his holy covenant,", "zh": "向我們列祖施憐憫， 記念他的聖約－", "ja": "こうして、神はわたしたちの父祖たちにあわれみをかけ、その聖なる契約、"}, "73": {"en": "the oath which he swore to Abraham our father,", "zh": "就是他對我們祖宗亞伯拉罕所起的誓－", "ja": "すなわち、父祖アブラハムにお立てになった誓いをおぼえて、"}, "74": {"en": "to grant to us that we, being delivered out of the hand of our enemies, should serve him without fear,", "zh": "叫我們既從仇敵手中被救出來，", "ja": "わたしたちを敵の手から救い出し、"}, "75": {"en": "in holiness and righteousness before him all the days of our life.", "zh": "就可以終身在他面前， 坦然無懼地用聖潔、公義事奉他。", "ja": "生きている限り、きよく正しく、みまえに恐れなく仕えさせてくださるのである。"}, "76": {"en": "And you, child, will be called a prophet of the Most High; for you will go before the face of the Lord to prepare his ways,", "zh": "孩子啊！你要稱為至高者的先知； 因為你要行在主的前面， 預備他的道路，", "ja": "幼な子よ、あなたは、いと高き者の預言者と呼ばれるであろう。主のみまえに先立って行き、その道を備え、"}, "77": {"en": "to give knowledge of salvation to his people by the remission of their sins,", "zh": "叫他的百姓因罪得赦， 就知道救恩。", "ja": "罪のゆるしによる救をその民に知らせるのであるから。"}, "78": {"en": "because of the tender mercy of our God, by which the dawn from on high will visit us,", "zh": "因我們上帝憐憫的心腸， 叫清晨的日光從高天臨到我們，", "ja": "これはわたしたちの神のあわれみ深いみこころによる。また、そのあわれみによって、日の光が上からわたしたちに臨み、"}, "79": {"en": "to shine on those who sit in darkness and the shadow of death; to guide our feet into the way of peace.”", "zh": "要照亮坐在黑暗中死蔭裏的人， 把我們的腳引到平安的路上。", "ja": "暗黒と死の陰とに住む者を照し、わたしたちの足を平和の道へ導くであろう」。"}, "80": {"en": "The child was growing and becoming strong in spirit, and was in the desert until the day of his public appearance to Israel.", "zh": "那孩子漸漸長大，心靈強健，住在曠野，直到他顯明在以色列人面前的日子。", "ja": "幼な子は成長し、その霊も強くなり、そしてイスラエルに現れる日まで、荒野にいた。"}}}, "2": {"verses": {"1": {"en": "Now in those days, a decree went out from Caesar Augustus that all the world should be enrolled.", "zh": "當那些日子，凱撒奧古斯都有旨意下來，叫天下人民都報名上冊。", "ja": "そのころ、全世界の人口調査をせよとの勅令が、皇帝アウグストから出た。"}, "2": {"en": "This was the first enrollment made when Quirinius was governor of Syria.", "zh": "這是居里扭作敘利亞巡撫的時候，頭一次行報名上冊的事。", "ja": "これは、クレニオがシリヤの総督であった時に行われた最初の人口調査であった。"}, "3": {"en": "All went to enroll themselves, everyone to his own city.", "zh": "眾人各歸各城，報名上冊。", "ja": "人々はみな登録をするために、それぞれ自分の町へ帰って行った。"}, "4": {"en": "Joseph also went up from Galilee, out of the city of Nazareth, into Judea, to David’s city, which is called Bethlehem, because he was of the house and family of David,", "zh": "約瑟也從加利利的拿撒勒城上猶太去，到了大衛的城，名叫伯利恆，因他本是大衛一族一家的人，", "ja": "ヨセフもダビデの家系であり、またその血統であったので、ガリラヤの町ナザレを出て、ユダヤのベツレヘムというダビデの町へ上って行った。"}, "5": {"en": "to enroll himself with Mary, who was pledged to be married to him as wife, being pregnant.", "zh": "要和他所聘之妻馬利亞一同報名上冊。那時馬利亞的身孕已經重了。", "ja": "それは、すでに身重になっていたいいなづけの妻マリヤと共に、登録をするためであった。"}, "6": {"en": "While they were there, the day had come for her to give birth.", "zh": "他們在那裏的時候，馬利亞的產期到了，", "ja": "ところが、彼らがベツレヘムに滞在している間に、マリヤは月が満ちて、"}, "7": {"en": "She gave birth to her firstborn son. She wrapped him in bands of cloth and laid him in a feeding trough, because there was no room for them in the inn.", "zh": "就生了頭胎的兒子，用布包起來，放在馬槽裏，因為客店裏沒有地方。", "ja": "初子を産み、布にくるんで、飼葉おけの中に寝かせた。客間には彼らのいる余地がなかったからである。"}, "8": {"en": "There were shepherds in the same country staying in the field, and keeping watch by night over their flock.", "zh": "在伯利恆之野地裏有牧羊的人，夜間按着更次看守羊群。", "ja": "さて、この地方で羊飼たちが夜、野宿しながら羊の群れの番をしていた。"}, "9": {"en": "Behold, an angel of the Lord stood by them, and the glory of the Lord shone around them, and they were terrified.", "zh": "有主的使者站在他們旁邊，主的榮光四面照着他們；牧羊的人就甚懼怕。", "ja": "すると主の御使が現れ、主の栄光が彼らをめぐり照したので、彼らは非常に恐れた。"}, "10": {"en": "The angel said to them, “Don’t be afraid, for behold, I bring you good news of great joy which will be to all the people.", "zh": "那天使對他們說：「不要懼怕！我報給你們大喜的信息，是關乎萬民的；", "ja": "御使は言った、「恐れるな。見よ、すべての民に与えられる大きな喜びを、あなたがたに伝える。"}, "11": {"en": "For there is born to you today, in David’s city, a Savior, who is Christ the Lord.", "zh": "因今天在大衛的城裏，為你們生了救主，就是主基督。", "ja": "きょうダビデの町に、あなたがたのために救主がお生れになった。このかたこそ主なるキリストである。"}, "12": {"en": "This is the sign to you: you will find a baby wrapped in strips of cloth, lying in a feeding trough.”", "zh": "你們要看見一個嬰孩，包着布，臥在馬槽裏，那就是記號了。」", "ja": "あなたがたは、幼な子が布にくるまって飼葉おけの中に寝かしてあるのを見るであろう。それが、あなたがたに与えられるしるしである」。"}, "13": {"en": "Suddenly, there was with the angel a multitude of the heavenly army praising God and saying,", "zh": "忽然，有一大隊天兵同那天使讚美上帝說：", "ja": "するとたちまち、おびただしい天の軍勢が現れ、御使と一緒になって神をさんびして言った、"}, "14": {"en": "“Glory to God in the highest, on earth peace, good will toward men.”", "zh": "在至高之處榮耀歸與上帝！ 在地上平安歸與他所喜悅的人 ！", "ja": "「いと高きところでは、神に栄光があるように、地の上では、み心にかなう人々に平和があるように」。"}, "15": {"en": "When the angels went away from them into the sky, the shepherds said to one another, “Let’s go to Bethlehem, now, and see this thing that has happened, which the Lord has made known to us.”", "zh": "眾天使離開他們，升天去了。牧羊的人彼此說：「我們往伯利恆去，看看所成的事，就是主所指示我們的。」", "ja": "御使たちが彼らを離れて天に帰ったとき、羊飼たちは「さあ、ベツレヘムへ行って、主がお知らせ下さったその出来事を見てこようではないか」と、互に語り合った。"}, "16": {"en": "They came with haste and found both Mary and Joseph, and the baby was lying in the feeding trough.", "zh": "他們急忙去了，就尋見馬利亞和約瑟，又有那嬰孩臥在馬槽裏；", "ja": "そして急いで行って、マリヤとヨセフ、また飼葉おけに寝かしてある幼な子を捜しあてた。"}, "17": {"en": "When they saw it, they publicized widely the saying which was spoken to them about this child.", "zh": "既然看見，就把天使論這孩子的話傳開了。", "ja": "彼らに会った上で、この子について自分たちに告げ知らされた事を、人々に伝えた。"}, "18": {"en": "All who heard it wondered at the things which were spoken to them by the shepherds.", "zh": "凡聽見的，就詫異牧羊之人對他們所說的話。", "ja": "人々はみな、羊飼たちが話してくれたことを聞いて、不思議に思った。"}, "19": {"en": "But Mary kept all these sayings, pondering them in her heart.", "zh": "馬利亞卻把這一切的事存在心裏，反覆思想。", "ja": "しかし、マリヤはこれらの事をことごとく心に留めて、思いめぐらしていた。"}, "20": {"en": "The shepherds returned, glorifying and praising God for all the things that they had heard and seen, just as it was told them.", "zh": "牧羊的人回去了，因所聽見所看見的一切事，正如天使向他們所說的，就歸榮耀與上帝，讚美他。", "ja": "羊飼たちは、見聞きしたことが何もかも自分たちに語られたとおりであったので、神をあがめ、またさんびしながら帰って行った。"}, "21": {"en": "When eight days were fulfilled for the circumcision of the child, his name was called Jesus, which was given by the angel before he was conceived in the womb.", "zh": "滿了八天，就給孩子行割禮，與他起名叫耶穌；這就是沒有成胎以前，天使所起的名。", "ja": "八日が過ぎ、割礼をほどこす時となったので、受胎のまえに御使が告げたとおり、幼な子をイエスと名づけた。"}, "22": {"en": "When the days of their purification according to the law of Moses were fulfilled, they brought him up to Jerusalem to present him to the Lord", "zh": "按摩西律法滿了潔淨的日子，他們帶着孩子上耶路撒冷去，要把他獻與主，（", "ja": "それから、モーセの律法による彼らのきよめの期間が過ぎたとき、両親は幼な子を連れてエルサレムへ上った。"}, "23": {"en": "(as it is written in the law of the Lord, “Every male who opens the womb shall be called holy to the Lord”),", "zh": "正如主的律法上所記：「凡頭生的男子必稱聖歸主。」）", "ja": "それは主の律法に「母の胎を初めて開く男の子はみな、主に聖別された者と、となえられねばならない」と書いてあるとおり、幼な子を主にささげるためであり、"}, "24": {"en": "and to offer a sacrifice according to that which is said in the law of the Lord, “A pair of turtledoves, or two young pigeons.”", "zh": "又要照主的律法上所說，或用一對斑鳩，或用兩隻雛鴿獻祭。", "ja": "また同じ主の律法に、「山ばと一つがい、または、家ばとのひな二羽」と定めてあるのに従って、犠牲をささげるためであった。"}, "25": {"en": "Behold, there was a man in Jerusalem whose name was Simeon. This man was righteous and devout, looking for the consolation of Israel, and the Holy Spirit was on him.", "zh": "在耶路撒冷有一個人，名叫西面；這人又公義又虔誠，素常盼望以色列的安慰者來到，又有聖靈在他身上。", "ja": "その時、エルサレムにシメオンという名の人がいた。この人は正しい信仰深い人で、イスラエルの慰められるのを待ち望んでいた。また聖霊が彼に宿っていた。"}, "26": {"en": "It had been revealed to him by the Holy Spirit that he should not see death before he had seen the Lord’s Christ.", "zh": "他得了聖靈的啟示，知道自己未死以前，必看見主所立的基督。", "ja": "そして主のつかわす救主に会うまでは死ぬことはないと、聖霊の示しを受けていた。"}, "27": {"en": "He came in the Spirit into the temple. When the parents brought in the child, Jesus, that they might do concerning him according to the custom of the law,", "zh": "他受了聖靈的感動，進入聖殿，正遇見耶穌的父母抱着孩子進來，要照律法的規矩辦理。", "ja": "この人が御霊に感じて宮にはいった。すると律法に定めてあることを行うため、両親もその子イエスを連れてはいってきたので、"}, "28": {"en": "then he received him into his arms and blessed God, and said,", "zh": "西面就用手接過他來，稱頌上帝說：", "ja": "シメオンは幼な子を腕に抱き、神をほめたたえて言った、"}, "29": {"en": "“Now you are releasing your servant, Master, according to your word, in peace;", "zh": "主啊！如今可以照你的話， 釋放僕人安然去世；", "ja": "「主よ、今こそ、あなたはみ言葉のとおりにこの僕を安らかに去らせてくださいます、"}, "30": {"en": "for my eyes have seen your salvation,", "zh": "因為我的眼睛已經看見你的救恩－", "ja": "わたしの目が今あなたの救を見たのですから。"}, "31": {"en": "which you have prepared before the face of all peoples;", "zh": "就是你在萬民面前所預備的：", "ja": "この救はあなたが万民のまえにお備えになったもので、"}, "32": {"en": "a light for revelation to the nations, and the glory of your people Israel.”", "zh": "是照亮外邦人的光， 又是你民以色列的榮耀。", "ja": "異邦人を照す啓示の光、み民イスラエルの栄光であります」。"}, "33": {"en": "Joseph and his mother were marveling at the things which were spoken concerning him.", "zh": "孩子的父母因這論耶穌的話就希奇。   34-", "ja": "父と母とは幼な子についてこのように語られたことを、不思議に思った。"}, "34": {"en": "Simeon blessed them, and said to Mary, his mother, “Behold, this child is appointed for the falling and the rising of many in Israel, and for a sign which is spoken against.", "zh": "", "ja": "するとシメオンは彼らを祝し、そして母マリヤに言った、「ごらんなさい、この幼な子は、イスラエルの多くの人を倒れさせたり立ちあがらせたりするために、また反対を受けるしるしとして、定められています。――"}, "35": {"en": "Yes, a sword will pierce through your own soul, that the thoughts of many hearts may be revealed.”", "zh": "西面給他們祝福，又對孩子的母親馬利亞說：「這孩子被立，是要叫以色列中許多人跌倒，許多人興起；又要作毀謗的話柄，叫許多人心裏的意念顯露出來；你自己的心也要被刀刺透。」", "ja": "そして、あなた自身もつるぎで胸を刺し貫かれるでしょう。――それは多くの人の心にある思いが、現れるようになるためです」。"}, "36": {"en": "There was one Anna, a prophetess, the daughter of Phanuel, of the tribe of Asher (she was of a great age, having lived with a husband seven years from her virginity,", "zh": "又有女先知，名叫亞拿，是亞設支派法內力的女兒，年紀已經老邁，從作童女出嫁的時候，同丈夫住了七年就寡居了，", "ja": "また、アセル族のパヌエルの娘で、アンナという女預言者がいた。彼女は非常に年をとっていた。むすめ時代にとついで、七年間だけ夫と共に住み、"}, "37": {"en": "and she had been a widow for about eighty-four years), who didn’t depart from the temple, worshiping with fastings and petitions night and day.", "zh": "現在已經八十四歲，並不離開聖殿，禁食祈求，晝夜事奉上帝。", "ja": "その後やもめぐらしをし、八十四歳になっていた。そして宮を離れずに夜も昼も断食と祈とをもって神に仕えていた。"}, "38": {"en": "Coming up at that very hour, she gave thanks to the Lord, and spoke of him to all those who were looking for redemption in Jerusalem.", "zh": "正當那時，她進前來稱謝上帝，將孩子的事對一切盼望耶路撒冷得救贖的人講說。", "ja": "この老女も、ちょうどそのとき近寄ってきて、神に感謝をささげ、そしてこの幼な子のことを、エルサレムの救を待ち望んでいるすべての人々に語りきかせた。"}, "39": {"en": "When they had accomplished all things that were according to the law of the Lord, they returned into Galilee, to their own city, Nazareth.", "zh": "約瑟和馬利亞照主的律法辦完了一切的事，就回加利利，到自己的城拿撒勒去了。", "ja": "両親は主の律法どおりすべての事をすませたので、ガリラヤへむかい、自分の町ナザレに帰った。"}, "40": {"en": "The child was growing, and was becoming strong in spirit, being filled with wisdom, and the grace of God was upon him.", "zh": "孩子漸漸長大，強健起來，充滿智慧，又有上帝的恩在他身上。", "ja": "幼な子は、ますます成長して強くなり、知恵に満ち、そして神の恵みがその上にあった。"}, "41": {"en": "His parents went every year to Jerusalem at the feast of the Passover.", "zh": "每年到逾越節，他父母就上耶路撒冷去。", "ja": "さて、イエスの両親は、過越の祭には毎年エルサレムへ上っていた。"}, "42": {"en": "When he was twelve years old, they went up to Jerusalem according to the custom of the feast;", "zh": "當他十二歲的時候，他們按着節期的規矩上去。", "ja": "イエスが十二歳になった時も、慣例に従って祭のために上京した。"}, "43": {"en": "and when they had fulfilled the days, as they were returning, the boy Jesus stayed behind in Jerusalem. Joseph and his mother didn’t know it,", "zh": "守滿了節期，他們回去，孩童耶穌仍舊在耶路撒冷。他的父母並不知道，", "ja": "ところが、祭が終って帰るとき、少年イエスはエルサレムに居残っておられたが、両親はそれに気づかなかった。"}, "44": {"en": "but supposing him to be in the company, they went a day’s journey; and they looked for him among their relatives and acquaintances.", "zh": "以為他在同行的人中間，走了一天的路程，就在親族和熟識的人中找他，", "ja": "そして道連れの中にいることと思いこんで、一日路を行ってしまい、それから、親族や知人の中を捜しはじめたが、"}, "45": {"en": "When they didn’t find him, they returned to Jerusalem, looking for him.", "zh": "既找不着，就回耶路撒冷去找他。", "ja": "見つからないので、捜しまわりながらエルサレムへ引返した。"}, "46": {"en": "After three days they found him in the temple, sitting in the middle of the teachers, both listening to them and asking them questions.", "zh": "過了三天，就遇見他在殿裏，坐在教師中間，一面聽，一面問。", "ja": "そして三日の後に、イエスが宮の中で教師たちのまん中にすわって、彼らの話を聞いたり質問したりしておられるのを見つけた。"}, "47": {"en": "All who heard him were amazed at his understanding and his answers.", "zh": "凡聽見他的，都希奇他的聰明和他的應對。", "ja": "聞く人々はみな、イエスの賢さやその答に驚嘆していた。"}, "48": {"en": "When they saw him, they were astonished; and his mother said to him, “Son, why have you treated us this way? Behold, your father and I were anxiously looking for you.”", "zh": "他父母看見就很希奇。他母親對他說：「我兒！為甚麼向我們這樣行呢？看哪，你父親和我傷心來找你！」", "ja": "両親はこれを見て驚き、そして母が彼に言った、「どうしてこんな事をしてくれたのです。ごらんなさい、おとう様もわたしも心配して、あなたを捜していたのです」。"}, "49": {"en": "He said to them, “Why were you looking for me? Didn’t you know that I must be in my Father’s house?”", "zh": "耶穌說：「為甚麼找我呢？豈不知我應當以我父的事為念嗎 ？」", "ja": "するとイエスは言われた、「どうしてお捜しになったのですか。わたしが自分の父の家にいるはずのことを、ご存じなかったのですか」。"}, "50": {"en": "They didn’t understand the saying which he spoke to them.", "zh": "他所說的這話，他們不明白。", "ja": "しかし、両親はその語られた言葉を悟ることができなかった。"}, "51": {"en": "And he went down with them and came to Nazareth. He was subject to them, and his mother kept all these sayings in her heart.", "zh": "他就同他們下去，回到拿撒勒，並且順從他們。他母親把這一切的事都存在心裏。", "ja": "それからイエスは両親と一緒にナザレに下って行き、彼らにお仕えになった。母はこれらの事をみな心に留めていた。"}, "52": {"en": "And Jesus increased in wisdom and stature, and in favor with God and men.", "zh": "耶穌的智慧和身量，並上帝和人喜愛他的心，都一齊增長。", "ja": "イエスはますます知恵が加わり、背たけも伸び、そして神と人から愛された。"}}}, "3": {"verses": {"1": {"en": "Now in the fifteenth year of the reign of Tiberius Caesar, Pontius Pilate being governor of Judea, and Herod being tetrarch of Galilee, and his brother Philip tetrarch of the region of Ituraea and Trachonitis, and Lysanias tetrarch of Abilene,", "zh": "凱撒提庇留在位第十五年，本丟‧彼拉多作猶太巡撫，希律作加利利分封的王，他兄弟腓力作以土利亞和特拉可尼地方分封的王，呂撒聶作亞比利尼分封的王，", "ja": "皇帝テベリオ在位の第十五年、ポンテオ・ピラトがユダヤの総督、ヘロデがガリラヤの領主、その兄弟ピリポがイツリヤ・テラコニテ地方の領主、ルサニヤがアビレネの領主、"}, "2": {"en": "during the high priesthood of Annas and Caiaphas, the word of God came to John, the son of Zacharias, in the wilderness.", "zh": "亞那和該亞法作大祭司。那時，撒迦利亞的兒子約翰在曠野裏，上帝的話臨到他。", "ja": "アンナスとカヤパとが大祭司であったとき、神の言が荒野でザカリヤの子ヨハネに臨んだ。"}, "3": {"en": "He came into all the region around the Jordan, preaching the baptism of repentance for remission of sins.", "zh": "他就來到約旦河一帶地方，宣講悔改的洗禮，使罪得赦。", "ja": "彼はヨルダンのほとりの全地方に行って、罪のゆるしを得させる悔改めのバプテスマを宣べ伝えた。"}, "4": {"en": "As it is written in the book of the words of Isaiah the prophet, “The voice of one crying in the wilderness, ‘Make ready the way of the Lord. Make his paths straight.", "zh": "正如先知以賽亞書上所記的話，說： 在曠野有人聲喊着說： 預備主的道， 修直他的路！", "ja": "それは、預言者イザヤの言葉の書に書いてあるとおりである。すなわち「荒野で呼ばわる者の声がする、『主の道を備えよ、その道筋をまっすぐにせよ』。"}, "5": {"en": "Every valley will be filled. Every mountain and hill will be brought low. The crooked will become straight, and the rough ways smooth.", "zh": "一切山窪都要填滿； 大小山岡都要削平！ 彎彎曲曲的地方要改為正直； 高高低低的道路要改為平坦！", "ja": "すべての谷は埋められ、すべての山と丘とは、平らにされ、曲ったところはまっすぐに、わるい道はならされ、"}, "6": {"en": "All flesh will see God’s salvation.’ ”", "zh": "凡有血氣的，都要見上帝的救恩！", "ja": "人はみな神の救を見るであろう」。"}, "7": {"en": "He said therefore to the multitudes who went out to be baptized by him, “You offspring of vipers, who warned you to flee from the wrath to come?", "zh": "約翰對那出來要受他洗的眾人說：「毒蛇的種類！誰指示你們逃避將來的忿怒呢？", "ja": "さて、ヨハネは、彼からバプテスマを受けようとして出てきた群衆にむかって言った、「まむしの子らよ、迫ってきている神の怒りから、のがれられると、おまえたちにだれが教えたのか。"}, "8": {"en": "Therefore produce fruits worthy of repentance, and don’t begin to say among yourselves, ‘We have Abraham for our father;’ for I tell you that God is able to raise up children to Abraham from these stones!", "zh": "你們要結出果子來，與悔改的心相稱。不要自己心裏說：『有亞伯拉罕為我們的祖宗。』我告訴你們，上帝能從這些石頭中，給亞伯拉罕興起子孫來。", "ja": "だから、悔改めにふさわしい実を結べ。自分たちの父にはアブラハムがあるなどと、心の中で思ってもみるな。おまえたちに言っておく。神はこれらの石ころからでも、アブラハムの子を起すことができるのだ。"}, "9": {"en": "Even now the ax also lies at the root of the trees. Every tree therefore that doesn’t produce good fruit is cut down and thrown into the fire.”", "zh": "現在斧子已經放在樹根上，凡不結好果子的樹就砍下來，丟在火裏。」", "ja": "斧がすでに木の根もとに置かれている。だから、良い実を結ばない木はことごとく切られて、火の中に投げ込まれるのだ」。"}, "10": {"en": "The multitudes asked him, “What then must we do?”", "zh": "眾人問他說：「這樣，我們當做甚麼呢？」", "ja": "そこで群衆が彼に、「それでは、わたしたちは何をすればよいのですか」と尋ねた。"}, "11": {"en": "He answered them, “He who has two coats, let him give to him who has none. He who has food, let him do likewise.”", "zh": "約翰回答說：「有兩件衣裳的，就分給那沒有的；有食物的，也當這樣行。」", "ja": "彼は答えて言った、「下着を二枚もっている者は、持たない者に分けてやりなさい。食物を持っている者も同様にしなさい」。"}, "12": {"en": "Tax collectors also came to be baptized, and they said to him, “Teacher, what must we do?”", "zh": "又有稅吏來要受洗，問他說：「夫子，我們當做甚麼呢？」", "ja": "取税人もバプテスマを受けにきて、彼に言った、「先生、わたしたちは何をすればよいのですか」。"}, "13": {"en": "He said to them, “Collect no more than that which is appointed to you.”", "zh": "約翰說：「除了例定的數目，不要多取。」", "ja": "彼らに言った、「きまっているもの以上に取り立ててはいけない」。"}, "14": {"en": "Soldiers also asked him, saying, “What about us? What must we do?” He said to them, “Extort from no one by violence, neither accuse anyone wrongfully. Be content with your wages.”", "zh": "又有兵丁問他說：「我們當做甚麼呢？」約翰說：「不要以強暴待人，也不要訛詐人，自己有錢糧就當知足。」", "ja": "兵卒たちもたずねて言った、「では、わたしたちは何をすればよいのですか」。彼は言った、「人をおどかしたり、だまし取ったりしてはいけない。自分の給与で満足していなさい」。"}, "15": {"en": "As the people were in expectation, and all men reasoned in their hearts concerning John, whether perhaps he was the Christ,", "zh": "百姓指望基督來的時候，人都心裏猜疑，或者約翰是基督。", "ja": "民衆は救主を待ち望んでいたので、みな心の中でヨハネのことを、もしかしたらこの人がそれではなかろうかと考えていた。"}, "16": {"en": "John answered them all, “I indeed baptize you with water, but he comes who is mightier than I, the strap of whose sandals I am not worthy to loosen. He will baptize you in the Holy Spirit and fire.", "zh": "約翰說：「我是用水給你們施洗，但有一位能力比我更大的要來，我就是給他解鞋帶也不配。他要用聖靈與火給你們施洗。", "ja": "そこでヨハネはみんなの者にむかって言った、「わたしは水でおまえたちにバプテスマを授けるが、わたしよりも力のあるかたが、おいでになる。わたしには、そのくつのひもを解く値うちもない。このかたは、聖霊と火とによっておまえたちにバプテスマをお授けになるであろう。"}, "17": {"en": "His winnowing fan is in his hand, and he will thoroughly cleanse his threshing floor, and will gather the wheat into his barn; but he will burn up the chaff with unquenchable fire.”", "zh": "他手裏拿着簸箕，要揚淨他的場，把麥子收在倉裏，把糠用不滅的火燒盡了。」", "ja": "また、箕を手に持って、打ち場の麦をふるい分け、麦は倉に納め、からは消えない火で焼き捨てるであろう」。"}, "18": {"en": "Then with many other exhortations he preached good news to the people,", "zh": "約翰又用許多別的話勸百姓，向他們傳福音。", "ja": "こうしてヨハネはほかにもなお、さまざまの勧めをして、民衆に教を説いた。"}, "19": {"en": "but Herod the tetrarch, being reproved by him for Herodias, his brother’s wife, and for all the evil things which Herod had done,", "zh": "只是分封的王希律，因他兄弟之妻希羅底的緣故，並因他所行的一切惡事，受了約翰的責備；", "ja": "ところが領主ヘロデは、兄弟の妻ヘロデヤのことで、また自分がしたあらゆる悪事について、ヨハネから非難されていたので、"}, "20": {"en": "added this also to them all, that he shut up John in prison.", "zh": "又另外添了一件，就是把約翰收在監裏。", "ja": "彼を獄に閉じ込めて、いろいろな悪事の上に、もう一つこの悪事を重ねた。"}, "21": {"en": "Now when all the people were baptized, Jesus also had been baptized and was praying. The sky was opened,", "zh": "眾百姓都受了洗，耶穌也受了洗。正禱告的時候，天就開了，", "ja": "さて、民衆がみなバプテスマを受けたとき、イエスもバプテスマを受けて祈っておられると、天が開けて、"}, "22": {"en": "and the Holy Spirit descended in a bodily form like a dove on him; and a voice came out of the sky, saying “You are my beloved Son. In you I am well pleased.”", "zh": "聖靈降臨在他身上，形狀彷彿鴿子；又有聲音從天上來，說：「你是我的愛子，我喜悅你。」", "ja": "聖霊がはとのような姿をとってイエスの上に下り、そして天から声がした、「あなたはわたしの愛する子、わたしの心にかなう者である」。"}, "23": {"en": "Jesus himself, when he began to teach, was about thirty years old, being the son (as was supposed) of Joseph, the son of Heli,", "zh": "耶穌開頭傳道，年紀約有三十歲。依人看來，他是約瑟的兒子；約瑟是希里的兒子；", "ja": "イエスが宣教をはじめられたのは、年およそ三十歳の時であって、人々の考えによれば、ヨセフの子であった。ヨセフはヘリの子、"}, "24": {"en": "the son of Matthat, the son of Levi, the son of Melchi, the son of Jannai, the son of Joseph,", "zh": "希里是瑪塔的兒子；瑪塔是利未的兒子；利未是麥基的兒子；麥基是雅拿的兒子；雅拿是約瑟的兒子；", "ja": "それから、さかのぼって、マタテ、レビ、メルキ、ヤンナイ、ヨセフ、"}, "25": {"en": "the son of Mattathias, the son of Amos, the son of Nahum, the son of Esli, the son of Naggai,", "zh": "約瑟是瑪他提亞的兒子；瑪他提亞是亞摩斯的兒子；亞摩斯是拿鴻的兒子；拿鴻是以斯利的兒子；以斯利是拿該的兒子；", "ja": "マタテヤ、アモス、ナホム、エスリ、ナンガイ、"}, "26": {"en": "the son of Maath, the son of Mattathias, the son of Semein, the son of Joseph, the son of Judah,", "zh": "拿該是瑪押的兒子；瑪押是瑪他提亞的兒子；瑪他提亞是西美的兒子；西美是約瑟的兒子；約瑟是猶大的兒子；猶大是約亞拿的兒子；", "ja": "マハテ、マタテヤ、シメイ、ヨセク、ヨダ、"}, "27": {"en": "the son of Joanan, the son of Rhesa, the son of Zerubbabel, the son of Shealtiel, the son of Neri,", "zh": "約亞拿是利撒的兒子；利撒是所羅巴伯的兒子；所羅巴伯是撒拉鐵的兒子；撒拉鐵是尼利的兒子；尼利是麥基的兒子；", "ja": "ヨハナン、レサ、ゾロバベル、サラテル、ネリ、"}, "28": {"en": "the son of Melchi, the son of Addi, the son of Cosam, the son of Elmodam, the son of Er,", "zh": "麥基是亞底的兒子；亞底是哥桑的兒子；哥桑是以摩當的兒子；以摩當是珥的兒子；珥是約細的兒子；", "ja": "メルキ、アデイ、コサム、エルマダム、エル、"}, "29": {"en": "the son of Jose, the son of Eliezer, the son of Jorim, the son of Matthat, the son of Levi,", "zh": "約細是以利以謝的兒子；以利以謝是約令的兒子；約令是瑪塔的兒子；瑪塔是利未的兒子；", "ja": "ヨシュア、エリエゼル、ヨリム、マタテ、レビ、"}, "30": {"en": "the son of Simeon, the son of Judah, the son of Joseph, the son of Jonan, the son of Eliakim,", "zh": "利未是西緬的兒子；西緬是猶大的兒子；猶大是約瑟的兒子；約瑟是約南的兒子；約南是以利亞敬的兒子；", "ja": "シメオン、ユダ、ヨセフ、ヨナム、エリヤキム、"}, "31": {"en": "the son of Melea, the son of Menan, the son of Mattatha, the son of Nathan, the son of David,", "zh": "以利亞敬是米利亞的兒子；米利亞是買南的兒子；買南是瑪達他的兒子；瑪達他是拿單的兒子；拿單是大衛的兒子；", "ja": "メレヤ、メナ、マタタ、ナタン、ダビデ、"}, "32": {"en": "the son of Jesse, the son of Obed, the son of Boaz, the son of Salmon, the son of Nahshon,", "zh": "大衛是耶西的兒子；耶西是俄備得的兒子；俄備得是波阿斯的兒子；波阿斯是撒門的兒子；撒門是拿順的兒子；", "ja": "エッサイ、オベデ、ボアズ、サラ、ナアソン、"}, "33": {"en": "the son of Amminadab, the son of Aram, the son of Hezron, the son of Perez, the son of Judah,", "zh": "拿順是亞米拿達的兒子；亞米拿達是亞蘭的兒子；亞蘭是希斯崙的兒子；希斯崙是法勒斯的兒子；法勒斯是猶大的兒子；", "ja": "アミナダブ、アデミン、アルニ、エスロン、パレス、ユダ、"}, "34": {"en": "the son of Jacob, the son of Isaac, the son of Abraham, the son of Terah, the son of Nahor,", "zh": "猶大是雅各的兒子；雅各是以撒的兒子；以撒是亞伯拉罕的兒子；亞伯拉罕是他拉的兒子；他拉是拿鶴的兒子；", "ja": "ヤコブ、イサク、アブラハム、テラ、ナホル、"}, "35": {"en": "the son of Serug, the son of Reu, the son of Peleg, the son of Eber, the son of Shelah,", "zh": "拿鶴是西鹿的兒子；西鹿是拉吳的兒子；拉吳是法勒的兒子；法勒是希伯的兒子；希伯是沙拉的兒子；", "ja": "セルグ、レウ、ペレグ、エベル、サラ、"}, "36": {"en": "the son of Cainan, the son of Arphaxad, the son of Shem, the son of Noah, the son of Lamech,", "zh": "沙拉是該南的兒子；該南是亞法撒的兒子；亞法撒是閃的兒子；閃是挪亞的兒子；挪亞是拉麥的兒子；", "ja": "カイナン、アルパクサデ、セム、ノア、ラメク、"}, "37": {"en": "the son of Methuselah, the son of Enoch, the son of Jared, the son of Mahalaleel, the son of Cainan,", "zh": "拉麥是瑪土撒拉的兒子；瑪土撒拉是以諾的兒子；以諾是雅列的兒子；雅列是瑪勒列的兒子；瑪勒列是該南的兒子；該南是以挪士的兒子；", "ja": "メトセラ、エノク、ヤレデ、マハラレル、カイナン、"}, "38": {"en": "the son of Enos, the son of Seth, the son of Adam, the son of God.", "zh": "以挪士是塞特的兒子；塞特是亞當的兒子；亞當是上帝的兒子。", "ja": "エノス、セツ、アダム、そして神にいたる。"}}}, "4": {"verses": {"1": {"en": "Jesus, full of the Holy Spirit, returned from the Jordan and was led by the Spirit into the wilderness", "zh": "耶穌被聖靈充滿，從約旦河回來，聖靈將他引到曠野，", "ja": "さて、イエスは聖霊に満ちてヨルダン川から帰り、"}, "2": {"en": "for forty days, being tempted by the devil. He ate nothing in those days. Afterward, when they were completed, he was hungry.", "zh": "四十天受魔鬼的試探。那些日子沒有吃甚麼；日子滿了，他就餓了。", "ja": "荒野を四十日のあいだ御霊にひきまわされて、悪魔の試みにあわれた。そのあいだ何も食べず、その日数がつきると、空腹になられた。"}, "3": {"en": "The devil said to him, “If you are the Son of God, command this stone to become bread.”", "zh": "魔鬼對他說：「你若是上帝的兒子，可以吩咐這塊石頭變成食物。」", "ja": "そこで悪魔が言った、「もしあなたが神の子であるなら、この石に、パンになれと命じてごらんなさい」。"}, "4": {"en": "Jesus answered him, saying, “It is written, ‘Man shall not live by bread alone, but by every word of God.’ ”", "zh": "耶穌回答說：「經上記着說：『人活着不是單靠食物，乃是靠上帝口裏所出的一切話。』」", "ja": "イエスは答えて言われた、「『人はパンだけで生きるものではない』と書いてある」。"}, "5": {"en": "The devil, leading him up on a high mountain, showed him all the kingdoms of the world in a moment of time.", "zh": "魔鬼又領他上了高山，霎時間把天下的萬國都指給他看，", "ja": "それから、悪魔はイエスを高い所へ連れて行き、またたくまに世界のすべての国々を見せて"}, "6": {"en": "The devil said to him, “I will give you all this authority and their glory, for it has been delivered to me, and I give it to whomever I want.", "zh": "對他說：「這一切權柄、榮華，我都要給你，因為這原是交付我的，我願意給誰就給誰。", "ja": "言った、「これらの国々の権威と栄華とをみんな、あなたにあげましょう。それらはわたしに任せられていて、だれでも好きな人にあげてよいのですから。"}, "7": {"en": "If you therefore will worship before me, it will all be yours.”", "zh": "你若在我面前下拜，這都要歸你。」", "ja": "それで、もしあなたがわたしの前にひざまずくなら、これを全部あなたのものにしてあげましょう」。"}, "8": {"en": "Jesus answered him, “Get behind me, Satan! For it is written, ‘You shall worship the Lord your God, and you shall serve him only.’ ”", "zh": "耶穌說：「經上記着說： 當拜主－你的上帝， 單要事奉他。」", "ja": "イエスは答えて言われた、「『主なるあなたの神を拝し、ただ神にのみ仕えよ』と書いてある」。"}, "9": {"en": "He led him to Jerusalem and set him on the pinnacle of the temple, and said to him, “If you are the Son of God, cast yourself down from here,", "zh": "魔鬼又領他到耶路撒冷去，叫他站在殿頂上，對他說：「你若是上帝的兒子，可以從這裏跳下去；", "ja": "それから悪魔はイエスをエルサレムに連れて行き、宮の頂上に立たせて言った、「もしあなたが神の子であるなら、ここから下へ飛びおりてごらんなさい。"}, "10": {"en": "for it is written, ‘He will put his angels in charge of you, to guard you;’", "zh": "因為經上記着說： 主要為你吩咐他的使者保護你；", "ja": "『神はあなたのために、御使たちに命じてあなたを守らせるであろう』とあり、"}, "11": {"en": "and, ‘On their hands they will bear you up, lest perhaps you dash your foot against a stone.’ ”", "zh": "他們要用手托着你， 免得你的腳碰在石頭上。」", "ja": "また、『あなたの足が石に打ちつけられないように、彼らはあなたを手でささえるであろう』とも書いてあります」。"}, "12": {"en": "Jesus answering, said to him, “It has been said, ‘You shall not tempt the Lord your God.’ ”", "zh": "耶穌對他說：「經上說：『不可試探主－你的上帝。』」", "ja": "イエスは答えて言われた、「『主なるあなたの神を試みてはならない』と言われている」。"}, "13": {"en": "When the devil had completed every temptation, he departed from him until another time.", "zh": "魔鬼用完了各樣的試探，就暫時離開耶穌。", "ja": "悪魔はあらゆる試みをしつくして、一時イエスを離れた。"}, "14": {"en": "Jesus returned in the power of the Spirit into Galilee, and news about him spread through all the surrounding area.", "zh": "耶穌滿有聖靈的能力，回到加利利；他的名聲就傳遍了四方。", "ja": "それからイエスは御霊の力に満ちあふれてガリラヤへ帰られると、そのうわさがその地方全体にひろまった。"}, "15": {"en": "He taught in their synagogues, being glorified by all.", "zh": "他在各會堂裏教訓人，眾人都稱讚他。", "ja": "イエスは諸会堂で教え、みんなの者から尊敬をお受けになった。"}, "16": {"en": "He came to Nazareth, where he had been brought up. He entered, as was his custom, into the synagogue on the Sabbath day, and stood up to read.", "zh": "耶穌來到拿撒勒，就是他長大的地方。在安息日，照他平常的規矩進了會堂，站起來要念聖經。", "ja": "それからお育ちになったナザレに行き、安息日にいつものように会堂にはいり、聖書を朗読しようとして立たれた。"}, "17": {"en": "The book of the prophet Isaiah was handed to him. He opened the book, and found the place where it was written,", "zh": "有人把先知以賽亞的書交給他，他就打開，找到一處寫着說：", "ja": "すると預言者イザヤの書が手渡されたので、その書を開いて、こう書いてある所を出された、"}, "18": {"en": "“The Spirit of the Lord is on me, because he has anointed me to preach good news to the poor. He has sent me to heal the broken hearted, to proclaim release to the captives, recovering of sight to the blind, to deliver those who are crushed,", "zh": "主的靈在我身上， 因為他用膏膏我， 叫我傳福音給貧窮的人； 差遣我報告： 被擄的得釋放， 瞎眼的得看見， 叫那受壓制的得自由，", "ja": "「主の御霊がわたしに宿っている。貧しい人々に福音を宣べ伝えさせるために、わたしを聖別してくださったからである。主はわたしをつかわして、囚人が解放され、盲人の目が開かれることを告げ知らせ、打ちひしがれている者に自由を得させ、"}, "19": {"en": "and to proclaim the acceptable year of the Lord.”", "zh": "報告上帝悅納人的禧年。", "ja": "主のめぐみの年を告げ知らせるのである」。"}, "20": {"en": "He closed the book, gave it back to the attendant, and sat down. The eyes of all in the synagogue were fastened on him.", "zh": "於是把書捲起來，交還執事，就坐下。會堂裏的人都定睛看他。", "ja": "イエスは聖書を巻いて係りの者に返し、席に着かれると、会堂にいるみんなの者の目がイエスに注がれた。"}, "21": {"en": "He began to tell them, “Today, this Scripture has been fulfilled in your hearing.”", "zh": "耶穌對他們說：「今天這經應驗在你們耳中了。」", "ja": "そこでイエスは、「この聖句は、あなたがたが耳にしたこの日に成就した」と説きはじめられた。"}, "22": {"en": "All testified about him and wondered at the gracious words which proceeded out of his mouth; and they said, “Isn’t this Joseph’s son?”", "zh": "眾人都稱讚他，並希奇他口中所出的恩言；又說：「這不是約瑟的兒子嗎？」", "ja": "すると、彼らはみなイエスをほめ、またその口から出て来るめぐみの言葉に感嘆して言った、「この人はヨセフの子ではないか」。"}, "23": {"en": "He said to them, “Doubtless you will tell me this proverb, ‘Physician, heal yourself! Whatever we have heard done at Capernaum, do also here in your hometown.’ ”", "zh": "耶穌對他們說：「你們必引這俗語向我說：『醫生，你醫治自己吧！我們聽見你在迦百農所行的事，也當行在你自己家鄉裏』」；", "ja": "そこで彼らに言われた、「あなたがたは、きっと『医者よ、自分自身をいやせ』ということわざを引いて、カペナウムで行われたと聞いていた事を、あなたの郷里のこの地でもしてくれ、と言うであろう」。"}, "24": {"en": "He said, “Most certainly I tell you, no prophet is acceptable in his hometown.", "zh": "又說：「我實在告訴你們，沒有先知在自己家鄉被人悅納的。", "ja": "それから言われた、「よく言っておく。預言者は、自分の郷里では歓迎されないものである。"}, "25": {"en": "But truly I tell you, there were many widows in Israel in the days of Elijah, when the sky was shut up three years and six months, when a great famine came over all the land.", "zh": "我對你們說實話，當以利亞的時候，天閉塞了三年零六個月，遍地有大饑荒，那時，以色列中有許多寡婦，", "ja": "よく聞いておきなさい。エリヤの時代に、三年六か月にわたって天が閉じ、イスラエル全土に大ききんがあった際、そこには多くのやもめがいたのに、"}, "26": {"en": "Elijah was sent to none of them, except to Zarephath, in the land of Sidon, to a woman who was a widow.", "zh": "以利亞並沒有奉差往她們一個人那裏去，只奉差往西頓的撒勒法一個寡婦那裏去。", "ja": "エリヤはそのうちのだれにもつかわされないで、ただシドンのサレプタにいるひとりのやもめにだけつかわされた。"}, "27": {"en": "There were many lepers in Israel in the time of Elisha the prophet, yet not one of them was cleansed, except Naaman, the Syrian.”", "zh": "先知以利沙的時候，以色列中有許多長大痲瘋的，但內中除了敘利亞國的乃縵，沒有一個得潔淨的。」", "ja": "また預言者エリシャの時代に、イスラエルには多くのらい病人がいたのに、そのうちのひとりもきよめられないで、ただシリヤのナアマンだけがきよめられた」。"}, "28": {"en": "They were all filled with wrath in the synagogue as they heard these things.", "zh": "會堂裏的人聽見這話，都怒氣滿胸，", "ja": "会堂にいた者たちはこれを聞いて、みな憤りに満ち、"}, "29": {"en": "They rose up, threw him out of the city, and led him to the brow of the hill that their city was built on, that they might throw him off the cliff.", "zh": "就起來攆他出城（他們的城造在山上）；他們帶他到山崖，要把他推下去。", "ja": "立ち上がってイエスを町の外へ追い出し、その町が建っている丘のがけまでひっぱって行って、突き落そうとした。"}, "30": {"en": "But he, passing through the middle of them, went his way.", "zh": "他卻從他們中間直行，過去了。", "ja": "しかし、イエスは彼らのまん中を通り抜けて、去って行かれた。"}, "31": {"en": "He came down to Capernaum, a city of Galilee. He was teaching them on the Sabbath day,", "zh": "耶穌下到迦百農，就是加利利的一座城，在安息日教訓眾人。", "ja": "それから、イエスはガリラヤの町カペナウムに下って行かれた。そして安息日になると、人々をお教えになったが、"}, "32": {"en": "and they were astonished at his teaching, for his word was with authority.", "zh": "他們很希奇他的教訓，因為他的話裏有權柄。", "ja": "その言葉に権威があったので、彼らはその教に驚いた。"}, "33": {"en": "In the synagogue there was a man who had a spirit of an unclean demon; and he cried out with a loud voice,", "zh": "在會堂裏有一個人，被污鬼的精氣附着，大聲喊叫說：", "ja": "すると、汚れた悪霊につかれた人が会堂にいて、大声で叫び出した、"}, "34": {"en": "saying, “Ah! what have we to do with you, Jesus of Nazareth? Have you come to destroy us? I know who you are: the Holy One of God!”", "zh": "「唉！拿撒勒的耶穌，我們與你有甚麼相干？你來滅我們嗎？我知道你是誰，乃是上帝的聖者。」", "ja": "「ああ、ナザレのイエスよ、あなたはわたしたちとなんの係わりがあるのです。わたしたちを滅ぼしにこられたのですか。あなたがどなたであるか、わかっています。神の聖者です」。"}, "35": {"en": "Jesus rebuked him, saying, “Be silent and come out of him!”  When the demon had thrown him down in the middle of them, he came out of him, having done him no harm.", "zh": "耶穌責備他說：「不要作聲，從這人身上出來吧！」鬼把那人摔倒在眾人中間，就出來了，卻也沒有害他。", "ja": "イエスはこれをしかって、「黙れ、この人から出て行け」と言われた。すると悪霊は彼を人なかに投げ倒し、傷は負わせずに、その人から出て行った。"}, "36": {"en": "Amazement came on all and they spoke together, one with another, saying, “What is this word? For with authority and power he commands the unclean spirits, and they come out!”", "zh": "眾人都驚訝，彼此對問說：「這是甚麼道理呢？因為他用權柄能力吩咐污鬼，污鬼就出來。」", "ja": "みんなの者は驚いて、互に語り合って言った、「これは、いったい、なんという言葉だろう。権威と力とをもって汚れた霊に命じられると、彼らは出て行くのだ」。"}, "37": {"en": "News about him went out into every place of the surrounding region.", "zh": "於是耶穌的名聲傳遍了周圍地方。", "ja": "こうしてイエスの評判が、その地方のいたる所にひろまっていった。"}, "38": {"en": "He rose up from the synagogue and entered into Simon’s house. Simon’s mother-in-law was afflicted with a great fever, and they begged him to help her.", "zh": "耶穌出了會堂，進了西門的家。西門的岳母害熱病甚重，有人為她求耶穌。", "ja": "イエスは会堂を出てシモンの家におはいりになった。ところがシモンのしゅうとめが高い熱を病んでいたので、人々は彼女のためにイエスにお願いした。"}, "39": {"en": "He stood over her and rebuked the fever, and it left her. Immediately she rose up and served them.", "zh": "耶穌站在她旁邊，斥責那熱病，熱就退了。她立刻起來服事他們。", "ja": "そこで、イエスはそのまくらもとに立って、熱が引くように命じられると、熱は引き、女はすぐに起き上がって、彼らをもてなした。"}, "40": {"en": "When the sun was setting, all those who had any sick with various diseases brought them to him; and he laid his hands on every one of them, and healed them.", "zh": "日落的時候，凡有病人的，不論害甚麼病，都帶到耶穌那裏。耶穌按手在他們各人身上，醫好他們。", "ja": "日が暮れると、いろいろな病気になやむ者をかかえている人々が、皆それをイエスのところに連れてきたので、そのひとりびとりに手を置いて、おいやしになった。"}, "41": {"en": "Demons also came out of many, crying out and saying, “You are the Christ, the Son of God!” Rebuking them, he didn’t allow them to speak, because they knew that he was the Christ.", "zh": "又有鬼從好些人身上出來，喊着說：「你是上帝的兒子。」耶穌斥責他們，不許他們說話，因為他們知道他是基督。", "ja": "悪霊も「あなたこそ神の子です」と叫びながら多くの人々から出ていった。しかし、イエスは彼らを戒めて、物を言うことをお許しにならなかった。彼らがイエスはキリストだと知っていたからである。"}, "42": {"en": "When it was day, he departed and went into an uninhabited place and the multitudes looked for him, and came to him, and held on to him, so that he wouldn’t go away from them.", "zh": "天亮的時候，耶穌出來，走到曠野地方。眾人去找他，到了他那裏，要留住他，不要他離開他們。", "ja": "夜が明けると、イエスは寂しい所へ出て行かれたが、群衆が捜しまわって、みもとに集まり、自分たちから離れて行かれないようにと、引き止めた。"}, "43": {"en": "But he said to them, “I must preach the good news of God’s Kingdom to the other cities also. For this reason I have been sent.”", "zh": "但耶穌對他們說：「我也必須在別城傳上帝國的福音，因我奉差原是為此。」", "ja": "しかしイエスは、「わたしは、ほかの町々にも神の国の福音を宣べ伝えねばならない。自分はそのためにつかわされたのである」と言われた。"}, "44": {"en": "He was preaching in the synagogues of Galilee.", "zh": "於是耶穌在加利利的各會堂傳道。", "ja": "そして、ユダヤの諸会堂で教を説かれた。"}}}, "5": {"verses": {"1": {"en": "Now while the multitude pressed on him and heard the word of God, he was standing by the lake of Gennesaret.", "zh": "耶穌站在革尼撒勒湖邊，眾人擁擠他，要聽上帝的道。", "ja": "さて、群衆が神の言を聞こうとして押し寄せてきたとき、イエスはゲネサレ湖畔に立っておられたが、"}, "2": {"en": "He saw two boats standing by the lake, but the fishermen had gone out of them and were washing their nets.", "zh": "他見有兩隻船灣在湖邊；打魚的人卻離開船洗網去了。", "ja": "そこに二そうの小舟が寄せてあるのをごらんになった。漁師たちは、舟からおりて網を洗っていた。"}, "3": {"en": "He entered into one of the boats, which was Simon’s, and asked him to put out a little from the land. He sat down and taught the multitudes from the boat.", "zh": "有一隻船是西門的，耶穌就上去，請他把船撐開，稍微離岸，就坐下，從船上教訓眾人。", "ja": "その一そうはシモンの舟であったが、イエスはそれに乗り込み、シモンに頼んで岸から少しこぎ出させ、そしてすわって、舟の中から群衆にお教えになった。"}, "4": {"en": "When he had finished speaking, he said to Simon, “Put out into the deep and let down your nets for a catch.”", "zh": "講完了，對西門說：「把船開到水深之處，下網打魚。」", "ja": "話がすむと、シモンに「沖へこぎ出し、網をおろして漁をしてみなさい」と言われた。"}, "5": {"en": "Simon answered him, “Master, we worked all night and caught nothing; but at your word I will let down the net.”", "zh": "西門說：「夫子，我們整夜勞力，並沒有打着甚麼。但依從你的話，我就下網。」", "ja": "シモンは答えて言った、「先生、わたしたちは夜通し働きましたが、何も取れませんでした。しかし、お言葉ですから、網をおろしてみましょう」。"}, "6": {"en": "When they had done this, they caught a great multitude of fish, and their net was breaking.", "zh": "他們下了網，就圈住許多魚，網險些裂開，", "ja": "そしてそのとおりにしたところ、おびただしい魚の群れがはいって、網が破れそうになった。"}, "7": {"en": "They beckoned to their partners in the other boat, that they should come and help them. They came and filled both boats, so that they began to sink.", "zh": "便招呼那隻船上的同伴來幫助。他們就來，把魚裝滿了兩隻船，甚至船要沉下去。", "ja": "そこで、もう一そうの舟にいた仲間に、加勢に来るよう合図をしたので、彼らがきて魚を両方の舟いっぱいに入れた。そのために、舟が沈みそうになった。"}, "8": {"en": "But Simon Peter, when he saw it, fell down at Jesus’ knees, saying, “Depart from me, for I am a sinful man, Lord.”", "zh": "西門‧彼得看見，就俯伏在耶穌膝前，說：「主啊，離開我，我是個罪人！」", "ja": "これを見てシモン・ペテロは、イエスのひざもとにひれ伏して言った、「主よ、わたしから離れてください。わたしは罪深い者です」。"}, "9": {"en": "For he was amazed, and all who were with him, at the catch of fish which they had caught;", "zh": "他和一切同在的人都驚訝這一網所打的魚。", "ja": "彼も一緒にいた者たちもみな、取れた魚がおびただしいのに驚いたからである。"}, "10": {"en": "and so also were James and John, sons of Zebedee, who were partners with Simon. Jesus said to Simon, “Don’t be afraid. From now on you will be catching people alive.”", "zh": "他的夥伴西庇太的兒子雅各、約翰，也是這樣。耶穌對西門說：「不要怕！從今以後，你要得人了。」", "ja": "シモンの仲間であったゼベダイの子ヤコブとヨハネも、同様であった。すると、イエスがシモンに言われた、「恐れることはない。今からあなたは人間をとる漁師になるのだ」。"}, "11": {"en": "When they had brought their boats to land, they left everything, and followed him.", "zh": "他們把兩隻船攏了岸，就撇下所有的，跟從了耶穌。", "ja": "そこで彼らは舟を陸に引き上げ、いっさいを捨ててイエスに従った。"}, "12": {"en": "While he was in one of the cities, behold, there was a man full of leprosy. When he saw Jesus, he fell on his face and begged him, saying, “Lord, if you want to, you can make me clean.”", "zh": "有一回，耶穌在一個城裏，有人滿身長了大痲瘋，看見他，就俯伏在地，求他說：「主若肯，必能叫我潔淨了。」", "ja": "イエスがある町におられた時、全身らい病になっている人がそこにいた。イエスを見ると、顔を地に伏せて願って言った、「主よ、みこころでしたら、きよめていただけるのですが」。"}, "13": {"en": "He stretched out his hand and touched him, saying, “I want to. Be made clean.”", "zh": "耶穌伸手摸他，說：「我肯，你潔淨了吧！」大痲瘋立刻就離了他的身。", "ja": "イエスは手を伸ばして彼にさわり、「そうしてあげよう、きよくなれ」と言われた。すると、らい病がただちに去ってしまった。"}, "14": {"en": "Immediately the leprosy left him.   He commanded him to tell no one, “But go your way and show yourself to the priest, and offer for your cleansing according to what Moses commanded, for a testimony to them.”", "zh": "耶穌囑咐他：「你切不可告訴人，只要去把身體給祭司察看，又要為你得了潔淨，照摩西所吩咐的獻上禮物，對眾人作證據。」", "ja": "イエスは、だれにも話さないようにと彼に言い聞かせ、「ただ行って自分のからだを祭司に見せ、それからあなたのきよめのため、モーセが命じたとおりのささげ物をして、人々に証明しなさい」とお命じになった。"}, "15": {"en": "But the report concerning him spread much more, and great multitudes came together to hear and to be healed by him of their infirmities.", "zh": "但耶穌的名聲越發傳揚出去。有極多的人聚集來聽道，也指望醫治他們的病。", "ja": "しかし、イエスの評判はますますひろまって行き、おびただしい群衆が、教を聞いたり、病気をなおしてもらったりするために、集まってきた。"}, "16": {"en": "But he withdrew himself into the desert and prayed.", "zh": "耶穌卻退到曠野去禱告。", "ja": "しかしイエスは、寂しい所に退いて祈っておられた。"}, "17": {"en": "On one of those days, he was teaching; and there were Pharisees and teachers of the law sitting by who had come out of every village of Galilee, Judea, and Jerusalem. The power of the Lord was with him to heal them.", "zh": "有一天，耶穌教訓人，有法利賽人和教法師在旁邊坐着；他們是從加利利各鄉村和猶太並耶路撒冷來的。主的能力與耶穌同在，使他能醫治病人。", "ja": "ある日のこと、イエスが教えておられると、ガリラヤやユダヤの方々の村から、またエルサレムからきたパリサイ人や律法学者たちが、そこにすわっていた。主の力が働いて、イエスは人々をいやされた。"}, "18": {"en": "Behold, men brought a paralyzed man on a cot, and they sought to bring him in to lay before Jesus.", "zh": "有人用褥子抬着一個癱子，要抬進去放在耶穌面前，", "ja": "その時、ある人々が、ひとりの中風をわずらっている人を床にのせたまま連れてきて、家の中に運び入れ、イエスの前に置こうとした。"}, "19": {"en": "Not finding a way to bring him in because of the multitude, they went up to the housetop and let him down through the tiles with his cot into the middle before Jesus.", "zh": "卻因人多，尋不出法子抬進去，就上了房頂，從瓦間把他連褥子縋到當中，正在耶穌面前。", "ja": "ところが、群衆のためにどうしても運び入れる方法がなかったので、屋根にのぼり、瓦をはいで、病人を床ごと群衆のまん中につりおろして、イエスの前においた。"}, "20": {"en": "Seeing their faith, he said to him, “Man, your sins are forgiven you.”", "zh": "耶穌見他們的信心，就對癱子說：「你的罪赦了。」", "ja": "イエスは彼らの信仰を見て、「人よ、あなたの罪はゆるされた」と言われた。"}, "21": {"en": "The scribes and the Pharisees began to reason, saying, “Who is this who speaks blasphemies? Who can forgive sins, but God alone?”", "zh": "文士和法利賽人就議論說：「這說僭妄話的是誰？除了上帝以外，誰能赦罪呢？」", "ja": "すると律法学者とパリサイ人たちとは、「神を汚すことを言うこの人は、いったい、何者だ。神おひとりのほかに、だれが罪をゆるすことができるか」と言って論じはじめた。"}, "22": {"en": "But Jesus, perceiving their thoughts, answered them, “Why are you reasoning so in your hearts?", "zh": "耶穌知道他們所議論的，就說：「你們心裏議論的是甚麼呢？", "ja": "イエスは彼らの論議を見ぬいて、「あなたがたは心の中で何を論じているのか。"}, "23": {"en": "Which is easier to say, ‘Your sins are forgiven you,’ or to say, ‘Arise and walk’?", "zh": "或說『你的罪赦了』，或說『你起來行走』，哪一樣容易呢？", "ja": "あなたの罪はゆるされたと言うのと、起きて歩けと言うのと、どちらがたやすいか。"}, "24": {"en": "But that you may know that the Son of Man has authority on earth to forgive sins,” he said to the paralyzed man, “I tell you, arise, take up your cot, and go to your house.”", "zh": "但要叫你們知道，人子在地上有赦罪的權柄。」就對癱子說：「我吩咐你，起來，拿你的褥子回家去吧！」", "ja": "しかし、人の子は地上で罪をゆるす権威を持っていることが、あなたがたにわかるために」と彼らに対して言い、中風の者にむかって、「あなたに命じる。起きよ、床を取り上げて家に帰れ」と言われた。"}, "25": {"en": "Immediately he rose up before them, and took up that which he was laying on, and departed to his house, glorifying God.", "zh": "那人當眾人面前立刻起來，拿着他所躺臥的褥子回家去，歸榮耀與上帝。", "ja": "すると病人は即座にみんなの前で起きあがり、寝ていた床を取りあげて、神をあがめながら家に帰って行った。"}, "26": {"en": "Amazement took hold on all, and they glorified God. They were filled with fear, saying, “We have seen strange things today.”", "zh": "眾人都驚奇，也歸榮耀與上帝，並且滿心懼怕，說：「我們今日看見非常的事了。」", "ja": "みんなの者は驚嘆してしまった。そして神をあがめ、おそれに満たされて、「きょうは驚くべきことを見た」と言った。"}, "27": {"en": "After these things he went out and saw a tax collector named Levi sitting at the tax office, and said to him, “Follow me!”", "zh": "這事以後，耶穌出去，看見一個稅吏，名叫利未，坐在稅關上，就對他說：「你跟從我來。」", "ja": "そののち、イエスが出て行かれると、レビという名の取税人が収税所にすわっているのを見て、「わたしに従ってきなさい」と言われた。"}, "28": {"en": "He left everything, and rose up and followed him.", "zh": "他就撇下所有的，起來，跟從了耶穌。", "ja": "すると、彼はいっさいを捨てて立ちあがり、イエスに従ってきた。"}, "29": {"en": "Levi made a great feast for him in his house. There was a great crowd of tax collectors and others who were reclining with them.", "zh": "利未在自己家裏為耶穌大擺筵席，有許多稅吏和別人與他們一同坐席。", "ja": "それから、レビは自分の家で、イエスのために盛大な宴会を催したが、取税人やそのほか大ぜいの人々が、共に食卓に着いていた。"}, "30": {"en": "Their scribes and the Pharisees murmured against his disciples, saying, “Why do you eat and drink with the tax collectors and sinners?”", "zh": "法利賽人和文士就向耶穌的門徒發怨言說：「你們為甚麼和稅吏並罪人一同吃喝呢？」", "ja": "ところが、パリサイ人やその律法学者たちが、イエスの弟子たちに対してつぶやいて言った、「どうしてあなたがたは、取税人や罪人などと飲食を共にするのか」。"}, "31": {"en": "Jesus answered them, “Those who are healthy have no need for a physician, but those who are sick do.", "zh": "耶穌對他們說：「無病的人用不着醫生；有病的人才用得着。", "ja": "イエスは答えて言われた、「健康な人には医者はいらない。いるのは病人である。"}, "32": {"en": "I have not come to call the righteous, but sinners, to repentance.”", "zh": "我來本不是召義人悔改，乃是召罪人悔改。」", "ja": "わたしがきたのは、義人を招くためではなく、罪人を招いて悔い改めさせるためである」。"}, "33": {"en": "They said to him, “Why do John’s disciples often fast and pray, likewise also the disciples of the Pharisees, but yours eat and drink?”", "zh": "他們說：「約翰的門徒屢次禁食祈禱，法利賽人的門徒也是這樣；惟獨你的門徒又吃又喝。」", "ja": "また彼らはイエスに言った、「ヨハネの弟子たちは、しばしば断食をし、また祈をしており、パリサイ人の弟子たちもそうしているのに、あなたの弟子たちは食べたり飲んだりしています」。"}, "34": {"en": "He said to them, “Can you make the friends of the bridegroom fast while the bridegroom is with them?", "zh": "耶穌對他們說：「新郎和陪伴之人同在的時候，豈能叫陪伴之人禁食呢？", "ja": "するとイエスは言われた、「あなたがたは、花婿が一緒にいるのに、婚礼の客に断食をさせることができるであろうか。"}, "35": {"en": "But the days will come when the bridegroom will be taken away from them. Then they will fast in those days.”", "zh": "但日子將到，新郎要離開他們，那日他們就要禁食了。」", "ja": "しかし、花婿が奪い去られる日が来る。その日には断食をするであろう」。"}, "36": {"en": "He also told a parable to them. “No one puts a piece from a new garment on an old garment, or else he will tear the new, and also the piece from the new will not match the old.", "zh": "耶穌又設一個比喻，對他們說：「沒有人把新衣服撕下一塊來補在舊衣服上；若是這樣，就把新的撕破了，並且所撕下來的那塊新的和舊的也不相稱。", "ja": "それからイエスはまた一つの譬を語られた、「だれも、新しい着物から布ぎれを切り取って、古い着物につぎを当てるものはない。もしそんなことをしたら、新しい着物を裂くことになるし、新しいのから取った布ぎれも古いのに合わないであろう。"}, "37": {"en": "No one puts new wine into old wineskins, or else the new wine will burst the skins, and it will be spilled and the skins will be destroyed.", "zh": "也沒有人把新酒裝在舊皮袋裏；若是這樣，新酒必將皮袋裂開，酒便漏出來，皮袋也就壞了。", "ja": "まただれも、新しいぶどう酒を古い皮袋に入れはしない。もしそんなことをしたら、新しいぶどう酒は皮袋をはり裂き、そしてぶどう酒は流れ出るし、皮袋もむだになるであろう。"}, "38": {"en": "But new wine must be put into fresh wineskins, and both are preserved.", "zh": "但新酒必須裝在新皮袋裏。", "ja": "新しいぶどう酒は新しい皮袋に入れるべきである。"}, "39": {"en": "No man having drunk old wine immediately desires new, for he says, ‘The old is better.’ ”", "zh": "沒有人喝了陳酒又想喝新的；他總說陳的好。」", "ja": "まただれも、古い酒を飲んでから、新しいのをほしがりはしない。『古いのが良い』と考えているからである」。"}}}, "6": {"verses": {"1": {"en": "Now on the second Sabbath after the first, he was going through the grain fields. His disciples plucked the heads of grain and ate, rubbing them in their hands.", "zh": "有一個安息日，耶穌從麥地經過。他的門徒掐了麥穗，用手搓着吃。", "ja": "ある安息日にイエスが麦畑の中をとおって行かれたとき、弟子たちが穂をつみ、手でもみながら食べていた。"}, "2": {"en": "But some of the Pharisees said to them, “Why do you do that which is not lawful to do on the Sabbath day?”", "zh": "有幾個法利賽人說：「你們為甚麼做安息日不可做的事呢？」", "ja": "すると、あるパリサイ人たちが言った、「あなたがたはなぜ、安息日にしてはならぬことをするのか」。"}, "3": {"en": "Jesus, answering them, said, “Haven’t you read what David did when he was hungry, he and those who were with him,", "zh": "耶穌對他們說：「經上記着大衛和跟從他的人飢餓之時所做的事，連這個你們也沒有念過嗎？", "ja": "そこでイエスが答えて言われた、「あなたがたは、ダビデとその供の者たちとが飢えていたとき、ダビデのしたことについて、読んだことがないのか。"}, "4": {"en": "how he entered into God’s house, and took and ate the show bread, and gave also to those who were with him, which is not lawful to eat except for the priests alone?”", "zh": "他怎麼進了上帝的殿，拿陳設餅吃，又給跟從的人吃？這餅除了祭司以外，別人都不可吃。」", "ja": "すなわち、神の家にはいって、祭司たちのほかだれも食べてはならぬ供えのパンを取って食べ、また供の者たちにも与えたではないか」。"}, "5": {"en": "He said to them, “The Son of Man is lord of the Sabbath.”", "zh": "又對他們說：「人子是安息日的主。」", "ja": "また彼らに言われた、「人の子は安息日の主である」。"}, "6": {"en": "It also happened on another Sabbath that he entered into the synagogue and taught. There was a man there, and his right hand was withered.", "zh": "又有一個安息日，耶穌進了會堂教訓人，在那裏有一個人右手枯乾了。", "ja": "また、ほかの安息日に会堂にはいって教えておられたところ、そこに右手のなえた人がいた。"}, "7": {"en": "The scribes and the Pharisees watched him, to see whether he would heal on the Sabbath, that they might find an accusation against him.", "zh": "文士和法利賽人窺探耶穌，在安息日治病不治病，要得把柄去告他。", "ja": "律法学者やパリサイ人たちは、イエスを訴える口実を見付けようと思って、安息日にいやされるかどうかをうかがっていた。"}, "8": {"en": "But he knew their thoughts; and he said to the man who had the withered hand, “Rise up and stand in the middle.” He arose and stood.", "zh": "耶穌卻知道他們的意念，就對那枯乾一隻手的人說：「起來！站在當中。」那人就起來，站着。", "ja": "イエスは彼らの思っていることを知って、その手のなえた人に、「起きて、まん中に立ちなさい」と言われると、起き上がって立った。"}, "9": {"en": "Then Jesus said to them, “I will ask you something: Is it lawful on the Sabbath to do good, or to do harm? To save a life, or to kill?”", "zh": "耶穌對他們說：「我問你們，在安息日行善行惡，救命害命，哪樣是可以的呢？」", "ja": "そこでイエスは彼らにむかって言われた、「あなたがたに聞くが、安息日に善を行うのと悪を行うのと、命を救うのと殺すのと、どちらがよいか」。"}, "10": {"en": "He looked around at them all, and said to the man, “Stretch out your hand.” He did, and his hand was restored as sound as the other.", "zh": "他就周圍看着他們眾人，對那人說：「伸出手來！」他把手一伸，手就復了原。", "ja": "そして彼ら一同を見まわして、その人に「手を伸ばしなさい」と言われた。そのとおりにすると、その手は元どおりになった。"}, "11": {"en": "But they were filled with rage, and talked with one another about what they might do to Jesus.", "zh": "他們就滿心大怒，彼此商議怎樣處治耶穌。", "ja": "そこで彼らは激しく怒って、イエスをどうかしてやろうと、互に話合いをはじめた。"}, "12": {"en": "In these days, he went out to the mountain to pray, and he continued all night in prayer to God.", "zh": "那時，耶穌出去，上山禱告，整夜禱告上帝；", "ja": "このころ、イエスは祈るために山へ行き、夜を徹して神に祈られた。"}, "13": {"en": "When it was day, he called his disciples, and from them he chose twelve, whom he also named apostles:", "zh": "到了天亮，叫他的門徒來，就從他們中間挑選十二個人，稱他們為使徒。", "ja": "夜が明けると、弟子たちを呼び寄せ、その中から十二人を選び出し、これに使徒という名をお与えになった。"}, "14": {"en": "Simon, whom he also named Peter; Andrew, his brother; James; John; Philip; Bartholomew;", "zh": "這十二個人有西門（耶穌又給他起名叫彼得），還有他兄弟安得烈，又有雅各和約翰，腓力和巴多羅買，", "ja": "すなわち、ペテロとも呼ばれたシモンとその兄弟アンデレ、ヤコブとヨハネ、ピリポとバルトロマイ、"}, "15": {"en": "Matthew; Thomas; James the son of Alphaeus; Simon who was called the Zealot;", "zh": "馬太和多馬，亞勒腓的兒子雅各和奮銳黨的西門，", "ja": "マタイとトマス、アルパヨの子ヤコブと、熱心党と呼ばれたシモン、"}, "16": {"en": "Judas the son of James; and Judas Iscariot, who also became a traitor.", "zh": "雅各的兒子猶大，和賣主的加略人猶大。", "ja": "ヤコブの子ユダ、それからイスカリオテのユダ。このユダが裏切者となったのである。"}, "17": {"en": "He came down with them and stood on a level place, with a crowd of his disciples and a great number of the people from all Judea and Jerusalem and the sea coast of Tyre and Sidon, who came to hear him and to be healed of their diseases,", "zh": "耶穌和他們下了山，站在一塊平地上；同站的有許多門徒，又有許多百姓，從猶太全地和耶路撒冷，並泰爾、西頓的海邊來，都要聽他講道，又指望醫治他們的病；", "ja": "そして、イエスは彼らと一緒に山を下って平地に立たれたが、大ぜいの弟子たちや、ユダヤ全土、エルサレム、ツロとシドンの海岸地方などからの大群衆が、"}, "18": {"en": "as well as those who were troubled by unclean spirits; and they were being healed.", "zh": "還有被污鬼纏磨的，也得了醫治。", "ja": "教を聞こうとし、また病気をなおしてもらおうとして、そこにきていた。そして汚れた霊に悩まされている者たちも、いやされた。"}, "19": {"en": "All the multitude sought to touch him, for power came out of him and healed them all.", "zh": "眾人都想要摸他；因為有能力從他身上發出來，醫好了他們。", "ja": "また群衆はイエスにさわろうと努めた。それは力がイエスの内から出て、みんなの者を次々にいやしたからである。"}, "20": {"en": "He lifted up his eyes to his disciples, and said: “Blessed are you who are poor, for God’s Kingdom is yours.", "zh": "耶穌舉目看着門徒，說： 你們貧窮的人有福了！ 因為上帝的國是你們的。", "ja": "そのとき、イエスは目をあげ、弟子たちを見て言われた、「あなたがた貧しい人たちは、さいわいだ。神の国はあなたがたのものである。"}, "21": {"en": "Blessed are you who hunger now, for you will be filled. Blessed are you who weep now, for you will laugh.", "zh": "你們飢餓的人有福了！ 因為你們將要飽足。 你們哀哭的人有福了！ 因為你們將要喜笑。", "ja": "あなたがたいま飢えている人たちは、さいわいだ。飽き足りるようになるからである。あなたがたいま泣いている人たちは、さいわいだ。笑うようになるからである。"}, "22": {"en": "Blessed are you when men hate you, and when they exclude and mock you, and throw out your name as evil, for the Son of Man’s sake.", "zh": "「人為人子恨惡你們，拒絕你們，辱罵你們，棄掉你們的名，以為是惡，你們就有福了！", "ja": "人々があなたがたを憎むとき、また人の子のためにあなたがたを排斥し、ののしり、汚名を着せるときは、あなたがたはさいわいだ。"}, "23": {"en": "Rejoice in that day and leap for joy, for behold, your reward is great in heaven, for their fathers did the same thing to the prophets.", "zh": "當那日，你們要歡喜跳躍，因為你們在天上的賞賜是大的。他們的祖宗待先知也是這樣。", "ja": "その日には喜びおどれ。見よ、天においてあなたがたの受ける報いは大きいのだから。彼らの祖先も、預言者たちに対して同じことをしたのである。"}, "24": {"en": "“But woe to you who are rich! For you have received your consolation.", "zh": "但你們富足的人有禍了！ 因為你們受過你們的安慰。", "ja": "しかしあなたがた富んでいる人たちは、わざわいだ。慰めを受けてしまっているからである。"}, "25": {"en": "Woe to you, you who are full now, for you will be hungry. Woe to you who laugh now, for you will mourn and weep.", "zh": "你們飽足的人有禍了！ 因為你們將要飢餓。 你們喜笑的人有禍了！ 因為你們將要哀慟哭泣。", "ja": "あなたがた今満腹している人たちは、わざわいだ。飢えるようになるからである。あなたがた今笑っている人たちは、わざわいだ。悲しみ泣くようになるからである。"}, "26": {"en": "Woe, when men speak well of you, for their fathers did the same thing to the false prophets.", "zh": "「人都說你們好的時候，你們就有禍了！因為他們的祖宗待假先知也是這樣。」", "ja": "人が皆あなたがたをほめるときは、あなたがたはわざわいだ。彼らの祖先も、にせ預言者たちに対して同じことをしたのである。"}, "27": {"en": "“But I tell you who hear: love your enemies, do good to those who hate you,", "zh": "「只是我告訴你們這聽道的人，你們的仇敵，要愛他！恨你們的，要待他好！", "ja": "しかし、聞いているあなたがたに言う。敵を愛し、憎む者に親切にせよ。"}, "28": {"en": "bless those who curse you, and pray for those who mistreat you.", "zh": "咒詛你們的，要為他祝福！凌辱你們的，要為他禱告！", "ja": "のろう者を祝福し、はずかしめる者のために祈れ。"}, "29": {"en": "To him who strikes you on the cheek, offer also the other; and from him who takes away your cloak, don’t withhold your coat also.", "zh": "有人打你這邊的臉，連那邊的臉也由他打。有人奪你的外衣，連裏衣也由他拿去。", "ja": "あなたの頬を打つ者にはほかの頬をも向けてやり、あなたの上着を奪い取る者には下着をも拒むな。"}, "30": {"en": "Give to everyone who asks you, and don’t ask him who takes away your goods to give them back again.", "zh": "凡求你的，就給他。有人奪你的東西去，不用再要回來。", "ja": "あなたに求める者には与えてやり、あなたの持ち物を奪う者からは取りもどそうとするな。"}, "31": {"en": "“As you would like people to do to you, do exactly so to them.", "zh": "你們願意人怎樣待你們，你們也要怎樣待人。", "ja": "人々にしてほしいと、あなたがたの望むことを、人々にもそのとおりにせよ。"}, "32": {"en": "“If you love those who love you, what credit is that to you? For even sinners love those who love them.", "zh": "你們若單愛那愛你們的人，有甚麼可酬謝的呢？就是罪人也愛那愛他們的人。", "ja": "自分を愛してくれる者を愛したからとて、どれほどの手柄になろうか。罪人でさえ、自分を愛してくれる者を愛している。"}, "33": {"en": "If you do good to those who do good to you, what credit is that to you? For even sinners do the same.", "zh": "你們若善待那善待你們的人，有甚麼可酬謝的呢？就是罪人也是這樣行。", "ja": "自分によくしてくれる者によくしたとて、どれほどの手柄になろうか。罪人でさえ、それくらいの事はしている。"}, "34": {"en": "If you lend to those from whom you hope to receive, what credit is that to you? Even sinners lend to sinners, to receive back as much.", "zh": "你們若借給人，指望從他收回，有甚麼可酬謝的呢？就是罪人也借給罪人，要如數收回。", "ja": "また返してもらうつもりで貸したとて、どれほどの手柄になろうか。罪人でも、同じだけのものを返してもらおうとして、仲間に貸すのである。"}, "35": {"en": "But love your enemies, and do good, and lend, expecting nothing back; and your reward will be great, and you will be children of the Most High; for he is kind toward the unthankful and evil.", "zh": "你們倒要愛仇敵，也要善待他們，並要借給人不指望償還，你們的賞賜就必大了，你們也必作至高者的兒子，因為他恩待那忘恩的和作惡的。", "ja": "しかし、あなたがたは、敵を愛し、人によくしてやり、また何も当てにしないで貸してやれ。そうすれば受ける報いは大きく、あなたがたはいと高き者の子となるであろう。いと高き者は、恩を知らぬ者にも悪人にも、なさけ深いからである。"}, "36": {"en": "“Therefore be merciful, even as your Father is also merciful.", "zh": "你們要慈悲，像你們的父慈悲一樣。」", "ja": "あなたがたの父なる神が慈悲深いように、あなたがたも慈悲深い者となれ。"}, "37": {"en": "Don’t judge, and you won’t be judged. Don’t condemn, and you won’t be condemned. Set free, and you will be set free.", "zh": "「你們不要論斷人，就不被論斷；你們不要定人的罪，就不被定罪；你們要饒恕人，就必蒙饒恕 ；", "ja": "人をさばくな。そうすれば、自分もさばかれることがないであろう。また人を罪に定めるな。そうすれば、自分も罪に定められることがないであろう。ゆるしてやれ。そうすれば、自分もゆるされるであろう。"}, "38": {"en": "“Give, and it will be given to you: good measure, pressed down, shaken together, and running over, will be given to you. For with the same measure you measure it will be measured back to you.”", "zh": "你們要給人，就必有給你們的，並且用十足的升斗，連搖帶按，上尖下流地倒在你們懷裏；因為你們用甚麼量器量給人，也必用甚麼量器量給你們。」", "ja": "与えよ。そうすれば、自分にも与えられるであろう。人々はおし入れ、ゆすり入れ、あふれ出るまでに量をよくして、あなたがたのふところに入れてくれるであろう。あなたがたの量るその量りで、自分にも量りかえされるであろうから」。"}, "39": {"en": "He spoke a parable to them. “Can the blind guide the blind? Won’t they both fall into a pit?", "zh": "耶穌又用比喻對他們說：「瞎子豈能領瞎子，兩個人不是都要掉在坑裏嗎？", "ja": "イエスはまた一つの譬を語られた、「盲人は盲人の手引ができようか。ふたりとも穴に落ち込まないだろうか。"}, "40": {"en": "A disciple is not above his teacher, but everyone when he is fully trained will be like his teacher.", "zh": "學生不能高過先生；凡學成了的不過和先生一樣。", "ja": "弟子はその師以上のものではないが、修業をつめば、みなその師のようになろう。"}, "41": {"en": "Why do you see the speck of chaff that is in your brother’s eye, but don’t consider the beam that is in your own eye?", "zh": "為甚麼看見你弟兄眼中有刺，卻不想自己眼中有樑木呢？", "ja": "なぜ、兄弟の目にあるちりを見ながら、自分の目にある梁を認めないのか。"}, "42": {"en": "Or how can you tell your brother, ‘Brother, let me remove the speck of chaff that is in your eye,’ when you yourself don’t see the beam that is in your own eye? You hypocrite! First remove the beam from your own eye, and then you can see clearly to remove the speck of chaff that is in your brother’s eye.", "zh": "你不見自己眼中有樑木，怎能對你弟兄說：『容我去掉你眼中的刺』呢？你這假冒為善的人！先去掉自己眼中的樑木，然後才能看得清楚，去掉你弟兄眼中的刺。」", "ja": "自分の目にある梁は見ないでいて、どうして兄弟にむかって、兄弟よ、あなたの目にあるちりを取らせてください、と言えようか。偽善者よ、まず自分の目から梁を取りのけるがよい、そうすれば、はっきり見えるようになって、兄弟の目にあるちりを取りのけることができるだろう。"}, "43": {"en": "“For there is no good tree that produces rotten fruit, nor again a rotten tree that produces good fruit.", "zh": "「因為，沒有好樹結壞果子，也沒有壞樹結好果子。", "ja": "悪い実のなる良い木はないし、また良い実のなる悪い木もない。"}, "44": {"en": "For each tree is known by its own fruit. For people don’t gather figs from thorns, nor do they gather grapes from a bramble bush.", "zh": "凡樹木看果子，就可以認出它來。人不是從荊棘上摘無花果，也不是從蒺藜裏摘葡萄。", "ja": "木はそれぞれ、その実でわかる。いばらからいちじくを取ることはないし、野ばらからぶどうを摘むこともない。"}, "45": {"en": "The good man out of the good treasure of his heart brings out that which is good, and the evil man out of the evil treasure of his heart brings out that which is evil, for out of the abundance of the heart, his mouth speaks.", "zh": "善人從他心裏所存的善就發出善來；惡人從他心裏所存的惡就發出惡來；因為心裏所充滿的，口裏就說出來。」", "ja": "善人は良い心の倉から良い物を取り出し、悪人は悪い倉から悪い物を取り出す。心からあふれ出ることを、口が語るものである。"}, "46": {"en": "“Why do you call me, ‘Lord, Lord,’ and don’t do the things which I say?", "zh": "「你們為甚麼稱呼我『主啊，主啊』卻不遵我的話行呢？", "ja": "わたしを主よ、主よ、と呼びながら、なぜわたしの言うことを行わないのか。"}, "47": {"en": "Everyone who comes to me, and hears my words and does them, I will show you who he is like.", "zh": "凡到我這裏來，聽見我的話就去行的，我要告訴你們他像甚麼人：", "ja": "わたしのもとにきて、わたしの言葉を聞いて行う者が、何に似ているか、あなたがたに教えよう。"}, "48": {"en": "He is like a man building a house, who dug and went deep and laid a foundation on the rock. When a flood arose, the stream broke against that house, and could not shake it, because it was founded on the rock.", "zh": "他像一個人蓋房子，深深地挖地，把根基安在磐石上；到發大水的時候，水沖那房子，房子總不能搖動，因為根基立在磐石上 。", "ja": "それは、地を深く掘り、岩の上に土台をすえて家を建てる人に似ている。洪水が出て激流がその家に押し寄せてきても、それを揺り動かすことはできない。よく建ててあるからである。"}, "49": {"en": "But he who hears and doesn’t do, is like a man who built a house on the earth without a foundation, against which the stream broke, and immediately it fell; and the ruin of that house was great.”", "zh": "惟有聽見不去行的，就像一個人在土地上蓋房子，沒有根基；水一沖，隨即倒塌了，並且那房子壞的很大。」", "ja": "しかし聞いても行わない人は、土台なしで、土の上に家を建てた人に似ている。激流がその家に押し寄せてきたら、たちまち倒れてしまい、その被害は大きいのである」。"}}}, "7": {"verses": {"1": {"en": "After he had finished speaking in the hearing of the people, he entered into Capernaum.", "zh": "耶穌對百姓講完了這一切的話，就進了迦百農。", "ja": "イエスはこれらの言葉をことごとく人々に聞かせてしまったのち、カペナウムに帰ってこられた。"}, "2": {"en": "A certain centurion’s servant, who was dear to him, was sick and at the point of death.", "zh": "有一個百夫長所寶貴的僕人害病，快要死了。", "ja": "ところが、ある百卒長の頼みにしていた僕が、病気になって死にかかっていた。"}, "3": {"en": "When he heard about Jesus, he sent to him elders of the Jews, asking him to come and save his servant.", "zh": "百夫長風聞耶穌的事，就託猶太人的幾個長老去求耶穌來救他的僕人。", "ja": "この百卒長はイエスのことを聞いて、ユダヤ人の長老たちをイエスのところにつかわし、自分の僕を助けにきてくださるようにと、お願いした。"}, "4": {"en": "When they came to Jesus, they begged him earnestly, saying, “He is worthy for you to do this for him,", "zh": "他們到了耶穌那裏，就切切地求他說：「你給他行這事是他所配得的；", "ja": "彼らはイエスのところにきて、熱心に願って言った、「あの人はそうしていただくねうちがございます。"}, "5": {"en": "for he loves our nation, and he built our synagogue for us.”", "zh": "因為他愛我們的百姓，給我們建造會堂。」", "ja": "わたしたちの国民を愛し、わたしたちのために会堂を建ててくれたのです」。"}, "6": {"en": "Jesus went with them. When he was now not far from the house, the centurion sent friends to him, saying to him, “Lord, don’t trouble yourself, for I am not worthy for you to come under my roof.", "zh": "耶穌就和他們同去。離那家不遠，百夫長託幾個朋友去見耶穌，對他說：「主啊！不要勞動；因你到我舍下，我不敢當。", "ja": "そこで、イエスは彼らと連れだってお出かけになった。ところが、その家からほど遠くないあたりまでこられたとき、百卒長は友だちを送ってイエスに言わせた、「主よ、どうぞ、ご足労くださいませんように。わたしの屋根の下にあなたをお入れする資格は、わたしにはございません。"}, "7": {"en": "Therefore I didn’t even think myself worthy to come to you; but say the word, and my servant will be healed.", "zh": "我也自以為不配去見你，只要你說一句話，我的僕人就必好了。", "ja": "それですから、自分でお迎えにあがるねうちさえないと思っていたのです。ただ、お言葉を下さい。そして、わたしの僕をなおしてください。"}, "8": {"en": "For I also am a man placed under authority, having under myself soldiers. I tell this one, ‘Go!’ and he goes; and to another, ‘Come!’ and he comes; and to my servant, ‘Do this,’ and he does it.”", "zh": "因為我在人的權下，也有兵在我以下，對這個說：『去！』他就去；對那個說：『來！』他就來；對我的僕人說：『你做這事！』他就去做。」", "ja": "わたしも権威の下に服している者ですが、わたしの下にも兵卒がいまして、ひとりの者に『行け』と言えば行き、ほかの者に『こい』と言えばきますし、また、僕に『これをせよ』と言えば、してくれるのです」。"}, "9": {"en": "When Jesus heard these things, he marveled at him, and turned and said to the multitude who followed him, “I tell you, I have not found such great faith, no, not in Israel.”", "zh": "耶穌聽見這話，就希奇他，轉身對跟隨的眾人說：「我告訴你們，這麼大的信心，就是在以色列中，我也沒有遇見過。」", "ja": "イエスはこれを聞いて非常に感心され、ついてきた群衆の方に振り向いて言われた、「あなたがたに言っておくが、これほどの信仰は、イスラエルの中でも見たことがない」。"}, "10": {"en": "Those who were sent, returning to the house, found that the servant who had been sick was well.", "zh": "那託來的人回到百夫長家裏，看見僕人已經好了。", "ja": "使にきた者たちが家に帰ってみると、僕は元気になっていた。"}, "11": {"en": "Soon afterwards, he went to a city called Nain. Many of his disciples, along with a great multitude, went with him.", "zh": "過了不多時，耶穌往一座城去，這城名叫拿因，他的門徒和極多的人與他同行。", "ja": "そののち、間もなく、ナインという町へおいでになったが、弟子たちや大ぜいの群衆も一緒に行った。"}, "12": {"en": "Now when he came near to the gate of the city, behold, one who was dead was carried out, the only born son of his mother, and she was a widow. Many people of the city were with her.", "zh": "將近城門，有一個死人被抬出來。這人是他母親獨生的兒子；他母親又是寡婦。有城裏的許多人同着寡婦送殯。", "ja": "町の門に近づかれると、ちょうど、あるやもめにとってひとりむすこであった者が死んだので、葬りに出すところであった。大ぜいの町の人たちが、その母につきそっていた。"}, "13": {"en": "When the Lord saw her, he had compassion on her and said to her, “Don’t cry.”", "zh": "主看見那寡婦，就憐憫她，對她說：「不要哭！」", "ja": "主はこの婦人を見て深い同情を寄せられ、「泣かないでいなさい」と言われた。"}, "14": {"en": "He came near and touched the coffin, and the bearers stood still. He said, “Young man, I tell you, arise!”", "zh": "於是進前按着槓，抬的人就站住了。耶穌說：「少年人，我吩咐你，起來！」", "ja": "そして近寄って棺に手をかけられると、かついでいる者たちが立ち止まったので、「若者よ、さあ、起きなさい」と言われた。"}, "15": {"en": "He who was dead sat up and began to speak. Then he gave him to his mother.", "zh": "那死人就坐起，並且說話。耶穌便把他交給他母親。", "ja": "すると、死人が起き上がって物を言い出した。イエスは彼をその母にお渡しになった。"}, "16": {"en": "Fear took hold of all, and they glorified God, saying, “A great prophet has arisen among us!” and, “God has visited his people!”", "zh": "眾人都驚奇，歸榮耀與上帝，說：「有大先知在我們中間興起來了！」又說：「上帝眷顧了他的百姓！」", "ja": "人々はみな恐れをいだき、「大預言者がわたしたちの間に現れた」、また、「神はその民を顧みてくださった」と言って、神をほめたたえた。"}, "17": {"en": "This report went out concerning him in the whole of Judea and in all the surrounding region.", "zh": "他這事的風聲就傳遍了猶太和周圍地方。", "ja": "イエスについてのこの話は、ユダヤ全土およびその附近のいたる所にひろまった。"}, "18": {"en": "The disciples of John told him about all these things.", "zh": "約翰的門徒把這些事都告訴約翰。", "ja": "ヨハネの弟子たちは、これらのことを全部彼に報告した。するとヨハネは弟子の中からふたりの者を呼んで、"}, "19": {"en": "John, calling to himself two of his disciples, sent them to Jesus, saying, “Are you the one who is coming, or should we look for another?”", "zh": "他便叫了兩個門徒來，打發他們到主那裏去，說：「那將要來的是你嗎？還是我們等候別人呢？」", "ja": "主のもとに送り、「『きたるべきかた』はあなたなのですか。それとも、ほかにだれかを待つべきでしょうか」と尋ねさせた。"}, "20": {"en": "When the men had come to him, they said, “John the Baptizer has sent us to you, saying, ‘Are you he who comes, or should we look for another?’ ”", "zh": "那兩個人來到耶穌那裏，說：「施洗的約翰打發我們來問你：『那將要來的是你嗎？還是我們等候別人呢？』」", "ja": "そこで、この人たちがイエスのもとにきて言った、「わたしたちはバプテスマのヨハネからの使ですが、『きたるべきかた』はあなたなのですか、それとも、ほかにだれかを待つべきでしょうか、とヨハネが尋ねています」。"}, "21": {"en": "In that hour he cured many of diseases and plagues and evil spirits; and to many who were blind he gave sight.", "zh": "正當那時候，耶穌治好了許多有疾病的，受災患的，被惡鬼附着的，又開恩叫好些瞎子能看見。", "ja": "そのとき、イエスはさまざまの病苦と悪霊とに悩む人々をいやし、また多くの盲人を見えるようにしておられたが、"}, "22": {"en": "Jesus answered them, “Go and tell John the things which you have seen and heard: that the blind receive their sight, the lame walk, the lepers are cleansed, the deaf hear, the dead are raised up, and the poor have good news preached to them.", "zh": "耶穌回答說：「你們去，把所看見所聽見的事告訴約翰，就是瞎子看見，瘸子行走，長大痲瘋的潔淨，聾子聽見，死人復活，窮人有福音傳給他們。", "ja": "答えて言われた、「行って、あなたがたが見聞きしたことを、ヨハネに報告しなさい。盲人は見え、足なえは歩き、らい病人はきよまり、耳しいは聞え、死人は生きかえり、貧しい人々は福音を聞かされている。"}, "23": {"en": "Blessed is he who finds no occasion for stumbling in me.”", "zh": "凡不因我跌倒的，就有福了！」", "ja": "わたしにつまずかない者は、さいわいである」。"}, "24": {"en": "When John’s messengers had departed, he began to tell the multitudes about John, “What did you go out into the wilderness to see? A reed shaken by the wind?", "zh": "約翰所差來的人既走了，耶穌就對眾人講論約翰說：「你們從前出去到曠野，是要看甚麼呢？要看風吹動的蘆葦嗎？", "ja": "ヨハネの使が行ってしまうと、イエスはヨハネのことを群衆に語りはじめられた、「あなたがたは、何を見に荒野に出てきたのか。風に揺らぐ葦であるか。"}, "25": {"en": "But what did you go out to see? A man clothed in soft clothing? Behold, those who are gorgeously dressed and live delicately are in kings’ courts.", "zh": "你們出去，到底是要看甚麼？要看穿細軟衣服的人嗎？那穿華麗衣服、宴樂度日的人是在王宮裏。", "ja": "では、何を見に出てきたのか。柔らかい着物をまとった人か。きらびやかに着かざって、ぜいたくに暮している人々なら、宮殿にいる。"}, "26": {"en": "But what did you go out to see? A prophet? Yes, I tell you, and much more than a prophet.", "zh": "你們出去，究竟是要看甚麼？要看先知嗎？我告訴你們，是的，他比先知大多了。", "ja": "では、何を見に出てきたのか。預言者か。そうだ、あなたがたに言うが、預言者以上の者である。"}, "27": {"en": "This is he of whom it is written, ‘Behold, I send my messenger before your face, who will prepare your way before you.’", "zh": "經上記着說：『我要差遣我的使者在你前面預備道路』，所說的就是這個人。", "ja": "『見よ、わたしは使をあなたの先につかわし、あなたの前に、道を整えさせるであろう』と書いてあるのは、この人のことである。"}, "28": {"en": "“For I tell you, among those who are born of women there is not a greater prophet than John the Baptizer; yet he who is least in God’s Kingdom is greater than he.”", "zh": "我告訴你們，凡婦人所生的，沒有一個大過約翰的；然而上帝國裏最小的比他還大。」", "ja": "あなたがたに言っておく。女の産んだ者の中で、ヨハネより大きい人物はいない。しかし、神の国で最も小さい者も、彼よりは大きい。"}, "29": {"en": "When all the people and the tax collectors heard this, they declared God to be just, having been baptized with John’s baptism.", "zh": "眾百姓和稅吏既受過約翰的洗，聽見這話，就以上帝為義；", "ja": "（これを聞いた民衆は皆、また取税人たちも、ヨハネのバプテスマを受けて神の正しいことを認めた。"}, "30": {"en": "But the Pharisees and the lawyers rejected the counsel of God, not being baptized by him themselves.", "zh": "但法利賽人和律法師沒有受過約翰的洗，竟為自己廢棄了上帝的旨意。", "ja": "しかし、パリサイ人と律法学者たちとは彼からバプテスマを受けないで、自分たちに対する神のみこころを無にした。）"}, "31": {"en": "“To what then should I compare the people of this generation? What are they like?", "zh": "主又說：「這樣，我可用甚麼比這世代的人呢？他們好像甚麼呢？", "ja": "だから今の時代の人々を何に比べようか。彼らは何に似ているか。"}, "32": {"en": "They are like children who sit in the marketplace and call to one another, saying, ‘We piped to you, and you didn’t dance. We mourned, and you didn’t weep.’", "zh": "好像孩童坐在街市上，彼此呼叫說： 我們向你們吹笛， 你們不跳舞； 我們向你們舉哀， 你們不啼哭。", "ja": "それは子供たちが広場にすわって、互に呼びかけ、『わたしたちが笛を吹いたのに、あなたたちは踊ってくれなかった。弔いの歌を歌ったのに、泣いてくれなかった』と言うのに似ている。"}, "33": {"en": "For John the Baptizer came neither eating bread nor drinking wine, and you say, ‘He has a demon.’", "zh": "施洗的約翰來，不吃餅，不喝酒，你們說他是被鬼附着的。", "ja": "なぜなら、バプテスマのヨハネがきて、パンを食べることも、ぶどう酒を飲むこともしないと、あなたがたは、あれは悪霊につかれているのだ、と言い、"}, "34": {"en": "The Son of Man has come eating and drinking, and you say, ‘Behold, a glutton and a drunkard, a friend of tax collectors and sinners!’", "zh": "人子來，也吃也喝，你們說他是貪食好酒的人，是稅吏和罪人的朋友。", "ja": "また人の子がきて食べたり飲んだりしていると、見よ、あれは食をむさぼる者、大酒を飲む者、また取税人、罪人の仲間だ、と言う。"}, "35": {"en": "Wisdom is justified by all her children.”", "zh": "但智慧之子都以智慧為是。」", "ja": "しかし、知恵の正しいことは、そのすべての子が証明する」。"}, "36": {"en": "One of the Pharisees invited him to eat with him. He entered into the Pharisee’s house and sat at the table.", "zh": "有一個法利賽人請耶穌和他吃飯；耶穌就到法利賽人家裏去坐席。", "ja": "あるパリサイ人がイエスに、食事を共にしたいと申し出たので、そのパリサイ人の家にはいって食卓に着かれた。"}, "37": {"en": "Behold, a woman in the city who was a sinner, when she knew that he was reclining in the Pharisee’s house, brought an alabaster jar of ointment.", "zh": "那城裏有一個女人，是個罪人，知道耶穌在法利賽人家裏坐席，就拿着盛香膏的玉瓶，", "ja": "するとそのとき、その町で罪の女であったものが、パリサイ人の家で食卓に着いておられることを聞いて、香油が入れてある石膏のつぼを持ってきて、"}, "38": {"en": "Standing behind at his feet weeping, she began to wet his feet with her tears, and she wiped them with the hair of her head, kissed his feet, and anointed them with the ointment.", "zh": "站在耶穌背後，挨着他的腳哭，眼淚濕了耶穌的腳，就用自己的頭髮擦乾，又用嘴連連親他的腳，把香膏抹上。", "ja": "泣きながら、イエスのうしろでその足もとに寄り、まず涙でイエスの足をぬらし、自分の髪の毛でぬぐい、そして、その足に接吻して、香油を塗った。"}, "39": {"en": "Now when the Pharisee who had invited him saw it, he said to himself, “This man, if he were a prophet, would have perceived who and what kind of woman this is who touches him, that she is a sinner.”", "zh": "請耶穌的法利賽人看見這事，心裏說：「這人若是先知，必知道摸他的是誰，是個怎樣的女人；乃是個罪人。」", "ja": "イエスを招いたパリサイ人がそれを見て、心の中で言った、「もしこの人が預言者であるなら、自分にさわっている女がだれだか、どんな女かわかるはずだ。それは罪の女なのだから」。"}, "40": {"en": "Jesus answered him, “Simon, I have something to tell you.” He said, “Teacher, say on.”", "zh": "耶穌對他說：「西門！我有句話要對你說。」西門說：「夫子，請說。」", "ja": "そこでイエスは彼にむかって言われた、「シモン、あなたに言うことがある」。彼は「先生、おっしゃってください」と言った。"}, "41": {"en": "“A certain lender had two debtors. The one owed five hundred denarii, and the other fifty.", "zh": "耶穌說：「一個債主有兩個人欠他的債；一個欠五十兩銀子，一個欠五兩銀子；", "ja": "イエスが言われた、「ある金貸しに金をかりた人がふたりいたが、ひとりは五百デナリ、もうひとりは五十デナリを借りていた。"}, "42": {"en": "When they couldn’t pay, he forgave them both. Which of them therefore will love him most?”", "zh": "因為他們無力償還，債主就開恩免了他們兩個人的債。這兩個人哪一個更愛他呢？」", "ja": "ところが、返すことができなかったので、彼はふたり共ゆるしてやった。このふたりのうちで、どちらが彼を多く愛するだろうか」。"}, "43": {"en": "Simon answered, “He, I suppose, to whom he forgave the most.”", "zh": "西門回答說：「我想是那多得恩免的人。」耶穌說：「你斷的不錯。」", "ja": "シモンが答えて言った、「多くゆるしてもらったほうだと思います」。イエスが言われた、「あなたの判断は正しい」。"}, "44": {"en": "He said to him, “You have judged correctly.” Turning to the woman, he said to Simon, “Do you see this woman? I entered into your house, and you gave me no water for my feet, but she has wet my feet with her tears, and wiped them with the hair of her head.", "zh": "於是轉過來向着那女人，便對西門說：「你看見這女人嗎？我進了你的家，你沒有給我水洗腳；但這女人用眼淚濕了我的腳，用頭髮擦乾。", "ja": "それから女の方に振り向いて、シモンに言われた、「この女を見ないか。わたしがあなたの家にはいってきた時に、あなたは足を洗う水をくれなかった。ところが、この女は涙でわたしの足をぬらし、髪の毛でふいてくれた。"}, "45": {"en": "You gave me no kiss, but she, since the time I came in, has not ceased to kiss my feet.", "zh": "你沒有與我親嘴；但這女人從我進來的時候就不住地用嘴親我的腳。", "ja": "あなたはわたしに接吻をしてくれなかったが、彼女はわたしが家にはいった時から、わたしの足に接吻をしてやまなかった。"}, "46": {"en": "You didn’t anoint my head with oil, but she has anointed my feet with ointment.", "zh": "你沒有用油抹我的頭；但這女人用香膏抹我的腳。", "ja": "あなたはわたしの頭に油を塗ってくれなかったが、彼女はわたしの足に香油を塗ってくれた。"}, "47": {"en": "Therefore I tell you, her sins, which are many, are forgiven, for she loved much. But one to whom little is forgiven, loves little.”", "zh": "所以我告訴你，她許多的罪都赦免了，因為她的愛多；但那赦免少的，他的愛就少。」", "ja": "それであなたに言うが、この女は多く愛したから、その多くの罪はゆるされているのである。少しだけゆるされた者は、少しだけしか愛さない」。"}, "48": {"en": "He said to her, “Your sins are forgiven.”", "zh": "於是對那女人說：「你的罪赦免了。」", "ja": "そして女に、「あなたの罪はゆるされた」と言われた。"}, "49": {"en": "Those who sat at the table with him began to say to themselves, “Who is this who even forgives sins?”", "zh": "同席的人心裏說：「這是甚麼人，竟赦免人的罪呢？」", "ja": "すると同席の者たちが心の中で言いはじめた、「罪をゆるすことさえするこの人は、いったい、何者だろう」。"}, "50": {"en": "He said to the woman, “Your faith has saved you. Go in peace.”", "zh": "耶穌對那女人說：「你的信救了你；平平安安回去吧！」", "ja": "しかし、イエスは女にむかって言われた、「あなたの信仰があなたを救ったのです。安心して行きなさい」。"}}}, "8": {"verses": {"1": {"en": "Soon afterwards, he went about through cities and villages, preaching and bringing the good news of God’s Kingdom. With him were the twelve,", "zh": "過了不多日，耶穌周遊各城各鄉傳道，宣講上帝國的福音。和他同去的有十二個門徒，", "ja": "そののちイエスは、神の国の福音を説きまた伝えながら、町々村々を巡回し続けられたが、十二弟子もお供をした。"}, "2": {"en": "and certain women who had been healed of evil spirits and infirmities: Mary who was called Magdalene, from whom seven demons had gone out;", "zh": "還有被惡鬼所附、被疾病所累、已經治好的幾個婦女，內中有稱為抹大拉的馬利亞（曾有七個鬼從她身上趕出來），", "ja": "また悪霊を追い出され病気をいやされた数名の婦人たち、すなわち、七つの悪霊を追い出してもらったマグダラと呼ばれるマリヤ、"}, "3": {"en": "and Joanna, the wife of Chuzas, Herod’s steward; Susanna; and many others who served them from their possessions.", "zh": "又有希律的家宰苦撒的妻子約亞拿，並蘇撒拿，和好些別的婦女，都是用自己的財物供給耶穌和門徒。", "ja": "ヘロデの家令クーザの妻ヨハンナ、スザンナ、そのほか多くの婦人たちも一緒にいて、自分たちの持ち物をもって一行に奉仕した。"}, "4": {"en": "When a great multitude came together and people from every city were coming to him, he spoke by a parable:", "zh": "當許多人聚集、又有人從各城裏出來見耶穌的時候，耶穌就用比喻說：", "ja": "さて、大ぜいの群衆が集まり、その上、町々からの人たちがイエスのところに、ぞくぞくと押し寄せてきたので、一つの譬で話をされた、"}, "5": {"en": "“The farmer went out to sow his seed. As he sowed, some fell along the road, and it was trampled under foot, and the birds of the sky devoured it.", "zh": "「有一個撒種的出去撒種。撒的時候，有落在路旁的，被人踐踏，天上的飛鳥又來吃盡了。", "ja": "「種まきが種をまきに出て行った。まいているうちに、ある種は道ばたに落ち、踏みつけられ、そして空の鳥に食べられてしまった。"}, "6": {"en": "Some seed fell on the rock, and as soon as it grew, it withered away, because it had no moisture.", "zh": "有落在磐石上的，一出來就枯乾了，因為得不着滋潤。", "ja": "ほかの種は岩の上に落ち、はえはしたが水気がないので枯れてしまった。"}, "7": {"en": "Some fell amid the thorns, and the thorns grew with it and choked it.", "zh": "有落在荊棘裏的，荊棘一同生長，把它擠住了。", "ja": "ほかの種は、いばらの間に落ちたので、いばらも一緒に茂ってきて、それをふさいでしまった。"}, "8": {"en": "Some fell into the good ground and grew and produced one hundred times as much fruit.” As he said these things, he called out, “He who has ears to hear, let him hear!”", "zh": "又有落在好土裏的，生長起來，結實百倍。」耶穌說了這些話，就大聲說：「有耳可聽的，就應當聽！」", "ja": "ところが、ほかの種は良い地に落ちたので、はえ育って百倍もの実を結んだ」。こう語られたのち、声をあげて「聞く耳のある者は聞くがよい」と言われた。"}, "9": {"en": "Then his disciples asked him, “What does this parable mean?”", "zh": "門徒問耶穌說：「這比喻是甚麼意思呢？」", "ja": "弟子たちは、この譬はどういう意味でしょうか、とイエスに質問した。"}, "10": {"en": "He said, “To you it is given to know the mysteries of God’s Kingdom, but to the rest it is given in parables, that ‘seeing they may not see, and hearing they may not understand.’", "zh": "他說：「上帝國的奧祕只叫你們知道；至於別人，就用比喻，叫他們看也看不見，聽也聽不明。」", "ja": "そこで言われた、「あなたがたには、神の国の奥義を知ることが許されているが、ほかの人たちには、見ても見えず、聞いても悟られないために、譬で話すのである。"}, "11": {"en": "“Now the parable is this: The seed is the word of God.", "zh": "「這比喻乃是這樣：種子就是上帝的道。", "ja": "この譬はこういう意味である。種は神の言である。"}, "12": {"en": "Those along the road are those who hear; then the devil comes and takes away the word from their heart, that they may not believe and be saved.", "zh": "那些在路旁的，就是人聽了道，隨後魔鬼來，從他們心裏把道奪去，恐怕他們信了得救。", "ja": "道ばたに落ちたのは、聞いたのち、信じることも救われることもないように、悪魔によってその心から御言が奪い取られる人たちのことである。"}, "13": {"en": "Those on the rock are they who, when they hear, receive the word with joy; but these have no root. They believe for a while, then fall away in time of temptation.", "zh": "那些在磐石上的，就是人聽道，歡喜領受，但心中沒有根，不過暫時相信，及至遇見試煉就退後了。", "ja": "岩の上に落ちたのは、御言を聞いた時には喜んで受けいれるが、根が無いので、しばらくは信じていても、試錬の時が来ると、信仰を捨てる人たちのことである。"}, "14": {"en": "What fell among the thorns, these are those who have heard, and as they go on their way they are choked with cares, riches, and pleasures of life; and they bring no fruit to maturity.", "zh": "那落在荊棘裏的，就是人聽了道，走開以後，被今生的思慮、錢財、宴樂擠住了，便結不出成熟的子粒來。", "ja": "いばらの中に落ちたのは、聞いてから日を過ごすうちに、生活の心づかいや富や快楽にふさがれて、実の熟するまでにならない人たちのことである。"}, "15": {"en": "Those in the good ground, these are those who with an honest and good heart, having heard the word, hold it tightly, and produce fruit with perseverance.", "zh": "那落在好土裏的，就是人聽了道，持守在誠實善良的心裏，並且忍耐着結實。」", "ja": "良い地に落ちたのは、御言を聞いたのち、これを正しい良い心でしっかりと守り、耐え忍んで実を結ぶに至る人たちのことである。"}, "16": {"en": "“No one, when he has lit a lamp, covers it with a container or puts it under a bed; but puts it on a stand, that those who enter in may see the light.", "zh": "「沒有人點燈用器皿蓋上，或放在床底下，乃是放在燈臺上，叫進來的人看見亮光。", "ja": "だれもあかりをともして、それを何かの器でおおいかぶせたり、寝台の下に置いたりはしない。燭台の上に置いて、はいって来る人たちに光が見えるようにするのである。"}, "17": {"en": "For nothing is hidden that will not be revealed, nor anything secret that will not be known and come to light.", "zh": "因為掩藏的事沒有不顯出來的；隱瞞的事沒有不露出來被人知道的。", "ja": "隠されているもので、あらわにならないものはなく、秘密にされているもので、ついには知られ、明るみに出されないものはない。"}, "18": {"en": "Be careful therefore how you hear. For whoever has, to him will be given; and whoever doesn’t have, from him will be taken away even that which he thinks he has.”", "zh": "所以，你們應當小心怎樣聽；因為凡有的，還要加給他；凡沒有的，連他自以為有的，也要奪去。」", "ja": "だから、どう聞くかに注意するがよい。持っている人は更に与えられ、持っていない人は、持っていると思っているものまでも、取り上げられるであろう」。"}, "19": {"en": "His mother and brothers came to him, and they could not come near him for the crowd.", "zh": "耶穌的母親和他弟兄來了，因為人多，不得到他跟前。", "ja": "さて、イエスの母と兄弟たちとがイエスのところにきたが、群衆のためそば近くに行くことができなかった。"}, "20": {"en": "Some people told him, “Your mother and your brothers stand outside, desiring to see you.”", "zh": "有人告訴他說：「你母親和你弟兄站在外邊，要見你。」", "ja": "それで、だれかが「あなたの母上と兄弟がたが、お目にかかろうと思って、外に立っておられます」と取次いだ。"}, "21": {"en": "But he answered them, “My mother and my brothers are these who hear the word of God and do it.”", "zh": "耶穌回答說：「聽了上帝之道而遵行的人就是我的母親，我的弟兄了。」", "ja": "するとイエスは人々にむかって言われた、「神の御言を聞いて行う者こそ、わたしの母、わたしの兄弟なのである」。"}, "22": {"en": "Now on one of those days, he entered into a boat, himself and his disciples, and he said to them, “Let’s go over to the other side of the lake.” So they launched out.", "zh": "有一天，耶穌和門徒上了船，對門徒說：「我們可以渡到湖那邊去。」他們就開了船。", "ja": "ある日のこと、イエスは弟子たちと舟に乗り込み、「湖の向こう岸へ渡ろう」と言われたので、一同が船出した。"}, "23": {"en": "But as they sailed, he fell asleep. A wind storm came down on the lake, and they were taking on dangerous amounts of water.", "zh": "正行的時候，耶穌睡着了。湖上忽然起了暴風，船將滿了水，甚是危險。", "ja": "渡って行く間に、イエスは眠ってしまわれた。すると突風が湖に吹きおろしてきたので、彼らは水をかぶって危険になった。"}, "24": {"en": "They came to him and awoke him, saying, “Master, Master, we are dying!” He awoke and rebuked the wind and the raging of the water; then they ceased, and it was calm.", "zh": "門徒來叫醒了他，說：「夫子！夫子！我們喪命啦！」耶穌醒了，斥責那狂風大浪；風浪就止住，平靜了。", "ja": "そこで、みそばに寄ってきてイエスを起し、「先生、先生、わたしたちは死にそうです」と言った。イエスは起き上がって、風と荒浪とをおしかりになると、止んでなぎになった。"}, "25": {"en": "He said to them, “Where is your faith?” Being afraid, they marveled, saying to one another, “Who is this then, that he commands even the winds and the water, and they obey him?”", "zh": "耶穌對他們說：「你們的信心在哪裏呢？」他們又懼怕又希奇，彼此說：「這到底是誰？他吩咐風和水，連風和水也聽從他了。」", "ja": "イエスは彼らに言われた、「あなたがたの信仰は、どこにあるのか」。彼らは恐れ驚いて互に言い合った、「いったい、このかたはだれだろう。お命じになると、風も水も従うとは」。"}, "26": {"en": "Then they arrived at the country of the Gadarenes, which is opposite Galilee.", "zh": "他們到了格拉森人的地方，就是加利利的對面。", "ja": "それから、彼らはガリラヤの対岸、ゲラサ人の地に渡った。"}, "27": {"en": "When Jesus stepped ashore, a certain man out of the city who had demons for a long time met him. He wore no clothes, and didn’t live in a house, but in the tombs.", "zh": "耶穌上了岸，就有城裏一個被鬼附着的人迎面而來。這個人許久不穿衣服，不住房子，只住在墳塋裏。", "ja": "陸にあがられると、その町の人で、悪霊につかれて長いあいだ着物も着ず、家に居つかないで墓場にばかりいた人に、出会われた。"}, "28": {"en": "When he saw Jesus, he cried out and fell down before him, and with a loud voice said, “What do I have to do with you, Jesus, you Son of the Most High God? I beg you, don’t torment me!”", "zh": "他見了耶穌，就俯伏在他面前，大聲喊叫，說：「至高上帝的兒子耶穌，我與你有甚麼相干？求你不要叫我受苦！」", "ja": "この人がイエスを見て叫び出し、みまえにひれ伏して大声で言った、「いと高き神の子イエスよ、あなたはわたしとなんの係わりがあるのです。お願いです、わたしを苦しめないでください」。"}, "29": {"en": "For Jesus was commanding the unclean spirit to come out of the man. For the unclean spirit had often seized the man. He was kept under guard and bound with chains and fetters. Breaking the bonds apart, he was driven by the demon into the desert.", "zh": "是因耶穌曾吩咐污鬼從那人身上出來。原來這鬼屢次抓住他；他常被人看守，又被鐵鍊和腳鐐捆鎖，他竟把鎖鍊掙斷，被鬼趕到曠野去。", "ja": "それは、イエスが汚れた霊に、その人から出て行け、とお命じになったからである。というのは、悪霊が何度も彼をひき捕えたので、彼は鎖と足かせとでつながれて看視されていたが、それを断ち切っては悪霊によって荒野へ追いやられていたのである。"}, "30": {"en": "Jesus asked him, “What is your name?”", "zh": "耶穌問他說：「你名叫甚麼？」他說：「我名叫『群』」；這是因為附着他的鬼多。", "ja": "イエスは彼に「なんという名前か」とお尋ねになると、「レギオンと言います」と答えた。彼の中にたくさんの悪霊がはいり込んでいたからである。"}, "31": {"en": "He said, “Legion,” for many demons had entered into him.   They begged him that he would not command them to go into the abyss.", "zh": "鬼就央求耶穌，不要吩咐他們到無底坑裏去。", "ja": "悪霊どもは、底知れぬ所に落ちて行くことを自分たちにお命じにならぬようにと、イエスに願いつづけた。"}, "32": {"en": "Now there was there a herd of many pigs feeding on the mountain, and they begged him that he would allow them to enter into those. Then he allowed them.", "zh": "那裏有一大群豬在山上吃食。鬼央求耶穌，准他們進入豬裏去。耶穌准了他們，", "ja": "ところが、そこの山べにおびただしい豚の群れが飼ってあったので、その豚の中へはいることを許していただきたいと、悪霊どもが願い出た。イエスはそれをお許しになった。"}, "33": {"en": "The demons came out of the man and entered into the pigs, and the herd rushed down the steep bank into the lake and were drowned.", "zh": "鬼就從那人出來，進入豬裏去。於是那群豬闖下山崖，投在湖裏淹死了。", "ja": "そこで悪霊どもは、その人から出て豚の中へはいり込んだ。するとその群れは、がけから湖へなだれを打って駆け下り、おぼれ死んでしまった。"}, "34": {"en": "When those who fed them saw what had happened, they fled and told it in the city and in the country.", "zh": "放豬的看見這事就逃跑了，去告訴城裏和鄉下的人。", "ja": "飼う者たちは、この出来事を見て逃げ出して、町や村里にふれまわった。"}, "35": {"en": "People went out to see what had happened. They came to Jesus and found the man from whom the demons had gone out, sitting at Jesus’ feet, clothed and in his right mind; and they were afraid.", "zh": "眾人出來要看是甚麼事；到了耶穌那裏，看見鬼所離開的那人，坐在耶穌腳前，穿着衣服，心裏明白過來，他們就害怕。", "ja": "人々はこの出来事を見に出てきた。そして、イエスのところにきて、悪霊を追い出してもらった人が着物を着て、正気になってイエスの足もとにすわっているのを見て、恐れた。"}, "36": {"en": "Those who saw it told them how he who had been possessed by demons was healed.", "zh": "看見這事的便將被鬼附着的人怎麼得救告訴他們。", "ja": "それを見た人たちは、この悪霊につかれていた者が救われた次第を、彼らに語り聞かせた。"}, "37": {"en": "All the people of the surrounding country of the Gadarenes asked him to depart from them, for they were very much afraid. Then he entered into the boat and returned.", "zh": "格拉森四圍的人，因為害怕得很，都求耶穌離開他們；耶穌就上船回去了。", "ja": "それから、ゲラサの地方の民衆はこぞって、自分たちの所から立ち去ってくださるようにとイエスに頼んだ。彼らが非常な恐怖に襲われていたからである。そこで、イエスは舟に乗って帰りかけられた。"}, "38": {"en": "But the man from whom the demons had gone out begged him that he might go with him, but Jesus sent him away, saying,", "zh": "鬼所離開的那人懇求和耶穌同在；耶穌卻打發他回去，說：", "ja": "悪霊を追い出してもらった人は、お供をしたいと、しきりに願ったが、イエスはこう言って彼をお帰しになった。"}, "39": {"en": "“Return to your house, and declare what great things God has done for you.” He went his way, proclaiming throughout the whole city what great things Jesus had done for him.", "zh": "「你回家去，傳說上帝為你做了何等大的事。」他就去，滿城裏傳揚耶穌為他做了何等大的事。", "ja": "「家へ帰って、神があなたにどんなに大きなことをしてくださったか、語り聞かせなさい」。そこで彼は立ち去って、自分にイエスがして下さったことを、ことごとく町中に言いひろめた。"}, "40": {"en": "When Jesus returned, the multitude welcomed him, for they were all waiting for him.", "zh": "耶穌回來的時候，眾人迎接他，因為他們都等候他。", "ja": "イエスが帰ってこられると、群衆は喜び迎えた。みんながイエスを待ちうけていたのである。"}, "41": {"en": "Behold, a man named Jairus came. He was a ruler of the synagogue. He fell down at Jesus’ feet and begged him to come into his house,", "zh": "有一個管會堂的，名叫睚魯，來俯伏在耶穌腳前，求耶穌到他家裏去；", "ja": "するとそこに、ヤイロという名の人がきた。この人は会堂司であった。イエスの足もとにひれ伏して、自分の家においでくださるようにと、しきりに願った。"}, "42": {"en": "for he had an only born daughter, about twelve years of age, and she was dying. But as he went, the multitudes pressed against him.", "zh": "因他有一個獨生女兒，約有十二歲，快要死了。", "ja": "彼に十二歳ばかりになるひとり娘があったが、死にかけていた。ところが、イエスが出て行かれる途中、群衆が押し迫ってきた。"}, "43": {"en": "A woman who had a flow of blood for twelve years, who had spent all her living on physicians and could not be healed by any,", "zh": "耶穌去的時候，眾人擁擠他。   有一個女人，患了十二年的血漏，在醫生手裏花盡了她一切養生的，並沒有一人能醫好她。", "ja": "ここに、十二年間も長血をわずらっていて、医者のために自分の身代をみな使い果してしまったが、だれにもなおしてもらえなかった女がいた。"}, "44": {"en": "came behind him and touched the fringe of his cloak. Immediately the flow of her blood stopped.", "zh": "她來到耶穌背後，摸他的衣裳繸子，血漏立刻就止住了。", "ja": "この女がうしろから近寄ってみ衣のふさにさわったところ、その長血がたちまち止まってしまった。"}, "45": {"en": "Jesus said, “Who touched me?” When all denied it, Peter and those with him said, “Master, the multitudes press and jostle you, and you say, ‘Who touched me?’”", "zh": "耶穌說：「摸我的是誰？」眾人都不承認。彼得和同行的人都說：「夫子，眾人擁擁擠擠緊靠着你。 」", "ja": "イエスは言われた、「わたしにさわったのは、だれか」。人々はみな自分ではないと言ったので、ペテロが「先生、群衆があなたを取り囲んで、ひしめき合っているのです」と答えた。"}, "46": {"en": "But Jesus said, “Someone did touch me, for I perceived that power has gone out of me.”", "zh": "耶穌說：「總有人摸我，因我覺得有能力從我身上出去。」", "ja": "しかしイエスは言われた、「だれかがわたしにさわった。力がわたしから出て行ったのを感じたのだ」。"}, "47": {"en": "When the woman saw that she was not hidden, she came trembling; and falling down before him declared to him in the presence of all the people the reason why she had touched him, and how she was healed immediately.", "zh": "那女人知道不能隱藏，就戰戰兢兢地來俯伏在耶穌腳前，把摸他的緣故和怎樣立刻得好了，當着眾人都說出來。", "ja": "女は隠しきれないのを知って、震えながら進み出て、みまえにひれ伏し、イエスにさわった訳と、さわるとたちまちなおったこととを、みんなの前で話した。"}, "48": {"en": "He said to her, “Daughter, cheer up. Your faith has made you well. Go in peace.”", "zh": "耶穌對她說：「女兒，你的信救了你；平平安安地去吧！」", "ja": "そこでイエスが女に言われた、「娘よ、あなたの信仰があなたを救ったのです。安心して行きなさい」。"}, "49": {"en": "While he still spoke, one from the ruler of the synagogue’s house came, saying to him, “Your daughter is dead. Don’t trouble the Teacher.”", "zh": "還說話的時候，有人從管會堂的家裏來，說：「你的女兒死了，不要勞動夫子。」", "ja": "イエスがまだ話しておられるうちに、会堂司の家から人がきて、「お嬢さんはなくなられました。この上、先生を煩わすには及びません」と言った。"}, "50": {"en": "But Jesus hearing it, answered him, “Don’t be afraid. Only believe, and she will be healed.”", "zh": "耶穌聽見就對他說：「不要怕，只要信！你的女兒就必得救。」", "ja": "しかしイエスはこれを聞いて会堂司にむかって言われた、「恐れることはない。ただ信じなさい。娘は助かるのだ」。"}, "51": {"en": "When he came to the house, he didn’t allow anyone to enter in, except Peter, John, James, the father of the child, and her mother.", "zh": "耶穌到了他的家，除了彼得、約翰、雅各，和女兒的父母，不許別人同他進去。", "ja": "それから家にはいられるとき、ペテロ、ヨハネ、ヤコブおよびその子の父母のほかは、だれも一緒にはいって来ることをお許しにならなかった。"}, "52": {"en": "All were weeping and mourning her, but he said, “Don’t weep. She isn’t dead, but sleeping.”", "zh": "眾人都為這女兒哀哭捶胸。耶穌說：「不要哭！她不是死了，是睡着了。」", "ja": "人々はみな、娘のために泣き悲しんでいた。イエスは言われた、「泣くな、娘は死んだのではない。眠っているだけである」。"}, "53": {"en": "They were ridiculing him, knowing that she was dead.", "zh": "他們曉得女兒已經死了，就嗤笑耶穌。", "ja": "人々は娘が死んだことを知っていたので、イエスをあざ笑った。"}, "54": {"en": "But he put them all outside, and taking her by the hand, he called, saying, “Child, arise!”", "zh": "耶穌拉着她的手，呼叫說：「女兒，起來吧！」", "ja": "イエスは娘の手を取って、呼びかけて言われた、「娘よ、起きなさい」。"}, "55": {"en": "Her spirit returned, and she rose up immediately. He commanded that something be given to her to eat.", "zh": "她的靈魂便回來，她就立刻起來了。耶穌吩咐給她東西吃。", "ja": "するとその霊がもどってきて、娘は即座に立ち上がった。イエスは何か食べ物を与えるように、さしずをされた。"}, "56": {"en": "Her parents were amazed, but he commanded them to tell no one what had been done.", "zh": "她的父母驚奇得很；耶穌囑咐他們，不要把所做的事告訴人。", "ja": "両親は驚いてしまった。イエスはこの出来事をだれにも話さないようにと、彼らに命じられた。"}}}, "9": {"verses": {"1": {"en": "He called the twelve together and gave them power and authority over all demons, and to cure diseases.", "zh": "耶穌叫齊了十二個門徒，給他們能力、權柄，制伏一切的鬼，醫治各樣的病，", "ja": "それからイエスは十二弟子を呼び集めて、彼らにすべての悪霊を制し、病気をいやす力と権威とをお授けになった。"}, "2": {"en": "He sent them out to preach God’s Kingdom and to heal the sick.", "zh": "又差遣他們去宣傳上帝國的道，醫治病人，", "ja": "また神の国を宣べ伝え、かつ病気をなおすためにつかわして"}, "3": {"en": "He said to them, “Take nothing for your journey—no staffs, nor wallet, nor bread, nor money. Don’t have two tunics each.", "zh": "對他們說：「行路的時候，不要帶柺杖和口袋，不要帶食物和銀子，也不要帶兩件褂子。", "ja": "言われた、「旅のために何も携えるな。つえも袋もパンも銭も持たず、また下着も二枚は持つな。"}, "4": {"en": "Into whatever house you enter, stay there, and depart from there.", "zh": "無論進哪一家，就住在那裏，也從那裏起行。", "ja": "また、どこかの家にはいったら、そこに留まっておれ。そしてそこから出かけることにしなさい。"}, "5": {"en": "As many as don’t receive you, when you depart from that city, shake off even the dust from your feet for a testimony against them.”", "zh": "凡不接待你們的，你們離開那城的時候，要把腳上的塵土跺下去，見證他們的不是。」", "ja": "だれもあなたがたを迎えるものがいなかったら、その町を出て行くとき、彼らに対する抗議のしるしに、足からちりを払い落しなさい」。"}, "6": {"en": "They departed and went throughout the villages, preaching the Good News and healing everywhere.", "zh": "門徒就出去，走遍各鄉宣傳福音，到處治病。", "ja": "弟子たちは出て行って、村々を巡り歩き、いたる所で福音を宣べ伝え、また病気をいやした。"}, "7": {"en": "Now Herod the tetrarch heard of all that was done by him; and he was very perplexed, because it was said by some that John had risen from the dead,", "zh": "分封的王希律聽見耶穌所做的一切事，就游移不定；因為有人說：「是約翰從死裏復活」；", "ja": "さて、領主ヘロデはいろいろな出来事を耳にして、あわて惑っていた。それは、ある人たちは、ヨハネが死人の中からよみがえったと言い、"}, "8": {"en": "and by some that Elijah had appeared, and by others that one of the old prophets had risen again.", "zh": "又有人說：「是以利亞顯現」；還有人說：「是古時的一個先知又活了。」", "ja": "またある人たちは、エリヤが現れたと言い、またほかの人たちは、昔の預言者のひとりが復活したのだと言っていたからである。"}, "9": {"en": "Herod said, “I beheaded John, but who is this about whom I hear such things?” He sought to see him.", "zh": "希律說：「約翰我已經斬了，這卻是甚麼人？我竟聽見他這樣的事呢？」就想要見他。", "ja": "そこでヘロデが言った、「ヨハネはわたしがすでに首を切ったのだが、こうしてうわさされているこの人は、いったい、だれなのだろう」。そしてイエスに会ってみようと思っていた。"}, "10": {"en": "The apostles, when they had returned, told him what things they had done.", "zh": "使徒回來，將所做的事告訴耶穌，耶穌就帶他們暗暗地離開那裏，往一座城去；那城名叫伯賽大。", "ja": "使徒たちは帰ってきて、自分たちのしたことをすべてイエスに話した。それからイエスは彼らを連れて、ベツサイダという町へひそかに退かれた。"}, "11": {"en": "He took them and withdrew apart to a desert region of a city called Bethsaida.   But the multitudes, perceiving it, followed him. He welcomed them, spoke to them of God’s Kingdom, and he cured those who needed healing.", "zh": "但眾人知道了，就跟着他去；耶穌便接待他們，對他們講論上帝國的道，醫治那些需醫的人。", "ja": "ところが群衆がそれと知って、ついてきたので、これを迎えて神の国のことを語り聞かせ、また治療を要する人たちをいやされた。"}, "12": {"en": "The day began to wear away; and the twelve came and said to him, “Send the multitude away, that they may go into the surrounding villages and farms and lodge and get food, for we are here in a deserted place.”", "zh": "日頭快要平西，十二個門徒來對他說：「請叫眾人散開，他們好往四面鄉村裏去借宿找吃的，因為我們這裏是野地。」", "ja": "それから日が傾きかけたので、十二弟子がイエスのもとにきて言った、「群衆を解散して、まわりの村々や部落へ行って宿を取り、食物を手にいれるようにさせてください。わたしたちはこんな寂しい所にきているのですから」。"}, "13": {"en": "But he said to them, “You give them something to eat.”", "zh": "耶穌說：「你們給他們吃吧！」門徒說：「我們不過有五個餅，兩條魚，若不去為這許多人買食物就不夠。」", "ja": "しかしイエスは言われた、「あなたがたの手で食物をやりなさい」。彼らは言った、「わたしたちにはパン五つと魚二ひきしかありません、この大ぜいの人のために食物を買いに行くかしなければ」。"}, "14": {"en": "They said, “We have no more than five loaves and two fish, unless we should go and buy food for all these people.”   For they were about five thousand men.", "zh": "那時，人數約有五千。耶穌對門徒說：「叫他們一排一排地坐下，每排大約五十個人。」", "ja": "というのは、男が五千人ばかりもいたからである。しかしイエスは弟子たちに言われた、「人々をおおよそ五十人ずつの組にして、すわらせなさい」。"}, "15": {"en": "He said to his disciples, “Make them sit down in groups of about fifty each.” They did so, and made them all sit down.", "zh": "門徒就如此行，叫眾人都坐下。", "ja": "彼らはそのとおりにして、みんなをすわらせた。"}, "16": {"en": "He took the five loaves and the two fish, and looking up to the sky, he blessed them, broke them, and gave them to the disciples to set before the multitude.", "zh": "耶穌拿着這五個餅，兩條魚，望着天祝福，擘開，遞給門徒，擺在眾人面前。", "ja": "イエスは五つのパンと二ひきの魚とを手に取り、天を仰いでそれを祝福してさき、弟子たちにわたして群衆に配らせた。"}, "17": {"en": "They ate and were all filled. They gathered up twelve baskets of broken pieces that were left over.", "zh": "他們就吃，並且都吃飽了；把剩下的零碎收拾起來，裝滿了十二籃子。", "ja": "みんなの者は食べて満腹した。そして、その余りくずを集めたら、十二かごあった。"}, "18": {"en": "As he was praying alone, the disciples were near him, and he asked them, “Who do the multitudes say that I am?”", "zh": "耶穌自己禱告的時候，門徒也同他在那裏。耶穌問他們說：「眾人說我是誰？」", "ja": "イエスがひとりで祈っておられたとき、弟子たちが近くにいたので、彼らに尋ねて言われた、「群衆はわたしをだれと言っているか」。"}, "19": {"en": "They answered, “ ‘John the Baptizer,’ but others say, ‘Elijah,’ and others, that one of the old prophets has risen again.”", "zh": "他們說：「有人說是施洗的約翰；有人說是以利亞；還有人說是古時的一個先知又活了。」", "ja": "彼らは答えて言った、「バプテスマのヨハネだと、言っています。しかしほかの人たちは、エリヤだと言い、また昔の預言者のひとりが復活したのだと、言っている者もあります」。"}, "20": {"en": "He said to them, “But who do you say that I am?” Peter answered, “The Christ of God.”", "zh": "耶穌說：「你們說我是誰？」彼得回答說：「是上帝所立的基督。」", "ja": "彼らに言われた、「それでは、あなたがたはわたしをだれと言うか」。ペテロが答えて言った、「神のキリストです」。"}, "21": {"en": "But he warned them and commanded them to tell this to no one,", "zh": "耶穌切切地囑咐他們，不可將這事告訴人，", "ja": "イエスは彼らを戒め、この事をだれにも言うなと命じ、そして言われた、"}, "22": {"en": "saying, “The Son of Man must suffer many things, and be rejected by the elders, chief priests, and scribes, and be killed, and the third day be raised up.”", "zh": "又說：「人子必須受許多的苦，被長老、祭司長，和文士棄絕，並且被殺，第三日復活。」", "ja": "「人の子は必ず多くの苦しみを受け、長老、祭司長、律法学者たちに捨てられ、また殺され、そして三日目によみがえる」。"}, "23": {"en": "He said to all, “If anyone desires to come after me, let him deny himself, take up his cross, and follow me.", "zh": "耶穌又對眾人說：「若有人要跟從我，就當捨己，天天背起他的十字架來跟從我。", "ja": "それから、みんなの者に言われた、「だれでもわたしについてきたいと思うなら、自分を捨て、日々自分の十字架を負うて、わたしに従ってきなさい。"}, "24": {"en": "For whoever desires to save his life will lose it, but whoever will lose his life for my sake will save it.", "zh": "因為，凡要救自己生命的，必喪掉生命；凡為我喪掉生命的，必救了生命。", "ja": "自分の命を救おうと思う者はそれを失い、わたしのために自分の命を失う者は、それを救うであろう。"}, "25": {"en": "For what does it profit a man if he gains the whole world, and loses or forfeits his own self?", "zh": "人若賺得全世界，卻喪了自己，賠上自己，有甚麼益處呢？", "ja": "人が全世界をもうけても、自分自身を失いまたは損したら、なんの得になろうか。"}, "26": {"en": "For whoever will be ashamed of me and of my words, of him will the Son of Man be ashamed when he comes in his glory, and the glory of the Father, and of the holy angels.", "zh": "凡把我和我的道當作可恥的，人子在自己的榮耀裏，並天父與聖天使的榮耀裏降臨的時候，也要把那人當作可恥的。", "ja": "わたしとわたしの言葉とを恥じる者に対しては、人の子もまた、自分の栄光と、父と聖なる御使との栄光のうちに現れて来るとき、その者を恥じるであろう。"}, "27": {"en": "But I tell you the truth: There are some of those who stand here who will in no way taste of death until they see God’s Kingdom.”", "zh": "我實在告訴你們，站在這裏的，有人在沒嘗死味以前，必看見上帝的國。」", "ja": "よく聞いておくがよい、神の国を見るまでは、死を味わわない者が、ここに立っている者の中にいる」。"}, "28": {"en": "About eight days after these sayings, he took with him Peter, John, and James, and went up onto the mountain to pray.", "zh": "說了這話以後約有八天，耶穌帶着彼得、約翰、雅各上山去禱告。", "ja": "これらのことを話された後、八日ほどたってから、イエスはペテロ、ヨハネ、ヤコブを連れて、祈るために山に登られた。"}, "29": {"en": "As he was praying, the appearance of his face was altered, and his clothing became white and dazzling.", "zh": "正禱告的時候，他的面貌就改變了，衣服潔白放光。", "ja": "祈っておられる間に、み顔の様が変り、み衣がまばゆいほどに白く輝いた。"}, "30": {"en": "Behold, two men were talking with him, who were Moses and Elijah,", "zh": "忽然有摩西、以利亞兩個人同耶穌說話；", "ja": "すると見よ、ふたりの人がイエスと語り合っていた。それはモーセとエリヤであったが、"}, "31": {"en": "who appeared in glory and spoke of his departure, which he was about to accomplish at Jerusalem.", "zh": "他們在榮光裏顯現，談論耶穌去世的事，就是他在耶路撒冷將要成的事。", "ja": "栄光の中に現れて、イエスがエルサレムで遂げようとする最後のことについて話していたのである。"}, "32": {"en": "Now Peter and those who were with him were heavy with sleep, but when they were fully awake, they saw his glory, and the two men who stood with him.", "zh": "彼得和他的同伴都打盹，既清醒了，就看見耶穌的榮光，並同他站着的那兩個人。", "ja": "ペテロとその仲間の者たちとは熟睡していたが、目をさますと、イエスの栄光の姿と、共に立っているふたりの人とを見た。"}, "33": {"en": "As they were parting from him, Peter said to Jesus, “Master, it is good for us to be here. Let’s make three tents: one for you, one for Moses, and one for Elijah,” not knowing what he said.", "zh": "二人正要和耶穌分離的時候，彼得對耶穌說：「夫子，我們在這裏真好！可以搭三座棚，一座為你，一座為摩西，一座為以利亞。」他卻不知道所說的是甚麼。", "ja": "このふたりがイエスを離れ去ろうとしたとき、ペテロは自分が何を言っているのかわからないで、イエスに言った、「先生、わたしたちがここにいるのは、すばらしいことです。それで、わたしたちは小屋を三つ建てましょう。一つはあなたのために、一つはモーセのために、一つはエリヤのために」。"}, "34": {"en": "While he said these things, a cloud came and overshadowed them, and they were afraid as they entered into the cloud.", "zh": "說這話的時候，有一朵雲彩來遮蓋他們；他們進入雲彩裏就懼怕。", "ja": "彼がこう言っている間に、雲がわき起って彼らをおおいはじめた。そしてその雲に囲まれたとき、彼らは恐れた。"}, "35": {"en": "A voice came out of the cloud, saying, “This is my beloved Son. Listen to him!”", "zh": "有聲音從雲彩裏出來，說：「這是我的兒子，我所揀選的，你們要聽他。」", "ja": "すると雲の中から声があった、「これはわたしの子、わたしの選んだ者である。これに聞け」。"}, "36": {"en": "When the voice came, Jesus was found alone. They were silent, and told no one in those days any of the things which they had seen.", "zh": "聲音住了，只見耶穌一人在那裏。當那些日子，門徒不提所看見的事，一樣也不告訴人。", "ja": "そして声が止んだとき、イエスがひとりだけになっておられた。弟子たちは沈黙を守って、自分たちが見たことについては、そのころだれにも話さなかった。"}, "37": {"en": "On the next day, when they had come down from the mountain, a great multitude met him.", "zh": "第二天，他們下了山，就有許多人迎見耶穌。", "ja": "翌日、一同が山を降りて来ると、大ぜいの群衆がイエスを出迎えた。"}, "38": {"en": "Behold, a man from the crowd called out, saying, “Teacher, I beg you to look at my son, for he is my only born child.", "zh": "其中有一人喊叫說：「夫子！求你看顧我的兒子，因為他是我的獨生子。", "ja": "すると突然、ある人が群衆の中から大声をあげて言った、「先生、お願いです。わたしのむすこを見てやってください。この子はわたしのひとりむすこですが、"}, "39": {"en": "Behold, a spirit takes him, he suddenly cries out, and it convulses him so that he foams; and it hardly departs from him, bruising him severely.", "zh": "他被鬼抓住就忽然喊叫；鬼又叫他抽瘋，口中流沫，並且重重地傷害他，難以離開他。", "ja": "霊が取りつきますと、彼は急に叫び出すのです。それから、霊は彼をひきつけさせて、あわを吹かせ、彼を弱り果てさせて、なかなか出て行かないのです。"}, "40": {"en": "I begged your disciples to cast it out, and they couldn’t.”", "zh": "我求過你的門徒，把鬼趕出去，他們卻是不能。」", "ja": "それで、お弟子たちに、この霊を追い出してくださるように願いましたが、できませんでした」。"}, "41": {"en": "Jesus answered, “Faithless and perverse generation, how long shall I be with you and bear with you? Bring your son here.”", "zh": "耶穌說：「噯！這又不信又悖謬的世代啊，我在你們這裏，忍耐你們要到幾時呢？將你的兒子帶到這裏來吧！」", "ja": "イエスは答えて言われた、「ああ、なんという不信仰な、曲った時代であろう。いつまで、わたしはあなたがたと一緒におられようか、またあなたがたに我慢ができようか。あなたの子をここに連れてきなさい」。"}, "42": {"en": "While he was still coming, the demon threw him down and convulsed him violently. But Jesus rebuked the unclean spirit, healed the boy, and gave him back to his father.", "zh": "正來的時候，鬼把他摔倒，叫他重重地抽瘋。耶穌就斥責那污鬼，把孩子治好了，交給他父親。", "ja": "ところが、その子がイエスのところに来る時にも、悪霊が彼を引き倒して、引きつけさせた。イエスはこの汚れた霊をしかりつけ、その子供をいやして、父親にお渡しになった。"}, "43": {"en": "They were all astonished at the majesty of God.", "zh": "眾人都詫異上帝的大能 。", "ja": "人々はみな、神の偉大な力に非常に驚いた。みんなの者がイエスのしておられた数々の事を不思議に思っていると、弟子たちに言われた、"}, "44": {"en": "But while all were marveling at all the things which Jesus did, he said to his disciples,   “Let these words sink into your ears, for the Son of Man will be delivered up into the hands of men.”", "zh": "耶穌所做的一切事，眾人正希奇的時候，耶穌對門徒說：   「你們要把這些話存在耳中，因為人子將要被交在人手裏。」", "ja": "「あなたがたはこの言葉を耳におさめて置きなさい。人の子は人々の手に渡されようとしている」。"}, "45": {"en": "But they didn’t understand this saying. It was concealed from them, that they should not perceive it, and they were afraid to ask him about this saying.", "zh": "他們不明白這話，意思乃是隱藏的，叫他們不能明白，他們也不敢問這話的意思。", "ja": "しかし、彼らはなんのことかわからなかった。それが彼らに隠されていて、悟ることができなかったのである。また彼らはそのことについて尋ねるのを恐れていた。"}, "46": {"en": "An argument arose among them about which of them was the greatest.", "zh": "門徒中間起了議論，誰將為大。", "ja": "弟子たちの間に、彼らのうちでだれがいちばん偉いだろうかということで、議論がはじまった。"}, "47": {"en": "Jesus, perceiving the reasoning of their hearts, took a little child, and set him by his side,", "zh": "耶穌看出他們心中的議論，就領一個小孩子來，叫他站在自己旁邊，", "ja": "イエスは彼らの心の思いを見抜き、ひとりの幼な子を取りあげて自分のそばに立たせ、彼らに言われた、"}, "48": {"en": "and said to them, “Whoever receives this little child in my name receives me. Whoever receives me receives him who sent me. For whoever is least among you all, this one will be great.”", "zh": "對他們說：「凡為我名接待這小孩子的，就是接待我；凡接待我的，就是接待那差我來的。你們中間最小的，他便為大。」", "ja": "「だれでもこの幼な子をわたしの名のゆえに受けいれる者は、わたしを受けいれるのである。そしてわたしを受けいれる者は、わたしをおつかわしになったかたを受けいれるのである。あなたがたみんなの中でいちばん小さい者こそ、大きいのである」。"}, "49": {"en": "John answered, “Master, we saw someone casting out demons in your name, and we forbade him, because he doesn’t follow with us.”", "zh": "約翰說：「夫子，我們看見一個人奉你的名趕鬼，我們就禁止他，因為他不與我們一同跟從你。」", "ja": "するとヨハネが答えて言った、「先生、わたしたちはある人があなたの名を使って悪霊を追い出しているのを見ましたが、その人はわたしたちの仲間でないので、やめさせました」。"}, "50": {"en": "Jesus said to him, “Don’t forbid him, for he who is not against us is for us.”", "zh": "耶穌說：「不要禁止他；因為不敵擋你們的，就是幫助你們的。」", "ja": "イエスは彼に言われた、「やめさせないがよい。あなたがたに反対しない者は、あなたがたの味方なのである」。"}, "51": {"en": "It came to pass, when the days were near that he should be taken up, he intently set his face to go to Jerusalem", "zh": "耶穌被接上升的日子將到，他就定意向耶路撒冷去，", "ja": "さて、イエスが天に上げられる日が近づいたので、エルサレムへ行こうと決意して、その方へ顔をむけられ、"}, "52": {"en": "and sent messengers before his face. They went and entered into a village of the Samaritans, so as to prepare for him.", "zh": "便打發使者在他前頭走。他們到了撒馬利亞的一個村莊，要為他預備。", "ja": "自分に先立って使者たちをおつかわしになった。そして彼らがサマリヤ人の村へはいって行き、イエスのために準備をしようとしたところ、"}, "53": {"en": "They didn’t receive him, because he was traveling with his face set toward Jerusalem.", "zh": "那裏的人不接待他，因他面向耶路撒冷去。", "ja": "村人は、エルサレムへむかって進んで行かれるというので、イエスを歓迎しようとはしなかった。"}, "54": {"en": "When his disciples, James and John, saw this, they said, “Lord, do you want us to command fire to come down from the sky and destroy them, just as Elijah did?”", "zh": "他的門徒雅各、約翰看見了，就說：「主啊，你要我們吩咐火從天上降下來燒滅他們，像以利亞所做的嗎？」", "ja": "弟子のヤコブとヨハネとはそれを見て言った、「主よ、いかがでしょう。彼らを焼き払ってしまうように、天から火をよび求めましょうか」。"}, "55": {"en": "But he turned and rebuked them, “You don’t know of what kind of spirit you are.", "zh": "耶穌轉身責備兩個門徒，說：「你們的心如何，你們並不知道。", "ja": "イエスは振りかえって、彼らをおしかりになった。"}, "56": {"en": "For the Son of Man didn’t come to destroy men’s lives, but to save them.”", "zh": "人子來不是要滅人的性命，是要救人的性命。」說着就往別的村莊去了。", "ja": "そして一同はほかの村へ行った。"}, "57": {"en": "They went to another village.   As they went on the way, a certain man said to him, “I want to follow you wherever you go, Lord.”", "zh": "他們走路的時候，有一人對耶穌說：「你無論往哪裏去，我要跟從你。」", "ja": "道を進んで行くと、ある人がイエスに言った、「あなたがおいでになる所ならどこへでも従ってまいります」。"}, "58": {"en": "Jesus said to him, “The foxes have holes and the birds of the sky have nests, but the Son of Man has no place to lay his head.”", "zh": "耶穌說：「狐狸有洞，天空的飛鳥有窩，只是人子沒有枕頭的地方。」", "ja": "イエスはその人に言われた、「きつねには穴があり、空の鳥には巣がある。しかし、人の子にはまくらする所がない」。"}, "59": {"en": "He said to another, “Follow me!” But he said, “Lord, allow me first to go and bury my father.”", "zh": "又對一個人說：「跟從我來！」那人說：「主，容我先回去埋葬我的父親。」", "ja": "またほかの人に、「わたしに従ってきなさい」と言われた。するとその人が言った、「まず、父を葬りに行かせてください」。"}, "60": {"en": "But Jesus said to him, “Leave the dead to bury their own dead, but you go and announce God’s Kingdom.”", "zh": "耶穌說：「任憑死人埋葬他們的死人，你只管去傳揚上帝國的道。」", "ja": "彼に言われた、「その死人を葬ることは、死人に任せておくがよい。あなたは、出て行って神の国を告げひろめなさい」。"}, "61": {"en": "Another also said, “I want to follow you, Lord, but first allow me to say good-bye to those who are at my house.”", "zh": "又有一人說：「主，我要跟從你，但容我先去辭別我家裏的人。」", "ja": "またほかの人が言った、「主よ、従ってまいりますが、まず家の者に別れを言いに行かせてください」。"}, "62": {"en": "But Jesus said to him, “No one, having put his hand to the plow and looking back, is fit for God’s Kingdom.”", "zh": "耶穌說：「手扶着犂向後看的，不配進上帝的國。」", "ja": "イエスは言われた、「手をすきにかけてから、うしろを見る者は、神の国にふさわしくないものである」。"}}}, "10": {"verses": {"1": {"en": "Now after these things, the Lord also appointed seventy others, and sent them two by two ahead of him into every city and place where he was about to come.", "zh": "這事以後，主又設立七十個人，差遣他們兩個兩個地在他前面，往自己所要到的各城各地方去，", "ja": "その後、主は別に七十二人を選び、行こうとしておられたすべての町や村へ、ふたりずつ先におつかわしになった。"}, "2": {"en": "Then he said to them, “The harvest is indeed plentiful, but the laborers are few. Pray therefore to the Lord of the harvest, that he may send out laborers into his harvest.", "zh": "就對他們說：「要收的莊稼多，做工的人少。所以，你們當求莊稼的主打發工人出去收他的莊稼。", "ja": "そのとき、彼らに言われた、「収穫は多いが、働き人が少ない。だから、収穫の主に願って、その収穫のために働き人を送り出すようにしてもらいなさい。"}, "3": {"en": "Go your ways. Behold, I send you out as lambs among wolves.", "zh": "你們去吧！我差你們出去，如同羊羔進入狼群。", "ja": "さあ、行きなさい。わたしがあなたがたをつかわすのは、小羊をおおかみの中に送るようなものである。"}, "4": {"en": "Carry no purse, nor wallet, nor sandals. Greet no one on the way.", "zh": "不要帶錢囊，不要帶口袋，不要帶鞋；在路上也不要問人的安。", "ja": "財布も袋もくつも持って行くな。だれにも道であいさつするな。"}, "5": {"en": "Into whatever house you enter, first say, ‘Peace be to this house.’", "zh": "無論進哪一家，先要說：『願這一家平安。』", "ja": "どこかの家にはいったら、まず『平安がこの家にあるように』と言いなさい。"}, "6": {"en": "If a son of peace is there, your peace will rest on him; but if not, it will return to you.", "zh": "那裏若有當得平安的人，你們所求的平安就必臨到那家；不然，就歸與你們了。", "ja": "もし平安の子がそこにおれば、あなたがたの祈る平安はその人の上にとどまるであろう。もしそうでなかったら、それはあなたがたの上に帰って来るであろう。"}, "7": {"en": "Remain in that same house, eating and drinking the things they give, for the laborer is worthy of his wages. Don’t go from house to house.", "zh": "你們要住在那家，吃喝他們所供給的，因為工人得工價是應當的；不要從這家搬到那家。", "ja": "それで、その同じ家に留まっていて、家の人が出してくれるものを飲み食いしなさい。働き人がその報いを得るのは当然である。家から家へと渡り歩くな。"}, "8": {"en": "Into whatever city you enter and they receive you, eat the things that are set before you.", "zh": "無論進哪一城，人若接待你們，給你們擺上甚麼，你們就吃甚麼。", "ja": "どの町へはいっても、人々があなたがたを迎えてくれるなら、前に出されるものを食べなさい。"}, "9": {"en": "Heal the sick who are there and tell them, ‘God’s Kingdom has come near to you.’", "zh": "要醫治那城裏的病人，對他們說：『上帝的國臨近你們了。』", "ja": "そして、その町にいる病人をいやしてやり、『神の国はあなたがたに近づいた』と言いなさい。"}, "10": {"en": "But into whatever city you enter and they don’t receive you, go out into its streets and say,", "zh": "無論進哪一城，人若不接待你們，你們就到街上去，", "ja": "しかし、どの町へはいっても、人々があなたがたを迎えない場合には、大通りに出て行って言いなさい、"}, "11": {"en": "‘Even the dust from your city that clings to us, we wipe off against you. Nevertheless know this, that God’s Kingdom has come near to you.’", "zh": "說：『就是你們城裏的塵土黏在我們的腳上，我們也當着你們擦去。雖然如此，你們該知道上帝的國臨近了。』", "ja": "『わたしたちの足についているこの町のちりも、ぬぐい捨てて行く。しかし、神の国が近づいたことは、承知しているがよい』。"}, "12": {"en": "I tell you, it will be more tolerable in that day for Sodom than for that city.", "zh": "我告訴你們，當審判的日子，所多瑪所受的，比那城還容易受呢！」", "ja": "あなたがたに言っておく。その日には、この町よりもソドムの方が耐えやすいであろう。"}, "13": {"en": "“Woe to you, Chorazin! Woe to you, Bethsaida! For if the mighty works had been done in Tyre and Sidon which were done in you, they would have repented long ago, sitting in sackcloth and ashes.", "zh": "「哥拉汛哪，你有禍了！伯賽大啊，你有禍了！因為在你們中間所行的異能若行在泰爾、西頓，他們早已披麻蒙灰，坐在地上悔改了。", "ja": "わざわいだ、コラジンよ。わざわいだ、ベツサイダよ。おまえたちの中でなされた力あるわざが、もしツロとシドンでなされたなら、彼らはとうの昔に、荒布をまとい灰の中にすわって、悔い改めたであろう。"}, "14": {"en": "But it will be more tolerable for Tyre and Sidon in the judgment than for you.", "zh": "當審判的日子，泰爾、西頓所受的，比你們還容易受呢！", "ja": "しかし、さばきの日には、ツロとシドンの方がおまえたちよりも、耐えやすいであろう。"}, "15": {"en": "You, Capernaum, who are exalted to heaven, will be brought down to Hades.", "zh": "迦百農啊，你已經升到天上，將來必推下陰間。」", "ja": "ああ、カペナウムよ、おまえは天にまで上げられようとでもいうのか。黄泉にまで落されるであろう。"}, "16": {"en": "Whoever listens to you listens to me, and whoever rejects you rejects me. Whoever rejects me rejects him who sent me.”", "zh": "又對門徒說：「聽從你們的就是聽從我；棄絕你們的就是棄絕我；棄絕我的就是棄絕那差我來的。」", "ja": "あなたがたに聞き従う者は、わたしに聞き従うのであり、あなたがたを拒む者は、わたしを拒むのである。そしてわたしを拒む者は、わたしをおつかわしになったかたを拒むのである」。"}, "17": {"en": "The seventy returned with joy, saying, “Lord, even the demons are subject to us in your name!”", "zh": "那七十個人歡歡喜喜地回來，說：「主啊！因你的名，就是鬼也服了我們。」", "ja": "七十二人が喜んで帰ってきて言った、「主よ、あなたの名によっていたしますと、悪霊までがわたしたちに服従します」。"}, "18": {"en": "He said to them, “I saw Satan having fallen like lightning from heaven.", "zh": "耶穌對他們說：「我曾看見撒但從天上墜落，像閃電一樣。", "ja": "彼らに言われた、「わたしはサタンが電光のように天から落ちるのを見た。"}, "19": {"en": "Behold, I give you authority to tread on serpents and scorpions, and over all the power of the enemy. Nothing will in any way hurt you.", "zh": "我已經給你們權柄可以踐踏蛇和蠍子，又勝過仇敵一切的能力，斷沒有甚麼能害你們。", "ja": "わたしはあなたがたに、へびやさそりを踏みつけ、敵のあらゆる力に打ち勝つ権威を授けた。だから、あなたがたに害をおよぼす者はまったく無いであろう。"}, "20": {"en": "Nevertheless, don’t rejoice in this, that the spirits are subject to you, but rejoice that your names are written in heaven.”", "zh": "然而，不要因鬼服了你們就歡喜，要因你們的名記錄在天上歡喜。」", "ja": "しかし、霊があなたがたに服従することを喜ぶな。むしろ、あなたがたの名が天にしるされていることを喜びなさい」。"}, "21": {"en": "In that same hour, Jesus rejoiced in the Holy Spirit, and said, “I thank you, O Father, Lord of heaven and earth, that you have hidden these things from the wise and understanding, and revealed them to little children. Yes, Father, for so it was well-pleasing in your sight.”", "zh": "正當那時，耶穌被聖靈感動就歡樂，說：「父啊，天地的主，我感謝你！因為你將這些事向聰明通達人就藏起來，向嬰孩就顯出來。父啊！是的，因為你的美意本是如此。", "ja": "そのとき、イエスは聖霊によって喜びあふれて言われた、「天地の主なる父よ。あなたをほめたたえます。これらの事を知恵のある者や賢い者に隠して、幼な子にあらわしてくださいました。父よ、これはまことに、みこころにかなった事でした。"}, "22": {"en": "Turning to the disciples, he said, “All things have been delivered to me by my Father. No one knows who the Son is, except the Father, and who the Father is, except the Son, and he to whomever the Son desires to reveal him.”", "zh": "一切所有的都是我父交付我的；除了父，沒有人知道子是誰；除了子和子所願意指示的，沒有人知道父是誰。」", "ja": "すべての事は父からわたしに任せられています。そして、子がだれであるかは、父のほか知っている者はありません。また父がだれであるかは、子と、父をあらわそうとして子が選んだ者とのほか、だれも知っている者はいません」。"}, "23": {"en": "Turning to the disciples, he said privately, “Blessed are the eyes which see the things that you see,", "zh": "耶穌轉身暗暗地對門徒說：「看見你們所看見的，那眼睛就有福了。", "ja": "それから弟子たちの方に振りむいて、ひそかに言われた、「あなたがたが見ていることを見る目は、さいわいである。"}, "24": {"en": "for I tell you that many prophets and kings desired to see the things which you see, and didn’t see them, and to hear the things which you hear, and didn’t hear them.”", "zh": "我告訴你們，從前有許多先知和君王要看你們所看的，卻沒有看見，要聽你們所聽的，卻沒有聽見。」", "ja": "あなたがたに言っておく。多くの預言者や王たちも、あなたがたの見ていることを見ようとしたが、見ることができず、あなたがたの聞いていることを聞こうとしたが、聞けなかったのである」。"}, "25": {"en": "Behold, a certain lawyer stood up and tested him, saying, “Teacher, what shall I do to inherit eternal life?”", "zh": "有一個律法師起來試探耶穌，說：「夫子！我該做甚麼才可以承受永生？」", "ja": "するとそこへ、ある律法学者が現れ、イエスを試みようとして言った、「先生、何をしたら永遠の生命が受けられましょうか」。"}, "26": {"en": "He said to him, “What is written in the law? How do you read it?”", "zh": "耶穌對他說：「律法上寫的是甚麼？你念的是怎樣呢？」", "ja": "彼に言われた、「律法にはなんと書いてあるか。あなたはどう読むか」。"}, "27": {"en": "He answered, “You shall love the Lord your God with all your heart, with all your soul, with all your strength, and with all your mind; and your neighbor as yourself.”", "zh": "他回答說：「你要盡心、盡性、盡力、盡意愛主－你的上帝；又要愛鄰舍如同自己。」", "ja": "彼は答えて言った、「『心をつくし、精神をつくし、力をつくし、思いをつくして、主なるあなたの神を愛せよ』。また、『自分を愛するように、あなたの隣り人を愛せよ』とあります」。"}, "28": {"en": "He said to him, “You have answered correctly. Do this, and you will live.”", "zh": "耶穌說：「你回答的是；你這樣行，就必得永生。」", "ja": "彼に言われた、「あなたの答は正しい。そのとおり行いなさい。そうすれば、いのちが得られる」。"}, "29": {"en": "But he, desiring to justify himself, asked Jesus, “Who is my neighbor?”", "zh": "那人要顯明自己有理，就對耶穌說：「誰是我的鄰舍呢？」", "ja": "すると彼は自分の立場を弁護しようと思って、イエスに言った、「では、わたしの隣り人とはだれのことですか」。"}, "30": {"en": "Jesus answered, “A certain man was going down from Jerusalem to Jericho, and he fell among robbers, who both stripped him and beat him, and departed, leaving him half dead.", "zh": "耶穌回答說：「有一個人從耶路撒冷下耶利哥去，落在強盜手中。他們剝去他的衣裳，把他打個半死，就丟下他走了。", "ja": "イエスが答えて言われた、「ある人がエルサレムからエリコに下って行く途中、強盗どもが彼を襲い、その着物をはぎ取り、傷を負わせ、半殺しにしたまま、逃げ去った。"}, "31": {"en": "By chance a certain priest was going down that way. When he saw him, he passed by on the other side.", "zh": "偶然有一個祭司從這條路下來，看見他就從那邊過去了。", "ja": "するとたまたま、ひとりの祭司がその道を下ってきたが、この人を見ると、向こう側を通って行った。"}, "32": {"en": "In the same way a Levite also, when he came to the place and saw him, passed by on the other side.", "zh": "又有一個利未人來到這地方，看見他，也照樣從那邊過去了。", "ja": "同様に、レビ人もこの場所にさしかかってきたが、彼を見ると向こう側を通って行った。"}, "33": {"en": "But a certain Samaritan, as he traveled, came where he was. When he saw him, he was moved with compassion,", "zh": "惟有一個撒馬利亞人行路來到那裏，看見他就動了慈心，", "ja": "ところが、あるサマリヤ人が旅をしてこの人のところを通りかかり、彼を見て気の毒に思い、"}, "34": {"en": "came to him, and bound up his wounds, pouring on oil and wine. He set him on his own animal, brought him to an inn, and took care of him.", "zh": "上前用油和酒倒在他的傷處，包裹好了，扶他騎上自己的牲口，帶到店裏去照應他。", "ja": "近寄ってきてその傷にオリブ油とぶどう酒とを注いでほうたいをしてやり、自分の家畜に乗せ、宿屋に連れて行って介抱した。"}, "35": {"en": "On the next day, when he departed, he took out two denarii, gave them to the host, and said to him, ‘Take care of him. Whatever you spend beyond that, I will repay you when I return.’", "zh": "第二天拿出二錢銀子來，交給店主，說：『你且照應他；此外所費用的，我回來必還你。』", "ja": "翌日、デナリ二つを取り出して宿屋の主人に手渡し、『この人を見てやってください。費用がよけいにかかったら、帰りがけに、わたしが支払います』と言った。"}, "36": {"en": "Now which of these three do you think seemed to be a neighbor to him who fell among the robbers?”", "zh": "你想，這三個人哪一個是落在強盜手中的鄰舍呢？」", "ja": "この三人のうち、だれが強盗に襲われた人の隣り人になったと思うか」。"}, "37": {"en": "He said, “He who showed mercy on him.” Then Jesus said to him, “Go and do likewise.”", "zh": "他說：「是憐憫他的。」耶穌說：「你去照樣行吧。」", "ja": "彼が言った、「その人に慈悲深い行いをした人です」。そこでイエスは言われた、「あなたも行って同じようにしなさい」。"}, "38": {"en": "As they went on their way, he entered into a certain village, and a certain woman named Martha received him into her house.", "zh": "他們走路的時候，耶穌進了一個村莊。有一個女人，名叫馬大，接他到自己家裏。", "ja": "一同が旅を続けているうちに、イエスがある村へはいられた。するとマルタという名の女がイエスを家に迎え入れた。"}, "39": {"en": "She had a sister called Mary, who also sat at Jesus’ feet and heard his word.", "zh": "她有一個妹子，名叫馬利亞，在耶穌腳前坐着聽他的道。", "ja": "この女にマリヤという妹がいたが、主の足もとにすわって、御言に聞き入っていた。"}, "40": {"en": "But Martha was distracted with much serving, and she came up to him, and said, “Lord, don’t you care that my sister left me to serve alone? Ask her therefore to help me.”", "zh": "馬大伺候的事多，心裏忙亂，就進前來，說：「主啊，我的妹子留下我一個人伺候，你不在意嗎？請吩咐她來幫助我。」", "ja": "ところが、マルタは接待のことで忙がしくて心をとりみだし、イエスのところにきて言った、「主よ、妹がわたしだけに接待をさせているのを、なんともお思いになりませんか。わたしの手伝いをするように妹におっしゃってください」。"}, "41": {"en": "Jesus answered her, “Martha, Martha, you are anxious and troubled about many things,", "zh": "耶穌回答說：「馬大！馬大！你為許多的事思慮煩擾，", "ja": "主は答えて言われた、「マルタよ、マルタよ、あなたは多くのことに心を配って思いわずらっている。"}, "42": {"en": "but one thing is needed. Mary has chosen the good part, which will not be taken away from her.”", "zh": "但是不可少的只有一件；馬利亞已經選擇那上好的福分，是不能奪去的。」", "ja": "しかし、無くてならぬものは多くはない。いや、一つだけである。マリヤはその良い方を選んだのだ。そしてそれは、彼女から取り去ってはならないものである」。"}}}, "11": {"verses": {"1": {"en": "When he finished praying in a certain place, one of his disciples said to him, “Lord, teach us to pray, just as John also taught his disciples.”", "zh": "耶穌在一個地方禱告；禱告完了，有個門徒對他說：「求主教導我們禱告，像約翰教導他的門徒。」", "ja": "また、イエスはある所で祈っておられたが、それが終ったとき、弟子のひとりが言った、「主よ、ヨハネがその弟子たちに教えたように、わたしたちにも祈ることを教えてください」。"}, "2": {"en": "He said to them, “When you pray, say, ‘Our Father in heaven, may your name be kept holy. May your Kingdom come. May your will be done on earth, as it is in heaven.", "zh": "耶穌說：「你們禱告的時候，要說： 我們在天上的父： 願人都尊你的名為聖。 願你的國降臨； 願你的旨意行在地上， 如同行在天上。", "ja": "そこで彼らに言われた、「祈るときには、こう言いなさい、『父よ、御名があがめられますように。御国がきますように。"}, "3": {"en": "Give us day by day our daily bread.", "zh": "我們日用的飲食， 天天賜給我們。", "ja": "わたしたちの日ごとの食物を、日々お与えください。"}, "4": {"en": "Forgive us our sins, for we ourselves also forgive everyone who is indebted to us. Bring us not into temptation, but deliver us from the evil one.’ ”", "zh": "赦免我們的罪， 因為我們也赦免凡虧欠我們的人。 不叫我們遇見試探； 救我們脫離凶惡。」", "ja": "わたしたちに負債のある者を皆ゆるしますから、わたしたちの罪をもおゆるしください。わたしたちを試みに会わせないでください』」。"}, "5": {"en": "He said to them, “Which of you, if you go to a friend at midnight and tell him, ‘Friend, lend me three loaves of bread,", "zh": "耶穌又說：「你們中間誰有一個朋友半夜到他那裏去，說：『朋友！請借給我三個餅；", "ja": "そして彼らに言われた、「あなたがたのうちのだれかに、友人があるとして、その人のところへ真夜中に行き、『友よ、パンを三つ貸してください。"}, "6": {"en": "for a friend of mine has come to me from a journey, and I have nothing to set before him,’", "zh": "因為我有一個朋友行路，來到我這裏，我沒有甚麼給他擺上。』", "ja": "友だちが旅先からわたしのところに着いたのですが、何も出すものがありませんから』と言った場合、"}, "7": {"en": "and he from within will answer and say, ‘Don’t bother me. The door is now shut, and my children are with me in bed. I can’t get up and give it to you’?", "zh": "那人在裏面回答說：『不要攪擾我，門已經關閉，孩子們也同我在床上了，我不能起來給你。』", "ja": "彼は内から、『面倒をかけないでくれ。もう戸は締めてしまったし、子供たちもわたしと一緒に床にはいっているので、いま起きて何もあげるわけにはいかない』と言うであろう。"}, "8": {"en": "I tell you, although he will not rise and give it to him because he is his friend, yet because of his persistence, he will get up and give him as many as he needs.", "zh": "我告訴你們，雖不因他是朋友起來給他，但因他情詞迫切地直求，就必起來照他所需用的給他。", "ja": "しかし、よく聞きなさい、友人だからというのでは起きて与えないが、しきりに願うので、起き上がって必要なものを出してくれるであろう。"}, "9": {"en": "“I tell you, keep asking, and it will be given you. Keep seeking, and you will find. Keep knocking, and it will be opened to you.", "zh": "我又告訴你們，你們祈求，就給你們；尋找，就尋見；叩門，就給你們開門。", "ja": "そこでわたしはあなたがたに言う。求めよ、そうすれば、与えられるであろう。捜せ、そうすれば見いだすであろう。門をたたけ、そうすれば、あけてもらえるであろう。"}, "10": {"en": "For everyone who asks receives. He who seeks finds. To him who knocks it will be opened.", "zh": "因為，凡祈求的，就得着；尋找的，就尋見；叩門的，就給他開門。", "ja": "すべて求める者は得、捜す者は見いだし、門をたたく者はあけてもらえるからである。"}, "11": {"en": "“Which of you fathers, if your son asks for bread, will give him a stone? Or if he asks for a fish, he won’t give him a snake instead of a fish, will he?", "zh": "你們中間作父親的，誰有兒子求餅，反給他石頭呢？求魚，反拿蛇當魚給他呢？", "ja": "あなたがたのうちで、父であるものは、その子が魚を求めるのに、魚の代りにへびを与えるだろうか。"}, "12": {"en": "Or if he asks for an egg, he won’t give him a scorpion, will he?", "zh": "求雞蛋，反給他蠍子呢？", "ja": "卵を求めるのに、さそりを与えるだろうか。"}, "13": {"en": "If you then, being evil, know how to give good gifts to your children, how much more will your heavenly Father give the Holy Spirit to those who ask him?”", "zh": "你們雖然不好，尚且知道拿好東西給兒女；何況天父，豈不更將聖靈給求他的人嗎？」", "ja": "このように、あなたがたは悪い者であっても、自分の子供には、良い贈り物をすることを知っているとすれば、天の父はなおさら、求めて来る者に聖霊を下さらないことがあろうか」。"}, "14": {"en": "He was casting out a demon, and it was mute. When the demon had gone out, the mute man spoke; and the multitudes marveled.", "zh": "耶穌趕出一個叫人啞巴的鬼；鬼出去了，啞巴就說出話來；眾人都希奇。", "ja": "さて、イエスが悪霊を追い出しておられた。それは、おしの霊であった。悪霊が出て行くと、おしが物を言うようになったので、群衆は不思議に思った。"}, "15": {"en": "But some of them said, “He casts out demons by Beelzebul, the prince of the demons.”", "zh": "內中卻有人說：「他是靠着鬼王別西卜趕鬼。」", "ja": "その中のある人々が、「彼は悪霊のかしらベルゼブルによって、悪霊どもを追い出しているのだ」と言い、"}, "16": {"en": "Others, testing him, sought from him a sign from heaven.", "zh": "又有人試探耶穌，向他求從天上來的神蹟。", "ja": "またほかの人々は、イエスを試みようとして、天からのしるしを求めた。"}, "17": {"en": "But he, knowing their thoughts, said to them, “Every kingdom divided against itself is brought to desolation. A house divided against itself falls.", "zh": "他曉得他們的意念，便對他們說：「凡一國自相紛爭，就成為荒場；凡一家自相紛爭，就必敗落。", "ja": "しかしイエスは、彼らの思いを見抜いて言われた、「おおよそ国が内部で分裂すれば自滅してしまい、また家が分れ争えば倒れてしまう。"}, "18": {"en": "If Satan also is divided against himself, how will his kingdom stand? For you say that I cast out demons by Beelzebul.", "zh": "若撒但自相紛爭，他的國怎能站得住呢？因為你們說我是靠着別西卜趕鬼。", "ja": "そこでサタンも内部で分裂すれば、その国はどうして立ち行けよう。あなたがたはわたしがベルゼブルによって悪霊を追い出していると言うが、"}, "19": {"en": "But if I cast out demons by Beelzebul, by whom do your children cast them out? Therefore they will be your judges.", "zh": "我若靠着別西卜趕鬼，你們的子弟趕鬼又靠着誰呢？這樣，他們就要斷定你們的是非。", "ja": "もしわたしがベルゼブルによって悪霊を追い出すとすれば、あなたがたの仲間はだれによって追い出すのであろうか。だから、彼らがあなたがたをさばく者となるであろう。"}, "20": {"en": "But if I by God’s finger cast out demons, then God’s Kingdom has come to you.", "zh": "我若靠着上帝的能力趕鬼，這就是上帝的國臨到你們了。", "ja": "しかし、わたしが神の指によって悪霊を追い出しているのなら、神の国はすでにあなたがたのところにきたのである。"}, "21": {"en": "“When the strong man, fully armed, guards his own dwelling, his goods are safe.", "zh": "壯士披掛整齊，看守自己的住宅，他所有的都平安無事；", "ja": "強い人が十分に武装して自分の邸宅を守っている限り、その持ち物は安全である。"}, "22": {"en": "But when someone stronger attacks him and overcomes him, he takes from him his whole armor in which he trusted, and divides his plunder.", "zh": "但有一個比他更壯的來，勝過他，就奪去他所倚靠的盔甲兵器，又分了他的贓。", "ja": "しかし、もっと強い者が襲ってきて彼に打ち勝てば、その頼みにしていた武具を奪って、その分捕品を分けるのである。"}, "23": {"en": "“He who is not with me is against me. He who doesn’t gather with me scatters.", "zh": "不與我相合的，就是敵我的；不同我收聚的，就是分散的。」", "ja": "わたしの味方でない者は、わたしに反対するものであり、わたしと共に集めない者は、散らすものである。"}, "24": {"en": "The unclean spirit, when he has gone out of the man, passes through dry places, seeking rest; and finding none, he says, ‘I will turn back to my house from which I came out.’", "zh": "「污鬼離了人身，就在無水之地過來過去，尋求安歇之處；既尋不着，便說：『我要回到我所出來的屋裏去。』", "ja": "汚れた霊が人から出ると、休み場を求めて水の無い所を歩きまわるが、見つからないので、出てきた元の家に帰ろうと言って、"}, "25": {"en": "When he returns, he finds it swept and put in order.", "zh": "到了，就看見裏面打掃乾淨，修飾好了，", "ja": "帰って見ると、その家はそうじがしてある上、飾りつけがしてあった。"}, "26": {"en": "Then he goes and takes seven other spirits more evil than himself, and they enter in and dwell there. The last state of that man becomes worse than the first.”", "zh": "便去另帶了七個比自己更惡的鬼來，都進去住在那裏。那人末後的景況比先前更不好了。」", "ja": "そこでまた出て行って、自分以上に悪い他の七つの霊を引き連れてきて中にはいり、そこに住み込む。そうすると、その人の後の状態は初めよりももっと悪くなるのである」。"}, "27": {"en": "It came to pass, as he said these things, a certain woman out of the multitude lifted up her voice and said to him, “Blessed is the womb that bore you, and the breasts which nursed you!”", "zh": "耶穌正說這話的時候，眾人中間有一個女人大聲說：「懷你胎的和乳養你的有福了！」", "ja": "イエスがこう話しておられるとき、群衆の中からひとりの女が声を張りあげて言った、「あなたを宿した胎、あなたが吸われた乳房は、なんとめぐまれていることでしょう」。"}, "28": {"en": "But he said, “On the contrary, blessed are those who hear the word of God, and keep it.”", "zh": "耶穌說：「是，卻還不如聽上帝之道而遵守的人有福。」", "ja": "しかしイエスは言われた、「いや、めぐまれているのは、むしろ、神の言を聞いてそれを守る人たちである」。"}, "29": {"en": "When the multitudes were gathering together to him, he began to say, “This is an evil generation. It seeks after a sign. No sign will be given to it but the sign of Jonah the prophet.", "zh": "當眾人聚集的時候，耶穌開講說：「這世代是一個邪惡的世代。他們求看神蹟，除了約拿的神蹟以外，再沒有神蹟給他們看。", "ja": "さて群衆が群がり集まったので、イエスは語り出された、「この時代は邪悪な時代である。それはしるしを求めるが、ヨナのしるしのほかには、なんのしるしも与えられないであろう。"}, "30": {"en": "For even as Jonah became a sign to the Ninevites, so the Son of Man will also be to this generation.", "zh": "約拿怎樣為尼尼微人成了神蹟，人子也要照樣為這世代的人成了神蹟。", "ja": "というのは、ニネベの人々に対してヨナがしるしとなったように、人の子もこの時代に対してしるしとなるであろう。"}, "31": {"en": "The Queen of the South will rise up in the judgment with the men of this generation and will condemn them, for she came from the ends of the earth to hear the wisdom of Solomon; and behold, one greater than Solomon is here.", "zh": "當審判的時候，南方的女王要起來定這世代的罪；因為她從地極而來，要聽所羅門的智慧話。看哪，在這裏有一人比所羅門更大。", "ja": "南の女王が、今の時代の人々と共にさばきの場に立って、彼らを罪に定めるであろう。なぜなら、彼女はソロモンの知恵を聞くために、地の果からはるばるきたからである。しかし見よ、ソロモンにまさる者がここにいる。"}, "32": {"en": "The men of Nineveh will stand up in the judgment with this generation, and will condemn it, for they repented at the preaching of Jonah; and behold, one greater than Jonah is here.", "zh": "當審判的時候，尼尼微人要起來定這世代的罪，因為尼尼微人聽了約拿所傳的就悔改了。看哪，在這裏有一人比約拿更大。」", "ja": "ニネベの人々が、今の時代の人々と共にさばきの場に立って、彼らを罪に定めるであろう。なぜなら、ニネベの人々はヨナの宣教によって悔い改めたからである。しかし見よ、ヨナにまさる者がここにいる。"}, "33": {"en": "“No one, when he has lit a lamp, puts it in a cellar or under a basket, but on a stand, that those who come in may see the light.", "zh": "「沒有人點燈放在地窨子裏，或是斗底下，總是放在燈臺上，使進來的人得見亮光。", "ja": "だれもあかりをともして、それを穴倉の中や枡の下に置くことはしない。むしろはいって来る人たちに、そのあかりが見えるように、燭台の上におく。"}, "34": {"en": "The lamp of the body is the eye. Therefore when your eye is good, your whole body is also full of light; but when it is evil, your body also is full of darkness.", "zh": "你眼睛就是身上的燈。你的眼睛若瞭亮，全身就光明；眼睛若昏花，全身就黑暗。", "ja": "あなたの目は、からだのあかりである。あなたの目が澄んでおれば、全身も明るいが、目がわるければ、からだも暗い。"}, "35": {"en": "Therefore see whether the light that is in you isn’t darkness.", "zh": "所以，你要省察，恐怕你裏頭的光或者黑暗了。", "ja": "だから、あなたの内なる光が暗くならないように注意しなさい。"}, "36": {"en": "If therefore your whole body is full of light, having no part dark, it will be wholly full of light, as when the lamp with its bright shining gives you light.”", "zh": "若是你全身光明，毫無黑暗，就必全然光明，如同燈的明光照亮你。」", "ja": "もし、あなたのからだ全体が明るくて、暗い部分が少しもなければ、ちょうど、あかりが輝いてあなたを照す時のように、全身が明るくなるであろう」。"}, "37": {"en": "Now as he spoke, a certain Pharisee asked him to dine with him. He went in and sat at the table.", "zh": "說話的時候，有一個法利賽人請耶穌同他吃飯，耶穌就進去坐席。", "ja": "イエスが語っておられた時、あるパリサイ人が、自分の家で食事をしていただきたいと申し出たので、はいって食卓につかれた。"}, "38": {"en": "When the Pharisee saw it, he marveled that he had not first washed himself before dinner.", "zh": "這法利賽人看見耶穌飯前不洗手便詫異。", "ja": "ところが、食前にまず洗うことをなさらなかったのを見て、そのパリサイ人が不思議に思った。"}, "39": {"en": "The Lord said to him, “Now you Pharisees cleanse the outside of the cup and of the platter, but your inward part is full of extortion and wickedness.", "zh": "主對他說：「如今你們法利賽人洗淨杯盤的外面，你們裏面卻滿了勒索和邪惡。", "ja": "そこで主は彼に言われた、「いったい、あなたがたパリサイ人は、杯や盆の外側をきよめるが、あなたがたの内側は貪欲と邪悪とで満ちている。"}, "40": {"en": "You foolish ones, didn’t he who made the outside make the inside also?", "zh": "無知的人哪，造外面的，不也造裏面嗎？", "ja": "愚かな者たちよ、外側を造ったかたは、また内側も造られたではないか。"}, "41": {"en": "But give for gifts to the needy those things which are within, and behold, all things will be clean to you.", "zh": "只要把裏面的施捨給人，凡物於你們就都潔淨了。", "ja": "ただ、内側にあるものをきよめなさい。そうすれば、いっさいがあなたがたにとって、清いものとなる。"}, "42": {"en": "But woe to you Pharisees! For you tithe mint and rue and every herb, but you bypass justice and God’s love. You ought to have done these, and not to have left the other undone.", "zh": "「你們法利賽人有禍了！因為你們將薄荷、芸香並各樣菜蔬獻上十分之一，那公義和愛上帝的事反倒不行了。這原是你們當行的；那也是不可不行的。", "ja": "しかし、あなた方パリサイ人は、わざわいである。はっか、うん香、あらゆる野菜などの十分の一を宮に納めておりながら、義と神に対する愛とをなおざりにしている。それもなおざりにはできないが、これは行わねばならない。"}, "43": {"en": "Woe to you Pharisees! For you love the best seats in the synagogues and the greetings in the marketplaces.", "zh": "你們法利賽人有禍了！因為你們喜愛會堂裏的首位，又喜愛人在街市上問你們的安。", "ja": "あなたがたパリサイ人は、わざわいである。会堂の上席や広場での敬礼を好んでいる。"}, "44": {"en": "Woe to you, scribes and Pharisees, hypocrites! For you are like hidden graves, and the men who walk over them don’t know it.”", "zh": "你們有禍了！因為你們如同不顯露的墳墓，走在上面的人並不知道。」", "ja": "あなたがたは、わざわいである。人目につかない墓のようなものである。その上を歩いても人々は気づかないでいる」。"}, "45": {"en": "One of the lawyers answered him, “Teacher, in saying this you insult us also.”", "zh": "律法師中有一個回答耶穌說：「夫子！你這樣說也把我們糟蹋了。」", "ja": "ひとりの律法学者がイエスに答えて言った、「先生、そんなことを言われるのは、わたしたちまでも侮辱することです」。"}, "46": {"en": "He said, “Woe to you lawyers also! For you load men with burdens that are difficult to carry, and you yourselves won’t even lift one finger to help carry those burdens.", "zh": "耶穌說：「你們律法師也有禍了！因為你們把難擔的擔子放在人身上，自己一個指頭卻不肯動。", "ja": "そこで言われた、「あなたがた律法学者も、わざわいである。負い切れない重荷を人に負わせながら、自分ではその荷に指一本でも触れようとしない。"}, "47": {"en": "Woe to you! For you build the tombs of the prophets, and your fathers killed them.", "zh": "你們有禍了！因為你們修造先知的墳墓，那先知正是你們的祖宗所殺的。", "ja": "あなたがたは、わざわいである。預言者たちの碑を建てるが、しかし彼らを殺したのは、あなたがたの先祖であったのだ。"}, "48": {"en": "So you testify and consent to the works of your fathers. For they killed them, and you build their tombs.", "zh": "可見你們祖宗所做的事，你們又證明又喜歡；因為他們殺了先知，你們修造先知的墳墓。", "ja": "だから、あなたがたは、自分の先祖のしわざに同意する証人なのだ。先祖が彼らを殺し、あなたがたがその碑を建てるのだから。"}, "49": {"en": "Therefore also the wisdom of God said, ‘I will send to them prophets and apostles; and some of them they will kill and persecute,", "zh": "所以上帝用智慧曾說：『我要差遣先知和使徒到他們那裏去，有的他們要殺害，有的他們要逼迫』，", "ja": "それゆえに、『神の知恵』も言っている、『わたしは預言者と使徒とを彼らにつかわすが、彼らはそのうちのある者を殺したり、迫害したりするであろう』。"}, "50": {"en": "that the blood of all the prophets, which was shed from the foundation of the world, may be required of this generation,", "zh": "使創世以來所流眾先知血的罪都要問在這世代的人身上，", "ja": "それで、アベルの血から祭壇と神殿との間で殺されたザカリヤの血に至るまで、世の初めから流されてきたすべての預言者の血について、この時代がその責任を問われる。"}, "51": {"en": "from the blood of Abel to the blood of Zachariah, who perished between the altar and the sanctuary.’ Yes, I tell you, it will be required of this generation.", "zh": "就是從亞伯的血起，直到被殺在壇和殿中間撒迦利亞的血為止。我實在告訴你們，這都要問在這世代的人身上。", "ja": "そうだ、あなたがたに言っておく、この時代がその責任を問われるであろう。"}, "52": {"en": "Woe to you lawyers! For you took away the key of knowledge. You didn’t enter in yourselves, and those who were entering in, you hindered.”", "zh": "你們律法師有禍了！因為你們把知識的鑰匙奪了去，自己不進去，正要進去的人你們也阻擋他們。」", "ja": "あなたがた律法学者は、わざわいである。知識のかぎを取りあげて、自分がはいらないばかりか、はいろうとする人たちを妨げてきた」。"}, "53": {"en": "As he said these things to them, the scribes and the Pharisees began to be terribly angry, and to draw many things out of him,", "zh": "耶穌從那裏出來，文士和法利賽人就極力地催逼他，引動他多說話，", "ja": "イエスがそこを出て行かれると、律法学者やパリサイ人は、激しく詰め寄り、いろいろな事を問いかけて、"}, "54": {"en": "lying in wait for him, and seeking to catch him in something he might say, that they might accuse him.", "zh": "私下窺聽，要拿他的話柄。", "ja": "イエスの口から何か言いがかりを得ようと、ねらいはじめた。"}}}, "12": {"verses": {"1": {"en": "Meanwhile, when a multitude of many thousands had gathered together, so much so that they trampled on each other, he began to tell his disciples first of all, “Beware of the yeast of the Pharisees, which is hypocrisy.", "zh": "這時，有幾萬人聚集，甚至彼此踐踏。耶穌開講，先對門徒說：「你們要防備法利賽人的酵，就是假冒為善。", "ja": "その間に、おびただしい群衆が、互に踏み合うほどに群がってきたが、イエスはまず弟子たちに語りはじめられた、「パリサイ人のパン種、すなわち彼らの偽善に気をつけなさい。"}, "2": {"en": "But there is nothing covered up that will not be revealed, nor hidden that will not be known.", "zh": "掩蓋的事沒有不露出來的；隱藏的事沒有不被人知道的。", "ja": "おおいかぶされたもので、現れてこないものはなく、隠れているもので、知られてこないものはない。"}, "3": {"en": "Therefore whatever you have said in the darkness will be heard in the light. What you have spoken in the ear in the inner rooms will be proclaimed on the housetops.", "zh": "因此，你們在暗中所說的，將要在明處被人聽見；在內室附耳所說的，將要在房上被人宣揚。」", "ja": "だから、あなたがたが暗やみで言ったことは、なんでもみな明るみで聞かれ、密室で耳にささやいたことは、屋根の上で言いひろめられるであろう。"}, "4": {"en": "“I tell you, my friends, don’t be afraid of those who kill the body, and after that have no more that they can do.", "zh": "「我的朋友，我對你們說，那殺身體以後不能再做甚麼的，不要怕他們。", "ja": "そこでわたしの友であるあなたがたに言うが、からだを殺しても、そのあとでそれ以上なにもできない者どもを恐れるな。"}, "5": {"en": "But I will warn you whom you should fear. Fear him who after he has killed, has power to cast into Gehenna. Yes, I tell you, fear him.", "zh": "我要指示你們當怕的是誰：當怕那殺了以後又有權柄丟在地獄裏的。我實在告訴你們，正要怕他。", "ja": "恐るべき者がだれであるか、教えてあげよう。殺したあとで、更に地獄に投げ込む権威のあるかたを恐れなさい。そうだ、あなたがたに言っておくが、そのかたを恐れなさい。"}, "6": {"en": "“Aren’t five sparrows sold for two assaria coins? Not one of them is forgotten by God.", "zh": "五個麻雀不是賣二分銀子嗎？但在上帝面前，一個也不忘記；", "ja": "五羽のすずめは二アサリオンで売られているではないか。しかも、その一羽も神のみまえで忘れられてはいない。"}, "7": {"en": "But the very hairs of your head are all counted. Therefore don’t be afraid. You are of more value than many sparrows.", "zh": "就是你們的頭髮，也都被數過了。不要懼怕，你們比許多麻雀還貴重！」", "ja": "その上、あなたがたの頭の毛までも、みな数えられている。恐れることはない。あなたがたは多くのすずめよりも、まさった者である。"}, "8": {"en": "“I tell you, everyone who confesses me before men, the Son of Man will also confess before the angels of God;", "zh": "「我又告訴你們，凡在人面前認我的，人子在上帝的使者面前也必認他；", "ja": "そこで、あなたがたに言う。だれでも人の前でわたしを受けいれる者を、人の子も神の使たちの前で受けいれるであろう。"}, "9": {"en": "but he who denies me in the presence of men will be denied in the presence of God’s angels.", "zh": "在人面前不認我的，人子在上帝的使者面前也必不認他。", "ja": "しかし、人の前でわたしを拒む者は、神の使たちの前で拒まれるであろう。"}, "10": {"en": "Everyone who speaks a word against the Son of Man will be forgiven, but those who blaspheme against the Holy Spirit will not be forgiven.", "zh": "凡說話干犯人子的，還可得赦免；惟獨褻瀆聖靈的，總不得赦免。", "ja": "また、人の子に言い逆らう者はゆるされるであろうが、聖霊をけがす者は、ゆるされることはない。"}, "11": {"en": "When they bring you before the synagogues, the rulers, and the authorities, don’t be anxious how or what you will answer or what you will say;", "zh": "人帶你們到會堂，並官府和有權柄的人面前，不要思慮怎麼分訴，說甚麼話；", "ja": "あなたがたが会堂や役人や高官の前へひっぱられて行った場合には、何をどう弁明しようか、何を言おうかと心配しないがよい。"}, "12": {"en": "for the Holy Spirit will teach you in that same hour what you must say.”", "zh": "因為正在那時候，聖靈要指教你們當說的話。」", "ja": "言うべきことは、聖霊がその時に教えてくださるからである」。"}, "13": {"en": "One of the multitude said to him, “Teacher, tell my brother to divide the inheritance with me.”", "zh": "眾人中有一個人對耶穌說：「夫子！請你吩咐我的兄長和我分開家業。」", "ja": "群衆の中のひとりがイエスに言った、「先生、わたしの兄弟に、遺産を分けてくれるようにおっしゃってください」。"}, "14": {"en": "But he said to him, “Man, who made me a judge or an arbitrator over you?”", "zh": "耶穌說：「你這個人！誰立我作你們斷事的官，給你們分家業呢？」", "ja": "彼に言われた、「人よ、だれがわたしをあなたがたの裁判人または分配人に立てたのか」。"}, "15": {"en": "He said to them, “Beware! Keep yourselves from covetousness, for a man’s life doesn’t consist of the abundance of the things which he possesses.”", "zh": "於是對眾人說：「你們要謹慎自守，免去一切的貪心，因為人的生命不在乎家道豐富。」", "ja": "それから人々にむかって言われた、「あらゆる貪欲に対してよくよく警戒しなさい。たといたくさんの物を持っていても、人のいのちは、持ち物にはよらないのである」。"}, "16": {"en": "He spoke a parable to them, saying, “The ground of a certain rich man produced abundantly.", "zh": "就用比喻對他們說：「有一個財主田產豐盛；", "ja": "そこで一つの譬を語られた、「ある金持の畑が豊作であった。"}, "17": {"en": "He reasoned within himself, saying, ‘What will I do, because I don’t have room to store my crops?’", "zh": "自己心裏思想說：『我的出產沒有地方收藏，怎麼辦呢？』", "ja": "そこで彼は心の中で、『どうしようか、わたしの作物をしまっておく所がないのだが』と思いめぐらして"}, "18": {"en": "He said, ‘This is what I will do. I will pull down my barns, build bigger ones, and there I will store all my grain and my goods.", "zh": "又說：『我要這麼辦：要把我的倉房拆了，另蓋更大的，在那裏好收藏我一切的糧食和財物，", "ja": "言った、『こうしよう。わたしの倉を取りこわし、もっと大きいのを建てて、そこに穀物や食糧を全部しまい込もう。"}, "19": {"en": "I will tell my soul, “Soul, you have many goods laid up for many years. Take your ease, eat, drink, and be merry.” ’", "zh": "然後要對我的靈魂說：靈魂哪，你有許多財物積存，可作多年的費用，只管安安逸逸地吃喝快樂吧！』", "ja": "そして自分の魂に言おう。たましいよ、おまえには長年分の食糧がたくさんたくわえてある。さあ安心せよ、食え、飲め、楽しめ』。"}, "20": {"en": "“But God said to him, ‘You foolish one, tonight your soul is required of you. The things which you have prepared—whose will they be?’", "zh": "上帝卻對他說：『無知的人哪，今夜必要你的靈魂；你所預備的要歸誰呢？』", "ja": "すると神が彼に言われた、『愚かな者よ、あなたの魂は今夜のうちにも取り去られるであろう。そしたら、あなたが用意した物は、だれのものになるのか』。"}, "21": {"en": "So is he who lays up treasure for himself, and is not rich toward God.”", "zh": "凡為自己積財，在上帝面前卻不富足的，也是這樣。」", "ja": "自分のために宝を積んで神に対して富まない者は、これと同じである」。"}, "22": {"en": "He said to his disciples, “Therefore I tell you, don’t be anxious for your life, what you will eat, nor yet for your body, what you will wear.", "zh": "耶穌又對門徒說：「所以我告訴你們，不要為生命憂慮吃甚麼，為身體憂慮穿甚麼；", "ja": "それから弟子たちに言われた、「それだから、あなたがたに言っておく。何を食べようかと、命のことで思いわずらい、何を着ようかとからだのことで思いわずらうな。"}, "23": {"en": "Life is more than food, and the body is more than clothing.", "zh": "因為生命勝於飲食，身體勝於衣裳。", "ja": "命は食物にまさり、からだは着物にまさっている。"}, "24": {"en": "Consider the ravens: they don’t sow, they don’t reap, they have no warehouse or barn, and God feeds them. How much more valuable are you than birds!", "zh": "你想烏鴉，也不種也不收，又沒有倉又沒有庫，上帝尚且養活牠。你們比飛鳥是何等地貴重呢！", "ja": "からすのことを考えて見よ。まくことも、刈ることもせず、また、納屋もなく倉もない。それだのに、神は彼らを養っていて下さる。あなたがたは鳥よりも、はるかにすぐれているではないか。"}, "25": {"en": "Which of you by being anxious can add a cubit to his height?", "zh": "你們哪一個能用思慮使壽數多加一刻呢？", "ja": "あなたがたのうち、だれが思いわずらったからとて、自分の寿命をわずかでも延ばすことができようか。"}, "26": {"en": "If then you aren’t able to do even the least things, why are you anxious about the rest?", "zh": "這最小的事，你們尚且不能做，為甚麼還憂慮其餘的事呢？", "ja": "そんな小さな事さえできないのに、どうしてほかのことを思いわずらうのか。"}, "27": {"en": "Consider the lilies, how they grow. They don’t toil, neither do they spin; yet I tell you, even Solomon in all his glory was not arrayed like one of these.", "zh": "你想百合花怎麼長起來；它也不勞苦，也不紡線。然而我告訴你們，就是所羅門極榮華的時候，他所穿戴的，還不如這花一朵呢！", "ja": "野の花のことを考えて見るがよい。紡ぎもせず、織りもしない。しかし、あなたがたに言うが、栄華をきわめた時のソロモンでさえ、この花の一つほどにも着飾ってはいなかった。"}, "28": {"en": "But if this is how God clothes the grass in the field, which today exists and tomorrow is cast into the oven, how much more will he clothe you, O you of little faith?", "zh": "你們這小信的人哪，野地裏的草今天還在，明天就丟在爐裏，上帝還給它這樣的妝飾，何況你們呢！", "ja": "きょうは野にあって、あすは炉に投げ入れられる草でさえ、神はこのように装って下さるのなら、あなたがたに、それ以上よくしてくださらないはずがあろうか。ああ、信仰の薄い者たちよ。"}, "29": {"en": "“Don’t seek what you will eat or what you will drink; neither be anxious.", "zh": "你們不要求吃甚麼，喝甚麼，也不要掛心；", "ja": "あなたがたも、何を食べ、何を飲もうかと、あくせくするな、また気を使うな。"}, "30": {"en": "For the nations of the world seek after all of these things, but your Father knows that you need these things.", "zh": "這都是外邦人所求的。你們必須用這些東西，你們的父是知道的。", "ja": "これらのものは皆、この世の異邦人が切に求めているものである。あなたがたの父は、これらのものがあなたがたに必要であることを、ご存じである。"}, "31": {"en": "But seek God’s Kingdom, and all these things will be added to you.", "zh": "你們只要求他的國，這些東西就必加給你們了。", "ja": "ただ、御国を求めなさい。そうすれば、これらのものは添えて与えられるであろう。"}, "32": {"en": "“Don’t be afraid, little flock, for it is your Father’s good pleasure to give you the Kingdom.", "zh": "你們這小群，不要懼怕，因為你們的父樂意把國賜給你們。", "ja": "恐れるな、小さい群れよ。御国を下さることは、あなたがたの父のみこころなのである。"}, "33": {"en": "Sell what you have and give gifts to the needy. Make for yourselves purses which don’t grow old, a treasure in the heavens that doesn’t fail, where no thief approaches and no moth destroys.", "zh": "你們要變賣所有的賙濟人，為自己預備永不壞的錢囊，用不盡的財寶在天上，就是賊不能近、蟲不能蛀的地方。", "ja": "自分の持ち物を売って、施しなさい。自分のために古びることのない財布をつくり、盗人も近寄らず、虫も食い破らない天に、尽きることのない宝をたくわえなさい。"}, "34": {"en": "For where your treasure is, there will your heart be also.", "zh": "因為，你們的財寶在哪裏，你們的心也在那裏。」", "ja": "あなたがたの宝のある所には、心もあるからである。"}, "35": {"en": "“Let your waist be dressed and your lamps burning.", "zh": "「你們腰裏要束上帶，燈也要點着，", "ja": "腰に帯をしめ、あかりをともしていなさい。"}, "36": {"en": "Be like men watching for their lord when he returns from the wedding feast, that when he comes and knocks, they may immediately open to him.", "zh": "自己好像僕人等候主人從婚姻的筵席上回來。他來到，叩門，就立刻給他開門。", "ja": "主人が婚宴から帰ってきて戸をたたくとき、すぐあけてあげようと待っている人のようにしていなさい。"}, "37": {"en": "Blessed are those servants whom the lord will find watching when he comes. Most certainly I tell you that he will dress himself, make them recline, and will come and serve them.", "zh": "主人來了，看見僕人警醒，那僕人就有福了。我實在告訴你們，主人必叫他們坐席，自己束上帶，進前伺候他們。", "ja": "主人が帰ってきたとき、目を覚しているのを見られる僕たちは、さいわいである。よく言っておく。主人が帯をしめて僕たちを食卓につかせ、進み寄って給仕をしてくれるであろう。"}, "38": {"en": "They will be blessed if he comes in the second or third watch and finds them so.", "zh": "或是二更天來，或是三更天來，看見僕人這樣，那僕人就有福了。", "ja": "主人が夜中ごろ、あるいは夜明けごろに帰ってきても、そうしているのを見られるなら、その人たちはさいわいである。"}, "39": {"en": "But know this, that if the master of the house had known in what hour the thief was coming, he would have watched and not allowed his house to be broken into.", "zh": "家主若知道賊甚麼時候來，就必警醒，不容賊挖透房屋，這是你們所知道的。", "ja": "このことを、わきまえているがよい。家の主人は、盗賊がいつごろ来るかわかっているなら、自分の家に押し入らせはしないであろう。"}, "40": {"en": "Therefore be ready also, for the Son of Man is coming in an hour that you don’t expect him.”", "zh": "你們也要預備；因為你們想不到的時候，人子就來了。」", "ja": "あなたがたも用意していなさい。思いがけない時に人の子が来るからである」。"}, "41": {"en": "Peter said to him, “Lord, are you telling this parable to us, or to everybody?”", "zh": "彼得說：「主啊，這比喻是為我們說的呢？還是為眾人呢？」", "ja": "するとペテロが言った、「主よ、この譬を話しておられるのはわたしたちのためなのですか。それとも、みんなの者のためなのですか」。"}, "42": {"en": "The Lord said, “Who then is the faithful and wise steward, whom his lord will set over his household, to give them their portion of food at the right times?", "zh": "主說：「誰是那忠心有見識的管家，主人派他管理家裏的人，按時分糧給他們呢？", "ja": "そこで主が言われた、「主人が、召使たちの上に立てて、時に応じて定めの食事をそなえさせる忠実な思慮深い家令は、いったいだれであろう。"}, "43": {"en": "Blessed is that servant whom his lord will find doing so when he comes.", "zh": "主人來到，看見僕人這樣行，那僕人就有福了。", "ja": "主人が帰ってきたとき、そのようにつとめているのを見られる僕は、さいわいである。"}, "44": {"en": "Truly I tell you that he will set him over all that he has.", "zh": "我實在告訴你們，主人要派他管理一切所有的。", "ja": "よく言っておくが、主人はその僕を立てて自分の全財産を管理させるであろう。"}, "45": {"en": "But if that servant says in his heart, ‘My lord delays his coming,’ and begins to beat the menservants and the maidservants, and to eat and drink and to be drunken,", "zh": "那僕人若心裏說：『我的主人必來得遲』，就動手打僕人和使女，並且吃喝醉酒；", "ja": "しかし、もしその僕が、主人の帰りがおそいと心の中で思い、男女の召使たちを打ちたたき、そして食べたり、飲んだりして酔いはじめるならば、"}, "46": {"en": "then the lord of that servant will come in a day when he isn’t expecting him and in an hour that he doesn’t know, and will cut him in two, and place his portion with the unfaithful.", "zh": "在他想不到的日子，不知道的時辰，那僕人的主人要來，重重地處治他，定他和不忠心的人同罪。", "ja": "その僕の主人は思いがけない日、気がつかない時に帰って来るであろう。そして、彼を厳罰に処して、不忠実なものたちと同じ目にあわせるであろう。"}, "47": {"en": "That servant who knew his lord’s will, and didn’t prepare nor do what he wanted, will be beaten with many stripes,", "zh": "僕人知道主人的意思，卻不預備，又不順他的意思行，那僕人必多受責打；", "ja": "主人のこころを知っていながら、それに従って用意もせず勤めもしなかった僕は、多くむち打たれるであろう。"}, "48": {"en": "but he who didn’t know, and did things worthy of stripes, will be beaten with few stripes. To whomever much is given, of him will much be required; and to whom much was entrusted, of him more will be asked.", "zh": "惟有那不知道的，做了當受責打的事，必少受責打；因為多給誰，就向誰多取；多託誰，就向誰多要。」", "ja": "しかし、知らずに打たれるようなことをした者は、打たれ方が少ないだろう。多く与えられた者からは多く求められ、多く任せられた者からは更に多く要求されるのである。"}, "49": {"en": "“I came to throw fire on the earth. I wish it were already kindled.", "zh": "「我來要把火丟在地上，倘若已經着起來，不也是我所願意的嗎？", "ja": "わたしは、火を地上に投じるためにきたのだ。火がすでに燃えていたならと、わたしはどんなに願っていることか。"}, "50": {"en": "But I have a baptism to be baptized with, and how distressed I am until it is accomplished!", "zh": "我有當受的洗還沒有成就，我是何等地迫切呢？", "ja": "しかし、わたしには受けねばならないバプテスマがある。そして、それを受けてしまうまでは、わたしはどんなにか苦しい思いをすることであろう。"}, "51": {"en": "Do you think that I have come to give peace on the earth? I tell you, no, but rather division.", "zh": "你們以為我來，是叫地上太平嗎？我告訴你們，不是，乃是叫人紛爭。", "ja": "あなたがたは、わたしが平和をこの地上にもたらすためにきたと思っているのか。あなたがたに言っておく。そうではない。むしろ分裂である。"}, "52": {"en": "For from now on, there will be five in one house divided, three against two, and two against three.", "zh": "從今以後，一家五個人將要紛爭：三個人和兩個人相爭，兩個人和三個人相爭；", "ja": "というのは、今から後は、一家の内で五人が相分れて、三人はふたりに、ふたりは三人に対立し、"}, "53": {"en": "They will be divided, father against son, and son against father; mother against daughter, and daughter against her mother; mother-in-law against her daughter-in-law, and daughter-in-law against her mother-in-law.”", "zh": "父親和兒子相爭， 兒子和父親相爭； 母親和女兒相爭， 女兒和母親相爭； 婆婆和媳婦相爭， 媳婦和婆婆相爭。」", "ja": "また父は子に、子は父に、母は娘に、娘は母に、しゅうとめは嫁に、嫁はしゅうとめに、対立するであろう」。"}, "54": {"en": "He said to the multitudes also, “When you see a cloud rising from the west, immediately you say, ‘A shower is coming,’ and so it happens.", "zh": "耶穌又對眾人說：「你們看見西邊起了雲彩，就說：『要下一陣雨』；果然就有。", "ja": "イエスはまた群衆に対しても言われた、「あなたがたは、雲が西に起るのを見るとすぐ、にわか雨がやって来る、と言う。果してそのとおりになる。"}, "55": {"en": "When a south wind blows, you say, ‘There will be a scorching heat,’ and it happens.", "zh": "起了南風，就說：『將要燥熱』；也就有了。", "ja": "それから南風が吹くと、暑つくなるだろう、と言う。果してそのとおりになる。"}, "56": {"en": "You hypocrites! You know how to interpret the appearance of the earth and the sky, but how is it that you don’t interpret this time?", "zh": "假冒為善的人哪，你們知道分辨天地的氣色，怎麼不知道分辨這時候呢？」", "ja": "偽善者よ、あなたがたは天地の模様を見分けることを知りながら、どうして今の時代を見分けることができないのか。"}, "57": {"en": "“Why don’t you judge for yourselves what is right?", "zh": "「你們又為何不自己審量甚麼是合理的呢？", "ja": "また、あなたがたは、なぜ正しいことを自分で判断しないのか。"}, "58": {"en": "For when you are going with your adversary before the magistrate, try diligently on the way to be released from him, lest perhaps he drag you to the judge, and the judge deliver you to the officer, and the officer throw you into prison.", "zh": "你同告你的對頭去見官，還在路上，務要盡力地和他了結；恐怕他拉你到官面前，官交付差役，差役把你下在監裏。", "ja": "たとえば、あなたを訴える人と一緒に役人のところへ行くときには、途中でその人と和解するように努めるがよい。そうしないと、その人はあなたを裁判官のところへひっぱって行き、裁判官はあなたを獄吏に引き渡し、獄吏はあなたを獄に投げ込むであろう。"}, "59": {"en": "I tell you, you will by no means get out of there until you have paid the very last penny.”", "zh": "我告訴你，若有半文錢沒有還清，你斷不能從那裏出來。」", "ja": "わたしは言って置く、最後の一レプタまでも支払ってしまうまでは、決してそこから出て来ることはできない」。"}}}, "13": {"verses": {"1": {"en": "Now there were some present at the same time who told him about the Galileans whose blood Pilate had mixed with their sacrifices.", "zh": "正當那時，有人將彼拉多使加利利人的血攙雜在他們祭物中的事告訴耶穌。", "ja": "ちょうどその時、ある人々がきて、ピラトがガリラヤ人たちの血を流し、それを彼らの犠牲の血に混ぜたことを、イエスに知らせた。"}, "2": {"en": "Jesus answered them, “Do you think that these Galileans were worse sinners than all the other Galileans, because they suffered such things?", "zh": "耶穌說：「你們以為這些加利利人比眾加利利人更有罪，所以受這害嗎？", "ja": "そこでイエスは答えて言われた、「それらのガリラヤ人が、そのような災難にあったからといって、他のすべてのガリラヤ人以上に罪が深かったと思うのか。"}, "3": {"en": "I tell you, no, but unless you repent, you will all perish in the same way.", "zh": "我告訴你們，不是的！你們若不悔改，都要如此滅亡！", "ja": "あなたがたに言うが、そうではない。あなたがたも悔い改めなければ、みな同じように滅びるであろう。"}, "4": {"en": "Or those eighteen on whom the tower in Siloam fell and killed them—do you think that they were worse offenders than all the men who dwell in Jerusalem?", "zh": "從前西羅亞樓倒塌了，壓死十八個人；你們以為那些人比一切住在耶路撒冷的人更有罪嗎？", "ja": "また、シロアムの塔が倒れたためにおし殺されたあの十八人は、エルサレムの他の全住民以上に罪の負債があったと思うか。"}, "5": {"en": "I tell you, no, but, unless you repent, you will all perish in the same way.”", "zh": "我告訴你們，不是的！你們若不悔改，都要如此滅亡！」", "ja": "あなたがたに言うが、そうではない。あなたがたも悔い改めなければ、みな同じように滅びるであろう」。"}, "6": {"en": "He spoke this parable. “A certain man had a fig tree planted in his vineyard, and he came seeking fruit on it and found none.", "zh": "於是用比喻說：「一個人有一棵無花果樹栽在葡萄園裏。他來到樹前找果子，卻找不着。", "ja": "それから、この譬を語られた、「ある人が自分のぶどう園にいちじくの木を植えて置いたので、実を捜しにきたが見つからなかった。"}, "7": {"en": "He said to the vine dresser, ‘Behold, these three years I have come looking for fruit on this fig tree, and found none. Cut it down! Why does it waste the soil?’", "zh": "就對管園的說：『看哪，我這三年來到這無花果樹前找果子，竟找不着。把它砍了吧，何必白佔地土呢！』", "ja": "そこで園丁に言った、『わたしは三年間も実を求めて、このいちじくの木のところにきたのだが、いまだに見あたらない。その木を切り倒してしまえ。なんのために、土地をむだにふさがせて置くのか』。"}, "8": {"en": "He answered, ‘Lord, leave it alone this year also, until I dig around it and fertilize it.", "zh": "管園的說：『 主啊，今年且留着，等我周圍掘開土，加上糞；", "ja": "すると園丁は答えて言った、『ご主人様、ことしも、そのままにして置いてください。そのまわりを掘って肥料をやって見ますから。"}, "9": {"en": "If it bears fruit, fine; but if not, after that, you can cut it down.’ ”", "zh": "以後若結果子便罷，不然再把它砍了。』」", "ja": "それで来年実がなりましたら結構です。もしそれでもだめでしたら、切り倒してください』」。"}, "10": {"en": "He was teaching in one of the synagogues on the Sabbath day.", "zh": "安息日，耶穌在會堂裏教訓人。", "ja": "安息日に、ある会堂で教えておられると、"}, "11": {"en": "Behold, there was a woman who had a spirit of infirmity eighteen years. She was bent over and could in no way straighten herself up.", "zh": "有一個女人被鬼附着，病了十八年，腰彎得一點直不起來。", "ja": "そこに十八年間も病気の霊につかれ、かがんだままで、からだを伸ばすことの全くできない女がいた。"}, "12": {"en": "When Jesus saw her, he called her and said to her, “Woman, you are freed from your infirmity.”", "zh": "耶穌看見，便叫過她來，對她說：「女人，你脫離這病了！」", "ja": "イエスはこの女を見て、呼びよせ、「女よ、あなたの病気はなおった」と言って、"}, "13": {"en": "He laid his hands on her, and immediately she stood up straight and glorified God.", "zh": "於是用兩隻手按着她；她立刻直起腰來，就歸榮耀與上帝。", "ja": "手をその上に置かれた。すると立ちどころに、そのからだがまっすぐになり、そして神をたたえはじめた。"}, "14": {"en": "The ruler of the synagogue, being indignant because Jesus had healed on the Sabbath, said to the multitude, “There are six days in which men ought to work. Therefore come on those days and be healed, and not on the Sabbath day!”", "zh": "管會堂的因為耶穌在安息日治病，就氣忿忿地對眾人說：「有六日應當做工；那六日之內可以來求醫，在安息日卻不可。」", "ja": "ところが会堂司は、イエスが安息日に病気をいやされたことを憤り、群衆にむかって言った、「働くべき日は六日ある。その間に、なおしてもらいにきなさい。安息日にはいけない」。"}, "15": {"en": "Therefore the Lord answered him, “You hypocrites! Doesn’t each one of you free his ox or his donkey from the stall on the Sabbath and lead him away to water?", "zh": "主說：「假冒為善的人哪，難道你們各人在安息日不解開槽上的牛、驢，牽去飲嗎？", "ja": "主はこれに答えて言われた、「偽善者たちよ、あなたがたはだれでも、安息日であっても、自分の牛やろばを家畜小屋から解いて、水を飲ませに引き出してやるではないか。"}, "16": {"en": "Ought not this woman, being a daughter of Abraham whom Satan had bound eighteen long years, be freed from this bondage on the Sabbath day?”", "zh": "況且這女人本是亞伯拉罕的後裔，被撒但捆綁了這十八年，不當在安息日解開她的綁嗎？」", "ja": "それなら、十八年間もサタンに縛られていた、アブラハムの娘であるこの女を、安息日であっても、その束縛から解いてやるべきではなかったか」。"}, "17": {"en": "As he said these things, all his adversaries were disappointed; and all the multitude rejoiced for all the glorious things that were done by him.", "zh": "耶穌說這話，他的敵人都慚愧了；眾人因他所行一切榮耀的事，就都歡喜了。", "ja": "こう言われたので、イエスに反対していた人たちはみな恥じ入った。そして群衆はこぞって、イエスがなされたすべてのすばらしいみわざを見て喜んだ。"}, "18": {"en": "He said, “What is God’s Kingdom like? To what shall I compare it?", "zh": "耶穌說：「上帝的國好像甚麼？我拿甚麼來比較呢？", "ja": "そこで言われた、「神の国は何に似ているか。またそれを何にたとえようか。"}, "19": {"en": "It is like a grain of mustard seed which a man took and put in his own garden. It grew and became a large tree, and the birds of the sky live in its branches.”", "zh": "好像一粒芥菜種，有人拿去種在園子裏，長大成樹，天上的飛鳥宿在它的枝上。」", "ja": "一粒のからし種のようなものである。ある人がそれを取って庭にまくと、育って木となり、空の鳥もその枝に宿るようになる」。"}, "20": {"en": "Again he said, “To what shall I compare God’s Kingdom?", "zh": "又說：「我拿甚麼來比上帝的國呢？", "ja": "また言われた、「神の国を何にたとえようか。"}, "21": {"en": "It is like yeast, which a woman took and hid in three measures  of flour, until it was all leavened.”", "zh": "好比麵酵，有婦人拿來藏在三斗麵裏，直等全團都發起來。」", "ja": "パン種のようなものである。女がそれを取って三斗の粉の中に混ぜると、全体がふくらんでくる」。"}, "22": {"en": "He went on his way through cities and villages, teaching, and traveling on to Jerusalem.", "zh": "耶穌往耶路撒冷去，在所經過的各城各鄉教訓人。", "ja": "さてイエスは教えながら町々村々を通り過ぎ、エルサレムへと旅を続けられた。"}, "23": {"en": "One said to him, “Lord, are they few who are saved?”", "zh": "有一個人問他說：「主啊，得救的人少嗎？」", "ja": "すると、ある人がイエスに、「主よ、救われる人は少ないのですか」と尋ねた。"}, "24": {"en": "He said to them,   “Strive to enter in by the narrow door, for many, I tell you, will seek to enter in and will not be able.", "zh": "耶穌對眾人說：「你們要努力進窄門。我告訴你們，將來有許多人想要進去，卻是不能。", "ja": "そこでイエスは人々にむかって言われた、「狭い戸口からはいるように努めなさい。事実、はいろうとしても、はいれない人が多いのだから。"}, "25": {"en": "When once the master of the house has risen up and has shut the door, and you begin to stand outside and to knock at the door, saying, ‘Lord, Lord, open to us!’ then he will answer and tell you, ‘I don’t know you or where you come from.’", "zh": "及至家主起來關了門，你們站在外面叩門，說：『主啊，給我們開門！』他就回答說：『我不認識你們，不曉得你們是哪裏來的！』", "ja": "家の主人が立って戸を閉じてしまってから、あなたがたが外に立ち戸をたたき始めて、『ご主人様、どうぞあけてください』と言っても、主人はそれに答えて、『あなたがたがどこからきた人なのか、わたしは知らない』と言うであろう。"}, "26": {"en": "Then you will begin to say, ‘We ate and drank in your presence, and you taught in our streets.’", "zh": "那時，你們要說：『我們在你面前吃過喝過，你也在我們的街上教訓過人。』", "ja": "そのとき、『わたしたちはあなたとご一緒に飲み食いしました。また、あなたはわたしたちの大通りで教えてくださいました』と言い出しても、"}, "27": {"en": "He will say, ‘I tell you, I don’t know where you come from. Depart from me, all you workers of iniquity.’", "zh": "他要說：『我告訴你們，我不曉得你們是哪裏來的。你們這一切作惡的人，離開我去吧！』", "ja": "彼は、『あなたがたがどこからきた人なのか、わたしは知らない。悪事を働く者どもよ、みんな行ってしまえ』と言うであろう。"}, "28": {"en": "There will be weeping and gnashing of teeth when you see Abraham, Isaac, Jacob, and all the prophets in God’s Kingdom, and yourselves being thrown outside.", "zh": "你們要看見亞伯拉罕、以撒、雅各，和眾先知都在上帝的國裏，你們卻被趕到外面，在那裏必要哀哭切齒了。", "ja": "あなたがたは、アブラハム、イサク、ヤコブやすべての預言者たちが、神の国にはいっているのに、自分たちは外に投げ出されることになれば、そこで泣き叫んだり、歯がみをしたりするであろう。"}, "29": {"en": "They will come from the east, west, north, and south, and will sit down in God’s Kingdom.", "zh": "從東、從西、從南、從北將有人來，在上帝的國裏坐席。", "ja": "それから人々が、東から西から、また南から北からきて、神の国で宴会の席につくであろう。"}, "30": {"en": "Behold, there are some who are last who will be first, and there are some who are first who will be last.”", "zh": "只是有在後的，將要在前；有在前的，將要在後。」", "ja": "こうしてあとのもので先になるものがあり、また、先のものであとになるものもある」。"}, "31": {"en": "On that same day, some Pharisees came, saying to him, “Get out of here and go away, for Herod wants to kill you.”", "zh": "正當那時，有幾個法利賽人來對耶穌說：「離開這裏去吧，因為希律想要殺你。」", "ja": "ちょうどその時、あるパリサイ人たちが、イエスに近寄ってきて言った、「ここから出て行きなさい。ヘロデがあなたを殺そうとしています」。"}, "32": {"en": "He said to them, “Go and tell that fox, ‘Behold, I cast out demons and perform cures today and tomorrow, and the third day I complete my mission.", "zh": "耶穌說：「你們去告訴那個狐狸說：『今天、明天我趕鬼治病，第三天我的事就成全了。』", "ja": "そこで彼らに言われた、「あのきつねのところへ行ってこう言え、『見よ、わたしはきょうもあすも悪霊を追い出し、また、病気をいやし、そして三日目にわざを終えるであろう。"}, "33": {"en": "Nevertheless I must go on my way today and tomorrow and the next day, for it can’t be that a prophet would perish outside of Jerusalem.’", "zh": "雖然這樣，今天、明天、後天，我必須前行，因為先知在耶路撒冷之外喪命是不能的。", "ja": "しかし、きょうもあすも、またその次の日も、わたしは進んで行かねばならない。預言者がエルサレム以外の地で死ぬことは、あり得ないからである』。"}, "34": {"en": "“Jerusalem, Jerusalem, you who kills the prophets and stones those who are sent to her! How often I wanted to gather your children together, like a hen gathers her own brood under her wings, and you refused!", "zh": "耶路撒冷啊！耶路撒冷啊！你常殺害先知，又用石頭打死那奉差遣到你這裏來的人。我多次願意聚集你的兒女，好像母雞把小雞聚集在翅膀底下；只是你們不願意。", "ja": "ああ、エルサレム、エルサレム、預言者たちを殺し、おまえにつかわされた人々を石で打ち殺す者よ。ちょうどめんどりが翼の下にひなを集めるように、わたしはおまえの子らを幾たび集めようとしたことであろう。それだのに、おまえたちは応じようとしなかった。"}, "35": {"en": "Behold, your house is left to you desolate. I tell you, you will not see me until you say, ‘Blessed is he who comes in the name of the Lord!’ ”", "zh": "看哪，你們的家成為荒場留給你們。我告訴你們，從今以後你們不得再見我，直等到你們說：『奉主名來的是應當稱頌的。』」", "ja": "見よ、おまえたちの家は見捨てられてしまう。わたしは言って置く、『主の名によってきたるものに、祝福あれ』とおまえたちが言う時の来るまでは、再びわたしに会うことはないであろう」。"}}}, "14": {"verses": {"1": {"en": "When he went into the house of one of the rulers of the Pharisees on a Sabbath to eat bread, they were watching him.", "zh": "安息日，耶穌到一個法利賽人的首領家裏去吃飯，他們就窺探他。", "ja": "ある安息日のこと、食事をするために、あるパリサイ派のかしらの家にはいって行かれたが、人々はイエスの様子をうかがっていた。"}, "2": {"en": "Behold, a certain man who had dropsy was in front of him.", "zh": "在他面前有一個患水臌的人。", "ja": "するとそこに、水腫をわずらっている人が、みまえにいた。"}, "3": {"en": "Jesus, answering, spoke to the lawyers and Pharisees, saying, “Is it lawful to heal on the Sabbath?”", "zh": "耶穌對律法師和法利賽人說：「安息日治病可以不可以？」", "ja": "イエスは律法学者やパリサイ人たちにむかって言われた、「安息日に人をいやすのは、正しいことかどうか」。"}, "4": {"en": "But they were silent.", "zh": "他們卻不言語。耶穌就治好那人，叫他走了；", "ja": "彼らは黙っていた。そこでイエスはその人に手を置いていやしてやり、そしてお帰しになった。"}, "5": {"en": "He took him, and healed him, and let him go.   He answered them, “Which of you, if your son or an ox fell into a well, wouldn’t immediately pull him out on a Sabbath day?”", "zh": "便對他們說：「你們中間誰有驢或有牛，在安息日掉在井裏，不立時拉牠上來呢？」", "ja": "それから彼らに言われた、「あなたがたのうちで、自分のむすこか牛が井戸に落ち込んだなら、安息日だからといって、すぐに引き上げてやらない者がいるだろうか」。"}, "6": {"en": "They couldn’t answer him regarding these things.", "zh": "他們不能對答這話。", "ja": "彼らはこれに対して返す言葉がなかった。"}, "7": {"en": "He spoke a parable to those who were invited, when he noticed how they chose the best seats, and said to them,", "zh": "耶穌見所請的客揀擇首位，就用比喻對他們說：", "ja": "客に招かれた者たちが上座を選んでいる様子をごらんになって、彼らに一つの譬を語られた。"}, "8": {"en": "“When you are invited by anyone to a wedding feast, don’t sit in the best seat, since perhaps someone more honorable than you might be invited by him,", "zh": "「你被人請去赴婚姻的筵席，不要坐在首位上，恐怕有比你尊貴的客被他請來；", "ja": "「婚宴に招かれたときには、上座につくな。あるいは、あなたよりも身分の高い人が招かれているかも知れない。"}, "9": {"en": "and he who invited both of you would come and tell you, ‘Make room for this person.’ Then you would begin, with shame, to take the lowest place.", "zh": "那請你們的人前來對你說：『讓座給這一位吧！』你就羞羞慚慚地退到末位上去了。", "ja": "その場合、あなたとその人とを招いた者がきて、『このかたに座を譲ってください』と言うであろう。そのとき、あなたは恥じ入って末座につくことになるであろう。"}, "10": {"en": "But when you are invited, go and sit in the lowest place, so that when he who invited you comes, he may tell you, ‘Friend, move up higher.’ Then you will be honored in the presence of all who sit at the table with you.", "zh": "你被請的時候，就去坐在末位上，好叫那請你的人來對你說：『朋友，請上座。』那時，你在同席的人面前就有光彩了。", "ja": "むしろ、招かれた場合には、末座に行ってすわりなさい。そうすれば、招いてくれた人がきて、『友よ、上座の方へお進みください』と言うであろう。そのとき、あなたは席を共にするみんなの前で、面目をほどこすことになるであろう。"}, "11": {"en": "For everyone who exalts himself will be humbled, and whoever humbles himself will be exalted.”", "zh": "因為，凡自高的，必降為卑；自卑的，必升為高。」", "ja": "おおよそ、自分を高くする者は低くされ、自分を低くする者は高くされるであろう」。"}, "12": {"en": "He also said to the one who had invited him, “When you make a dinner or a supper, don’t call your friends, nor your brothers, nor your kinsmen, nor rich neighbors, or perhaps they might also return the favor, and pay you back.", "zh": "耶穌又對請他的人說：「你擺設午飯或晚飯，不要請你的朋友、弟兄、親屬，和富足的鄰舍，恐怕他們也請你，你就得了報答。", "ja": "また、イエスは自分を招いた人に言われた、「午餐または晩餐の席を設ける場合には、友人、兄弟、親族、金持の隣り人などは呼ばぬがよい。恐らく彼らもあなたを招きかえし、それであなたは返礼を受けることになるから。"}, "13": {"en": "But when you make a feast, ask the poor, the maimed, the lame, or the blind;", "zh": "你擺設筵席，倒要請那貧窮的、殘廢的、瘸腿的、瞎眼的，你就有福了！", "ja": "むしろ、宴会を催す場合には、貧乏人、不具者、足なえ、盲人などを招くがよい。"}, "14": {"en": "and you will be blessed, because they don’t have the resources to repay you. For you will be repaid in the resurrection of the righteous.”", "zh": "因為他們沒有甚麼可報答你。到義人復活的時候，你要得着報答。」", "ja": "そうすれば、彼らは返礼ができないから、あなたはさいわいになるであろう。正しい人々の復活の際には、あなたは報いられるであろう」。"}, "15": {"en": "When one of those who sat at the table with him heard these things, he said to him, “Blessed is he who will feast in God’s Kingdom!”", "zh": "同席的有一人聽見這話，就對耶穌說：「在上帝國裏吃飯的有福了！」", "ja": "列席者のひとりがこれを聞いてイエスに「神の国で食事をする人は、さいわいです」と言った。"}, "16": {"en": "But he said to him, “A certain man made a great supper, and he invited many people.", "zh": "耶穌對他說：「有一人擺設大筵席，請了許多客。", "ja": "そこでイエスが言われた、「ある人が盛大な晩餐会を催して、大ぜいの人を招いた。"}, "17": {"en": "He sent out his servant at supper time to tell those who were invited, ‘Come, for everything is ready now.’", "zh": "到了坐席的時候，打發僕人去對所請的人說：『請來吧！樣樣都齊備了。』", "ja": "晩餐の時刻になったので、招いておいた人たちのもとに僕を送って、『さあ、おいでください。もう準備ができましたから』と言わせた。"}, "18": {"en": "They all as one began to make excuses. “The first said to him, ‘I have bought a field, and I must go and see it. Please have me excused.’", "zh": "眾人一口同音地推辭。頭一個說：『我買了一塊地，必須去看看。請你准我辭了。』", "ja": "ところが、みんな一様に断りはじめた。最初の人は、『わたしは土地を買いましたので、行って見なければなりません。どうぞ、おゆるしください』と言った。"}, "19": {"en": "“Another said, ‘I have bought five yoke of oxen, and I must go try them out. Please have me excused.’", "zh": "又有一個說：『我買了五對牛，要去試一試。請你准我辭了。』", "ja": "ほかの人は、『わたしは五対の牛を買いましたので、それをしらべに行くところです。どうぞ、おゆるしください』、"}, "20": {"en": "“Another said, ‘I have married a wife, and therefore I can’t come.’", "zh": "又有一個說：『我才娶了妻，所以不能去。』", "ja": "もうひとりの人は、『わたしは妻をめとりましたので、参ることができません』と言った。"}, "21": {"en": "“That servant came, and told his lord these things. Then the master of the house, being angry, said to his servant, ‘Go out quickly into the streets and lanes of the city, and bring in the poor, maimed, blind, and lame.’", "zh": "那僕人回來，把這事都告訴了主人。家主就動怒，對僕人說：『快出去，到城裏大街小巷，領那貧窮的、殘廢的、瞎眼的、瘸腿的來。』", "ja": "僕は帰ってきて、以上の事を主人に報告した。すると家の主人はおこって僕に言った、『いますぐに、町の大通りや小道へ行って、貧乏人、不具者、盲人、足なえなどを、ここへ連れてきなさい』。"}, "22": {"en": "“The servant said, ‘Lord, it is done as you commanded, and there is still room.’", "zh": "僕人說：『主啊，你所吩咐的已經辦了，還有空座。』", "ja": "僕は言った、『ご主人様、仰せのとおりにいたしましたが、まだ席がございます』。"}, "23": {"en": "“The lord said to the servant, ‘Go out into the highways and hedges, and compel them to come in, that my house may be filled.", "zh": "主人對僕人說：『你出去到路上和籬笆那裏，勉強人進來，坐滿我的屋子。", "ja": "主人が僕に言った、『道やかきねのあたりに出て行って、この家がいっぱいになるように、人々を無理やりにひっぱってきなさい。"}, "24": {"en": "For I tell you that none of those men who were invited will taste of my supper. For many are called, but few are chosen.’ ”", "zh": "我告訴你們，先前所請的人沒有一個得嘗我的筵席。』」", "ja": "あなたがたに言って置くが、招かれた人で、わたしの晩餐にあずかる者はひとりもないであろう』」。"}, "25": {"en": "Now great multitudes were going with him. He turned and said to them,", "zh": "有極多的人和耶穌同行。他轉過來對他們說：", "ja": "大ぜいの群衆がついてきたので、イエスは彼らの方に向いて言われた、"}, "26": {"en": "“If anyone comes to me, and doesn’t disregard his own father, mother, wife, children, brothers, and sisters, yes, and his own life also, he can’t be my disciple.", "zh": "「人到我這裏來，若不愛我勝過愛自己的父母、妻子、兒女、弟兄、姊妹，和自己的性命，就不能作我的門徒。", "ja": "「だれでも、父、母、妻、子、兄弟、姉妹、さらに自分の命までも捨てて、わたしのもとに来るのでなければ、わたしの弟子となることはできない。"}, "27": {"en": "Whoever doesn’t bear his own cross and come after me, can’t be my disciple.", "zh": "凡不背着自己十字架跟從我的，也不能作我的門徒。", "ja": "自分の十字架を負うてわたしについて来るものでなければ、わたしの弟子となることはできない。"}, "28": {"en": "For which of you, desiring to build a tower, doesn’t first sit down and count the cost, to see if he has enough to complete it?", "zh": "你們哪一個要蓋一座樓，不先坐下算計花費，能蓋成不能呢？", "ja": "あなたがたのうちで、だれかが邸宅を建てようと思うなら、それを仕上げるのに足りるだけの金を持っているかどうかを見るため、まず、すわってその費用を計算しないだろうか。"}, "29": {"en": "Or perhaps, when he has laid a foundation and isn’t able to finish, everyone who sees begins to mock him,", "zh": "恐怕安了地基，不能成功，看見的人都笑話他，說：", "ja": "そうしないと、土台をすえただけで完成することができず、見ているみんなの人が、"}, "30": {"en": "saying, ‘This man began to build and wasn’t able to finish.’", "zh": "『這個人開了工，卻不能完工。』", "ja": "『あの人は建てかけたが、仕上げができなかった』と言ってあざ笑うようになろう。"}, "31": {"en": "Or what king, as he goes to encounter another king in war, will not sit down first and consider whether he is able with ten thousand to meet him who comes against him with twenty thousand?", "zh": "或是一個王出去和別的王打仗，豈不先坐下酌量，能用一萬兵去敵那領二萬兵來攻打他的嗎？", "ja": "また、どんな王でも、ほかの王と戦いを交えるために出て行く場合には、まず座して、こちらの一万人をもって、二万人を率いて向かって来る敵に対抗できるかどうか、考えて見ないだろうか。"}, "32": {"en": "Or else, while the other is yet a great way off, he sends an envoy and asks for conditions of peace.", "zh": "若是不能，就趁敵人還遠的時候，派使者去求和息的條款。", "ja": "もし自分の力にあまれば、敵がまだ遠くにいるうちに、使者を送って、和を求めるであろう。"}, "33": {"en": "So therefore, whoever of you who doesn’t renounce all that he has, he can’t be my disciple.", "zh": "這樣，你們無論甚麼人，若不撇下一切所有的，就不能作我的門徒。」", "ja": "それと同じように、あなたがたのうちで、自分の財産をことごとく捨て切るものでなくては、わたしの弟子となることはできない。"}, "34": {"en": "“Salt is good, but if the salt becomes flat and tasteless, with what do you season it?", "zh": "「鹽本是好的；鹽若失了味，可用甚麼叫它再鹹呢？", "ja": "塩は良いものだ。しかし、塩もききめがなくなったら、何によって塩味が取りもどされようか。"}, "35": {"en": "It is fit neither for the soil nor for the manure pile. It is thrown out. He who has ears to hear, let him hear.”", "zh": "或用在田裏，或堆在糞裏，都不合式，只好丟在外面。有耳可聽的，就應當聽！」", "ja": "土にも肥料にも役立たず、外に投げ捨てられてしまう。聞く耳のあるものは聞くがよい」。"}}}, "15": {"verses": {"1": {"en": "Now all the tax collectors and sinners were coming close to him to hear him.", "zh": "眾稅吏和罪人都挨近耶穌，要聽他講道。", "ja": "さて、取税人や罪人たちが皆、イエスの話を聞こうとして近寄ってきた。"}, "2": {"en": "The Pharisees and the scribes murmured, saying, “This man welcomes sinners, and eats with them.”", "zh": "法利賽人和文士私下議論說：「這個人接待罪人，又同他們吃飯。」", "ja": "するとパリサイ人や律法学者たちがつぶやいて、「この人は罪人たちを迎えて一緒に食事をしている」と言った。"}, "3": {"en": "He told them this parable:", "zh": "耶穌就用比喻說：", "ja": "そこでイエスは彼らに、この譬をお話しになった、"}, "4": {"en": "“Which of you men, if you had one hundred sheep and lost one of them, wouldn’t leave the ninety-nine in the wilderness and go after the one that was lost, until he found it?", "zh": "「你們中間誰有一百隻羊失去一隻，不把這九十九隻撇在曠野、去找那失去的羊，直到找着呢？", "ja": "「あなたがたのうちに、百匹の羊を持っている者がいたとする。その一匹がいなくなったら、九十九匹を野原に残しておいて、いなくなった一匹を見つけるまでは捜し歩かないであろうか。"}, "5": {"en": "When he has found it, he carries it on his shoulders, rejoicing.", "zh": "找着了，就歡歡喜喜地扛在肩上，回到家裏，", "ja": "そして見つけたら、喜んでそれを自分の肩に乗せ、"}, "6": {"en": "When he comes home, he calls together his friends and his neighbors, saying to them, ‘Rejoice with me, for I have found my sheep which was lost!’", "zh": "就請朋友鄰舍來，對他們說：『我失去的羊已經找着了，你們和我一同歡喜吧！』", "ja": "家に帰ってきて友人や隣り人を呼び集め、『わたしと一緒に喜んでください。いなくなった羊を見つけましたから』と言うであろう。"}, "7": {"en": "I tell you that even so there will be more joy in heaven over one sinner who repents, than over ninety-nine righteous people who need no repentance.", "zh": "我告訴你們，一個罪人悔改，在天上也要這樣為他歡喜，較比為九十九個不用悔改的義人歡喜更大。」", "ja": "よく聞きなさい。それと同じように、罪人がひとりでも悔い改めるなら、悔改めを必要としない九十九人の正しい人のためにもまさる大きいよろこびが、天にあるであろう。"}, "8": {"en": "“Or what woman, if she had ten drachma coins, if she lost one drachma coin, wouldn’t light a lamp, sweep the house, and seek diligently until she found it?", "zh": "「或是一個婦人有十塊錢，若失落一塊，豈不點上燈，打掃屋子，細細地找，直到找着嗎？", "ja": "また、ある女が銀貨十枚を持っていて、もしその一枚をなくしたとすれば、彼女はあかりをつけて家中を掃き、それを見つけるまでは注意深く捜さないであろうか。"}, "9": {"en": "When she has found it, she calls together her friends and neighbors, saying, ‘Rejoice with me, for I have found the drachma which I had lost!’", "zh": "找着了，就請朋友鄰舍來，對他們說：『我失落的那塊錢已經找着了，你們和我一同歡喜吧！』", "ja": "そして、見つけたなら、女友だちや近所の女たちを呼び集めて、『わたしと一緒に喜んでください。なくした銀貨が見つかりましたから』と言うであろう。"}, "10": {"en": "Even so, I tell you, there is joy in the presence of the angels of God over one sinner repenting.”", "zh": "我告訴你們，一個罪人悔改，在上帝的使者面前也是這樣為他歡喜。」", "ja": "よく聞きなさい。それと同じように、罪人がひとりでも悔い改めるなら、神の御使たちの前でよろこびがあるであろう」。"}, "11": {"en": "He said, “A certain man had two sons.", "zh": "耶穌又說：「一個人有兩個兒子。", "ja": "また言われた、「ある人に、ふたりのむすこがあった。"}, "12": {"en": "The younger of them said to his father, ‘Father, give me my share of your property.’ So he divided his livelihood between them.", "zh": "小兒子對父親說：『父親，請你把我應得的家業分給我。』他父親就把產業分給他們。", "ja": "ところが、弟が父親に言った、『父よ、あなたの財産のうちでわたしがいただく分をください』。そこで、父はその身代をふたりに分けてやった。"}, "13": {"en": "Not many days after, the younger son gathered all of this together and traveled into a far country. There he wasted his property with riotous living.", "zh": "過了不多幾日，小兒子就把他一切所有的都收拾起來，往遠方去了。在那裏任意放蕩，浪費資財。", "ja": "それから幾日もたたないうちに、弟は自分のものを全部とりまとめて遠い所へ行き、そこで放蕩に身を持ちくずして財産を使い果した。"}, "14": {"en": "When he had spent all of it, there arose a severe famine in that country, and he began to be in need.", "zh": "既耗盡了一切所有的，又遇着那地方大遭饑荒，就窮苦起來。", "ja": "何もかも浪費してしまったのち、その地方にひどいききんがあったので、彼は食べることにも窮しはじめた。"}, "15": {"en": "He went and joined himself to one of the citizens of that country, and he sent him into his fields to feed pigs.", "zh": "於是去投靠那地方的一個人；那人打發他到田裏去放豬。", "ja": "そこで、その地方のある住民のところに行って身を寄せたところが、その人は彼を畑にやって豚を飼わせた。"}, "16": {"en": "He wanted to fill his belly with the pods that the pigs ate, but no one gave him any.", "zh": "他恨不得拿豬所吃的豆莢充飢，也沒有人給他。", "ja": "彼は、豚の食べるいなご豆で腹を満たしたいと思うほどであったが、何もくれる人はなかった。"}, "17": {"en": "But when he came to himself, he said, ‘How many hired servants of my father’s have bread enough to spare, and I’m dying with hunger!", "zh": "他醒悟過來，就說：『我父親有多少的雇工，口糧有餘，我倒在這裏餓死嗎？", "ja": "そこで彼は本心に立ちかえって言った、『父のところには食物のあり余っている雇人が大ぜいいるのに、わたしはここで飢えて死のうとしている。"}, "18": {"en": "I will get up and go to my father, and will tell him, “Father, I have sinned against heaven and in your sight.", "zh": "我要起來，到我父親那裏去，向他說：父親！我得罪了天，又得罪了你；", "ja": "立って、父のところへ帰って、こう言おう、父よ、わたしは天に対しても、あなたにむかっても、罪を犯しました。"}, "19": {"en": "I am no more worthy to be called your son. Make me as one of your hired servants.” ’", "zh": "從今以後，我不配稱為你的兒子，把我當作一個雇工吧！』", "ja": "もう、あなたのむすこと呼ばれる資格はありません。どうぞ、雇人のひとり同様にしてください』。"}, "20": {"en": "“He arose and came to his father. But while he was still far off, his father saw him and was moved with compassion, and ran, fell on his neck, and kissed him.", "zh": "於是起來，往他父親那裏去。相離還遠，他父親看見，就動了慈心，跑去抱着他的頸項，連連與他親嘴。", "ja": "そこで立って、父のところへ出かけた。まだ遠く離れていたのに、父は彼をみとめ、哀れに思って走り寄り、その首をだいて接吻した。"}, "21": {"en": "The son said to him, ‘Father, I have sinned against heaven and in your sight. I am no longer worthy to be called your son.’", "zh": "兒子說：『父親！我得罪了天，又得罪了你；從今以後，我不配稱為你的兒子。』", "ja": "むすこは父に言った、『父よ、わたしは天に対しても、あなたにむかっても、罪を犯しました。もうあなたのむすこと呼ばれる資格はありません』。"}, "22": {"en": "“But the father said to his servants, ‘Bring out the best robe and put it on him. Put a ring on his hand and sandals on his feet.", "zh": "父親卻吩咐僕人說：『把那上好的袍子快拿出來給他穿；把戒指戴在他指頭上；把鞋穿在他腳上；", "ja": "しかし父は僕たちに言いつけた、『さあ、早く、最上の着物を出してきてこの子に着せ、指輪を手にはめ、はきものを足にはかせなさい。"}, "23": {"en": "Bring the fattened calf, kill it, and let’s eat and celebrate;", "zh": "把那肥牛犢牽來宰了，我們可以吃喝快樂；", "ja": "また、肥えた子牛を引いてきてほふりなさい。食べて楽しもうではないか。"}, "24": {"en": "for this, my son, was dead and is alive again. He was lost and is found.’ Then they began to celebrate.", "zh": "因為我這個兒子是死而復活，失而又得的。』他們就快樂起來。", "ja": "このむすこが死んでいたのに生き返り、いなくなっていたのに見つかったのだから』。それから祝宴がはじまった。"}, "25": {"en": "“Now his elder son was in the field. As he came near to the house, he heard music and dancing.", "zh": "那時，大兒子正在田裏。他回來，離家不遠，聽見作樂跳舞的聲音，", "ja": "ところが、兄は畑にいたが、帰ってきて家に近づくと、音楽や踊りの音が聞えたので、"}, "26": {"en": "He called one of the servants to him and asked what was going on.", "zh": "便叫過一個僕人來，問是甚麼事。", "ja": "ひとりの僕を呼んで、『いったい、これは何事なのか』と尋ねた。"}, "27": {"en": "He said to him, ‘Your brother has come, and your father has killed the fattened calf, because he has received him back safe and healthy.’", "zh": "僕人說：『你兄弟來了；你父親因為得他無災無病地回來，把肥牛犢宰了。』", "ja": "僕は答えた、『あなたのご兄弟がお帰りになりました。無事に迎えたというので、父上が肥えた子牛をほふらせなさったのです』。"}, "28": {"en": "But he was angry and would not go in. Therefore his father came out and begged him.", "zh": "大兒子卻生氣，不肯進去；他父親就出來勸他。", "ja": "兄はおこって家にはいろうとしなかったので、父が出てきてなだめると、"}, "29": {"en": "But he answered his father, ‘Behold, these many years I have served you, and I never disobeyed a commandment of yours, but you never gave me a goat, that I might celebrate with my friends.", "zh": "他對父親說：『我服事你這多年，從來沒有違背過你的命，你並沒有給我一隻山羊羔，叫我和朋友一同快樂。", "ja": "兄は父にむかって言った、『わたしは何か年もあなたに仕えて、一度でもあなたの言いつけにそむいたことはなかったのに、友だちと楽しむために子やぎ一匹も下さったことはありません。"}, "30": {"en": "But when this your son came, who has devoured your living with prostitutes, you killed the fattened calf for him.’", "zh": "但你這個兒子和娼妓吞盡了你的產業，他一來了，你倒為他宰了肥牛犢。』", "ja": "それだのに、遊女どもと一緒になって、あなたの身代を食いつぶしたこのあなたの子が帰ってくると、そのために肥えた子牛をほふりなさいました』。"}, "31": {"en": "“He said to him, ‘Son, you are always with me, and all that is mine is yours.", "zh": "父親對他說：『兒啊！你常和我同在，我一切所有的都是你的；", "ja": "すると父は言った、『子よ、あなたはいつもわたしと一緒にいるし、またわたしのものは全部あなたのものだ。"}, "32": {"en": "But it was appropriate to celebrate and be glad, for this, your brother, was dead, and is alive again. He was lost, and is found.’ ”", "zh": "只是你這個兄弟是死而復活、失而又得的，所以我們理當歡喜快樂。』」", "ja": "しかし、このあなたの弟は、死んでいたのに生き返り、いなくなっていたのに見つかったのだから、喜び祝うのはあたりまえである』」。"}}}, "16": {"verses": {"1": {"en": "He also said to his disciples, “There was a certain rich man who had a manager. An accusation was made to him that this man was wasting his possessions.", "zh": "耶穌又對門徒說：「有一個財主的管家，別人向他主人告他浪費主人的財物。", "ja": "イエスはまた、弟子たちに言われた、「ある金持のところにひとりの家令がいたが、彼は主人の財産を浪費していると、告げ口をする者があった。"}, "2": {"en": "He called him, and said to him, ‘What is this that I hear about you? Give an accounting of your management, for you can no longer be manager.’", "zh": "主人叫他來，對他說：『我聽見你這事怎麼樣呢？把你所經管的交代明白，因你不能再作我的管家。』", "ja": "そこで主人は彼を呼んで言った、『あなたについて聞いていることがあるが、あれはどうなのか。あなたの会計報告を出しなさい。もう家令をさせて置くわけにはいかないから』。"}, "3": {"en": "“The manager said within himself, ‘What will I do, seeing that my lord is taking away the management position from me? I don’t have strength to dig. I am ashamed to beg.", "zh": "那管家心裏說：『主人辭我，不用我再作管家，我將來做甚麼？鋤地呢？無力；討飯呢？怕羞。", "ja": "この家令は心の中で思った、『どうしようか。主人がわたしの職を取り上げようとしている。土を掘るには力がないし、物ごいするのは恥ずかしい。"}, "4": {"en": "I know what I will do, so that when I am removed from management, they may receive me into their houses.’", "zh": "我知道怎麼行，好叫人在我不作管家之後，接我到他們家裏去。』", "ja": "そうだ、わかった。こうしておけば、職をやめさせられる場合、人々がわたしをその家に迎えてくれるだろう』。"}, "5": {"en": "Calling each one of his lord’s debtors to him, he said to the first, ‘How much do you owe to my lord?’", "zh": "於是把欠他主人債的，一個一個地叫了來，問頭一個說：『你欠我主人多少？』", "ja": "それから彼は、主人の負債者をひとりびとり呼び出して、初めの人に、『あなたは、わたしの主人にどれだけ負債がありますか』と尋ねた。"}, "6": {"en": "He said, ‘A hundred batos of oil.’ He said to him, ‘Take your bill, and sit down quickly and write fifty.’", "zh": "他說：『一百簍油。』管家說：『拿你的帳，快坐下，寫五十。』", "ja": "『油百樽です』と答えた。そこで家令が言った、『ここにあなたの証書がある。すぐそこにすわって、五十樽と書き変えなさい』。"}, "7": {"en": "Then he said to another, ‘How much do you owe?’ He said, ‘A hundred cors of wheat.’ He said to him, ‘Take your bill, and write eighty.’", "zh": "又問一個說：『你欠多少？』他說：『一百石麥子。』管家說：『拿你的帳，寫八十。』", "ja": "次に、もうひとりに、『あなたの負債はどれだけですか』と尋ねると、『麦百石です』と答えた。これに対して、『ここに、あなたの証書があるが、八十石と書き変えなさい』と言った。"}, "8": {"en": "“His lord commended the dishonest manager because he had done wisely, for the children of this world are, in their own generation, wiser than the children of the light.", "zh": "主人就誇獎這不義的管家做事聰明；因為今世之子，在世事之上，較比光明之子更加聰明。", "ja": "ところが主人は、この不正な家令の利口なやり方をほめた。この世の子らはその時代に対しては、光の子らよりも利口である。"}, "9": {"en": "I tell you, make for yourselves friends by means of unrighteous mammon, so that when you fail, they may receive you into the eternal tents.", "zh": "我又告訴你們，要藉着那不義的錢財結交朋友，到了錢財無用的時候，他們可以接你們到永存的帳幕裏去。", "ja": "またあなたがたに言うが、不正の富を用いてでも、自分のために友だちをつくるがよい。そうすれば、富が無くなった場合、あなたがたを永遠のすまいに迎えてくれるであろう。"}, "10": {"en": "He who is faithful in a very little is faithful also in much. He who is dishonest in a very little is also dishonest in much.", "zh": "人在最小的事上忠心，在大事上也忠心；在最小的事上不義，在大事上也不義。", "ja": "小事に忠実な人は、大事にも忠実である。そして、小事に不忠実な人は大事にも不忠実である。"}, "11": {"en": "If therefore you have not been faithful in the unrighteous mammon, who will commit to your trust the true riches?", "zh": "倘若你們在不義的錢財上不忠心，誰還把那真實的錢財託付你們呢？", "ja": "だから、もしあなたがたが不正の富について忠実でなかったら、だれが真の富を任せるだろうか。"}, "12": {"en": "If you have not been faithful in that which is another’s, who will give you that which is your own?", "zh": "倘若你們在別人的東西上不忠心，誰還把你們自己的東西給你們呢？", "ja": "また、もしほかの人のものについて忠実でなかったら、だれがあなたがたのものを与えてくれようか。"}, "13": {"en": "No servant can serve two masters, for either he will hate the one and love the other; or else he will hold to one and despise the other. You aren’t able to serve God and Mammon.”", "zh": "一個僕人不能事奉兩個主；不是惡這個愛那個，就是重這個輕那個。你們不能又事奉上帝，又事奉瑪門。」", "ja": "どの僕でも、ふたりの主人に兼ね仕えることはできない。一方を憎んで他方を愛し、あるいは、一方に親しんで他方をうとんじるからである。あなたがたは、神と富とに兼ね仕えることはできない」。"}, "14": {"en": "The Pharisees, who were lovers of money, also heard all these things, and they scoffed at him.", "zh": "法利賽人是貪愛錢財的；他們聽見這一切話，就嗤笑耶穌。", "ja": "欲の深いパリサイ人たちが、すべてこれらの言葉を聞いて、イエスをあざ笑った。"}, "15": {"en": "He said to them, “You are those who justify yourselves in the sight of men, but God knows your hearts. For that which is exalted among men is an abomination in the sight of God.", "zh": "耶穌對他們說：「你們是在人面前自稱為義的，你們的心，上帝卻知道；因為人所尊貴的，是上帝看為可憎惡的。", "ja": "そこで彼らにむかって言われた、「あなたがたは、人々の前で自分を正しいとする人たちである。しかし、神はあなたがたの心をご存じである。人々の間で尊ばれるものは、神のみまえでは忌みきらわれる。"}, "16": {"en": "“The law and the prophets were until John. From that time the Good News of God’s Kingdom is preached, and everyone is forcing his way into it.", "zh": "律法和先知到約翰為止，從此上帝國的福音傳開了，人人努力要進去。", "ja": "律法と預言者とはヨハネの時までのものである。それ以来、神の国が宣べ伝えられ、人々は皆これに突入している。"}, "17": {"en": "But it is easier for heaven and earth to pass away than for one tiny stroke of a pen in the law to fall.", "zh": "天地廢去較比律法的一點一畫落空還容易。", "ja": "しかし、律法の一画が落ちるよりは、天地の滅びる方が、もっとたやすい。"}, "18": {"en": "“Everyone who divorces his wife and marries another commits adultery. He who marries one who is divorced from a husband commits adultery.", "zh": "凡休妻另娶的就是犯姦淫；娶被休之妻的也是犯姦淫。」", "ja": "すべて自分の妻を出して他の女をめとる者は、姦淫を行うものであり、また、夫から出された女をめとる者も、姦淫を行うものである。"}, "19": {"en": "“Now there was a certain rich man, and he was clothed in purple and fine linen, living in luxury every day.", "zh": "「有一個財主穿着紫色袍和細麻布衣服，天天奢華宴樂。", "ja": "ある金持がいた。彼は紫の衣や細布を着て、毎日ぜいたくに遊び暮していた。"}, "20": {"en": "A certain beggar, named Lazarus, was taken to his gate, full of sores,", "zh": "又有一個討飯的，名叫拉撒路，渾身生瘡，被人放在財主門口，", "ja": "ところが、ラザロという貧乏人が全身でき物でおおわれて、この金持の玄関の前にすわり、"}, "21": {"en": "and desiring to be fed with the crumbs that fell from the rich man’s table. Yes, even the dogs came and licked his sores.", "zh": "要得財主桌子上掉下來的零碎充飢，並且狗來舔他的瘡。", "ja": "その食卓から落ちるもので飢えをしのごうと望んでいた。その上、犬がきて彼のでき物をなめていた。"}, "22": {"en": "The beggar died, and he was carried away by the angels to Abraham’s bosom. The rich man also died and was buried.", "zh": "後來那討飯的死了，被天使帶去放在亞伯拉罕的懷裏。財主也死了，並且埋葬了。", "ja": "この貧乏人がついに死に、御使たちに連れられてアブラハムのふところに送られた。金持も死んで葬られた。"}, "23": {"en": "In Hades, he lifted up his eyes, being in torment, and saw Abraham far off, and Lazarus at his bosom.", "zh": "他在陰間受痛苦，舉目遠遠地望見亞伯拉罕，又望見拉撒路在他懷裏，", "ja": "そして黄泉にいて苦しみながら、目をあげると、アブラハムとそのふところにいるラザロとが、はるかに見えた。"}, "24": {"en": "He cried and said, ‘Father Abraham, have mercy on me, and send Lazarus, that he may dip the tip of his finger in water and cool my tongue! For I am in anguish in this flame.’", "zh": "就喊着說：『我祖亞伯拉罕哪，可憐我吧！打發拉撒路來，用指頭尖蘸點水，涼涼我的舌頭；因為我在這火焰裏，極其痛苦。』", "ja": "そこで声をあげて言った、『父、アブラハムよ、わたしをあわれんでください。ラザロをおつかわしになって、その指先を水でぬらし、わたしの舌を冷やさせてください。わたしはこの火炎の中で苦しみもだえています』。"}, "25": {"en": "“But Abraham said, ‘Son, remember that you, in your lifetime, received your good things, and Lazarus, in the same way, bad things. But here he is now comforted and you are in anguish.", "zh": "亞伯拉罕說：『兒啊，你該回想你生前享過福，拉撒路也受過苦；如今他在這裏得安慰，你倒受痛苦。", "ja": "アブラハムが言った、『子よ、思い出すがよい。あなたは生前よいものを受け、ラザロの方は悪いものを受けた。しかし今ここでは、彼は慰められ、あなたは苦しみもだえている。"}, "26": {"en": "Besides all this, between us and you there is a great gulf fixed, that those who want to pass from here to you are not able, and that no one may cross over from there to us.’", "zh": "不但這樣，並且在你我之間，有深淵限定，以致人要從這邊過到你們那邊是不能的；要從那邊過到我們這邊也是不能的。』", "ja": "そればかりか、わたしたちとあなたがたとの間には大きな淵がおいてあって、こちらからあなたがたの方へ渡ろうと思ってもできないし、そちらからわたしたちの方へ越えて来ることもできない』。"}, "27": {"en": "“He said, ‘I ask you therefore, father, that you would send him to my father’s house—", "zh": "財主說：『我祖啊！既是這樣，求你打發拉撒路到我父家去；", "ja": "そこで金持が言った、『父よ、ではお願いします。わたしの父の家へラザロをつかわしてください。"}, "28": {"en": "for I have five brothers—that he may testify to them, so they won’t also come into this place of torment.’", "zh": "因為我還有五個弟兄，他可以對他們作見證，免得他們也來到這痛苦的地方。』", "ja": "わたしに五人の兄弟がいますので、こんな苦しい所へ来ることがないように、彼らに警告していただきたいのです』。"}, "29": {"en": "“But Abraham said to him, ‘They have Moses and the prophets. Let them listen to them.’", "zh": "亞伯拉罕說：『他們有摩西和先知的話可以聽從。』", "ja": "アブラハムは言った、『彼らにはモーセと預言者とがある。それに聞くがよかろう』。"}, "30": {"en": "“He said, ‘No, father Abraham, but if one goes to them from the dead, they will repent.’", "zh": "他說：『我祖亞伯拉罕哪，不是的，若有一個從死裏復活的，到他們那裏去的，他們必要悔改。』", "ja": "金持が言った、『いえいえ、父アブラハムよ、もし死人の中からだれかが兄弟たちのところへ行ってくれましたら、彼らは悔い改めるでしょう』。"}, "31": {"en": "“He said to him, ‘If they don’t listen to Moses and the prophets, neither will they be persuaded if one rises from the dead.’ ”", "zh": "亞伯拉罕說：『若不聽從摩西和先知的話，就是有一個從死裏復活的，他們也是不聽勸。』」", "ja": "アブラハムは言った、『もし彼らがモーセと預言者とに耳を傾けないなら、死人の中からよみがえってくる者があっても、彼らはその勧めを聞き入れはしないであろう』」。"}}}, "17": {"verses": {"1": {"en": "He said to the disciples, “It is impossible that no occasions of stumbling should come, but woe to him through whom they come!", "zh": "耶穌又對門徒說：「絆倒人的事是免不了的；但那絆倒人的有禍了。", "ja": "イエスは弟子たちに言われた、「罪の誘惑が来ることは避けられない。しかし、それをきたらせる者は、わざわいである。"}, "2": {"en": "It would be better for him if a millstone were hung around his neck, and he were thrown into the sea, rather than that he should cause one of these little ones to stumble.", "zh": "就是把磨石拴在這人的頸項上，丟在海裏，還強如他把這小子裏的一個絆倒了。", "ja": "これらの小さい者のひとりを罪に誘惑するよりは、むしろ、ひきうすを首にかけられて海に投げ入れられた方が、ましである。"}, "3": {"en": "Be careful. If your brother sins against you, rebuke him. If he repents, forgive him.", "zh": "你們要謹慎！若是你的弟兄得罪你，就勸戒他；他若懊悔，就饒恕他。", "ja": "あなたがたは、自分で注意していなさい。もしあなたの兄弟が罪を犯すなら、彼をいさめなさい。そして悔い改めたら、ゆるしてやりなさい。"}, "4": {"en": "If he sins against you seven times in the day, and seven times returns, saying, ‘I repent,’ you shall forgive him.”", "zh": "倘若他一天七次得罪你，又七次回轉，說：『我懊悔了』，你總要饒恕他。」", "ja": "もしあなたに対して一日に七度罪を犯し、そして七度『悔い改めます』と言ってあなたのところへ帰ってくれば、ゆるしてやるがよい」。"}, "5": {"en": "The apostles said to the Lord, “Increase our faith.”", "zh": "使徒對主說：「求主加增我們的信心。」", "ja": "使徒たちは主に「わたしたちの信仰を増してください」と言った。"}, "6": {"en": "The Lord said, “If you had faith like a grain of mustard seed, you would tell this sycamore tree, ‘Be uprooted and be planted in the sea,’ and it would obey you.", "zh": "主說：「你們若有信心像一粒芥菜種，就是對這棵桑樹說：『你要拔起根來，栽在海裏』，它也必聽從你們。", "ja": "そこで主が言われた、「もし、からし種一粒ほどの信仰があるなら、この桑の木に、『抜け出して海に植われ』と言ったとしても、その言葉どおりになるであろう。"}, "7": {"en": "But who is there among you, having a servant plowing or keeping sheep, that will say when he comes in from the field, ‘Come immediately and sit down at the table’?", "zh": "你們誰有僕人耕地或是放羊，從田裏回來，就對他說：『你快來坐下吃飯』呢？", "ja": "あなたがたのうちのだれかに、耕作か牧畜かをする僕があるとする。その僕が畑から帰って来たとき、彼に『すぐきて、食卓につきなさい』と言うだろうか。"}, "8": {"en": "Wouldn’t he rather tell him, ‘Prepare my supper, clothe yourself properly, and serve me while I eat and drink. Afterward you shall eat and drink’?", "zh": "豈不對他說：『你給我預備晚飯，束上帶子伺候我，等我吃喝完了，你才可以吃喝』嗎？", "ja": "かえって、『夕食の用意をしてくれ。そしてわたしが飲み食いをするあいだ、帯をしめて給仕をしなさい。そのあとで、飲み食いをするがよい』と、言うではないか。"}, "9": {"en": "Does he thank that servant because he did the things that were commanded? I think not.", "zh": "僕人照所吩咐的去做，主人還謝謝他嗎？", "ja": "僕が命じられたことをしたからといって、主人は彼に感謝するだろうか。"}, "10": {"en": "Even so you also, when you have done all the things that are commanded you, say, ‘We are unworthy servants. We have done our duty.’ ”", "zh": "這樣，你們做完了一切所吩咐的，只當說：『我們是無用的僕人，所做的本是我們應分做的。』」", "ja": "同様にあなたがたも、命じられたことを皆してしまったとき、『わたしたちはふつつかな僕です。すべき事をしたに過ぎません』と言いなさい」。"}, "11": {"en": "As he was on his way to Jerusalem, he was passing along the borders of Samaria and Galilee.", "zh": "耶穌往耶路撒冷去，經過撒馬利亞和加利利。", "ja": "イエスはエルサレムへ行かれるとき、サマリヤとガリラヤとの間を通られた。"}, "12": {"en": "As he entered into a certain village, ten men who were lepers met him, who stood at a distance.", "zh": "進入一個村子，有十個長大痲瘋的，迎面而來，遠遠地站着，", "ja": "そして、ある村にはいられると、十人のらい病人に出会われたが、彼らは遠くの方で立ちとどまり、"}, "13": {"en": "They lifted up their voices, saying, “Jesus, Master, have mercy on us!”", "zh": "高聲說：「耶穌，夫子，可憐我們吧！」", "ja": "声を張りあげて、「イエスさま、わたしたちをあわれんでください」と言った。"}, "14": {"en": "When he saw them, he said to them, “Go and show yourselves to the priests.” As they went, they were cleansed.", "zh": "耶穌看見，就對他們說：「你們去把身體給祭司察看。」他們去的時候就潔淨了。", "ja": "イエスは彼らをごらんになって、「祭司たちのところに行って、からだを見せなさい」と言われた。そして、行く途中で彼らはきよめられた。"}, "15": {"en": "One of them, when he saw that he was healed, turned back, glorifying God with a loud voice.", "zh": "內中有一個見自己已經好了，就回來大聲歸榮耀與上帝，", "ja": "そのうちのひとりは、自分がいやされたことを知り、大声で神をほめたたえながら帰ってきて、"}, "16": {"en": "He fell on his face at Jesus’ feet, giving him thanks; and he was a Samaritan.", "zh": "又俯伏在耶穌腳前感謝他；這人是撒馬利亞人。", "ja": "イエスの足もとにひれ伏して感謝した。これはサマリヤ人であった。"}, "17": {"en": "Jesus answered, “Weren’t the ten cleansed? But where are the nine?", "zh": "耶穌說：「潔淨了的不是十個人嗎？那九個在哪裏呢？", "ja": "イエスは彼にむかって言われた、「きよめられたのは、十人ではなかったか。ほかの九人は、どこにいるのか。"}, "18": {"en": "Were there none found who returned to give glory to God, except this foreigner?”", "zh": "除了這外族人，再沒有別人回來歸榮耀與上帝嗎？」", "ja": "神をほめたたえるために帰ってきたものは、この他国人のほかにはいないのか」。"}, "19": {"en": "Then he said to him, “Get up, and go your way. Your faith has healed you.”", "zh": "就對那人說：「起來，走吧！你的信救了你了。 」", "ja": "それから、その人に言われた、「立って行きなさい。あなたの信仰があなたを救ったのだ」。"}, "20": {"en": "Being asked by the Pharisees when God’s Kingdom would come, he answered them, “God’s Kingdom doesn’t come with observation;", "zh": "法利賽人問：「上帝的國幾時來到？」耶穌回答說：「上帝的國來到不是眼所能見的。", "ja": "神の国はいつ来るのかと、パリサイ人が尋ねたので、イエスは答えて言われた、「神の国は、見られるかたちで来るものではない。"}, "21": {"en": "neither will they say, ‘Look, here!’ or, ‘Look, there!’ for behold, God’s Kingdom is within you.”", "zh": "人也不得說：『看哪，在這裏！看哪，在那裏！』因為上帝的國就在你們心裏。」", "ja": "また『見よ、ここにある』『あそこにある』などとも言えない。神の国は、実にあなたがたのただ中にあるのだ」。"}, "22": {"en": "He said to the disciples, “The days will come when you will desire to see one of the days of the Son of Man, and you will not see it.", "zh": "他又對門徒說：「日子將到，你們巴不得看見人子的一個日子，卻不得看見。", "ja": "それから弟子たちに言われた、「あなたがたは、人の子の日を一日でも見たいと願っても見ることができない時が来るであろう。"}, "23": {"en": "They will tell you, ‘Look, here!’ or ‘Look, there!’ Don’t go away or follow after them,", "zh": "人將要對你們說：『看哪，在那裏！看哪，在這裏！』你們不要出去，也不要跟隨他們！", "ja": "人々はあなたがたに、『見よ、あそこに』『見よ、ここに』と言うだろう。しかし、そちらへ行くな、彼らのあとを追うな。"}, "24": {"en": "for as the lightning, when it flashes out of one part under the sky, shines to another part under the sky, so will the Son of Man be in his day.", "zh": "因為人子在他降臨的日子，好像閃電從天這邊一閃直照到天那邊。", "ja": "いなずまが天の端からひかり出て天の端へとひらめき渡るように、人の子もその日には同じようであるだろう。"}, "25": {"en": "But first, he must suffer many things and be rejected by this generation.", "zh": "只是他必須先受許多苦，又被這世代棄絕。", "ja": "しかし、彼はまず多くの苦しみを受け、またこの時代の人々に捨てられねばならない。"}, "26": {"en": "As it was in the days of Noah, even so it will also be in the days of the Son of Man.", "zh": "挪亞的日子怎樣，人子的日子也要怎樣。", "ja": "そして、ノアの時にあったように、人の子の時にも同様なことが起るであろう。"}, "27": {"en": "They ate, they drank, they married, and they were given in marriage until the day that Noah entered into the ship, and the flood came and destroyed them all.", "zh": "那時候的人又吃又喝，又娶又嫁，到挪亞進方舟的那日，洪水就來，把他們全都滅了。", "ja": "ノアが箱舟にはいる日まで、人々は食い、飲み、めとり、とつぎなどしていたが、そこへ洪水が襲ってきて、彼らをことごとく滅ぼした。"}, "28": {"en": "Likewise, even as it was in the days of Lot: they ate, they drank, they bought, they sold, they planted, they built;", "zh": "又好像羅得的日子；人又吃又喝，又買又賣，又耕種又蓋造。", "ja": "ロトの時にも同じようなことが起った。人々は食い、飲み、買い、売り、植え、建てなどしていたが、"}, "29": {"en": "but in the day that Lot went out from Sodom, it rained fire and sulfur from the sky and destroyed them all.", "zh": "到羅得出所多瑪的那日，就有火與硫磺從天上降下來，把他們全都滅了。", "ja": "ロトがソドムから出て行った日に、天から火と硫黄とが降ってきて、彼らをことごとく滅ぼした。"}, "30": {"en": "It will be the same way in the day that the Son of Man is revealed.", "zh": "人子顯現的日子也要這樣。", "ja": "人の子が現れる日も、ちょうどそれと同様であろう。"}, "31": {"en": "In that day, he who will be on the housetop and his goods in the house, let him not go down to take them away. Let him who is in the field likewise not turn back.", "zh": "當那日，人在房上，器具在屋裏，不要下來拿；人在田裏，也不要回家。", "ja": "その日には、屋上にいる者は、自分の持ち物が家の中にあっても、取りにおりるな。畑にいる者も同じように、あとへもどるな。"}, "32": {"en": "Remember Lot’s wife!", "zh": "你們要回想羅得的妻子。", "ja": "ロトの妻のことを思い出しなさい。"}, "33": {"en": "Whoever seeks to save his life loses it, but whoever loses his life preserves it.", "zh": "凡想要保全生命的，必喪掉生命；凡喪掉生命的，必救活生命。", "ja": "自分の命を救おうとするものは、それを失い、それを失うものは、保つのである。"}, "34": {"en": "I tell you, in that night there will be two people in one bed. One will be taken and the other will be left.", "zh": "我對你們說，當那一夜，兩個人在一個床上，要取去一個，撇下一個。", "ja": "あなたがたに言っておく。その夜、ふたりの男が一つ寝床にいるならば、ひとりは取り去られ、他のひとりは残されるであろう。"}, "35": {"en": "There will be two grinding grain together. One will be taken and the other will be left.” 36", "zh": "兩個女人一同推磨，要取去一個，撇下一個。」", "ja": "ふたりの女が一緒にうすをひいているならば、ひとりは取り去られ、他のひとりは残されるであろう。〔"}, "36": {"en": "", "zh": "", "ja": "ふたりの男が畑におれば、ひとりは取り去られ、他のひとりは残されるであろう〕」。"}, "37": {"en": "They, answering, asked him, “Where, Lord?” He said to them, “Where the body is, there the vultures will also be gathered together.”", "zh": "門徒說：「主啊，在哪裏有這事呢？」耶穌說：「屍首在哪裏，鷹也必聚在那裏。」", "ja": "弟子たちは「主よ、それはどこであるのですか」と尋ねた。するとイエスは言われた、「死体のある所には、またはげたかが集まるものである」。"}}}, "18": {"verses": {"1": {"en": "He also spoke a parable to them that they must always pray and not give up,", "zh": "耶穌設一個比喻，是要人常常禱告，不可灰心。", "ja": "また、イエスは失望せずに常に祈るべきことを、人々に譬で教えられた。"}, "2": {"en": "saying, “There was a judge in a certain city who didn’t fear God and didn’t respect man.", "zh": "說：「某城裏有一個官，不懼怕上帝，也不尊重世人。", "ja": "「ある町に、神を恐れず、人を人とも思わぬ裁判官がいた。"}, "3": {"en": "A widow was in that city, and she often came to him, saying, ‘Defend me from my adversary!’", "zh": "那城裏有個寡婦，常到他那裏，說：『我有一個對頭，求你給我伸冤。』", "ja": "ところが、その同じ町にひとりのやもめがいて、彼のもとにたびたびきて、『どうぞ、わたしを訴える者をさばいて、わたしを守ってください』と願いつづけた。"}, "4": {"en": "He wouldn’t for a while; but afterward he said to himself, ‘Though I neither fear God nor respect man,", "zh": "他多日不准， 後來心裏說：『我雖不懼怕上帝，也不尊重世人，", "ja": "彼はしばらくの間きき入れないでいたが、そののち、心のうちで考えた、『わたしは神をも恐れず、人を人とも思わないが、"}, "5": {"en": "yet because this widow bothers me, I will defend her, or else she will wear me out by her continual coming.’ ”", "zh": "只因這寡婦煩擾我，我就給她伸冤吧，免得她常來纏磨我！』」", "ja": "このやもめがわたしに面倒をかけるから、彼女のためになる裁判をしてやろう。そうしたら、絶えずやってきてわたしを悩ますことがなくなるだろう』」。"}, "6": {"en": "The Lord said, “Listen to what the unrighteous judge says.", "zh": "主說：「你們聽這不義之官所說的話。", "ja": "そこで主は言われた、「この不義な裁判官の言っていることを聞いたか。"}, "7": {"en": "Won’t God avenge his chosen ones who are crying out to him day and night, and yet he exercises patience with them?", "zh": "上帝的選民晝夜呼籲他，他縱然為他們忍了多時，豈不終久給他們伸冤嗎？", "ja": "まして神は、日夜叫び求める選民のために、正しいさばきをしてくださらずに長い間そのままにしておかれることがあろうか。"}, "8": {"en": "I tell you that he will avenge them quickly. Nevertheless, when the Son of Man comes, will he find faith on the earth?”", "zh": "我告訴你們，要快快地給他們伸冤了。然而，人子來的時候，遇得見世上有信德嗎？」", "ja": "あなたがたに言っておくが、神はすみやかにさばいてくださるであろう。しかし、人の子が来るとき、地上に信仰が見られるであろうか」。"}, "9": {"en": "He also spoke this parable to certain people who were convinced of their own righteousness, and who despised all others:", "zh": "耶穌向那些仗着自己是義人，藐視別人的，設一個比喻，", "ja": "自分を義人だと自任して他人を見下げている人たちに対して、イエスはまたこの譬をお話しになった。"}, "10": {"en": "“Two men went up into the temple to pray; one was a Pharisee, and the other was a tax collector.", "zh": "說：「有兩個人上殿裏去禱告：一個是法利賽人，一個是稅吏。", "ja": "「ふたりの人が祈るために宮に上った。そのひとりはパリサイ人であり、もうひとりは取税人であった。"}, "11": {"en": "The Pharisee stood and prayed by himself like this: ‘God, I thank you that I am not like the rest of men: extortionists, unrighteous, adulterers, or even like this tax collector.", "zh": "法利賽人站着，自言自語地禱告說：『上帝啊，我感謝你，我不像別人勒索、不義、姦淫，也不像這個稅吏。", "ja": "パリサイ人は立って、ひとりでこう祈った、『神よ、わたしはほかの人たちのような貪欲な者、不正な者、姦淫をする者ではなく、また、この取税人のような人間でもないことを感謝します。"}, "12": {"en": "I fast twice a week. I give tithes of all that I get.’", "zh": "我一個禮拜禁食兩次，凡我所得的都捐上十分之一。』", "ja": "わたしは一週に二度断食しており、全収入の十分の一をささげています』。"}, "13": {"en": "But the tax collector, standing far away, wouldn’t even lift up his eyes to heaven, but beat his chest, saying, ‘God, be merciful to me, a sinner!’", "zh": "那稅吏遠遠地站着，連舉目望天也不敢，只捶着胸說：『上帝啊，開恩可憐我這個罪人！』", "ja": "ところが、取税人は遠く離れて立ち、目を天にむけようともしないで、胸を打ちながら言った、『神様、罪人のわたしをおゆるしください』と。"}, "14": {"en": "I tell you, this man went down to his house justified rather than the other; for everyone who exalts himself will be humbled, but he who humbles himself will be exalted.”", "zh": "我告訴你們，這人回家去比那人倒算為義了；因為，凡自高的，必降為卑；自卑的，必升為高。」", "ja": "あなたがたに言っておく。神に義とされて自分の家に帰ったのは、この取税人であって、あのパリサイ人ではなかった。おおよそ、自分を高くする者は低くされ、自分を低くする者は高くされるであろう」。"}, "15": {"en": "They were also bringing their babies to him, that he might touch them. But when the disciples saw it, they rebuked them.", "zh": "有人抱着自己的嬰孩來見耶穌，要他摸他們；門徒看見就責備那些人。", "ja": "イエスにさわっていただくために、人々が幼な子らをみもとに連れてきた。ところが、弟子たちはそれを見て、彼らをたしなめた。"}, "16": {"en": "Jesus summoned them, saying, “Allow the little children to come to me, and don’t hinder them, for God’s Kingdom belongs to such as these.", "zh": "耶穌卻叫他們來，說：「讓小孩子到我這裏來，不要禁止他們，因為在上帝國的正是這樣的人。", "ja": "するとイエスは幼な子らを呼び寄せて言われた、「幼な子らをわたしのところに来るままにしておきなさい、止めてはならない。神の国はこのような者の国である。"}, "17": {"en": "Most certainly, I tell you, whoever doesn’t receive God’s Kingdom like a little child, he will in no way enter into it.”", "zh": "我實在告訴你們，凡要承受上帝國的，若不像小孩子，斷不能進去。」", "ja": "よく聞いておくがよい。だれでも幼な子のように神の国を受けいれる者でなければ、そこにはいることは決してできない」。"}, "18": {"en": "A certain ruler asked him, saying, “Good Teacher, what shall I do to inherit eternal life?”", "zh": "有一個官問耶穌說：「良善的夫子，我該做甚麼事才可以承受永生？」", "ja": "また、ある役人がイエスに尋ねた、「よき師よ、何をしたら永遠の生命が受けられましょうか」。"}, "19": {"en": "Jesus asked him, “Why do you call me good? No one is good, except one: God.", "zh": "耶穌對他說：「你為甚麼稱我是良善的？除了上帝一位之外，再沒有良善的。", "ja": "イエスは言われた、「なぜわたしをよき者と言うのか。神ひとりのほかによい者はいない。"}, "20": {"en": "You know the commandments: ‘Don’t commit adultery,’ ‘Don’t murder,’ ‘Don’t steal,’ ‘Don’t give false testimony,’ ‘Honor your father and your mother.’ ”", "zh": "誡命你是曉得的：『不可姦淫；不可殺人；不可偷盜；不可作假見證；當孝敬父母。』」", "ja": "いましめはあなたの知っているとおりである、『姦淫するな、殺すな、盗むな、偽証を立てるな、父と母とを敬え』」。"}, "21": {"en": "He said, “I have observed all these things from my youth up.”", "zh": "那人說：「這一切我從小都遵守了。」", "ja": "すると彼は言った、「それらのことはみな、小さい時から守っております」。"}, "22": {"en": "When Jesus heard these things, he said to him, “You still lack one thing. Sell all that you have and distribute it to the poor. Then you will have treasure in heaven; then come, follow me.”", "zh": "耶穌聽見了，就說：「你還缺少一件：要變賣你一切所有的，分給窮人，就必有財寶在天上；你還要來跟從我。」", "ja": "イエスはこれを聞いて言われた、「あなたのする事がまだ一つ残っている。持っているものをみな売り払って、貧しい人々に分けてやりなさい。そうすれば、天に宝を持つようになろう。そして、わたしに従ってきなさい」。"}, "23": {"en": "But when he heard these things, he became very sad, for he was very rich.", "zh": "他聽見這話，就甚憂愁，因為他很富足。", "ja": "彼はこの言葉を聞いて非常に悲しんだ。大金持であったからである。"}, "24": {"en": "Jesus, seeing that he became very sad, said, “How hard it is for those who have riches to enter into God’s Kingdom!", "zh": "耶穌看見他，就說：「有錢財的人進上帝的國是何等的難哪！", "ja": "イエスは彼の様子を見て言われた、「財産のある者が神の国にはいるのはなんとむずかしいことであろう。"}, "25": {"en": "For it is easier for a camel to enter in through a needle’s eye than for a rich man to enter into God’s Kingdom.”", "zh": "駱駝穿過針的眼比財主進上帝的國還容易呢！」", "ja": "富んでいる者が神の国にはいるよりは、らくだが針の穴を通る方が、もっとやさしい」。"}, "26": {"en": "Those who heard it said, “Then who can be saved?”", "zh": "聽見的人說：「這樣，誰能得救呢？」", "ja": "これを聞いた人々が、「それでは、だれが救われることができるのですか」と尋ねると、"}, "27": {"en": "But he said, “The things which are impossible with men are possible with God.”", "zh": "耶穌說：「在人所不能的事，在上帝卻能。」", "ja": "イエスは言われた、「人にはできない事も、神にはできる」。"}, "28": {"en": "Peter said, “Look, we have left everything and followed you.”", "zh": "彼得說：「看哪，我們已經撇下自己所有的跟從你了。」", "ja": "ペテロが言った、「ごらんなさい、わたしたちは自分のものを捨てて、あなたに従いました」。"}, "29": {"en": "He said to them, “Most certainly I tell you, there is no one who has left house, or wife, or brothers, or parents, or children, for God’s Kingdom’s sake,", "zh": "耶穌說：「我實在告訴你們，人為上帝的國撇下房屋，或是妻子、弟兄、父母、兒女，", "ja": "イエスは言われた、「よく聞いておくがよい。だれでも神の国のために、家、妻、兄弟、両親、子を捨てた者は、"}, "30": {"en": "who will not receive many times more in this time, and in the world to come, eternal life.”", "zh": "沒有在今世不得百倍，在來世不得永生的。」", "ja": "必ずこの時代ではその幾倍もを受け、また、きたるべき世では永遠の生命を受けるのである」。"}, "31": {"en": "He took the twelve aside and said to them, “Behold, we are going up to Jerusalem, and all the things that are written through the prophets concerning the Son of Man will be completed.", "zh": "耶穌帶着十二個門徒，對他們說：「看哪，我們上耶路撒冷去，先知所寫的一切事都要成就在人子身上。", "ja": "イエスは十二弟子を呼び寄せて言われた、「見よ、わたしたちはエルサレムへ上って行くが、人の子について預言者たちがしるしたことは、すべて成就するであろう。"}, "32": {"en": "For he will be delivered up to the Gentiles, will be mocked, treated shamefully, and spit on.", "zh": "他將要被交給外邦人；他們要戲弄他，凌辱他，吐唾沫在他臉上，", "ja": "人の子は異邦人に引きわたされ、あざけられ、はずかしめを受け、つばきをかけられ、"}, "33": {"en": "They will scourge and kill him. On the third day, he will rise again.”", "zh": "並要鞭打他，殺害他；第三日他要復活。」", "ja": "また、むち打たれてから、ついに殺され、そして三日目によみがえるであろう」。"}, "34": {"en": "They understood none of these things. This saying was hidden from them, and they didn’t understand the things that were said.", "zh": "這些事門徒一樣也不懂得，意思乃是隱藏的；他們不曉得所說的是甚麼。", "ja": "弟子たちには、これらのことが何一つわからなかった。この言葉が彼らに隠されていたので、イエスの言われた事が理解できなかった。"}, "35": {"en": "As he came near Jericho, a certain blind man sat by the road, begging.", "zh": "耶穌將近耶利哥的時候，有一個瞎子坐在路旁討飯。", "ja": "イエスがエリコに近づかれたとき、ある盲人が道ばたにすわって、物ごいをしていた。"}, "36": {"en": "Hearing a multitude going by, he asked what this meant.", "zh": "聽見許多人經過，就問是甚麼事。", "ja": "群衆が通り過ぎる音を耳にして、彼は何事があるのかと尋ねた。"}, "37": {"en": "They told him that Jesus of Nazareth was passing by.", "zh": "他們告訴他，是拿撒勒人耶穌經過。", "ja": "ところが、ナザレのイエスがお通りなのだと聞かされたので、"}, "38": {"en": "He cried out, “Jesus, you son of David, have mercy on me!”", "zh": "他就呼叫說：「大衛的子孫耶穌啊，可憐我吧！」", "ja": "声をあげて、「ダビデの子イエスよ、わたしをあわれんで下さい」と言った。"}, "39": {"en": "Those who led the way rebuked him, that he should be quiet; but he cried out all the more, “You son of David, have mercy on me!”", "zh": "在前頭走的人就責備他，不許他作聲；他卻越發喊叫說：「大衛的子孫，可憐我吧！」", "ja": "先頭に立つ人々が彼をしかって黙らせようとしたが、彼はますます激しく叫びつづけた、「ダビデの子よ、わたしをあわれんで下さい」。"}, "40": {"en": "Standing still, Jesus commanded him to be brought to him. When he had come near, he asked him,", "zh": "耶穌站住，吩咐把他領過來，到了跟前，就問他說：", "ja": "そこでイエスは立ちどまって、その者を連れて来るように、とお命じになった。彼が近づいたとき、"}, "41": {"en": "“What do you want me to do?” He said, “Lord, that I may see again.”", "zh": "「你要我為你做甚麼？」他說：「主啊，我要能看見。」", "ja": "「わたしに何をしてほしいのか」とおたずねになると、「主よ、見えるようになることです」と答えた。"}, "42": {"en": "Jesus said to him, “Receive your sight. Your faith has healed you.”", "zh": "耶穌說：「你可以看見！你的信救了你了。」", "ja": "そこでイエスは言われた、「見えるようになれ。あなたの信仰があなたを救った」。"}, "43": {"en": "Immediately he received his sight and followed him, glorifying God. All the people, when they saw it, praised God.", "zh": "瞎子立刻看見了，就跟隨耶穌，一路歸榮耀與上帝。眾人看見這事，也讚美上帝。", "ja": "すると彼は、たちまち見えるようになった。そして神をあがめながらイエスに従って行った。これを見て、人々はみな神をさんびした。"}}}, "19": {"verses": {"1": {"en": "He entered and was passing through Jericho.", "zh": "耶穌進了耶利哥，正經過的時候，", "ja": "さて、イエスはエリコにはいって、その町をお通りになった。"}, "2": {"en": "There was a man named Zacchaeus. He was a chief tax collector, and he was rich.", "zh": "有一個人名叫撒該，作稅吏長，是個財主。", "ja": "ところが、そこにザアカイという名の人がいた。この人は取税人のかしらで、金持であった。"}, "3": {"en": "He was trying to see who Jesus was, and couldn’t because of the crowd, because he was short.", "zh": "他要看看耶穌是怎樣的人；只因人多，他的身量又矮，所以不得看見，", "ja": "彼は、イエスがどんな人か見たいと思っていたが、背が低かったので、群衆にさえぎられて見ることができなかった。"}, "4": {"en": "He ran on ahead and climbed up into a sycamore tree to see him, for he was going to pass that way.", "zh": "就跑到前頭，爬上桑樹，要看耶穌，因為耶穌必從那裏經過。", "ja": "それでイエスを見るために、前の方に走って行って、いちじく桑の木に登った。そこを通られるところだったからである。"}, "5": {"en": "When Jesus came to the place, he looked up and saw him, and said to him, “Zacchaeus, hurry and come down, for today I must stay at your house.”", "zh": "耶穌到了那裏，抬頭一看，對他說：「撒該，快下來！今天我必住在你家裏。」", "ja": "イエスは、その場所にこられたとき、上を見あげて言われた、「ザアカイよ、急いで下りてきなさい。きょう、あなたの家に泊まることにしているから」。"}, "6": {"en": "He hurried, came down, and received him joyfully.", "zh": "他就急忙下來，歡歡喜喜地接待耶穌。", "ja": "そこでザアカイは急いでおりてきて、よろこんでイエスを迎え入れた。"}, "7": {"en": "When they saw it, they all murmured, saying, “He has gone in to lodge with a man who is a sinner.”", "zh": "眾人看見，都私下議論說：「他竟到罪人家裏去住宿。」", "ja": "人々はみな、これを見てつぶやき、「彼は罪人の家にはいって客となった」と言った。"}, "8": {"en": "Zacchaeus stood and said to the Lord, “Behold, Lord, half of my goods I give to the poor. If I have wrongfully exacted anything of anyone, I restore four times as much.”", "zh": "撒該站着對主說：「主啊，我把所有的一半給窮人；我若訛詐了誰，就還他四倍。」", "ja": "ザアカイは立って主に言った、「主よ、わたしは誓って自分の財産の半分を貧民に施します。また、もしだれかから不正な取立てをしていましたら、それを四倍にして返します」。"}, "9": {"en": "Jesus said to him, “Today, salvation has come to this house, because he also is a son of Abraham.", "zh": "耶穌說：「今天救恩到了這家，因為他也是亞伯拉罕的子孫。", "ja": "イエスは彼に言われた、「きょう、救がこの家にきた。この人もアブラハムの子なのだから。"}, "10": {"en": "For the Son of Man came to seek and to save that which was lost.”", "zh": "人子來，為要尋找、拯救失喪的人。」", "ja": "人の子がきたのは、失われたものを尋ね出して救うためである」。"}, "11": {"en": "As they heard these things, he went on and told a parable, because he was near Jerusalem, and they supposed that God’s Kingdom would be revealed immediately.", "zh": "眾人正在聽見這些話的時候，耶穌因為將近耶路撒冷，又因他們以為上帝的國快要顯出來，就另設一個比喻，說：", "ja": "人々がこれらの言葉を聞いているときに、イエスはなお一つの譬をお話しになった。それはエルサレムに近づいてこられたし、また人々が神の国はたちまち現れると思っていたためである。"}, "12": {"en": "He said therefore, “A certain nobleman went into a far country to receive for himself a kingdom and to return.", "zh": "「有一個貴冑往遠方去，要得國回來，", "ja": "それで言われた、「ある身分の高い人が、王位を受けて帰ってくるために遠い所へ旅立つことになった。"}, "13": {"en": "He called ten servants of his and gave them ten mina coins,  and told them, ‘Conduct business until I come.’", "zh": "便叫了他的十個僕人來，交給他們十錠銀子，說：『你們去做生意，直等我回來。』", "ja": "そこで十人の僕を呼び十ミナを渡して言った、『わたしが帰って来るまで、これで商売をしなさい』。"}, "14": {"en": "But his citizens hated him, and sent an envoy after him, saying, ‘We don’t want this man to reign over us.’", "zh": "他本國的人卻恨他，打發使者隨後去，說：『我們不願意這個人作我們的王。』", "ja": "ところが、本国の住民は彼を憎んでいたので、あとから使者をおくって、『この人が王になるのをわれわれは望んでいない』と言わせた。"}, "15": {"en": "“When he had come back again, having received the kingdom, he commanded these servants, to whom he had given the money, to be called to him, that he might know what they had gained by conducting business.", "zh": "他既得國回來，就吩咐叫那領銀子的僕人來，要知道他們做生意賺了多少。", "ja": "さて、彼が王位を受けて帰ってきたとき、だれがどんなもうけをしたかを知ろうとして、金を渡しておいた僕たちを呼んでこさせた。"}, "16": {"en": "The first came before him, saying, ‘Lord, your mina has made ten more minas.’", "zh": "頭一個上來，說：『主啊，你的一錠銀子已經賺了十錠。』", "ja": "最初の者が進み出て言った、『ご主人様、あなたの一ミナで十ミナをもうけました』。"}, "17": {"en": "“He said to him, ‘Well done, you good servant! Because you were found faithful with very little, you shall have authority over ten cities.’", "zh": "主人說：『好！良善的僕人，你既在最小的事上有忠心，可以有權柄管十座城。』", "ja": "主人は言った、『よい僕よ、うまくやった。あなたは小さい事に忠実であったから、十の町を支配させる』。"}, "18": {"en": "“The second came, saying, ‘Your mina, Lord, has made five minas.’", "zh": "第二個來，說：『主啊， 你的一錠銀子已經賺了五錠。』", "ja": "次の者がきて言った、『ご主人様、あなたの一ミナで五ミナをつくりました』。"}, "19": {"en": "“So he said to him, ‘And you are to be over five cities.’", "zh": "主人說：『你也可以管五座城。』", "ja": "そこでこの者にも、『では、あなたは五つの町のかしらになれ』と言った。"}, "20": {"en": "Another came, saying, ‘Lord, behold, your mina, which I kept laid away in a handkerchief,", "zh": "又有一個來說：『主啊，看哪，你的一錠銀子在這裏，我把它包在手巾裏存着。", "ja": "それから、もうひとりの者がきて言った、『ご主人様、さあ、ここにあなたの一ミナがあります。わたしはそれをふくさに包んで、しまっておきました。"}, "21": {"en": "for I feared you, because you are an exacting man. You take up that which you didn’t lay down, and reap that which you didn’t sow.’", "zh": "我原是怕你，因為你是嚴厲的人；沒有放下的，還要去拿， 沒有種下的，還要去收。』", "ja": "あなたはきびしい方で、おあずけにならなかったものを取りたて、おまきにならなかったものを刈る人なので、おそろしかったのです』。"}, "22": {"en": "“He said to him, ‘Out of your own mouth I will judge you, you wicked servant! You knew that I am an exacting man, taking up that which I didn’t lay down and reaping that which I didn’t sow.", "zh": "主人對他說：『你這惡僕，我要憑你的口定你的罪。你既知道我是嚴厲的人，沒有放下的，還要去拿，沒有種下的，還要去收，", "ja": "彼に言った、『悪い僕よ、わたしはあなたの言ったその言葉であなたをさばこう。わたしがきびしくて、あずけなかったものを取りたて、まかなかったものを刈る人間だと、知っているのか。"}, "23": {"en": "Then why didn’t you deposit my money in the bank, and at my coming, I might have earned interest on it?’", "zh": "為甚麼不把我的銀子交給銀行，等我來的時候，連本帶利都可以要回來呢？』", "ja": "では、なぜわたしの金を銀行に入れなかったのか。そうすれば、わたしが帰ってきたとき、その金を利子と一緒に引き出したであろうに』。"}, "24": {"en": "He said to those who stood by, ‘Take the mina away from him and give it to him who has the ten minas.’", "zh": "就對旁邊站着的人說：『奪過他這一錠來，給那有十錠的。』", "ja": "そして、そばに立っていた人々に、『その一ミナを彼から取り上げて、十ミナを持っている者に与えなさい』と言った。"}, "25": {"en": "“They said to him, ‘Lord, he has ten minas!’", "zh": "他們說：『主啊，他已經有十錠了。』", "ja": "彼らは言った、『ご主人様、あの人は既に十ミナを持っています』。"}, "26": {"en": "‘For I tell you that to everyone who has, will more be given; but from him who doesn’t have, even that which he has will be taken away from him.", "zh": "主人說：『我告訴你們，凡有的，還要加給他；沒有的，連他所有的也要奪過來。", "ja": "『あなたがたに言うが、おおよそ持っている人には、なお与えられ、持っていない人からは、持っているものまでも取り上げられるであろう。"}, "27": {"en": "But bring those enemies of mine who didn’t want me to reign over them here, and kill them before me.’ ”", "zh": "至於我那些仇敵，不要我作他們王的，把他們拉來，在我面前殺了吧！』」", "ja": "しかしわたしが王になることを好まなかったあの敵どもを、ここにひっぱってきて、わたしの前で打ち殺せ』」。"}, "28": {"en": "Having said these things, he went on ahead, going up to Jerusalem.", "zh": "耶穌說完了這話，就在前面走，上耶路撒冷去。", "ja": "イエスはこれらのことを言ったのち、先頭に立ち、エルサレムへ上って行かれた。"}, "29": {"en": "When he came near to Bethsphage and Bethany, at the mountain that is called Olivet, he sent two of his disciples,", "zh": "將近伯法其和伯大尼，在一座山名叫橄欖山那裏，就打發兩個門徒，說：", "ja": "そしてオリブという山に沿ったベテパゲとベタニヤに近づかれたとき、ふたりの弟子をつかわして言われた、"}, "30": {"en": "saying, “Go your way into the village on the other side, in which, as you enter, you will find a colt tied, which no man has ever sat upon. Untie it and bring it.", "zh": "「你們往對面村子裏去，進去的時候，必看見一匹驢駒拴在那裏，是從來沒有人騎過的，可以解開牽來。", "ja": "「向こうの村へ行きなさい。そこにはいったら、まだだれも乗ったことのないろばの子がつないであるのを見るであろう。それを解いて、引いてきなさい。"}, "31": {"en": "If anyone asks you, ‘Why are you untying it?’ say to him: ‘The Lord needs it.’ ”", "zh": "若有人問為甚麼解牠，你們就說：『主要用牠。』」", "ja": "もしだれかが『なぜ解くのか』と問うたら、『主がお入り用なのです』と、そう言いなさい」。"}, "32": {"en": "Those who were sent went away and found things just as he had told them.", "zh": "打發的人去了，所遇見的正如耶穌所說的。", "ja": "そこで、つかわされた者たちが行って見ると、果して、言われたとおりであった。"}, "33": {"en": "As they were untying the colt, its owners said to them, “Why are you untying the colt?”", "zh": "他們解驢駒的時候，主人問他們說：「解驢駒做甚麼？」", "ja": "彼らが、そのろばの子を解いていると、その持ち主たちが、「なぜろばの子を解くのか」と言ったので、"}, "34": {"en": "They said, “The Lord needs it.”", "zh": "他們說：「主要用牠。」", "ja": "「主がお入り用なのです」と答えた。"}, "35": {"en": "Then they brought it to Jesus. They threw their cloaks on the colt and sat Jesus on them.", "zh": "他們牽到耶穌那裏，把自己的衣服搭在上面，扶着耶穌騎上。", "ja": "そしてそれをイエスのところに引いてきて、その子ろばの上に自分たちの上着をかけてイエスをお乗せした。"}, "36": {"en": "As he went, they spread their cloaks on the road.", "zh": "走的時候，眾人把衣服鋪在路上。", "ja": "そして進んで行かれると、人々は自分たちの上着を道に敷いた。"}, "37": {"en": "As he was now getting near, at the descent of the Mount of Olives, the whole multitude of the disciples began to rejoice and praise God with a loud voice for all the mighty works which they had seen,", "zh": "將近耶路撒冷，正下橄欖山的時候，眾門徒因所見過的一切異能，都歡樂起來，大聲讚美上帝，", "ja": "いよいよオリブ山の下り道あたりに近づかれると、大ぜいの弟子たちはみな喜んで、彼らが見たすべての力あるみわざについて、声高らかに神をさんびして言いはじめた、"}, "38": {"en": "saying, “Blessed is the King who comes in the name of the Lord! Peace in heaven, and glory in the highest!”", "zh": "說： 奉主名來的王是應當稱頌的！ 在天上有和平； 在至高之處有榮光。", "ja": "「主の御名によってきたる王に、祝福あれ。天には平和、いと高きところには栄光あれ」。"}, "39": {"en": "Some of the Pharisees from the multitude said to him, “Teacher, rebuke your disciples!”", "zh": "眾人中有幾個法利賽人對耶穌說：「夫子，責備你的門徒吧！」", "ja": "ところが、群衆の中にいたあるパリサイ人たちがイエスに言った、「先生、あなたの弟子たちをおしかり下さい」。"}, "40": {"en": "He answered them, “I tell you that if these were silent, the stones would cry out.”", "zh": "耶穌說：「我告訴你們，若是他們閉口不說，這些石頭必要呼叫起來。」", "ja": "答えて言われた、「あなたがたに言うが、もしこの人たちが黙れば、石が叫ぶであろう」。"}, "41": {"en": "When he came near, he saw the city and wept over it,", "zh": "耶穌快到耶路撒冷，看見城，就為它哀哭，", "ja": "いよいよ都の近くにきて、それが見えたとき、そのために泣いて言われた、"}, "42": {"en": "saying, “If you, even you, had known today the things which belong to your peace! But now, they are hidden from your eyes.", "zh": "說：「巴不得你在這日子知道關係你平安的事；無奈這事現在是隱藏的，叫你的眼看不出來。", "ja": "「もしおまえも、この日に、平和をもたらす道を知ってさえいたら……しかし、それは今おまえの目に隠されている。"}, "43": {"en": "For the days will come on you when your enemies will throw up a barricade against you, surround you, hem you in on every side,", "zh": "因為日子將到，你的仇敵必築起土壘，周圍環繞你，四面困住你，", "ja": "いつかは、敵が周囲に塁を築き、おまえを取りかこんで、四方から押し迫り、"}, "44": {"en": "and will dash you and your children within you to the ground. They will not leave in you one stone on another, because you didn’t know the time of your visitation.”", "zh": "並要掃滅你和你裏頭的兒女，連一塊石頭也不留在石頭上，因你不知道眷顧你的時候。」", "ja": "おまえとその内にいる子らとを地に打ち倒し、城内の一つの石も他の石の上に残して置かない日が来るであろう。それは、おまえが神のおとずれの時を知らないでいたからである」。"}, "45": {"en": "He entered into the temple and began to drive out those who bought and sold in it,", "zh": "耶穌進了殿，趕出裏頭做買賣的人，", "ja": "それから宮にはいり、商売人たちを追い出しはじめて、"}, "46": {"en": "saying to them, “It is written, ‘My house is a house of prayer,’  but you have made it a ‘den of robbers’!”", "zh": "對他們說：「經上說： 我的殿必作禱告的殿， 你們倒使它成為賊窩了。」", "ja": "彼らに言われた、「『わが家は祈の家であるべきだ』と書いてあるのに、あなたがたはそれを盗賊の巣にしてしまった」。"}, "47": {"en": "He was teaching daily in the temple, but the chief priests, the scribes, and the leading men among the people sought to destroy him.", "zh": "耶穌天天在殿裏教訓人。祭司長和文士與百姓的尊長都想要殺他，", "ja": "イエスは毎日、宮で教えておられた。祭司長、律法学者また民衆の重立った者たちはイエスを殺そうと思っていたが、"}, "48": {"en": "They couldn’t find what they might do, for all the people hung on to every word that he said.", "zh": "但尋不出法子來，因為百姓都側耳聽他。", "ja": "民衆がみな熱心にイエスに耳を傾けていたので、手のくだしようがなかった。"}}}, "20": {"verses": {"1": {"en": "On one of those days, as he was teaching the people in the temple and preaching the Good News, the priests and scribes came to him with the elders.", "zh": "有一天，耶穌在殿裏教訓百姓，講福音的時候，祭司長和文士並長老上前來，", "ja": "ある日、イエスが宮で人々に教え、福音を宣べておられると、祭司長や律法学者たちが、長老たちと共に近寄ってきて、"}, "2": {"en": "They asked him, “Tell us: by what authority do you do these things? Or who is giving you this authority?”", "zh": "問他說：「你告訴我們，你仗着甚麼權柄做這些事？給你這權柄的是誰呢？」", "ja": "イエスに言った、「何の権威によってこれらの事をするのですか。そうする権威をあなたに与えたのはだれですか、わたしたちに言ってください」。"}, "3": {"en": "He answered them, “I also will ask you one question. Tell me:", "zh": "耶穌回答說：「我也要問你們一句話，你們且告訴我。", "ja": "そこで、イエスは答えて言われた、「わたしも、ひと言たずねよう。それに答えてほしい。"}, "4": {"en": "the baptism of John, was it from heaven, or from men?”", "zh": "約翰的洗禮是從天上來的？是從人間來的呢？」", "ja": "ヨハネのバプテスマは、天からであったか、人からであったか」。"}, "5": {"en": "They reasoned with themselves, saying, “If we say, ‘From heaven,’ he will say, ‘Why didn’t you believe him?’", "zh": "他們彼此商議說：「我們若說『從天上來』，他必說：『你們為甚麼不信他呢？』", "ja": "彼らは互に論じて言った、「もし天からだと言えば、では、なぜ彼を信じなかったのか、とイエスは言うだろう。"}, "6": {"en": "But if we say, ‘From men,’ all the people will stone us, for they are persuaded that John was a prophet.”", "zh": "若說『從人間來』，百姓都要用石頭打死我們，因為他們信約翰是先知。」", "ja": "しかし、もし人からだと言えば、民衆はみな、ヨハネを預言者だと信じているから、わたしたちを石で打つだろう」。"}, "7": {"en": "They answered that they didn’t know where it was from.", "zh": "於是回答說：「不知道是從哪裏來的。」", "ja": "それで彼らは「どこからか、知りません」と答えた。"}, "8": {"en": "Jesus said to them, “Neither will I tell you by what authority I do these things.”", "zh": "耶穌說：「我也不告訴你們，我仗着甚麼權柄做這些事。」", "ja": "イエスはこれに対して言われた、「わたしも何の権威によってこれらの事をするのか、あなたがたに言うまい」。"}, "9": {"en": "He began to tell the people this parable: “A  man planted a vineyard and rented it out to some farmers, and went into another country for a long time.", "zh": "耶穌就設比喻對百姓說：「有人栽了一個葡萄園，租給園戶，就往外國去住了許久。", "ja": "そこでイエスは次の譬を民衆に語り出された、「ある人がぶどう園を造って農夫たちに貸し、長い旅に出た。"}, "10": {"en": "At the proper season, he sent a servant to the farmers to collect his share of the fruit of the vineyard. But the farmers beat him and sent him away empty.", "zh": "到了時候，打發一個僕人到園戶那裏去，叫他們把園中當納的果子交給他；園戶竟打了他，叫他空手回去。", "ja": "季節になったので、農夫たちのところへ、ひとりの僕を送って、ぶどう園の収穫の分け前を出させようとした。ところが、農夫たちは、その僕を袋だたきにし、から手で帰らせた。"}, "11": {"en": "He sent yet another servant, and they also beat him and treated him shamefully, and sent him away empty.", "zh": "又打發一個僕人去，他們也打了他，並且凌辱他，叫他空手回去。", "ja": "そこで彼はもうひとりの僕を送った。彼らはその僕も袋だたきにし、侮辱を加えて、から手で帰らせた。"}, "12": {"en": "He sent yet a third, and they also wounded him and threw him out.", "zh": "又打發第三個僕人去，他們也打傷了他，把他推出去了。", "ja": "そこで更に三人目の者を送ったが、彼らはこの者も、傷を負わせて追い出した。"}, "13": {"en": "The lord of the vineyard said, ‘What shall I do? I will send my beloved son. It may be that seeing him, they will respect him.’", "zh": "園主說：『我怎麼辦呢？我要打發我的愛子去，或者他們尊敬他。』", "ja": "ぶどう園の主人は言った、『どうしようか。そうだ、わたしの愛子をつかわそう。これなら、たぶん敬ってくれるだろう』。"}, "14": {"en": "“But when the farmers saw him, they reasoned among themselves, saying, ‘This is the heir. Come, let’s kill him, that the inheritance may be ours.’", "zh": "不料，園戶看見他，就彼此商量說：『這是承受產業的，我們殺他吧，使產業歸於我們！』", "ja": "ところが、農夫たちは彼を見ると、『あれはあと取りだ。あれを殺してしまおう。そうしたら、その財産はわれわれのものになるのだ』と互に話し合い、"}, "15": {"en": "Then they threw him out of the vineyard and killed him. What therefore will the lord of the vineyard do to them?", "zh": "於是把他推出葡萄園外，殺了。這樣，葡萄園的主人要怎樣處治他們呢？", "ja": "彼をぶどう園の外に追い出して殺した。そのさい、ぶどう園の主人は、彼らをどうするだろうか。"}, "16": {"en": "He will come and destroy these farmers, and will give the vineyard to others.” When they heard that, they said, “May that never be!”", "zh": "他要來除滅這些園戶，將葡萄園轉給別人。」聽見的人說：「這是萬不可的！」", "ja": "彼は出てきて、この農夫たちを殺し、ぶどう園を他の人々に与えるであろう」。人々はこれを聞いて、「そんなことがあってはなりません」と言った。"}, "17": {"en": "But he looked at them and said, “Then what is this that is written, ‘The stone which the builders rejected was made the chief cornerstone’?", "zh": "耶穌看着他們說：「經上記着： 匠人所棄的石頭 已作了房角的頭塊石頭。", "ja": "そこで、イエスは彼らを見つめて言われた、「それでは、『家造りらの捨てた石が隅のかしら石になった』と書いてあるのは、どういうことか。"}, "18": {"en": "Everyone who falls on that stone will be broken to pieces, but it will crush whomever it falls on to dust.”", "zh": "這是甚麼意思呢？   凡掉在那石頭上的，必要跌碎；那石頭掉在誰的身上，就要把誰砸得稀爛。」", "ja": "すべてその石の上に落ちる者は打ち砕かれ、それがだれかの上に落ちかかるなら、その人はこなみじんにされるであろう」。"}, "19": {"en": "The chief priests and the scribes sought to lay hands on him that very hour, but they feared the people—for they knew he had spoken this parable against them.", "zh": "文士和祭司長看出這比喻是指着他們說的，當時就想要下手拿他，只是懼怕百姓。", "ja": "このとき、律法学者たちや祭司長たちはイエスに手をかけようと思ったが、民衆を恐れた。いまの譬が自分たちに当てて語られたのだと、悟ったからである。"}, "20": {"en": "They watched him and sent out spies, who pretended to be righteous, that they might trap him in something he said, so as to deliver him up to the power and authority of the governor.", "zh": "於是窺探耶穌，打發奸細裝作好人，要在他的話上得把柄，好將他交在巡撫的政權之下。", "ja": "そこで、彼らは機会をうかがい、義人を装うまわし者どもを送って、イエスを総督の支配と権威とに引き渡すため、その言葉じりを捕えさせようとした。"}, "21": {"en": "They asked him, “Teacher, we know that you say and teach what is right, and aren’t partial to anyone, but truly teach the way of God.", "zh": "奸細就問耶穌說：「夫子，我們曉得你所講所傳都是正道，也不取人的外貌，乃是誠誠實實傳上帝的道。", "ja": "彼らは尋ねて言った、「先生、わたしたちは、あなたの語り教えられることが正しく、また、あなたは分け隔てをなさらず、真理に基いて神の道を教えておられることを、承知しています。"}, "22": {"en": "Is it lawful for us to pay taxes to Caesar, or not?”", "zh": "我們納稅給凱撒，可以不可以？」", "ja": "ところで、カイザルに貢を納めてよいでしょうか、いけないでしょうか」。"}, "23": {"en": "But he perceived their craftiness, and said to them, “Why do you test me?", "zh": "耶穌看出他們的詭詐，就對他們說：", "ja": "イエスは彼らの悪巧みを見破って言われた、"}, "24": {"en": "Show me a denarius. Whose image and inscription are on it?” They answered, “Caesar’s.”", "zh": "「拿一個銀錢來給我看。這像和這號是誰的？」他們說：「是凱撒的。」", "ja": "「デナリを見せなさい。それにあるのは、だれの肖像、だれの記号なのか」。「カイザルのです」と、彼らが答えた。"}, "25": {"en": "He said to them, “Then give to Caesar the things that are Caesar’s, and to God the things that are God’s.”", "zh": "耶穌說：「這樣，凱撒的物當歸給凱撒，上帝的物當歸給上帝。」", "ja": "するとイエスは彼らに言われた、「それなら、カイザルのものはカイザルに、神のものは神に返しなさい」。"}, "26": {"en": "They weren’t able to trap him in his words before the people. They marveled at his answer and were silent.", "zh": "他們當着百姓，在這話上得不着把柄，又希奇他的應對，就閉口無言了。", "ja": "そこで彼らは、民衆の前でイエスの言葉じりを捕えることができず、その答に驚嘆して、黙ってしまった。"}, "27": {"en": "Some of the Sadducees came to him, those who deny that there is a resurrection.", "zh": "撒都該人常說沒有復活的事。有幾個來問耶穌說：", "ja": "復活ということはないと言い張っていたサドカイ人のある者たちが、イエスに近寄ってきて質問した、"}, "28": {"en": "They asked him, “Teacher, Moses wrote to us that if a man’s brother dies having a wife, and he is childless, his brother should take the wife and raise up children for his brother.", "zh": "「夫子！摩西為我們寫着說：『人若有妻無子就死了，他兄弟當娶他的妻，為哥哥生子立後。』", "ja": "「先生、モーセは、わたしたちのためにこう書いています、『もしある人の兄が妻をめとり、子がなくて死んだなら、弟はこの女をめとって、兄のために子をもうけねばならない』。"}, "29": {"en": "There were therefore seven brothers. The first took a wife, and died childless.", "zh": "有弟兄七人，第一個娶了妻，沒有孩子死了；", "ja": "ところで、ここに七人の兄弟がいました。長男は妻をめとりましたが、子がなくて死に、"}, "30": {"en": "The second took her as wife, and he died childless.", "zh": "第二個、第三個也娶過她；", "ja": "そして次男、三男と、次々に、その女をめとり、"}, "31": {"en": "The third took her, and likewise the seven all left no children, and died.", "zh": "那七個人都娶過她，沒有留下孩子就死了。", "ja": "七人とも同様に、子をもうけずに死にました。"}, "32": {"en": "Afterward the woman also died.", "zh": "後來婦人也死了。", "ja": "のちに、その女も死にました。"}, "33": {"en": "Therefore in the resurrection whose wife of them will she be? For the seven had her as a wife.”", "zh": "這樣，當復活的時候，她是哪一個的妻子呢？因為他們七個人都娶過她。」", "ja": "さて、復活の時には、この女は七人のうち、だれの妻になるのですか。七人とも彼女を妻にしたのですが」。"}, "34": {"en": "Jesus said to them, “The children of this age marry and are given in marriage.", "zh": "耶穌說：「這世界的人有娶有嫁；", "ja": "イエスは彼らに言われた、「この世の子らは、めとったり、とついだりするが、"}, "35": {"en": "But those who are considered worthy to attain to that age and the resurrection from the dead neither marry nor are given in marriage.", "zh": "惟有算為配得那世界，與從死裏復活的人也不娶也不嫁；", "ja": "かの世にはいって死人からの復活にあずかるにふさわしい者たちは、めとったり、とついだりすることはない。"}, "36": {"en": "For they can’t die any more, for they are like the angels and are children of God, being children of the resurrection.", "zh": "因為他們不能再死，和天使一樣；既是復活的人，就為上帝的兒子。", "ja": "彼らは天使に等しいものであり、また復活にあずかるゆえに、神の子でもあるので、もう死ぬことはあり得ないからである。"}, "37": {"en": "But that the dead are raised, even Moses showed at the bush, when he called the Lord ‘The God of Abraham, the God of Isaac, and the God of Jacob.’", "zh": "至於死人復活，摩西在荊棘篇上，稱主是亞伯拉罕的上帝，以撒的上帝，雅各的上帝，就指示明白了。", "ja": "死人がよみがえることは、モーセも柴の篇で、主を『アブラハムの神、イサクの神、ヤコブの神』と呼んで、これを示した。"}, "38": {"en": "Now he is not the God of the dead, but of the living, for all are alive to him.”", "zh": "上帝原不是死人的上帝，乃是活人的上帝；因為在他那裏，人都是活的。」", "ja": "神は死んだ者の神ではなく、生きている者の神である。人はみな神に生きるものだからである」。"}, "39": {"en": "Some of the scribes answered, “Teacher, you speak well.”", "zh": "有幾個文士說：「夫子！你說得好。」", "ja": "律法学者のうちのある人々が答えて言った、「先生、仰せのとおりです」。"}, "40": {"en": "They didn’t dare to ask him any more questions.", "zh": "以後他們不敢再問他甚麼。", "ja": "彼らはそれ以上何もあえて問いかけようとしなかった。"}, "41": {"en": "He said to them, “Why do they say that the Christ is David’s son?", "zh": "耶穌對他們說：「人怎麼說基督是大衛的子孫呢？", "ja": "イエスは彼らに言われた、「どうして人々はキリストをダビデの子だと言うのか。"}, "42": {"en": "David himself says in the book of Psalms, ‘The Lord said to my Lord, “Sit at my right hand,", "zh": "詩篇上大衛自己說： 主對我主說： 你坐在我的右邊，", "ja": "ダビデ自身が詩篇の中で言っている、『主はわが主に仰せになった、"}, "43": {"en": "until I make your enemies the footstool of your feet.” ’", "zh": "等我使你仇敵作你的腳凳。", "ja": "あなたの敵をあなたの足台とする時までは、わたしの右に座していなさい』。"}, "44": {"en": "“David therefore calls him Lord, so how is he his son?”", "zh": "大衛既稱他為主，他怎麼又是大衛的子孫呢？」", "ja": "このように、ダビデはキリストを主と呼んでいる。それなら、どうしてキリストはダビデの子であろうか」。"}, "45": {"en": "In the hearing of all the people, he said to his disciples,", "zh": "眾百姓聽的時候，耶穌對門徒說：", "ja": "民衆がみな聞いているとき、イエスは弟子たちに言われた、"}, "46": {"en": "“Beware of those scribes who like to walk in long robes, and love greetings in the marketplaces, the best seats in the synagogues, and the best places at feasts;", "zh": "「你們要防備文士。他們好穿長衣遊行，喜愛人在街市上問他們安，又喜愛會堂裏的高位，筵席上的首座；", "ja": "「律法学者に気をつけなさい。彼らは長い衣を着て歩くのを好み、広場での敬礼や会堂の上席や宴会の上座をよろこび、"}, "47": {"en": "who devour widows’ houses, and for a pretense make long prayers. These will receive greater condemnation.”", "zh": "他們侵吞寡婦的家產，假意作很長的禱告。這些人要受更重的刑罰！」", "ja": "やもめたちの家を食い倒し、見えのために長い祈をする。彼らはもっときびしいさばきを受けるであろう」。"}}}, "21": {"verses": {"1": {"en": "He looked up and saw the rich people who were putting their gifts into the treasury.", "zh": "耶穌抬頭觀看，見財主把捐項投在庫裏，", "ja": "イエスは目をあげて、金持たちがさいせん箱に献金を投げ入れるのを見られ、"}, "2": {"en": "He saw a certain poor widow casting in two small brass coins.", "zh": "又見一個窮寡婦投了兩個小錢，", "ja": "また、ある貧しいやもめが、レプタ二つを入れるのを見て"}, "3": {"en": "He said, “Truly I tell you, this poor widow put in more than all of them,", "zh": "就說：「我實在告訴你們，這窮寡婦所投的比眾人還多；", "ja": "言われた、「よく聞きなさい。あの貧しいやもめはだれよりもたくさん入れたのだ。"}, "4": {"en": "for all these put in gifts for God from their abundance, but she, out of her poverty, put in all that she had to live on.”", "zh": "因為眾人都是自己有餘，拿出來投在捐項裏，但這寡婦是自己不足，把她一切養生的都投上了。」", "ja": "これらの人たちはみな、ありあまる中から献金を投げ入れたが、あの婦人は、その乏しい中から、持っている生活費全部を入れたからである」。"}, "5": {"en": "As some were talking about the temple and how it was decorated with beautiful stones and gifts, he said,", "zh": "有人談論聖殿是用美石和供物妝飾的；", "ja": "ある人々が、見事な石と奉納物とで宮が飾られていることを話していたので、イエスは言われた、"}, "6": {"en": "“As for these things which you see, the days will come in which there will not be left here one stone on another that will not be thrown down.”", "zh": "耶穌就說：「論到你們所看見的這一切，將來日子到了，在這裏沒有一塊石頭留在石頭上，不被拆毀了。」", "ja": "「あなたがたはこれらのものをながめているが、その石一つでもくずされずに、他の石の上に残ることもなくなる日が、来るであろう」。"}, "7": {"en": "They asked him, “Teacher, so when will these things be? What is the sign that these things are about to happen?”", "zh": "他們問他說：「夫子！甚麼時候有這事呢？這事將到的時候有甚麼預兆呢？」", "ja": "そこで彼らはたずねた、「先生、では、いつそんなことが起るのでしょうか。またそんなことが起るような場合には、どんな前兆がありますか」。"}, "8": {"en": "He said, “Watch out that you don’t get led astray, for many will come in my name, saying, ‘I am he,’ and, ‘The time is at hand.’ Therefore don’t follow them.", "zh": "耶穌說：「你們要謹慎，不要受迷惑；因為將來有好些人冒我的名來，說：『我是基督』，又說：『時候近了』，你們不要跟從他們！", "ja": "イエスが言われた、「あなたがたは、惑わされないように気をつけなさい。多くの者がわたしの名を名のって現れ、自分がそれだとか、時が近づいたとか、言うであろう。彼らについて行くな。"}, "9": {"en": "When you hear of wars and disturbances, don’t be terrified, for these things must happen first, but the end won’t come immediately.”", "zh": "你們聽見打仗和擾亂的事，不要驚惶；因為這些事必須先有，只是末期不能立時就到。」", "ja": "戦争と騒乱とのうわさを聞くときにも、おじ恐れるな。こうしたことはまず起らねばならないが、終りはすぐにはこない」。"}, "10": {"en": "Then he said to them, “Nation will rise against nation, and kingdom against kingdom.", "zh": "當時，耶穌對他們說：「民要攻打民，國要攻打國；", "ja": "それから彼らに言われた、「民は民に、国は国に敵対して立ち上がるであろう。"}, "11": {"en": "There will be great earthquakes, famines, and plagues in various places. There will be terrors and great signs from heaven.", "zh": "地要大大震動，多處必有饑荒、瘟疫，又有可怕的異象和大神蹟從天上顯現。", "ja": "また大地震があり、あちこちに疫病やききんが起り、いろいろ恐ろしいことや天からの物すごい前兆があるであろう。"}, "12": {"en": "But before all these things, they will lay their hands on you and will persecute you, delivering you up to synagogues and prisons, bringing you before kings and governors for my name’s sake.", "zh": "但這一切的事以先，人要下手拿住你們，逼迫你們，把你們交給會堂，並且收在監裏，又為我的名拉你們到君王諸侯面前。", "ja": "しかし、これらのあらゆる出来事のある前に、人々はあなたがたに手をかけて迫害をし、会堂や獄に引き渡し、わたしの名のゆえに王や総督の前にひっぱって行くであろう。"}, "13": {"en": "It will turn out as a testimony for you.", "zh": "但這些事終必為你們的見證。", "ja": "それは、あなたがたがあかしをする機会となるであろう。"}, "14": {"en": "Settle it therefore in your hearts not to meditate beforehand how to answer,", "zh": "所以，你們當立定心意，不要預先思想怎樣分訴；", "ja": "だから、どう答弁しようかと、前もって考えておかないことに心を決めなさい。"}, "15": {"en": "for I will give you a mouth and wisdom which all your adversaries will not be able to withstand or to contradict.", "zh": "因為我必賜你們口才、智慧，是你們一切敵人所敵不住、駁不倒的。", "ja": "あなたの反対者のだれもが抗弁も否定もできないような言葉と知恵とを、わたしが授けるから。"}, "16": {"en": "You will be handed over even by parents, brothers, relatives, and friends. They will cause some of you to be put to death.", "zh": "連你們的父母、弟兄、親族、朋友也要把你們交官；你們也有被他們害死的。", "ja": "しかし、あなたがたは両親、兄弟、親族、友人にさえ裏切られるであろう。また、あなたがたの中で殺されるものもあろう。"}, "17": {"en": "You will be hated by all men for my name’s sake.", "zh": "你們要為我的名被眾人恨惡，", "ja": "また、わたしの名のゆえにすべての人に憎まれるであろう。"}, "18": {"en": "And not a hair of your head will perish.", "zh": "然而，你們連一根頭髮也必不損壞。", "ja": "しかし、あなたがたの髪の毛一すじでも失われることはない。"}, "19": {"en": "“By your endurance you will win your lives.", "zh": "你們常存忍耐，就必保全靈魂。」", "ja": "あなたがたは耐え忍ぶことによって、自分の魂をかち取るであろう。"}, "20": {"en": "“But when you see Jerusalem surrounded by armies, then know that its desolation is at hand.", "zh": "「你們看見耶路撒冷被兵圍困，就可知道它成荒場的日子近了。", "ja": "エルサレムが軍隊に包囲されるのを見たならば、そのときは、その滅亡が近づいたとさとりなさい。"}, "21": {"en": "Then let those who are in Judea flee to the mountains. Let those who are in the middle of her depart. Let those who are in the country not enter therein.", "zh": "那時，在猶太的應當逃到山上；在城裏的應當出來；在鄉下的不要進城；", "ja": "そのとき、ユダヤにいる人々は山へ逃げよ。市中にいる者は、そこから出て行くがよい。また、いなかにいる者は市内にはいってはいけない。"}, "22": {"en": "For these are days of vengeance, that all things which are written may be fulfilled.", "zh": "因為這是報應的日子，使經上所寫的都得應驗。", "ja": "それは、聖書にしるされたすべての事が実現する刑罰の日であるからだ。"}, "23": {"en": "Woe to those who are pregnant and to those who nurse infants in those days! For there will be great distress in the land and wrath to this people.", "zh": "當那些日子，懷孕的和奶孩子的有禍了！因為將有大災難降在這地方，也有震怒臨到這百姓。", "ja": "その日には、身重の女と乳飲み子をもつ女とは、不幸である。地上には大きな苦難があり、この民にはみ怒りが臨み、"}, "24": {"en": "They will fall by the edge of the sword, and will be led captive into all the nations. Jerusalem will be trampled down by the Gentiles until the times of the Gentiles are fulfilled.", "zh": "他們要倒在刀下，又被擄到各國去。耶路撒冷要被外邦人踐踏，直到外邦人的日期滿了。」", "ja": "彼らはつるぎの刃に倒れ、また捕えられて諸国へ引きゆかれるであろう。そしてエルサレムは、異邦人の時期が満ちるまで、彼らに踏みにじられているであろう。"}, "25": {"en": "“There will be signs in the sun, moon, and stars; and on the earth anxiety of nations, in perplexity for the roaring of the sea and the waves;", "zh": "「日、月、星辰要顯出異兆，地上的邦國也有困苦；因海中波浪的響聲，就慌慌不定。", "ja": "また日と月と星とに、しるしが現れるであろう。そして、地上では、諸国民が悩み、海と大波とのとどろきにおじ惑い、"}, "26": {"en": "men fainting for fear and for expectation of the things which are coming on the world, for the powers of the heavens will be shaken.", "zh": "天勢都要震動，人想起那將要臨到世界的事，就都嚇得魂不附體。", "ja": "人々は世界に起ろうとする事を思い、恐怖と不安で気絶するであろう。もろもろの天体が揺り動かされるからである。"}, "27": {"en": "Then they will see the Son of Man coming in a cloud with power and great glory.", "zh": "那時，他們要看見人子有能力，有大榮耀駕雲降臨。", "ja": "そのとき、大いなる力と栄光とをもって、人の子が雲に乗って来るのを、人々は見るであろう。"}, "28": {"en": "But when these things begin to happen, look up and lift up your heads, because your redemption is near.”", "zh": "一有這些事，你們就當挺身昂首，因為你們得贖的日子近了。」", "ja": "これらの事が起りはじめたら、身を起し頭をもたげなさい。あなたがたの救が近づいているのだから」。"}, "29": {"en": "He told them a parable. “See the fig tree and all the trees.", "zh": "耶穌又設比喻對他們說：「你們看無花果樹和各樣的樹；它發芽的時候，你們一看見，自然曉得夏天近了。", "ja": "それから一つの譬を話された、「いちじくの木を、またすべての木を見なさい。"}, "30": {"en": "When they are already budding, you see it and know by your own selves that the summer is already near.", "zh": "", "ja": "はや芽を出せば、あなたがたはそれを見て、夏がすでに近いと、自分で気づくのである。"}, "31": {"en": "Even so you also, when you see these things happening, know that God’s Kingdom is near.", "zh": "這樣，你們看見這些事漸漸地成就，也該曉得上帝的國近了。", "ja": "このようにあなたがたも、これらの事が起るのを見たなら、神の国が近いのだとさとりなさい。"}, "32": {"en": "Most certainly I tell you, this generation will not pass away until all things are accomplished.", "zh": "我實在告訴你們，這世代還沒有過去，這些事都要成就。", "ja": "よく聞いておきなさい。これらの事が、ことごとく起るまでは、この時代は滅びることがない。"}, "33": {"en": "Heaven and earth will pass away, but my words will by no means pass away.", "zh": "天地要廢去，我的話卻不能廢去。」", "ja": "天地は滅びるであろう。しかしわたしの言葉は決して滅びることがない。"}, "34": {"en": "“So be careful, or your hearts will be loaded down with carousing, drunkenness, and cares of this life, and that day will come on you suddenly.", "zh": "「你們要謹慎，恐怕因貪食、醉酒，並今生的思慮累住你們的心，那日子就如同網羅忽然臨到你們；", "ja": "あなたがたが放縦や、泥酔や、世の煩いのために心が鈍っているうちに、思いがけないとき、その日がわなのようにあなたがたを捕えることがないように、よく注意していなさい。"}, "35": {"en": "For it will come like a snare on all those who dwell on the surface of all the earth.", "zh": "因為那日子要這樣臨到全地上一切居住的人。", "ja": "その日は地の全面に住むすべての人に臨むのであるから。"}, "36": {"en": "Therefore be watchful all the time, praying that you may be counted worthy to escape all these things that will happen, and to stand before the Son of Man.”", "zh": "你們要時時警醒，常常祈求，使你們能逃避這一切要來的事，得以站立在人子面前。」", "ja": "これらの起ろうとしているすべての事からのがれて、人の子の前に立つことができるように、絶えず目をさまして祈っていなさい」。"}, "37": {"en": "Every day Jesus was teaching in the temple, and every night he would go out and spend the night on the mountain that is called Olivet.", "zh": "耶穌每日在殿裏教訓人，每夜出城在一座山，名叫橄欖山住宿。", "ja": "イエスは昼のあいだは宮で教え、夜には出て行ってオリブという山で夜をすごしておられた。"}, "38": {"en": "All the people came early in the morning to him in the temple to hear him.", "zh": "眾百姓清早上聖殿，到耶穌那裏，要聽他講道。", "ja": "民衆はみな、み教を聞こうとして、いつも朝早く宮に行き、イエスのもとに集まった。"}}}, "22": {"verses": {"1": {"en": "Now the feast of unleavened bread, which is called the Passover, was approaching.", "zh": "除酵節（又名逾越節）近了。", "ja": "さて、過越といわれている除酵祭が近づいた。"}, "2": {"en": "The chief priests and the scribes sought how they might put him to death, for they feared the people.", "zh": "祭司長和文士想法子怎麼才能殺害耶穌，是因他們懼怕百姓。", "ja": "祭司長たちや律法学者たちは、どうかしてイエスを殺そうと計っていた。民衆を恐れていたからである。"}, "3": {"en": "Satan entered into Judas, who was also called Iscariot, who was counted with the twelve.", "zh": "這時，撒但入了那稱為加略人猶大的心；他本是十二門徒裏的一個。", "ja": "そのとき、十二弟子のひとりで、イスカリオテと呼ばれていたユダに、サタンがはいった。"}, "4": {"en": "He went away and talked with the chief priests and captains about how he might deliver him to them.", "zh": "他去和祭司長並守殿官商量，怎麼可以把耶穌交給他們。", "ja": "すなわち、彼は祭司長たちや宮守がしらたちのところへ行って、どうしてイエスを彼らに渡そうかと、その方法について協議した。"}, "5": {"en": "They were glad, and agreed to give him money.", "zh": "他們歡喜，就約定給他銀子。", "ja": "彼らは喜んで、ユダに金を与える取決めをした。"}, "6": {"en": "He consented and sought an opportunity to deliver him to them in the absence of the multitude.", "zh": "他應允了，就找機會，要趁眾人不在跟前的時候把耶穌交給他們。", "ja": "ユダはそれを承諾した。そして、群衆のいないときにイエスを引き渡そうと、機会をねらっていた。"}, "7": {"en": "The day of unleavened bread came, on which the Passover must be sacrificed.", "zh": "除酵節，須宰逾越羊羔的那一天到了。", "ja": "さて、過越の小羊をほふるべき除酵祭の日がきたので、"}, "8": {"en": "Jesus sent Peter and John, saying, “Go and prepare the Passover for us, that we may eat.”", "zh": "耶穌打發彼得、約翰，說：「你們去為我們預備逾越節的筵席，好叫我們吃。」", "ja": "イエスはペテロとヨハネとを使いに出して言われた、「行って、過越の食事ができるように準備をしなさい」。"}, "9": {"en": "They said to him, “Where do you want us to prepare?”", "zh": "他們問他說：「要我們在哪裏預備？」", "ja": "彼らは言った、「どこに準備をしたらよいのですか」。"}, "10": {"en": "He said to them, “Behold, when you have entered into the city, a man carrying a pitcher of water will meet you. Follow him into the house which he enters.", "zh": "耶穌說：「你們進了城，必有人拿着一瓶水迎面而來，你們就跟着他，到他所進的房子裏去，", "ja": "イエスは言われた、「市内にはいったら、水がめを持っている男に出会うであろう。その人がはいる家までついて行って、"}, "11": {"en": "Tell the master of the house, ‘The Teacher says to you, “Where is the guest room, where I may eat the Passover with my disciples?” ’", "zh": "對那家的主人說：『夫子說：客房在哪裏？我與門徒好在那裏吃逾越節的筵席。』", "ja": "その家の主人に言いなさい、『弟子たちと一緒に過越の食事をする座敷はどこか、と先生が言っておられます』。"}, "12": {"en": "He will show you a large, furnished upper room. Make preparations there.”", "zh": "他必指給你們擺設整齊的一間大樓，你們就在那裏預備。」", "ja": "すると、その主人は席の整えられた二階の広間を見せてくれるから、そこに用意をしなさい」。"}, "13": {"en": "They went, found things as Jesus had told them, and they prepared the Passover.", "zh": "他們去了，所遇見的正如耶穌所說的；他們就預備了逾越節的筵席。", "ja": "弟子たちは出て行ってみると、イエスが言われたとおりであったので、過越の食事の用意をした。"}, "14": {"en": "When the hour had come, he sat down with the twelve apostles.", "zh": "時候到了，耶穌坐席，使徒也和他同坐。", "ja": "時間になったので、イエスは食卓につかれ、使徒たちも共に席についた。"}, "15": {"en": "He said to them, “I have earnestly desired to eat this Passover with you before I suffer,", "zh": "耶穌對他們說：「我很願意在受害以先和你們吃這逾越節的筵席。", "ja": "イエスは彼らに言われた、「わたしは苦しみを受ける前に、あなたがたとこの過越の食事をしようと、切に望んでいた。"}, "16": {"en": "for I tell you, I will no longer by any means eat of it until it is fulfilled in God’s Kingdom.”", "zh": "我告訴你們，我不再吃這筵席，直到成就在上帝的國裏。」", "ja": "あなたがたに言って置くが、神の国で過越が成就する時までは、わたしは二度と、この過越の食事をすることはない」。"}, "17": {"en": "He received a cup, and when he had given thanks, he said, “Take this and share it among yourselves,", "zh": "耶穌接過杯來，祝謝了，說：「你們拿這個，大家分着喝。", "ja": "そして杯を取り、感謝して言われた、「これを取って、互に分けて飲め。"}, "18": {"en": "for I tell you, I will not drink at all again from the fruit of the vine, until God’s Kingdom comes.”", "zh": "我告訴你們，從今以後，我不再喝這葡萄汁，直等上帝的國來到。」", "ja": "あなたがたに言っておくが、今からのち神の国が来るまでは、わたしはぶどうの実から造ったものを、いっさい飲まない」。"}, "19": {"en": "He took bread, and when he had given thanks, he broke and gave it to them, saying, “This is my body which is given for you. Do this in memory of me.”", "zh": "又拿起餅來，祝謝了，就擘開，遞給他們，說：「這是我的身體，為你們捨的，你們也應當如此行，為的是記念我。」", "ja": "またパンを取り、感謝してこれをさき、弟子たちに与えて言われた、「これは、あなたがたのために与えるわたしのからだである。わたしを記念するため、このように行いなさい」。"}, "20": {"en": "Likewise, he took the cup after supper, saying, “This cup is the new covenant in my blood, which is poured out for you.", "zh": "飯後也照樣拿起杯來，說：「這杯是用我血所立的新約，是為你們流出來的。", "ja": "食事ののち、杯も同じ様にして言われた、「この杯は、あなたがたのために流すわたしの血で立てられる新しい契約である。"}, "21": {"en": "But behold, the hand of him who betrays me is with me on the table.", "zh": "看哪， 那賣我之人的手與我一同在桌子上。", "ja": "しかし、そこに、わたしを裏切る者が、わたしと一緒に食卓に手を置いている。"}, "22": {"en": "The Son of Man indeed goes as it has been determined, but woe to that man through whom he is betrayed!”", "zh": "人子固然要照所預定的去世，但賣人子的人有禍了！」", "ja": "人の子は定められたとおりに、去って行く。しかし人の子を裏切るその人は、わざわいである」。"}, "23": {"en": "They began to question among themselves which of them it was who would do this thing.", "zh": "他們就彼此對問，是哪一個要做這事。", "ja": "弟子たちは、自分たちのうちのだれが、そんな事をしようとしているのだろうと、互に論じはじめた。"}, "24": {"en": "A dispute also arose among them, which of them was considered to be greatest.", "zh": "門徒起了爭論，他們中間哪一個可算為大。", "ja": "それから、自分たちの中でだれがいちばん偉いだろうかと言って、争論が彼らの間に、起った。"}, "25": {"en": "He said to them, “The kings of the nations lord it over them, and those who have authority over them are called ‘benefactors.’", "zh": "耶穌說：「外邦人有君王為主治理他們，那掌權管他們的稱為恩主。", "ja": "そこでイエスが言われた、「異邦の王たちはその民の上に君臨し、また、権力をふるっている者たちは恩人と呼ばれる。"}, "26": {"en": "But not so with you. Rather, the one who is greater among you, let him become as the younger, and one who is governing, as one who serves.", "zh": "但你們不可這樣；你們裏頭為大的，倒要像年幼的，為首領的，倒要像服事人的。", "ja": "しかし、あなたがたは、そうであってはならない。かえって、あなたがたの中でいちばん偉い人はいちばん若い者のように、指導する人は仕える者のようになるべきである。"}, "27": {"en": "For who is greater, one who sits at the table, or one who serves? Isn’t it he who sits at the table? But I am among you as one who serves.", "zh": "是誰為大？是坐席的呢？是服事人的呢？不是坐席的大嗎？然而，我在你們中間如同服事人的。", "ja": "食卓につく人と給仕する者と、どちらが偉いのか。食卓につく人の方ではないか。しかし、わたしはあなたがたの中で、給仕をする者のようにしている。"}, "28": {"en": "“But you are those who have continued with me in my trials.", "zh": "我在磨煉之中，常和我同在的就是你們。", "ja": "あなたがたは、わたしの試錬のあいだ、わたしと一緒に最後まで忍んでくれた人たちである。"}, "29": {"en": "I confer on you a kingdom, even as my Father conferred on me,", "zh": "我將國賜給你們，正如我父賜給我一樣，", "ja": "それで、わたしの父が国の支配をわたしにゆだねてくださったように、わたしもそれをあなたがたにゆだね、"}, "30": {"en": "that you may eat and drink at my table in my Kingdom. You will sit on thrones, judging the twelve tribes of Israel.”", "zh": "叫你們在我國裏，坐在我的席上吃喝，並且坐在寶座上，審判以色列十二個支派。」", "ja": "わたしの国で食卓について飲み食いをさせ、また位に座してイスラエルの十二の部族をさばかせるであろう。"}, "31": {"en": "The Lord said, “Simon, Simon, behold, Satan asked to have all of you, that he might sift you as wheat,", "zh": "主又說：「西門！西門！撒但想要得着你們，好篩你們像篩麥子一樣；", "ja": "シモン、シモン、見よ、サタンはあなたがたを麦のようにふるいにかけることを願って許された。"}, "32": {"en": "but I prayed for you, that your faith wouldn’t fail. You, when once you have turned again, establish your brothers.”", "zh": "但我已經為你祈求，叫你不至於失了信心。你回頭以後，要堅固你的弟兄。」", "ja": "しかし、わたしはあなたの信仰がなくならないように、あなたのために祈った。それで、あなたが立ち直ったときには、兄弟たちを力づけてやりなさい」。"}, "33": {"en": "He said to him, “Lord, I am ready to go with you both to prison and to death!”", "zh": "彼得說：「主啊，我就是同你下監，同你受死，也是甘心！」", "ja": "シモンが言った、「主よ、わたしは獄にでも、また死に至るまでも、あなたとご一緒に行く覚悟です」。"}, "34": {"en": "He said, “I tell you, Peter, the rooster will by no means crow today until you deny that you know me three times.”", "zh": "耶穌說：「彼得，我告訴你，今日雞還沒有叫，你要三次說不認得我。」", "ja": "するとイエスが言われた、「ペテロよ、あなたに言っておく。きょう、鶏が鳴くまでに、あなたは三度わたしを知らないと言うだろう」。"}, "35": {"en": "He said to them, “When I sent you out without purse, bag, and sandals, did you lack anything?” They said, “Nothing.”", "zh": "耶穌又對他們說：「我差你們出去的時候，沒有錢囊，沒有口袋，沒有鞋，你們缺少甚麼沒有？」他們說：「沒有。」", "ja": "そして彼らに言われた、「わたしが財布も袋もくつも持たせずにあなたがたをつかわしたとき、何かこまったことがあったか」。彼らは、「いいえ、何もありませんでした」と答えた。"}, "36": {"en": "Then he said to them, “But now, whoever has a purse, let him take it, and likewise a bag. Whoever has none, let him sell his cloak, and buy a sword.", "zh": "耶穌說：「但如今有錢囊的可以帶着，有口袋的也可以帶着，沒有刀的要賣衣服買刀。", "ja": "そこで言われた、「しかし今は、財布のあるものは、それを持って行け。袋も同様に持って行け。また、つるぎのない者は、自分の上着を売って、それを買うがよい。"}, "37": {"en": "For I tell you that this which is written must still be fulfilled in me: ‘He was counted with transgressors.’ For that which concerns me is being fulfilled.”", "zh": "我告訴你們，經上寫着說：『他被列在罪犯之中。』這話必應驗在我身上，因為那關係我的事必然成就。」", "ja": "あなたがたに言うが、『彼は罪人のひとりに数えられた』としるしてあることは、わたしの身に成しとげられねばならない。そうだ、わたしに係わることは成就している」。"}, "38": {"en": "They said, “Lord, behold, here are two swords.” He said to them, “That is enough.”", "zh": "他們說：「主啊，請看！這裏有兩把刀。」耶穌說：「夠了。」", "ja": "弟子たちが言った、「主よ、ごらんなさい、ここにつるぎが二振りございます」。イエスは言われた、「それでよい」。"}, "39": {"en": "He came out and went, as his custom was, to the Mount of Olives. His disciples also followed him.", "zh": "耶穌出來，照常往橄欖山去，門徒也跟隨他。", "ja": "イエスは出て、いつものようにオリブ山に行かれると、弟子たちも従って行った。"}, "40": {"en": "When he was at the place, he said to them, “Pray that you don’t enter into temptation.”", "zh": "到了那地方，就對他們說：「你們要禱告，免得入了迷惑。」", "ja": "いつもの場所に着いてから、彼らに言われた、「誘惑に陥らないように祈りなさい」。"}, "41": {"en": "He was withdrawn from them about a stone’s throw, and he knelt down and prayed,", "zh": "於是離開他們約有扔一塊石頭那麼遠，跪下禱告，", "ja": "そしてご自分は、石を投げてとどくほど離れたところへ退き、ひざまずいて、祈って言われた、"}, "42": {"en": "saying, “Father, if you are willing, remove this cup from me. Nevertheless, not my will, but yours, be done.”", "zh": "說：「父啊！你若願意，就把這杯撤去；然而，不要成就我的意思，只要成就你的意思。」", "ja": "「父よ、みこころならば、どうぞ、この杯をわたしから取りのけてください。しかし、わたしの思いではなく、みこころが成るようにしてください」。"}, "43": {"en": "An angel from heaven appeared to him, strengthening him.", "zh": "有一位天使從天上顯現，加添他的力量。", "ja": "そのとき、御使が天からあらわれてイエスを力づけた。"}, "44": {"en": "Being in agony, he prayed more earnestly. His sweat became like great drops of blood falling down on the ground.", "zh": "耶穌極其傷痛，禱告更加懇切，汗珠如大血點滴在地上。", "ja": "イエスは苦しみもだえて、ますます切に祈られた。そして、その汗が血のしたたりのように地に落ちた。"}, "45": {"en": "When he rose up from his prayer, he came to the disciples and found them sleeping because of grief,", "zh": "禱告完了，就起來，到門徒那裏，見他們因為憂愁都睡着了，", "ja": "祈を終えて立ちあがり、弟子たちのところへ行かれると、彼らが悲しみのはて寝入っているのをごらんになって"}, "46": {"en": "and said to them, “Why do you sleep? Rise and pray that you may not enter into temptation.”", "zh": "就對他們說：「你們為甚麼睡覺呢？起來禱告，免得入了迷惑！」", "ja": "言われた、「なぜ眠っているのか。誘惑に陥らないように、起きて祈っていなさい」。"}, "47": {"en": "While he was still speaking, a crowd appeared. He who was called Judas, one of the twelve, was leading them. He came near to Jesus to kiss him.", "zh": "說話之間，來了許多人。那十二個門徒裏名叫猶大的，走在前頭，就近耶穌，要與他親嘴。", "ja": "イエスがまだそう言っておられるうちに、そこに群衆が現れ、十二弟子のひとりでユダという者が先頭に立って、イエスに接吻しようとして近づいてきた。"}, "48": {"en": "But Jesus said to him, “Judas, do you betray the Son of Man with a kiss?”", "zh": "耶穌對他說：「猶大！你用親嘴的暗號賣人子嗎？」", "ja": "そこでイエスは言われた、「ユダ、あなたは接吻をもって人の子を裏切るのか」。"}, "49": {"en": "When those who were around him saw what was about to happen, they said to him, “Lord, shall we strike with the sword?”", "zh": "左右的人見光景不好，就說：「主啊！我們拿刀砍可以不可以？」", "ja": "イエスのそばにいた人たちは、事のなりゆきを見て、「主よ、つるぎで切りつけてやりましょうか」と言って、"}, "50": {"en": "A certain one of them struck the servant of the high priest, and cut off his right ear.", "zh": "內中有一個人把大祭司的僕人砍了一刀，削掉了他的右耳。", "ja": "そのうちのひとりが、祭司長の僕に切りつけ、その右の耳を切り落した。"}, "51": {"en": "But Jesus answered, “Let me at least do this”—and he touched his ear and healed him.", "zh": "耶穌說：「到了這個地步，由他們吧！」就摸那人的耳朵，把他治好了。", "ja": "イエスはこれに対して言われた、「それだけでやめなさい」。そして、その僕の耳に手を触て、おいやしになった。"}, "52": {"en": "Jesus said to the chief priests, captains of the temple, and elders, who had come against him, “Have you come out as against a robber, with swords and clubs?", "zh": "耶穌對那些來拿他的祭司長和守殿官並長老說：「你們帶着刀棒出來拿我，如同拿強盜嗎？", "ja": "それから、自分にむかって来る祭司長、宮守がしら、長老たちに対して言われた、「あなたがたは、強盗にむかうように剣や棒を持って出てきたのか。"}, "53": {"en": "When I was with you in the temple daily, you didn’t stretch out your hands against me. But this is your hour, and the power of darkness.”", "zh": "我天天同你們在殿裏，你們不下手拿我。現在卻是你們的時候，黑暗掌權了。」", "ja": "毎日あなたがたと一緒に宮にいた時には、わたしに手をかけなかった。だが、今はあなたがたの時、また、やみの支配の時である」。"}, "54": {"en": "They seized him and led him away, and brought him into the high priest’s house. But Peter followed from a distance.", "zh": "他們拿住耶穌，把他帶到大祭司的宅裏。彼得遠遠地跟着。", "ja": "それから人々はイエスを捕え、ひっぱって大祭司の邸宅へつれて行った。ペテロは遠くからついて行った。"}, "55": {"en": "When they had kindled a fire in the middle of the courtyard and had sat down together, Peter sat among them.", "zh": "他們在院子裏生了火，一同坐着；彼得也坐在他們中間。", "ja": "人々は中庭のまん中に火をたいて、一緒にすわっていたので、ペテロもその中にすわった。"}, "56": {"en": "A certain servant girl saw him as he sat in the light, and looking intently at him, said, “This man also was with him.”", "zh": "有一個使女看見彼得坐在火光裏，就定睛看他，說：「這個人素來也是同那人一夥的。」", "ja": "すると、ある女中が、彼が火のそばにすわっているのを見、彼を見つめて、「この人もイエスと一緒にいました」と言った。"}, "57": {"en": "He denied Jesus, saying, “Woman, I don’t know him.”", "zh": "彼得卻不承認，說：「女子，我不認得他。」", "ja": "ペテロはそれを打ち消して、「わたしはその人を知らない」と言った。"}, "58": {"en": "After a little while someone else saw him and said, “You also are one of them!” But Peter answered, “Man, I am not!”", "zh": "過了不多的時候，又有一個人看見他，說：「你也是他們一黨的。」彼得說：「你這個人！我不是。」", "ja": "しばらくして、ほかの人がペテロを見て言った、「あなたもあの仲間のひとりだ」。するとペテロは言った、「いや、それはちがう」。"}, "59": {"en": "After about one hour passed, another confidently affirmed, saying, “Truly this man also was with him, for he is a Galilean!”", "zh": "約過了一小時，又有一個人極力地說：「他實在是同那人一夥的，因為他也是加利利人。」", "ja": "約一時間たってから、またほかの者が言い張った、「たしかにこの人もイエスと一緒だった。この人もガリラヤ人なのだから」。"}, "60": {"en": "But Peter said, “Man, I don’t know what you are talking about!” Immediately, while he was still speaking, a rooster crowed.", "zh": "彼得說：「你這個人！我不曉得你說的是甚麼！」正說話之間，雞就叫了。", "ja": "ペテロは言った、「あなたの言っていることは、わたしにわからない」。すると、彼がまだ言い終らぬうちに、たちまち、鶏が鳴いた。"}, "61": {"en": "The Lord turned and looked at Peter. Then Peter remembered the Lord’s word, how he said to him, “Before the rooster crows you will deny me three times.”", "zh": "主轉過身來看彼得，彼得便想起主對他所說的話：「今日雞叫以先，你要三次不認我。」", "ja": "主は振りむいてペテロを見つめられた。そのときペテロは、「きょう、鶏が鳴く前に、三度わたしを知らないと言うであろう」と言われた主のお言葉を思い出した。"}, "62": {"en": "He went out, and wept bitterly.", "zh": "他就出去痛哭。", "ja": "そして外へ出て、激しく泣いた。"}, "63": {"en": "The men who held Jesus mocked him and beat him.", "zh": "看守耶穌的人戲弄他，打他，", "ja": "イエスを監視していた人たちは、イエスを嘲弄し、打ちたたき、"}, "64": {"en": "Having blindfolded him, they struck him on the face and asked him, “Prophesy! Who is the one who struck you?”", "zh": "又蒙着他的眼，問他說：「你是先知，告訴我們打你的是誰？」", "ja": "目かくしをして、「言いあててみよ。打ったのは、だれか」ときいたりした。"}, "65": {"en": "They spoke many other things against him, insulting him.", "zh": "他們還用許多別的話辱罵他。", "ja": "そのほか、いろいろな事を言って、イエスを愚弄した。"}, "66": {"en": "As soon as it was day, the assembly of the elders of the people were gathered together, both chief priests and scribes, and they led him away into their council, saying,", "zh": "天一亮，民間的眾長老連祭司長帶文士都聚會， 把耶穌帶到他們的公會裏，", "ja": "夜が明けたとき、人民の長老、祭司長たち、律法学者たちが集まり、イエスを議会に引き出して言った、"}, "67": {"en": "“If you are the Christ, tell us.”", "zh": "說：「你若是基督，就告訴我們。」耶穌說：「我若告訴你們，你們也不信；", "ja": "「あなたがキリストなら、そう言ってもらいたい」。イエスは言われた、「わたしが言っても、あなたがたは信じないだろう。"}, "68": {"en": "But he said to them, “If I tell you, you won’t believe,  and if I ask, you will in no way answer me or let me go.", "zh": "我若問你們，你們也不回答。", "ja": "また、わたしがたずねても、答えないだろう。"}, "69": {"en": "From now on, the Son of Man will be seated at the right hand of the power of God.”", "zh": "從今以後，人子要坐在上帝權能的右邊。」", "ja": "しかし、人の子は今からのち、全能の神の右に座するであろう」。"}, "70": {"en": "They all said, “Are you then the Son of God?” He said to them, “You say it, because I am.”", "zh": "他們都說：「這樣，你是上帝的兒子嗎？」耶穌說：「你們所說的是。」", "ja": "彼らは言った、「では、あなたは神の子なのか」。イエスは言われた、「あなたがたの言うとおりである」。"}, "71": {"en": "They said, “Why do we need any more witness? For we ourselves have heard from his own mouth!”", "zh": "他們說：「何必再用見證呢？他親口所說的，我們都親自聽見了。」", "ja": "すると彼らは言った、「これ以上、なんの証拠がいるか。われわれは直接彼の口から聞いたのだから」。"}}}, "23": {"verses": {"1": {"en": "The whole company of them rose up and brought him before Pilate.", "zh": "眾人都起來，把耶穌解到彼拉多面前，", "ja": "群衆はみな立ちあがって、イエスをピラトのところへ連れて行った。"}, "2": {"en": "They began to accuse him, saying, “We found this man perverting the nation, forbidding paying taxes to Caesar, and saying that he himself is Christ, a king.”", "zh": "就告他說：「我們見這人誘惑國民，禁止納稅給凱撒，並說自己是基督，是王。」", "ja": "そして訴え出て言った、「わたしたちは、この人が国民を惑わし、貢をカイザルに納めることを禁じ、また自分こそ王なるキリストだと、となえているところを目撃しました」。"}, "3": {"en": "Pilate asked him, “Are you the King of the Jews?” He answered him, “So you say.”", "zh": "彼拉多問耶穌說：「你是猶太人的王嗎？」耶穌回答說：「你說的是。」", "ja": "ピラトはイエスに尋ねた、「あなたがユダヤ人の王であるか」。イエスは「そのとおりである」とお答えになった。"}, "4": {"en": "Pilate said to the chief priests and the multitudes, “I find no basis for a charge against this man.”", "zh": "彼拉多對祭司長和眾人說：「我查不出這人有甚麼罪來。」", "ja": "そこでピラトは祭司長たちと群衆とにむかって言った、「わたしはこの人になんの罪もみとめない」。"}, "5": {"en": "But they insisted, saying, “He stirs up the people, teaching throughout all Judea, beginning from Galilee even to this place.”", "zh": "但他們越發極力地說：「他煽惑百姓，在猶太遍地傳道，從加利利起，直到這裏了。」", "ja": "ところが彼らは、ますます言いつのってやまなかった、「彼は、ガリラヤからはじめてこの所まで、ユダヤ全国にわたって教え、民衆を煽動しているのです」。"}, "6": {"en": "But when Pilate heard Galilee mentioned, he asked if the man was a Galilean.", "zh": "彼拉多一聽見，就問：「這人是加利利人嗎？」", "ja": "ピラトはこれを聞いて、この人はガリラヤ人かと尋ね、"}, "7": {"en": "When he found out that he was in Herod’s jurisdiction, he sent him to Herod, who was also in Jerusalem during those days.", "zh": "既曉得耶穌屬希律所管，就把他送到希律那裏去。那時希律正在耶路撒冷。", "ja": "そしてヘロデの支配下のものであることを確かめたので、ちょうどこのころ、ヘロデがエルサレムにいたのをさいわい、そちらへイエスを送りとどけた。"}, "8": {"en": "Now when Herod saw Jesus, he was exceedingly glad, for he had wanted to see him for a long time, because he had heard many things about him. He hoped to see some miracle done by him.", "zh": "希律看見耶穌，就很歡喜；因為聽見過他的事，久已想要見他，並且指望看他行一件神蹟，", "ja": "ヘロデはイエスを見て非常に喜んだ。それは、かねてイエスのことを聞いていたので、会って見たいと長いあいだ思っていたし、またイエスが何か奇跡を行うのを見たいと望んでいたからである。"}, "9": {"en": "He questioned him with many words, but he gave no answers.", "zh": "於是問他許多的話，耶穌卻一言不答。", "ja": "それで、いろいろと質問を試みたが、イエスは何もお答えにならなかった。"}, "10": {"en": "The chief priests and the scribes stood, vehemently accusing him.", "zh": "祭司長和文士都站着，極力地告他。", "ja": "祭司長たちと律法学者たちとは立って、激しい語調でイエスを訴えた。"}, "11": {"en": "Herod with his soldiers humiliated him and mocked him. Dressing him in luxurious clothing, they sent him back to Pilate.", "zh": "希律和他的兵丁就藐視耶穌，戲弄他，給他穿上華麗衣服，把他送回彼拉多那裏去。", "ja": "またヘロデはその兵卒どもと一緒になって、イエスを侮辱したり嘲弄したりしたあげく、はなやかな着物を着せてピラトへ送りかえした。"}, "12": {"en": "Herod and Pilate became friends with each other that very day, for before that they were enemies with each other.", "zh": "從前希律和彼拉多彼此有仇，在那一天就成了朋友。", "ja": "ヘロデとピラトとは以前は互に敵視していたが、この日に親しい仲になった。"}, "13": {"en": "Pilate called together the chief priests, the rulers, and the people,", "zh": "彼拉多傳齊了祭司長和官府並百姓，", "ja": "ピラトは、祭司長たちと役人たちと民衆とを、呼び集めて言った、"}, "14": {"en": "and said to them, “You brought this man to me as one that perverts the people, and behold, having examined him before you, I found no basis for a charge against this man concerning those things of which you accuse him.", "zh": "就對他們說：「你們解這人到我這裏，說他是誘惑百姓的。看哪，我也曾將你們告他的事，在你們面前審問他，並沒有查出他甚麼罪來；", "ja": "「おまえたちは、この人を民衆を惑わすものとしてわたしのところに連れてきたので、おまえたちの面前でしらべたが、訴え出ているような罪は、この人に少しもみとめられなかった。"}, "15": {"en": "Neither has Herod, for I sent you to him, and see, nothing worthy of death has been done by him.", "zh": "就是希律也是如此，所以把他送回來。可見他沒有做甚麼該死的事。", "ja": "ヘロデもまたみとめなかった。現に彼はイエスをわれわれに送りかえしてきた。この人はなんら死に当るようなことはしていないのである。"}, "16": {"en": "I will therefore chastise him and release him.”", "zh": "故此，我要責打他，把他釋放了。」", "ja": "だから、彼をむち打ってから、ゆるしてやることにしよう」。〔"}, "17": {"en": "Now he had to release one prisoner to them at the feast.", "zh": "", "ja": "祭ごとにピラトがひとりの囚人をゆるしてやることになっていた。〕"}, "18": {"en": "But they all cried out together, saying, “Away with this man! Release to us Barabbas!”—", "zh": "眾人卻一齊喊着說：「除掉這個人！釋放巴拉巴給我們！」", "ja": "ところが、彼らはいっせいに叫んで言った、「その人を殺せ。バラバをゆるしてくれ」。"}, "19": {"en": "one who was thrown into prison for a certain revolt in the city, and for murder.", "zh": "這巴拉巴是因在城裏作亂殺人，下在監裏的。", "ja": "このバラバは、都で起った暴動と殺人とのかどで、獄に投ぜられていた者である。"}, "20": {"en": "Then Pilate spoke to them again, wanting to release Jesus,", "zh": "彼拉多願意釋放耶穌，就又勸解他們。", "ja": "ピラトはイエスをゆるしてやりたいと思って、もう一度かれらに呼びかけた。"}, "21": {"en": "but they shouted, saying, “Crucify! Crucify him!”", "zh": "無奈他們喊着說：「釘他十字架！釘他十字架！」", "ja": "しかし彼らは、わめきたてて「十字架につけよ、彼を十字架につけよ」と言いつづけた。"}, "22": {"en": "He said to them the third time, “Why? What evil has this man done? I have found no capital crime in him. I will therefore chastise him and release him.”", "zh": "彼拉多第三次對他們說：「為甚麼呢？這人做了甚麼惡事呢？我並沒有查出他甚麼該死的罪來。所以，我要責打他，把他釋放了。」", "ja": "ピラトは三度目に彼らにむかって言った、「では、この人は、いったい、どんな悪事をしたのか。彼には死に当る罪は全くみとめられなかった。だから、むち打ってから彼をゆるしてやることにしよう」。"}, "23": {"en": "But they were urgent with loud voices, asking that he might be crucified. Their voices and the voices of the chief priests prevailed.", "zh": "他們大聲催逼彼拉多，求他把耶穌釘在十字架上。他們的聲音就得了勝。", "ja": "ところが、彼らは大声をあげて詰め寄り、イエスを十字架につけるように要求した。そして、その声が勝った。"}, "24": {"en": "Pilate decreed that what they asked for should be done.", "zh": "彼拉多這才照他們所求的定案，", "ja": "ピラトはついに彼らの願いどおりにすることに決定した。"}, "25": {"en": "He released him who had been thrown into prison for insurrection and murder, for whom they asked, but he delivered Jesus up to their will.", "zh": "把他們所求的那作亂殺人、下在監裏的釋放了，把耶穌交給他們，任憑他們的意思行。", "ja": "そして、暴動と殺人とのかどで獄に投ぜられた者の方を、彼らの要求に応じてゆるしてやり、イエスの方は彼らに引き渡して、その意のままにまかせた。"}, "26": {"en": "When they led him away, they grabbed one Simon of Cyrene, coming from the country, and laid the cross on him to carry it after Jesus.", "zh": "帶耶穌去的時候，有一個古利奈人西門，從鄉下來；他們就抓住他，把十字架擱在他身上，叫他背着跟隨耶穌。", "ja": "彼らがイエスをひいてゆく途中、シモンというクレネ人が郊外から出てきたのを捕えて十字架を負わせ、それをになってイエスのあとから行かせた。"}, "27": {"en": "A great multitude of the people followed him, including women who also mourned and lamented him.", "zh": "有許多百姓跟隨耶穌，內中有好些婦女；婦女們為他號咷痛哭。", "ja": "大ぜいの民衆と、悲しみ嘆いてやまない女たちの群れとが、イエスに従って行った。"}, "28": {"en": "But Jesus, turning to them, said, “Daughters of Jerusalem, don’t weep for me, but weep for yourselves and for your children.", "zh": "耶穌轉身對她們說：「耶路撒冷的女子，不要為我哭，當為自己和自己的兒女哭。", "ja": "イエスは女たちの方に振りむいて言われた、「エルサレムの娘たちよ、わたしのために泣くな。むしろ、あなたがた自身のため、また自分の子供たちのために泣くがよい。"}, "29": {"en": "For behold, the days are coming in which they will say, ‘Blessed are the barren, the wombs that never bore, and the breasts that never nursed.’", "zh": "因為日子要到，人必說：『不生育的，和未曾懷胎的，未曾乳養嬰孩的，有福了！』", "ja": "『不妊の女と子を産まなかった胎と、ふくませなかった乳房とは、さいわいだ』と言う日が、いまに来る。"}, "30": {"en": "Then they will begin to tell the mountains, ‘Fall on us!’ and tell the hills, ‘Cover us.’", "zh": "那時，人要向大山說： 倒在我們身上！ 向小山說： 遮蓋我們！", "ja": "そのとき、人々は山にむかって、われわれの上に倒れかかれと言い、また丘にむかって、われわれにおおいかぶされと言い出すであろう。"}, "31": {"en": "For if they do these things in the green tree, what will be done in the dry?”", "zh": "「這些事既行在有汁水的樹上，那枯乾的樹將來怎麼樣呢？」", "ja": "もし、生木でさえもそうされるなら、枯木はどうされることであろう」。"}, "32": {"en": "There were also others, two criminals, led with him to be put to death.", "zh": "又有兩個犯人，和耶穌一同帶來處死。", "ja": "さて、イエスと共に刑を受けるために、ほかにふたりの犯罪人も引かれていった。"}, "33": {"en": "When they came to the place that is called “The Skull”, they crucified him there with the criminals, one on the right and the other on the left.", "zh": "到了一個地方，名叫「髑髏地」，就在那裏把耶穌釘在十字架上，又釘了兩個犯人：一個在左邊，一個在右邊。", "ja": "されこうべと呼ばれている所に着くと、人々はそこでイエスを十字架につけ、犯罪人たちも、ひとりは右に、ひとりは左に、十字架につけた。"}, "34": {"en": "Jesus said, “Father, forgive them, for they don’t know what they are doing.”", "zh": "當下耶穌說：「父啊！赦免他們；因為他們所做的，他們不曉得。」兵丁就拈鬮分他的衣服。", "ja": "そのとき、イエスは言われた、「父よ、彼らをおゆるしください。彼らは何をしているのか、わからずにいるのです」。人々はイエスの着物をくじ引きで分け合った。"}, "35": {"en": "Dividing his garments among them, they cast lots.   The people stood watching. The rulers with them also scoffed at him, saying, “He saved others. Let him save himself, if this is the Christ of God, his chosen one!”", "zh": "百姓站在那裏觀看。官府也嗤笑他，說：「他救了別人；他若是基督，上帝所揀選的，可以救自己吧！」", "ja": "民衆は立って見ていた。役人たちもあざ笑って言った、「彼は他人を救った。もし彼が神のキリスト、選ばれた者であるなら、自分自身を救うがよい」。"}, "36": {"en": "The soldiers also mocked him, coming to him and offering him vinegar,", "zh": "兵丁也戲弄他，上前拿醋送給他喝，", "ja": "兵卒どももイエスをののしり、近寄ってきて酢いぶどう酒をさし出して言った、"}, "37": {"en": "and saying, “If you are the King of the Jews, save yourself!”", "zh": "說：「你若是猶太人的王，可以救自己吧！」", "ja": "「あなたがユダヤ人の王なら、自分を救いなさい」。"}, "38": {"en": "An inscription was also written over him in letters of Greek, Latin, and Hebrew: “THIS IS THE KING OF THE JEWS.”", "zh": "在耶穌以上有一個牌子寫着：「這是猶太人的王。」", "ja": "イエスの上には、「これはユダヤ人の王」と書いた札がかけてあった。"}, "39": {"en": "One of the criminals who was hanged insulted him, saying, “If you are the Christ, save yourself and us!”", "zh": "那同釘的兩個犯人有一個譏笑他，說：「你不是基督嗎？可以救自己和我們吧！」", "ja": "十字架にかけられた犯罪人のひとりが、「あなたはキリストではないか。それなら、自分を救い、またわれわれも救ってみよ」と、イエスに悪口を言いつづけた。"}, "40": {"en": "But the other answered, and rebuking him said, “Don’t you even fear God, seeing you are under the same condemnation?", "zh": "那一個就應聲責備他，說：「你既是一樣受刑的，還不怕上帝嗎？", "ja": "もうひとりは、それをたしなめて言った、「おまえは同じ刑を受けていながら、神を恐れないのか。"}, "41": {"en": "And we indeed justly, for we receive the due reward for our deeds, but this man has done nothing wrong.”", "zh": "我們是應該的，因我們所受的與我們所做的相稱，但這個人沒有做過一件不好的事。」", "ja": "お互は自分のやった事のむくいを受けているのだから、こうなったのは当然だ。しかし、このかたは何も悪いことをしたのではない」。"}, "42": {"en": "He said to Jesus, “Lord, remember me when you come into your Kingdom.”", "zh": "就說：「耶穌啊，你得國降臨的時候，求你記念我！」", "ja": "そして言った、「イエスよ、あなたが御国の権威をもっておいでになる時には、わたしを思い出してください」。"}, "43": {"en": "Jesus said to him, “Assuredly I tell you, today you will be with me in Paradise.”", "zh": "耶穌對他說：「我實在告訴你，今日你要同我在樂園裏了。」", "ja": "イエスは言われた、「よく言っておくが、あなたはきょう、わたしと一緒にパラダイスにいるであろう」。"}, "44": {"en": "It was now about the sixth hour, and darkness came over the whole land until the ninth hour.", "zh": "那時約有午正，遍地都黑暗了，直到申初，", "ja": "時はもう昼の十二時ごろであったが、太陽は光を失い、全地は暗くなって、三時に及んだ。"}, "45": {"en": "The sun was darkened, and the veil of the temple was torn in two.", "zh": "日頭變黑了；殿裏的幔子從當中裂為兩半。", "ja": "そして聖所の幕がまん中から裂けた。"}, "46": {"en": "Jesus, crying with a loud voice, said, “Father, into your hands I commit my spirit!” Having said this, he breathed his last.", "zh": "耶穌大聲喊着說：「父啊！我將我的靈魂交在你手裏。」說了這話，氣就斷了。", "ja": "そのとき、イエスは声高く叫んで言われた、「父よ、わたしの霊をみ手にゆだねます」。こう言ってついに息を引きとられた。"}, "47": {"en": "When the centurion saw what was done, he glorified God, saying, “Certainly this was a righteous man.”", "zh": "百夫長看見所成的事，就歸榮耀與上帝，說：「這真是個義人！」", "ja": "百卒長はこの有様を見て、神をあがめ、「ほんとうに、この人は正しい人であった」と言った。"}, "48": {"en": "All the multitudes that came together to see this, when they saw the things that were done, returned home beating their chests.", "zh": "聚集觀看的眾人見了這所成的事都捶着胸回去了。", "ja": "この光景を見に集まってきた群衆も、これらの出来事を見て、みな胸を打ちながら帰って行った。"}, "49": {"en": "All his acquaintances and the women who followed with him from Galilee stood at a distance, watching these things.", "zh": "還有一切與耶穌熟識的人，和從加利利跟着他來的婦女們，都遠遠地站着看這些事。", "ja": "すべてイエスを知っていた者や、ガリラヤから従ってきた女たちも、遠い所に立って、これらのことを見ていた。"}, "50": {"en": "Behold, there was a man named Joseph, who was a member of the council, a good and righteous man", "zh": "有一個人名叫約瑟，是個議士，為人善良公義；", "ja": "ここに、ヨセフという議員がいたが、善良で正しい人であった。"}, "51": {"en": "(he had not consented to their counsel and deed), from Arimathaea, a city of the Jews, who was also waiting for God’s Kingdom.", "zh": "眾人所謀所為，他並沒有附從。他本是猶太、亞利馬太城裏素常盼望上帝國的人。", "ja": "この人はユダヤの町アリマタヤの出身で、神の国を待ち望んでいた。彼は議会の議決や行動には賛成していなかった。"}, "52": {"en": "This man went to Pilate, and asked for Jesus’ body.", "zh": "這人去見彼拉多，求耶穌的身體，", "ja": "この人がピラトのところへ行って、イエスのからだの引取り方を願い出て、"}, "53": {"en": "He took it down and wrapped it in a linen cloth, and laid him in a tomb that was cut in stone, where no one had ever been laid.", "zh": "就取下來，用細麻布裹好，安放在石頭鑿成的墳墓裏；那裏頭從來沒有葬過人。", "ja": "それを取りおろして亜麻布に包み、まだだれも葬ったことのない、岩を掘って造った墓に納めた。"}, "54": {"en": "It was the day of the Preparation, and the Sabbath was drawing near.", "zh": "那日是預備日，安息日也快到了。", "ja": "この日は準備の日であって、安息日が始まりかけていた。"}, "55": {"en": "The women who had come with him out of Galilee followed after, and saw the tomb and how his body was laid.", "zh": "那些從加利利和耶穌同來的婦女跟在後面，看見了墳墓和他的身體怎樣安放。", "ja": "イエスと一緒にガリラヤからきた女たちは、あとについてきて、その墓を見、またイエスのからだが納められる様子を見とどけた。"}, "56": {"en": "They returned and prepared spices and ointments. On the Sabbath they rested according to the commandment.", "zh": "她們就回去，預備了香料香膏。她們在安息日，便遵着誡命安息了。", "ja": "そして帰って、香料と香油とを用意した。それからおきてに従って安息日を休んだ。"}}}, "24": {"verses": {"1": {"en": "But on the first day of the week, at early dawn, they and some others came to the tomb, bringing the spices which they had prepared.", "zh": "七日的頭一日，黎明的時候，那些婦女帶着所預備的香料來到墳墓前，", "ja": "週の初めの日、夜明け前に、女たちは用意しておいた香料を携えて、墓に行った。"}, "2": {"en": "They found the stone rolled away from the tomb.", "zh": "看見石頭已經從墳墓滾開了，", "ja": "ところが、石が墓からころがしてあるので、"}, "3": {"en": "They entered in, and didn’t find the Lord Jesus’ body.", "zh": "她們就進去，只是不見主耶穌的身體。", "ja": "中にはいってみると、主イエスのからだが見当らなかった。"}, "4": {"en": "While they were greatly perplexed about this, behold, two men stood by them in dazzling clothing.", "zh": "正在猜疑之間，忽然有兩個人站在旁邊，衣服放光。", "ja": "そのため途方にくれていると、見よ、輝いた衣を着たふたりの者が、彼らに現れた。"}, "5": {"en": "Becoming terrified, they bowed their faces down to the earth.", "zh": "婦女們驚怕，將臉伏地。那兩個人就對她們說：「為甚麼在死人中找活人呢？", "ja": "女たちは驚き恐れて、顔を地に伏せていると、このふたりの者が言った、「あなたがたは、なぜ生きた方を死人の中にたずねているのか。"}, "6": {"en": "The men said to them, “Why do you seek the living among the dead?   He isn’t here, but is risen. Remember what he told you when he was still in Galilee,", "zh": "他不在這裏，已經復活了。當記念他還在加利利的時候怎樣告訴你們，", "ja": "そのかたは、ここにはおられない。よみがえられたのだ。まだガリラヤにおられたとき、あなたがたにお話しになったことを思い出しなさい。"}, "7": {"en": "saying that the Son of Man must be delivered up into the hands of sinful men and be crucified, and the third day rise again?”", "zh": "說：『人子必須被交在罪人手裏，釘在十字架上，第三日復活。』」", "ja": "すなわち、人の子は必ず罪人らの手に渡され、十字架につけられ、そして三日目によみがえる、と仰せられたではないか」。"}, "8": {"en": "They remembered his words,", "zh": "她們就想起耶穌的話來，", "ja": "そこで女たちはその言葉を思い出し、"}, "9": {"en": "returned from the tomb, and told all these things to the eleven and to all the rest.", "zh": "便從墳墓那裏回去，把這一切的事告訴十一個使徒和其餘的人。", "ja": "墓から帰って、これらいっさいのことを、十一弟子や、その他みんなの人に報告した。"}, "10": {"en": "Now they were Mary Magdalene, Joanna, and Mary the mother of James. The other women with them told these things to the apostles.", "zh": "那告訴使徒的就是抹大拉的馬利亞和約亞拿，並雅各的母親馬利亞，還有與她們在一處的婦女。", "ja": "この女たちというのは、マグダラのマリヤ、ヨハンナ、およびヤコブの母マリヤであった。彼女たちと一緒にいたほかの女たちも、このことを使徒たちに話した。"}, "11": {"en": "These words seemed to them to be nonsense, and they didn’t believe them.", "zh": "她們這些話，使徒以為是胡言，就不相信。", "ja": "ところが、使徒たちには、それが愚かな話のように思われて、それを信じなかった。〔"}, "12": {"en": "But Peter got up and ran to the tomb. Stooping and looking in, he saw the strips of linen lying by themselves, and he departed to his home, wondering what had happened.", "zh": "彼得起來，跑到墳墓前，低頭往裏看，見細麻布獨在一處，就回去了，心裏希奇所成的事。", "ja": "ペテロは立って墓へ走って行き、かがんで中を見ると、亜麻布だけがそこにあったので、事の次第を不思議に思いながら帰って行った。〕"}, "13": {"en": "Behold, two of them were going that very day to a village named Emmaus, which was sixty stadia from Jerusalem.", "zh": "正當那日，門徒中有兩個人往一個村子去；這村子名叫以馬忤斯，離耶路撒冷約有二十五里。", "ja": "この日、ふたりの弟子が、エルサレムから七マイルばかり離れたエマオという村へ行きながら、"}, "14": {"en": "They talked with each other about all of these things which had happened.", "zh": "他們彼此談論所遇見的這一切事。", "ja": "このいっさいの出来事について互に語り合っていた。"}, "15": {"en": "While they talked and questioned together, Jesus himself came near, and went with them.", "zh": "正談論相問的時候，耶穌親自就近他們，和他們同行；", "ja": "語り合い論じ合っていると、イエスご自身が近づいてきて、彼らと一緒に歩いて行かれた。"}, "16": {"en": "But their eyes were kept from recognizing him.", "zh": "只是他們的眼睛迷糊了，不認識他。", "ja": "しかし、彼らの目がさえぎられて、イエスを認めることができなかった。"}, "17": {"en": "He said to them, “What are you talking about as you walk, and are sad?”", "zh": "耶穌對他們說：「你們走路彼此談論的是甚麼事呢？」他們就站住，臉上帶着愁容。", "ja": "イエスは彼らに言われた、「歩きながら互に語り合っているその話は、なんのことなのか」。彼らは悲しそうな顔をして立ちどまった。"}, "18": {"en": "One of them, named Cleopas, answered him, “Are you the only stranger in Jerusalem who doesn’t know the things which have happened there in these days?”", "zh": "二人中有一個名叫革流巴的回答說：「你在耶路撒冷作客，還不知道這幾天在那裏所出的事嗎？」", "ja": "そのひとりのクレオパという者が、答えて言った、「あなたはエルサレムに泊まっていながら、あなただけが、この都でこのごろ起ったことをご存じないのですか」。"}, "19": {"en": "He said to them, “What things?”", "zh": "耶穌說：「甚麼事呢？」他們說：「就是拿撒勒人耶穌的事。他是個先知，在上帝和眾百姓面前，說話行事都有大能。", "ja": "「それは、どんなことか」と言われると、彼らは言った、「ナザレのイエスのことです。あのかたは、神とすべての民衆との前で、わざにも言葉にも力ある預言者でしたが、"}, "20": {"en": "They said to him, “The things concerning Jesus the Nazarene, who was a prophet mighty in deed and word before God and all the people;   and how the chief priests and our rulers delivered him up to be condemned to death, and crucified him.", "zh": "祭司長和我們的官府竟把他解去，定了死罪，釘在十字架上。", "ja": "祭司長たちや役人たちが、死刑に処するために引き渡し、十字架につけたのです。"}, "21": {"en": "But we were hoping that it was he who would redeem Israel. Yes, and besides all this, it is now the third day since these things happened.", "zh": "但我們素來所盼望、要贖以色列民的就是他！不但如此，而且這事成就，現在已經三天了。", "ja": "わたしたちは、イスラエルを救うのはこの人であろうと、望みをかけていました。しかもその上に、この事が起ってから、きょうが三日目なのです。"}, "22": {"en": "Also, certain women of our company amazed us, having arrived early at the tomb;", "zh": "再者，我們中間有幾個婦女使我們驚奇；她們清早到了墳墓那裏，", "ja": "ところが、わたしたちの仲間である数人の女が、わたしたちを驚かせました。というのは、彼らが朝早く墓に行きますと、"}, "23": {"en": "and when they didn’t find his body, they came saying that they had also seen a vision of angels, who said that he was alive.", "zh": "不見他的身體，就回來告訴我們，說看見了天使顯現，說他活了。", "ja": "イエスのからだが見当らないので、帰ってきましたが、そのとき御使が現れて、『イエスは生きておられる』と告げたと申すのです。"}, "24": {"en": "Some of us went to the tomb and found it just like the women had said, but they didn’t see him.”", "zh": "又有我們的幾個人往墳墓那裏去，所遇見的正如婦女們所說的，只是沒有看見他。」", "ja": "それで、わたしたちの仲間が数人、墓に行って見ますと、果して女たちが言ったとおりで、イエスは見当りませんでした」。"}, "25": {"en": "He said to them, “Foolish people, and slow of heart to believe in all that the prophets have spoken!", "zh": "耶穌對他們說：「無知的人哪，先知所說的一切話，你們的心信得太遲鈍了。", "ja": "そこでイエスが言われた、「ああ、愚かで心のにぶいため、預言者たちが説いたすべての事を信じられない者たちよ。"}, "26": {"en": "Didn’t the Christ have to suffer these things and to enter into his glory?”", "zh": "基督這樣受害，又進入他的榮耀，豈不是應當的嗎？」", "ja": "キリストは必ず、これらの苦難を受けて、その栄光に入るはずではなかったのか」。"}, "27": {"en": "Beginning from Moses and from all the prophets, he explained to them in all the Scriptures the things concerning himself.", "zh": "於是從摩西和眾先知起，凡經上所指着自己的話都給他們講解明白了。", "ja": "こう言って、モーセやすべての預言者からはじめて、聖書全体にわたり、ご自身についてしるしてある事どもを、説きあかされた。"}, "28": {"en": "They came near to the village where they were going, and he acted like he would go further.", "zh": "將近他們所去的村子，耶穌好像還要往前行，", "ja": "それから、彼らは行こうとしていた村に近づいたが、イエスがなお先へ進み行かれる様子であった。"}, "29": {"en": "They urged him, saying, “Stay with us, for it is almost evening, and the day is almost over.”", "zh": "他們卻強留他，說：「時候晚了，日頭已經平西了，請你同我們住下吧！」耶穌就進去，要同他們住下。", "ja": "そこで、しいて引き止めて言った、「わたしたちと一緒にお泊まり下さい。もう夕暮になっており、日もはや傾いています」。イエスは、彼らと共に泊まるために、家にはいられた。"}, "30": {"en": "He went in to stay with them.   When he had sat down at the table with them, he took the bread and gave thanks. Breaking it, he gave it to them.", "zh": "到了坐席的時候，耶穌拿起餅來，祝謝了，擘開，遞給他們。", "ja": "一緒に食卓につかれたとき、パンを取り、祝福してさき、彼らに渡しておられるうちに、"}, "31": {"en": "Their eyes were opened and they recognized him; then he vanished out of their sight.", "zh": "他們的眼睛明亮了，這才認出他來。忽然耶穌不見了。", "ja": "彼らの目が開けて、それがイエスであることがわかった。すると、み姿が見えなくなった。"}, "32": {"en": "They said to one another, “Weren’t our hearts burning within us while he spoke to us along the way, and while he opened the Scriptures to us?”", "zh": "他們彼此說：「在路上，他和我們說話，給我們講解聖經的時候，我們的心豈不是火熱的嗎？」", "ja": "彼らは互に言った、「道々お話しになったとき、また聖書を説き明してくださったとき、お互の心が内に燃えたではないか」。"}, "33": {"en": "They rose up that very hour, returned to Jerusalem, and found the eleven gathered together, and those who were with them,", "zh": "他們就立時起身，回耶路撒冷去，正遇見十一個使徒和他們的同人聚集在一處，", "ja": "そして、すぐに立ってエルサレムに帰って見ると、十一弟子とその仲間が集まっていて、"}, "34": {"en": "saying, “The Lord is risen indeed, and has appeared to Simon!”", "zh": "說：「主果然復活，已經現給西門看了。」", "ja": "「主は、ほんとうによみがえって、シモンに現れなさった」と言っていた。"}, "35": {"en": "They related the things that happened along the way, and how he was recognized by them in the breaking of the bread.", "zh": "兩個人就把路上所遇見，和擘餅的時候怎麼被他們認出來的事，都述說了一遍。", "ja": "そこでふたりの者は、途中であったことや、パンをおさきになる様子でイエスだとわかったことなどを話した。"}, "36": {"en": "As they said these things, Jesus himself stood among them, and said to them, “Peace be to you.”", "zh": "正說這話的時候，耶穌親自站在他們當中，說：「願你們平安！」", "ja": "こう話していると、イエスが彼らの中にお立ちになった。〔そして「やすかれ」と言われた。〕"}, "37": {"en": "But they were terrified and filled with fear, and supposed that they had seen a spirit.", "zh": "他們卻驚慌害怕，以為所看見的是魂。", "ja": "彼らは恐れ驚いて、霊を見ているのだと思った。"}, "38": {"en": "He said to them, “Why are you troubled? Why do doubts arise in your hearts?", "zh": "耶穌說：「你們為甚麼愁煩？為甚麼心裏起疑念呢？", "ja": "そこでイエスが言われた、「なぜおじ惑っているのか。どうして心に疑いを起すのか。"}, "39": {"en": "See my hands and my feet, that it is truly me. Touch me and see, for a spirit doesn’t have flesh and bones, as you see that I have.”", "zh": "你們看我的手，我的腳，就知道實在是我了。摸我看看！魂無骨無肉，你們看，我是有的。」", "ja": "わたしの手や足を見なさい。まさしくわたしなのだ。さわって見なさい。霊には肉や骨はないが、あなたがたが見るとおり、わたしにはあるのだ」。〔"}, "40": {"en": "When he had said this, he showed them his hands and his feet.", "zh": "說了這話，就把手和腳給他們看。", "ja": "こう言って、手と足とをお見せになった。〕"}, "41": {"en": "While they still didn’t believe for joy, and wondered, he said to them, “Do you have anything here to eat?”", "zh": "他們正喜得不敢信，並且希奇；耶穌就說：「你們這裏有甚麼吃的沒有？」", "ja": "彼らは喜びのあまり、まだ信じられないで不思議に思っていると、イエスが「ここに何か食物があるか」と言われた。"}, "42": {"en": "They gave him a piece of a broiled fish and some honeycomb.", "zh": "他們便給他一片燒魚。", "ja": "彼らが焼いた魚の一きれをさしあげると、"}, "43": {"en": "He took them, and ate in front of them.", "zh": "他接過來，在他們面前吃了。", "ja": "イエスはそれを取って、みんなの前で食べられた。"}, "44": {"en": "He said to them, “This is what I told you while I was still with you, that all things which are written in the law of Moses, the prophets, and the psalms concerning me must be fulfilled.”", "zh": "耶穌對他們說：「這就是我從前與你們同在之時所告訴你們的話說：摩西的律法、先知的書，和詩篇上所記的，凡指着我的話都必須應驗。」", "ja": "それから彼らに対して言われた、「わたしが以前あなたがたと一緒にいた時分に話して聞かせた言葉は、こうであった。すなわち、モーセの律法と預言書と詩篇とに、わたしについて書いてあることは、必ずことごとく成就する」。"}, "45": {"en": "Then he opened their minds, that they might understand the Scriptures.", "zh": "於是耶穌開他們的心竅，使他們能明白聖經，", "ja": "そこでイエスは、聖書を悟らせるために彼らの心を開いて"}, "46": {"en": "He said to them, “Thus it is written, and thus it was necessary for the Christ to suffer and to rise from the dead the third day,", "zh": "又對他們說：「照經上所寫的，基督必受害，第三日從死裏復活，", "ja": "言われた、「こう、しるしてある。キリストは苦しみを受けて、三日目に死人の中からよみがえる。"}, "47": {"en": "and that repentance and remission of sins should be preached in his name to all the nations, beginning at Jerusalem.", "zh": "並且人要奉他的名傳悔改、赦罪的道，從耶路撒冷起直傳到萬邦。", "ja": "そして、その名によって罪のゆるしを得させる悔改めが、エルサレムからはじまって、もろもろの国民に宣べ伝えられる。"}, "48": {"en": "You are witnesses of these things.", "zh": "你們就是這些事的見證。", "ja": "あなたがたは、これらの事の証人である。"}, "49": {"en": "Behold, I send out the promise of my Father on you. But wait in the city of Jerusalem until you are clothed with power from on high.”", "zh": "我要將我父所應許的降在你們身上，你們要在城裏等候，直到你們領受從上頭來的能力。」", "ja": "見よ、わたしの父が約束されたものを、あなたがたに贈る。だから、上から力を授けられるまでは、あなたがたは都にとどまっていなさい」。"}, "50": {"en": "He led them out as far as Bethany, and he lifted up his hands and blessed them.", "zh": "耶穌領他們到伯大尼的對面，就舉手給他們祝福。", "ja": "それから、イエスは彼らをベタニヤの近くまで連れて行き、手をあげて彼らを祝福された。"}, "51": {"en": "While he blessed them, he withdrew from them and was carried up into heaven.", "zh": "正祝福的時候，他就離開他們，被帶到天上去了。", "ja": "祝福しておられるうちに、彼らを離れて、〔天にあげられた。〕"}, "52": {"en": "They worshiped him and returned to Jerusalem with great joy,", "zh": "他們就拜他，大大地歡喜，回耶路撒冷去，", "ja": "彼らは〔イエスを拝し、〕非常な喜びをもってエルサレムに帰り、"}, "53": {"en": "and were continually in the temple, praising and blessing God. Amen.", "zh": "常在殿裏稱頌上帝。", "ja": "絶えず宮にいて、神をほめたたえていた。"}}}}};
